CAOIDataCollect::CAOIDataCollect()
{	
	// 暫時固定 Input：檢測1片、跳過2片。
	m_BoardSkipPolicyLA.Configure(true, 1, 2);
	m_BoardSkipPolicyLB.Configure(true, 1, 2);
	m_SaveDebugMessage_RGN = false;
	CString str;
	size_t  i=0;
	int     BarcodeDeviceID = 0;
	const size_t MaxDeviceCount = MAX_BARCODE_DEVICE_COUNT;			
	for ( i=0; i<MaxDeviceCount; i++ )
	{	
		m_BarcodeDevicePtr[i]  = NULL; 
		switch ( i )
		{
		case 0:	BarcodeDeviceID=BARCODE_DEVICE_ID_01; break;
		case 1:	BarcodeDeviceID=BARCODE_DEVICE_ID_02; break;
		case 2:	BarcodeDeviceID=BARCODE_DEVICE_ID_03; break;
		case 3:	BarcodeDeviceID=BARCODE_DEVICE_ID_04; break;
		case 4:	BarcodeDeviceID=BARCODE_DEVICE_ID_05; break;
		case 5:	BarcodeDeviceID=BARCODE_DEVICE_ID_06; break;
		case 6:	BarcodeDeviceID=BARCODE_DEVICE_ID_07; break;
		case 7:	BarcodeDeviceID=BARCODE_DEVICE_ID_08; break;
		default: BarcodeDeviceID=BARCODE_DEVICE_ID_OFF; break;
		}
		m_BarcodeDeviceIDList_LA[i] = BarcodeDeviceID;
		m_BarcodeDeviceIDList_LB[i] = BarcodeDeviceID;
	}
	SetAOIDirectory(AOI3D_MAIN_FOLDER);
	
	::InitializeCriticalSection(&m_csGlobal);
	::InitializeCriticalSection(&m_csThread);
	::InitializeCriticalSection(&m_csITSProc);		
	::InitializeCriticalSection(&m_csUserInput);
	::InitializeCriticalSection(&m_csSystemException);
	::InitializeCriticalSection(&m_csThreadSystemRun);	
	::InitializeCriticalSection(&m_csThreadSliceFill);
	::InitializeCriticalSection(&m_csThreadFrameMerge);
	::InitializeCriticalSection(&m_csThreadFieldMerge);	
	::InitializeCriticalSection(&m_csThreadFrameLoad);
	::InitializeCriticalSection(&m_csThreadFieldCalc);
	::InitializeCriticalSection(&m_csThreadFrameRelease);
	::InitializeCriticalSection(&m_csThreadRegionCalc);
	::InitializeCriticalSection(&m_csThreadSequenceThread);	
	::InitializeCriticalSection(&m_csThreadOnlineInspection);
	::InitializeCriticalSection(&m_csThreadRemoveFolder);
	::InitializeCriticalSection(&m_csThreadConveyerAutoRun);
	::InitializeCriticalSection(&m_csThreadSimpleJob);	
	::InitializeCriticalSection(&m_csRepairResultList);
	::InitializeCriticalSection(&m_csThreadLoadRepairFile);	
	::InitializeCriticalSection(&m_csThreadHASI_Monitor);
	
	InitialAOIDataCollect();	
	LoadSystemParameter(true);	
	UpdateSystemParameter(false);
	SaveSystemParameter();
	CreateSystemDirectory();
	LoadCalibrationParameter();
	SaveCalibrationParameter();	
	LoadSystemImageParameter();
	SaveSystemImageParameter();
	LoadSystemBarcodeParameter();
	SaveSystemBarcodeParameter();
	SaveModelDefaultWndParam();
	CreateDefaultUserFile();
	AddDefaultUser_JetSenior();

	DefaultSystemBasePlaneParam();
	LoadSystemBasePlaneParam();
	SaveSystemBasePlaneParam();

	DefaultSystemNoiseFilterParam();
	LoadSystemNoiseFilterParam();
	SaveSystemNoiseFilterParam();

	LoadSystemRemoteParameter();
	SaveSystemRemoteParameter();

	LoadSystemFilenameSyntax();
	SaveSystemFilenameSyntax();

	m_PCBOKNGSignalOnTickCount_LA = 0;
	m_PCBOKNGSignalOnTickCount_LB = 0;
	m_LanePCBOutMode_LA = m_SystemParameter.m_DefaultPCBOutMode;//PCB出板模式
	m_LanePCBOutMode_LB = m_SystemParameter.m_DefaultPCBOutMode;//PCB出板模式	
	m_LaneDefectHandleMode_LA = m_SystemParameter.m_DefaultDefectHandleMode;//檢出異常處理模式
	m_LaneDefectHandleMode_LB = m_SystemParameter.m_DefaultDefectHandleMode;//檢出異常處理模式
	m_EnableConveyerPreRun = FN_DISABLE;//軌道提前運轉功能
	
	ONLINE_FROMVIEW_MODE OnlineFormViewMode = GetOnlineFormViewMode();
	if ( ONLINE_FROMVIEW_DUAL == OnlineFormViewMode )
	{	m_MainViewWndID = IDD_ONLINE_FORMVIEW_DUAL;	}
	else
	{	m_MainViewWndID = IDD_ONLINE_FORMVIEW;	}
	//m_EnableConveyerPreRun = m_SystemParameter.m_DefaultEnableConveyerPreRun;//軌道提前運轉功能
	
	m_RibbonTuneGroupCmdID = ID_TUNE_SELECTED_MODEL;//調適的視窗命令編號
	m_RibbonTuneGroupCmdText = _T("ID_TUNE_SELECTED_MODEL");//調適的視窗命令文字	

	m_RibbonDefaultWndCmdID = MENU_MODEL_EDIT_ADD_ALL_WND;;//預設檢測框的視窗命令編號
	m_RibbonDefaultWndCmdText = _T("MENU_MODEL_EDIT_ADD_ALL_WND");//預設檢測框的視窗命令文字
}
//-------------------------------------------------------------------------------------//
CAOIDataCollect::~CAOIDataCollect()
{	
	::DeleteCriticalSection(&m_csThreadLoadRepairFile);	
	::DeleteCriticalSection(&m_csRepairResultList);
	::DeleteCriticalSection(&m_csThreadHASI_Monitor);
	::DeleteCriticalSection(&m_csThreadSimpleJob);
	::DeleteCriticalSection(&m_csThreadConveyerAutoRun);
	::DeleteCriticalSection(&m_csThreadRemoveFolder);
	::DeleteCriticalSection(&m_csThreadOnlineInspection);
	::DeleteCriticalSection(&m_csThreadSequenceThread);
	::DeleteCriticalSection(&m_csThreadRegionCalc);
	::DeleteCriticalSection(&m_csThreadFrameRelease);
	::DeleteCriticalSection(&m_csThreadFieldCalc);
	::DeleteCriticalSection(&m_csThreadFrameLoad);
	::DeleteCriticalSection(&m_csThreadFieldMerge);
	::DeleteCriticalSection(&m_csThreadFrameMerge);	
	::DeleteCriticalSection(&m_csThreadSliceFill);
	::DeleteCriticalSection(&m_csThreadSystemRun);	
	::DeleteCriticalSection(&m_csSystemException);	
	::DeleteCriticalSection(&m_csUserInput);	
	::DeleteCriticalSection(&m_csITSProc);	
	::DeleteCriticalSection(&m_csThread);		
	::DeleteCriticalSection(&m_csGlobal);
}
