//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::BuildAsciiTable()
{
	char Buf[32]="";
	bool bSkip=false;
	m_AsciiTable.clear();
	::memset(Buf, 0x00, sizeof(Buf));
	for ( int i=0; i<256; i++ )
	{		
		bSkip=false;
		switch ( i )
		{
		case 0: ::strcpy(Buf, "NULL"); break;
		case 1: ::strcpy(Buf, "SOH"); break;
		case 2: ::strcpy(Buf, "STX"); break;
		case 3: ::strcpy(Buf, "ETX"); break;
		case 4: ::strcpy(Buf, "EOT"); break;
		case 5: ::strcpy(Buf, "ENQ"); break;
		case 6: ::strcpy(Buf, "ACK"); break;
		case 7: ::strcpy(Buf, "BEL"); break;
		case 8: ::strcpy(Buf, "BS"); break;
		case 9: ::strcpy(Buf, "TAB"); break;

		case 10: ::strcpy(Buf, "LF"); break;
		case 11: ::strcpy(Buf, "VT"); break;
		case 12: ::strcpy(Buf, "FF"); break;
		case 13: ::strcpy(Buf, "CR"); break;
		case 14: ::strcpy(Buf, "SO"); break;
		case 15: ::strcpy(Buf, "SI"); break;
		case 16: ::strcpy(Buf, "DLE"); break;

		case 17: ::strcpy(Buf, "DC1"); break;
		case 18: ::strcpy(Buf, "DC2"); break;
		case 19: ::strcpy(Buf, "DC3"); break;
		case 20: ::strcpy(Buf, "DC4"); break;

		case 21: ::strcpy(Buf, "NAK"); break;
		case 22: ::strcpy(Buf, "SYN"); break;
		case 23: ::strcpy(Buf, "ETB"); break;
		case 24: ::strcpy(Buf, "CAN"); break;

		case 25: ::strcpy(Buf, "EM"); break;
		case 26: ::strcpy(Buf, "SUB"); break;
		case 27: ::strcpy(Buf, "ESC"); break;
		case 28: ::strcpy(Buf, "FS"); break;
		case 29: ::strcpy(Buf, "GS"); break;
		case 30: ::strcpy(Buf, "RS"); break;
		case 31: ::strcpy(Buf, "US"); break;
			/*
		case 32: ::strcpy(Buf, " "); break;
		case 33: ::strcpy(Buf, "!"); break;
		case 34: ::strcpy(Buf, """"); break;
		case 35: ::strcpy(Buf, "#"); break;
		case 36: ::strcpy(Buf, "$"); break;
		case 37: ::strcpy(Buf, "%"); break;
		case 38: ::strcpy(Buf, "&"); break;
		case 39: ::strcpy(Buf, "''"); break;
		case 40: ::strcpy(Buf, "("); break;
		case 41: ::strcpy(Buf, ")"); break;
		case 42: ::strcpy(Buf, "*"); break;
		case 43: ::strcpy(Buf, "+"); break;
		case 44: ::strcpy(Buf, ","); break;
		case 45: ::strcpy(Buf, "-"); break;
		case 46: ::strcpy(Buf, "."); break;
		case 47: ::strcpy(Buf, "/"); break;

		case 48: ::strcpy(Buf, "0"); break;
		case 49: ::strcpy(Buf, "1"); break;
		case 50: ::strcpy(Buf, "2"); break;
		case 51: ::strcpy(Buf, "3"); break;
		case 52: ::strcpy(Buf, "4"); break;
		case 53: ::strcpy(Buf, "5"); break;
		case 54: ::strcpy(Buf, "6"); break;
		case 55: ::strcpy(Buf, "7"); break;
		case 56: ::strcpy(Buf, "8"); break;
		case 57: ::strcpy(Buf, "9"); break;

		case 58: ::strcpy(Buf, ":"); break;
		case 59: ::strcpy(Buf, ";"); break;
		case 60: ::strcpy(Buf, "<"); break;
		case 61: ::strcpy(Buf, "="); break;
		case 62: ::strcpy(Buf, ">"); break;
		case 63: ::strcpy(Buf, "?"); break;
		case 64: ::strcpy(Buf, "@"); break;

		case 65: ::strcpy(Buf, "A"); break;
		case 66: ::strcpy(Buf, "B"); break;
		case 67: ::strcpy(Buf, "C"); break;
		case 68: ::strcpy(Buf, "D"); break;
		case 69: ::strcpy(Buf, "E"); break;
		case 70: ::strcpy(Buf, "F"); break;
		case 71: ::strcpy(Buf, "G"); break;
		case 72: ::strcpy(Buf, "H"); break;
		case 73: ::strcpy(Buf, "I"); break;
		case 74: ::strcpy(Buf, "J"); break;
		case 75: ::strcpy(Buf, "K"); break;
		case 76: ::strcpy(Buf, "L"); break;
		case 77: ::strcpy(Buf, "M"); break;
		case 78: ::strcpy(Buf, "N"); break;
		case 79: ::strcpy(Buf, "O"); break;

		case 80: ::strcpy(Buf, "P"); break;
		case 81: ::strcpy(Buf, "Q"); break;
		case 82: ::strcpy(Buf, "R"); break;
		case 83: ::strcpy(Buf, "S"); break;
		case 84: ::strcpy(Buf, "T"); break;
		case 85: ::strcpy(Buf, "U"); break;
		case 86: ::strcpy(Buf, "V"); break;
		case 87: ::strcpy(Buf, "W"); break;
		case 88: ::strcpy(Buf, "X"); break;
		case 89: ::strcpy(Buf, "Y"); break;
		case 90: ::strcpy(Buf, "Z"); break;

		case 91: ::strcpy(Buf, "["); break;
		case 92: ::strcpy(Buf, "\\"); break;
		case 93: ::strcpy(Buf, "]"); break;
		case 94: ::strcpy(Buf, "^"); break;
		case 95: ::strcpy(Buf, "_"); break;
		case 96: ::strcpy(Buf, "''"); break;
		case 97: ::strcpy(Buf, "a"); break;
		case 98: ::strcpy(Buf, "b"); break;
		case 99: ::strcpy(Buf, "c"); break;

		case 100: ::strcpy(Buf, "d"); break;
		case 101: ::strcpy(Buf, "e"); break;
		case 102: ::strcpy(Buf, "f"); break;
		case 103: ::strcpy(Buf, "g"); break;
		case 104: ::strcpy(Buf, "h"); break;
		case 105: ::strcpy(Buf, "i"); break;
		case 106: ::strcpy(Buf, "j"); break;
		case 107: ::strcpy(Buf, "k"); break;
		case 108: ::strcpy(Buf, "l"); break;
		case 109: ::strcpy(Buf, "m"); break;

		case 110: ::strcpy(Buf, "n"); break;
		case 111: ::strcpy(Buf, "o"); break;
		case 112: ::strcpy(Buf, "p"); break;
		case 113: ::strcpy(Buf, "q"); break;
		case 114: ::strcpy(Buf, "r"); break;
		case 115: ::strcpy(Buf, "s"); break;
		case 116: ::strcpy(Buf, "t"); break;
		case 117: ::strcpy(Buf, "u"); break;
		case 118: ::strcpy(Buf, "v"); break;
		case 119: ::strcpy(Buf, "w"); break;

		case 120: ::strcpy(Buf, "x"); break;
		case 121: ::strcpy(Buf, "y"); break;
		case 122: ::strcpy(Buf, "z"); break;
		case 123: ::strcpy(Buf, "{"); break;
		case 124: ::strcpy(Buf, "|"); break;
		case 125: ::strcpy(Buf, "}"); break;
		case 126: ::strcpy(Buf, "~"); break;
		*/
		case 127: ::strcpy(Buf, "DEL"); break;
		default:
			bSkip = true;
			::sprintf_s(Buf, sizeof(Buf), "%c", (char)(i));		
			break;
		}
		if ( true == bSkip )
		{	continue; }
		m_AsciiTable[i] = Buf;
	}	
	return true;
}
