void CAOIDataCollect::InitialAOIColorGroupSetList()//初始化AOI抽色群組列表
{
	int          idx=0;
	int          nID=0;
	CString      str;
	unsigned int i=0, j=0;	

	idx=0;
	nID=0;
	CColorGroupSet ColorGroupSet;
	for ( j=0; j<MAX_SYSTEM_COLOR_GROUP_COUNT; j++ )
	{	
		str.Format(_T("Set-Name [%d]"), j+1);
		ColorGroupSet.SetColorGroupSetIndex(j);
		ColorGroupSet.SetColorGroupSetName(str);
		m_SystemColorGroupSetList.push_back(ColorGroupSet); 
	}	
	return;
}
