//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadSystemParamFileFromProjectParam(LPCTSTR ProjectFolder)//載入專案的系統參數
{
	if ( LoadSystemParamFileFromProjectParamFn(ProjectFolder) == false )
	{
		SetSystemExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadSystemParamFileFromProjectParamFn(LPCTSTR ProjectFolder)//載入專案的系統參數
{
	if ( NULL == ProjectFolder ) { return false; }

	bool    IsOK=true;
	CString str;	
	CString FileName;
	CString FileNameSrc;
	CString FileNameDst;	
	CString AOIDirectory = GetAOIDirectory();	
	CString SystemFolder = AOIDataDefine.GetProjectSystemFolderName(ProjectFolder);			
#ifdef OFFLINE_VERSION
	if ( JetAPI::IsFolderExist(ProjectFolder)==false )
	{
		m_ErrorString.Format(_T("Error, Folder does not exist [%s]"), ProjectFolder);
		return false;
	}
	if ( JetAPI::IsFolderExist(SystemFolder)==false )
	{
		m_ErrorString.Format(_T("Error, Folder does not exist [%s]"), SystemFolder);
		return false;
	}
	if ( LoadSystemParamFileFromOther(SystemFolder) == false )
	{	return false; }	
	UpdateSystemParameter();
	ApplyCalibrationParameter();
	//ApplySystemParameterToAllProject	
#endif//OFFLINE_VERSION	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ApplyCalibrationParameter()//套用校正參數
{
	CAMERA_ID   CameraID=PRIMARY_CAMERA_ID;
	std::vector<CAMERA_ID> CameraIDList;
	const double FovSizeW = GetFovSizeRealW();
	const double FovSizeH = GetFovSizeRealH();
	BuildCameraIDList(CameraIDList);
	const size_t CameraIDCount=CameraIDList.size();	
	for ( size_t i=0; i<CameraIDCount; i++ )
	{
		CameraID = CameraIDList[i];		
		m_CameraImageW[CameraID] = CameraCtrl.GetCameraImageSizeW(CameraID);
		m_CameraImageH[CameraID] = CameraCtrl.GetCameraImageSizeH(CameraID);	
		m_CameraImageMode[CameraID] = CameraCtrl.GetCameraImageMode(CameraID);
		m_CameraResolutionX[CameraID] = FovSizeW/m_CameraImageW[CameraID];//最多八個相機的解析度-X
		m_CameraResolutionY[CameraID] = FovSizeH/m_CameraImageH[CameraID];//最多八個相機的解析度-Y
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveAllCalibrationParameter()//儲存所有校正參數
{
	bool IsOK = true;
	CString ErrorString, ErrorMSG, ErrorTemp;
	if ( CheckIsLockSystemParameter() == true ) 
	{	return false; }
	if ( MotionCtrlPtr->SaveMotionParamInternal() == false )
	{
		IsOK = false;
		ErrorString = MotionCtrlPtr->GetErrorString();
		if ( ErrorMSG.GetLength() == 0 ) 
		{	ErrorMSG = ErrorString; }
		else
		{
			ErrorTemp = ErrorMSG;
			ErrorMSG.Format(_T("%s\n%s"), ErrorTemp, ErrorString);
		}
	}
	if ( MotionCtrlPtr->SaveMotionParameter() == false )
	{	
		IsOK = false;
		ErrorString = MotionCtrlPtr->GetErrorString();
		if ( ErrorMSG.GetLength() == 0 ) 
		{	ErrorMSG = ErrorString; }
		else
		{
			ErrorTemp = ErrorMSG;
			ErrorMSG.Format(_T("%s\n%s"), ErrorTemp, ErrorString);
		}
	}
	if ( Light3DCtrl.SaveAllLight3DCastParameter() == false )
	{
		IsOK = false;
		ErrorString = Light3DCtrl.GetErrorString();
		if ( ErrorMSG.GetLength() == 0 ) 
		{	ErrorMSG = ErrorString; }
		else
		{
			ErrorTemp = ErrorMSG;
			ErrorMSG.Format(_T("%s\n%s"), ErrorTemp, ErrorString);
		}
	}
	if ( SaveSystemSliceParamINI() == false )
	{
		IsOK = false;
		ErrorString = GetErrorString();
		if ( ErrorMSG.GetLength() == 0 ) 
		{	ErrorMSG = ErrorString; }
		else
		{
			ErrorTemp = ErrorMSG;
			ErrorMSG.Format(_T("%s\n%s"), ErrorTemp, ErrorString);
		}
	}
	if ( SaveSystemParameter() == false )
	{
		IsOK = false;
		ErrorString = GetErrorString();
		if ( ErrorMSG.GetLength() == 0 ) 
		{	ErrorMSG = ErrorString; }
		else
		{
			ErrorTemp = ErrorMSG;
			ErrorMSG.Format(_T("%s\n%s"), ErrorTemp, ErrorString);
		}
	}
	if ( SaveCalibrationParameter() == false )
	{
		IsOK = false;
		ErrorString = GetErrorString();
		if ( ErrorMSG.GetLength() == 0 ) 
		{	ErrorMSG = ErrorString; }
		else
		{
			ErrorTemp = ErrorMSG;
			ErrorMSG.Format(_T("%s\n%s"), ErrorTemp, ErrorString);
		}
	}

	if ( true == IsOK )
	{ ApplyCalibrationParameter(); }
	else
	{	SetErrorString(ErrorMSG);	}
	return IsOK;
}
