	{	BasePlaneParam.CalcBasePlaneMode = (CALC_BASE_PLANE_MODE)::_ttoi(String); }

	//基準面自動選區最大差距
	KeyName = _T("Base Plane Auto Region Max Gap");
	Default.Format(_T("%.2f"), BasePlaneParam.BaePlaneAutRgnMaxGap);
