	Default.Format(_T("%.2f"), BasePlaneParam.PlaneRatioLSL);
	if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
	{	BasePlaneParam.PlaneRatioLSL = ::_ttof(String); }

	//滿足平面的比例上限
