	Default.Format(_T("%s"), BasePlaneParam.BasePlaneInfoText);
	if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
	{	BasePlaneParam.BasePlaneInfoText = (String); }

	//使用本體外圍
	KeyName = _T("Base Plane Body Outside Enabled");
	Default.Format(_T("%d"), BasePlaneParam.BodyOutsideMode);
	if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
	{	BasePlaneParam.BodyOutsideMode = (BASE_PLANE_BODY_OUTSIDE_MODE)(::_ttoi(String)); }

	//本體外圍寬度-um
	KeyName = _T("Base Plane Body Outside Size X");
