//-------------------------------------------------------------------------------------//
CString CAOIDataCollect::GetSystemNoiseFilterParamFilename()
{
	CString str;
	CString SysFolder = GetAOIDirectory();
	CString ShortName = SPACE_NOISE_FILTER_INI_FILE;
	str.Format(_T("%s\\%s"), SysFolder, ShortName);
	return str;
}
//-------------------------------------------------------------------------------------//
CString CAOIDataCollect::GetSystemNoiseFilterParamSection(int index)
{
	CString str;
	str.Format(_T("%s-%d"), _T("Space Noise Filter Param"), index+1);
	return str;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadSystemNoiseFilterParam()
{
	int   i=0;
	CString FileName = GetSystemNoiseFilterParamFilename();
	const int MaxCount = MAX_SYSTEM_NOISE_FILTER_PARAM_COUNT;
	for ( i=0; i<MaxCount; i++ )
	{	LoadSystemNoiseFilterParamFile(FileName, i, m_SystemNoiseFilterParam[i]);	}
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::DefaultSystemNoiseFilterParam()
{
	int   i=0;
	const int MaxCount = MAX_SYSTEM_NOISE_FILTER_PARAM_COUNT;
	for ( i=0; i<MaxCount; i++ )
	{	
		GetSpaceNoiseFilterParam(m_SystemNoiseFilterParam[i]);	
		m_SystemNoiseFilterParam[i].DataFilterIndex = i;
		m_SystemNoiseFilterParam[i].DataFilterInfoText.Format(_T("Filter_%d"), i+1);
	}
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveSystemNoiseFilterParam()
{
	int   i=0;
	CString FileName = GetSystemNoiseFilterParamFilename();
	const int MaxCount = MAX_SYSTEM_NOISE_FILTER_PARAM_COUNT;
	for ( i=0; i<MaxCount; i++ )
	{	SaveSystemNoiseFilterParamFile(FileName, i, m_SystemNoiseFilterParam[i]);	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::UpdateSystemNoiseFilterParamToProject()//更新系統空間雜訊過濾至專案
{
	size_t         i=0;
	CAOIProject   *ProjectPtr = NULL;
	std::vector<TNoiseFilterParam> FilterList;
	const size_t ProjectCount = GetProjectPtrCount();

	CloneSystemNoiseFilterParamList(FilterList);
	for ( i=0; i<ProjectCount; i++ )
	{
		ProjectPtr = GetProjectPtr(i, false);
		if ( NULL == ProjectPtr ) { continue; }
		ProjectPtr->UpdateProjectSpaceNoiseFilterParamList(FilterList);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::TurnOffNoiseFilterParam(TNoiseFilterParam &Param)//關閉空間雜訊過濾器
{
	Param.DataVoidExpandEnabled = false;//無效點外擴啟用
	Param.DataFirstFilterMode = DATA_NF_DISABLE;//首次濾波器啟用
	Param.DataOverLowFTMode = DATA_NF_DISABLE;//過低濾除模式
	Param.DataHeightFTMode = DATA_NF_DISABLE;//高度異常濾除模式
	Param.DataVoidReContructed = false;//雜訊資料重建
	Param.DataFinalFilterMode = DATA_NF_DISABLE;//最終濾波啟用
	Param.DataFinalFilterMode2 = DATA_NF_DISABLE;//最終濾波啟用-2
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CloneSystemNoiseFilterParamList(std::vector<TNoiseFilterParam> &List)//複製空間雜訊過濾表
{
	int   i=0;
	const int MaxCount = MAX_SYSTEM_NOISE_FILTER_PARAM_COUNT;
	for ( i=0; i<MaxCount; i++ )
	{	List.push_back(m_SystemNoiseFilterParam[i]);	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::GetSystemNoiseFilterParam(int index, TNoiseFilterParam &NoiseFilterParam) const
{
	const int MaxCount = MAX_SYSTEM_NOISE_FILTER_PARAM_COUNT;
	if ( index<0 || index>=MaxCount ) { return false; }
	NoiseFilterParam = m_SystemNoiseFilterParam[index];
	NoiseFilterParam.DataFilterIndex = index;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SetSystemNoiseFilterParam(int index, const TNoiseFilterParam &NoiseFilterParam)
{
	const int MaxCount = MAX_SYSTEM_NOISE_FILTER_PARAM_COUNT;
	if ( index<0 || index>=MaxCount ) { return false; }
	m_SystemNoiseFilterParam[index] = NoiseFilterParam;
	m_SystemNoiseFilterParam[index].DataFilterIndex = index;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadSystemNoiseFilterParamFile(LPCTSTR filename, int index, TNoiseFilterParam &NoiseFilterParam)
{
	if ( LoadSystemNoiseFilterParamFileFn(filename, index, NoiseFilterParam) == false )
	{
		SetSystemExceptionCode_FileRead();
		return false;
	}
	return true;
}
