//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveSystemColorGroupSetFile()
{
	if ( SaveSystemColorGroupSetFileFn() == false )
	{
		SetSystemExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveSystemColorGroupSetFileFn()
{
	CString    Folder;
	CString    FileName;		
	CAOIFileIO FileIO;	
	Folder = GetAOIDirectory();
	FileName.Format(_T("%s\\%s"), Folder, _T("SystemColorGroupSetList.dat"));
	//::_tcstod(String, NULL);	
	
	if ( FileIO.OpenSaveFile(FileName) == false )
	{
		m_ErrorString = FileIO.GetErrorString();
		return false;
	}	
	if ( WriteSystemColorGroupSetList(FileIO) == false )
	{
		FileIO.CloseFile();
		m_ErrorString = FileIO.GetErrorString();
		return false;
	}		
	FileIO.CloseFile();
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadSystemColorGroupSetFile()
{
	if ( LoadSystemColorGroupSetFileFn() == false )
	{
		SetSystemExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadSystemColorGroupSetFileFn()
{
	CString    Folder;
	CString    FileName;		
	CAOIFileIO FileIO;	
	Folder = GetAOIDirectory();
	FileName.Format(_T("%s\\%s"), Folder, _T("SystemColorGroupSetList.dat"));
	//::_tcstod(String, NULL);	
	
	if ( FileIO.OpenLoadFile(FileName) == false )
	{
		m_ErrorString = FileIO.GetErrorString();
		return false;
	}	
	if ( ReadSystemColorGroupSetList(FileIO) == false )
	{
		FileIO.CloseFile();
		m_ErrorString = FileIO.GetErrorString();
		return false;
	}
	FileIO.CloseFile();	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ReadSystemColorGroupSetList(CAOIFileIO &FileIO)
{
#ifdef _DEBUG
	if ( FileIO.CheckFileMode() == FALSE ) { return false; }
	if ( FileIO.CheckFileOpened() == FALSE ) { return false; }
#endif//_DEBUG
	
	int            i=0, j=0;
	int            index=0;
	int            nValue=0;
	//----------------------------------------------------------------------------------------//
	size_t         ColorGroupSetIndex=0;
	//----------------------------------------------------------------------------------------//
	CColorGroupSet    ColorGroupSet;	
	std::vector<CColorGroupSet> ColorGroupSetList;
	FileIO.SetFnName(_T("CAOIDataCollect::ReadSystemColorGroupSetList"));
	//----------------------------------------------------------------------------------------//	
	while ( FileIO.CheckFileEnd()==false )
	{ 	
		if ( FileIO.LoadChunk(index) == false )		
		{	continue; }
		
		switch ( index )
		{
		case FILE_IO_START://系統參數區間-起點			
			break;		
		case FILE_IO_SYSTEM_COLOR_GROUP_SET_NODE:
			nValue = FileIO.GetData_INT();
			if ( ColorGroupSet.ReadColorGroupSetFile(FileIO) == false )
			{	return false; }
			
			ColorGroupSetIndex = ColorGroupSetList.size();
			ColorGroupSet.SetColorGroupSetIndex(ColorGroupSetIndex);			
			ColorGroupSetList.push_back(ColorGroupSet);			
			break;
		case FILE_IO_END:			
			ColorGroupSetIndex = ColorGroupSetList.size();
			if ( MAX_SYSTEM_COLOR_GROUP_COUNT == ColorGroupSetIndex )
			{	m_SystemColorGroupSetList = ColorGroupSetList;	}			
			break;
		}
	};
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::WriteSystemColorGroupSetList(CAOIFileIO &FileIO)
{
#ifdef _DEBUG
	if ( FileIO.CheckFileMode() == false ) { return false; }
	if ( FileIO.CheckFileOpened() == false ) { return false; }
#endif//_DEBUG

	size_t     i=0, j=0, k=0;
	CColorGroupSet *GroupSetPtr=NULL;
	const size_t ColorGroupSetCount = GetSystemColorGroupSetCount();
	FileIO.SetFnName(_T("CAOIDataCollect::WriteSystemColorGroupSetList"));
	if ( FileIO.SaveChunk_INT(FILE_IO_START, 0) == false ) { return false; }

	for ( j=0; j<ColorGroupSetCount; j++ )
	{
		GroupSetPtr = GetSystemColorGroupSetPtr(j, true);
		if ( NULL == GroupSetPtr ) { continue; }
		if ( FileIO.SaveChunk_INT(FILE_IO_SYSTEM_COLOR_GROUP_SET_NODE, j) == false ) { return false; }		              
		if ( GroupSetPtr->WriteColorGroupSetFile(FileIO) == false )	{	return false;	}				
	}
	if ( FileIO.SaveChunk_INT(FILE_IO_END, 0) == false ) { return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
size_t CAOIDataCollect::GetSystemColorGroupSetCount()
{
	return m_SystemColorGroupSetList.size();
}
//-------------------------------------------------------------------------------------//
CColorGroupSet* CAOIDataCollect::GetSystemColorGroupSetPtr(size_t index, bool bCheck)
{
	if ( true == bCheck )
	{
		const size_t Count = GetSystemColorGroupSetCount();
		if ( index >= Count ) 
		{	return NULL; }
	}
	return &m_SystemColorGroupSetList[index];
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CloneSystemColorGroupSetList(size_t index, std::vector<CColorGroup> &ColorGroupList)
{
	CColorGroupSet* ColorGroupSetPtr = GetSystemColorGroupSetPtr(index, true);
	if ( NULL == ColorGroupSetPtr ) { return false; }	
	ColorGroupSetPtr->CloneColorGroupSetColorGroupList(ColorGroupList);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SetSystemColorGroupSetList(size_t index, const std::vector<CColorGroup> &ColorGroupList)
{
	CColorGroupSet* ColorGroupSetPtr = GetSystemColorGroupSetPtr(index, true);
	if ( NULL == ColorGroupSetPtr ) { return false; }
	ColorGroupSetPtr->SetColorGroupSetColorGroupList(ColorGroupList);
	return true;
}
//-------------------------------------------------------------------------------------//
CString CAOIDataCollect::GetSystemBackupFolder() const
{
	CString str;
	str.Format(_T("%s\\%s"), GetAOIDirectory(), _T("SystemBackup"));
	return str;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::BackupAllSystemFilesFirst()//備份系統檔案-首次
{
	CString SystemBackupFolder=GetSystemBackupFolder();
	if ( JetAPI::IsFolderExist(SystemBackupFolder) == true )//首次沒有建立備份資料夾, 就自動備份
	{	return true; }
	if ( BackupAllSystemIniFiles() == false )
	{	return false; }
	if (BackupAllSystemBinFiles() == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::BackupAllSystemIniFiles()//備份系統INI檔案
{
#ifndef OFFLINE_VERSION
	const CString SrcFolder = GetAOIDirectory();
	const CString DstFolder = GetSystemBackupFolder();
	::CreateDirectory(DstFolder, NULL);
	if ( JetAPI::CopyFiles(SrcFolder, DstFolder, _T("INI")) == false )
	{
		m_ErrorString.Format(_T("Error, Copy System INI Files Fault [%s] -> [%s]"), SrcFolder, DstFolder);
		SetSystemExceptionCode_FileWrite();
		return false;
	}
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::BackupAllSystemBinFiles()//備份系統Bin檔案
{	
#ifndef OFFLINE_VERSION
#ifdef PHASE_CTRL_DISABLE	
	CString SrcFolder = GetAOIDirectory();	
	CString DstFolder = GetSystemBackupFolder();	
	DstFolder.Format(_T("%s\\%s"), GetAOITempDirectory(), _T("SystemBackupTmp"));	
	::CreateDirectory(DstFolder, NULL);
	if ( JetAPI::CopyFiles(SrcFolder, DstFolder, _T("BIN")) == false )
	{
		m_ErrorString.Format(_T("Error, Copy System BIN Files Fault [%s] -> [%s]"), SrcFolder, DstFolder);
		SetSystemExceptionCode_FileWrite();
		return false;
	}
#else	
	CString TmpFolder;
	CString SrcFolder = GetAOIDirectory();	
	TmpFolder.Format(_T("%s\\%s"), GetAOITempDirectory(), _T("SystemBackupTmp"));	
	::CreateDirectory(TmpFolder, NULL);
	if ( JetAPI::CopyFiles(SrcFolder, TmpFolder, _T("BIN")) == false )
	{
		m_ErrorString.Format(_T("Error, Copy System BIN Files Fault [%s] -> [%s]"), SrcFolder, TmpFolder);
		SetSystemExceptionCode_FileWrite();
		return false;
	}
	CheckDlpBinFiles(TmpFolder);
	CString DstFolder = GetSystemBackupFolder();	
	::CreateDirectory(DstFolder, NULL);
	if ( JetAPI::CopyFiles(TmpFolder, DstFolder, _T("BIN")) == false )
	{
		m_ErrorString.Format(_T("Error, Copy System BIN Files Fault [%s] -> [%s]"), TmpFolder, DstFolder);
		SetSystemExceptionCode_FileWrite();
		return false;
	}
#endif//PHASE_CTRL_DISABLE
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckDlpBinFiles(LPCTSTR DstFolder)//確認DLP-BIN檔案
{
#ifndef PHASE_CTRL_DISABLE
	int DlpLedColor=0;	
	CString Error;
	CString Filename;
	CString BinFilename;
	const bool bShowMessage=false;
	const bool bCheckAllLedColor=true;	
	CAMERA_ID CameraID = PRIMARY_CAMERA_ID;	
	std::vector<int> DlpLedColorList;
	std::vector<int> DlpLedColorListAll;
	std::vector<LIGHT_3D_CAST_ID> CastIDList;	
	IMAGE_SIZE ImageW = GetCameraImageW(CameraID);
	IMAGE_SIZE ImageH = GetCameraImageH(CameraID);
	IMAGE_SIZE ImageStep = JetAPI::GetBMPImagePixelsPerLine(ImageW, 4);
	Light3DCtrl.GetLight3DCastIDList(CastIDList);
	DlpLedColorListAll.push_back(DLP_LED_COLOR_RED);
	DlpLedColorListAll.push_back(DLP_LED_COLOR_GREEN);
	DlpLedColorListAll.push_back(DLP_LED_COLOR_BLUE);
	DlpLedColorListAll.push_back(DLP_LED_COLOR_WHITE);
	for ( size_t i=0; i<CastIDList.size(); i++ )
	{
		const LIGHT_3D_CAST_ID CastID = CastIDList[i];
		LIGHT_3D_CLS_PTR CastPtr = Light3DCtrl.GetLight3DCastPtr(CastID);
		if ( NULL == CastPtr ) { continue; }	
		if ( true == bCheckAllLedColor )
		{	DlpLedColorList = DlpLedColorListAll;	}
		else
		{	
			DlpLedColorList.clear();
			DlpLedColor = DLP_LED_COLOR_NO;						
			if ( CastPtr->CheckPhaseZeroRed() == true )
			{	DlpLedColor = DLP_LED_COLOR_RED;	}
			if ( CastPtr->CheckPhaseZeroGrn() == true )
			{	DlpLedColor = DLP_LED_COLOR_GREEN;	}
			if ( CastPtr->CheckPhaseZeroBlu() == true )
			{	DlpLedColor = DLP_LED_COLOR_BLUE;	}
			if ( CastPtr->CheckPhaseZeroWhite() == true )
			{	DlpLedColor = DLP_LED_COLOR_WHITE;	}
			if ( CastPtr->CheckPhaseZeroDebug() == true )
			{	DlpLedColor = DLP_LED_COLOR_DEBUG;	}			
			if ( DLP_LED_COLOR_NO != DlpLedColor )
			{	DlpLedColorList.push_back(DlpLedColor);	}
		}
		for ( size_t j=0; j<DlpLedColorList.size(); j++ )
		{
			DlpLedColor = DlpLedColorList[j];			
			Filename = CastPtr->GetDLPPhaseZeroBinFilename(DlpLedColor);					
			if ( Filename.GetLength() != 0 )
			{
				JetAPI::ExtractFileNameNoPath(Filename, BinFilename);
				Filename.Format(_T("%s\\%s"), DstFolder, BinFilename);				
				if ( CastPtr->CheckDLPPhaseZeroFile(Filename, ImageW, ImageH, ImageStep) == false )
				{
					if ( true == bShowMessage )
					{
						Error = CastPtr->GetErrorString();
						JetAPI::ShowMessageBox(Error);
					}
					::DeleteFile(Filename);
				}
			}
		}

		if ( true == bCheckAllLedColor )
		{	DlpLedColorList = DlpLedColorListAll;	}
		else
		{	
			DlpLedColorList.clear();
			DlpLedColor = DLP_LED_COLOR_NO;
			if ( CastPtr->CheckPhaseFactorRed() == true )
			{	DlpLedColor = DLP_LED_COLOR_RED;	}
			if ( CastPtr->CheckPhaseFactorGrn() == true )
			{	DlpLedColor = DLP_LED_COLOR_GREEN;	}
			if ( CastPtr->CheckPhaseFactorBlu() == true )
			{	DlpLedColor = DLP_LED_COLOR_BLUE;	}
			if ( CastPtr->CheckPhaseFactorWhite() == true )
			{	DlpLedColor = DLP_LED_COLOR_WHITE;	}
			if ( CastPtr->CheckPhaseFactorDebug() == true )
			{	DlpLedColor = DLP_LED_COLOR_DEBUG;	}			
			if ( DLP_LED_COLOR_NO != DlpLedColor )
			{	DlpLedColorList.push_back(DlpLedColor);	}
		}
		for ( size_t j=0; j<DlpLedColorList.size(); j++ )
		{
			DlpLedColor = DlpLedColorList[j];	
			Filename = CastPtr->GetDLPPhaseFactorBinFilename(DlpLedColor);		
			if ( Filename.GetLength() != 0 )
			{
				JetAPI::ExtractFileNameNoPath(Filename, BinFilename);
				Filename.Format(_T("%s\\%s"), DstFolder, BinFilename);
				if ( CastPtr->CheckDLPPhaseFactorFile(Filename, ImageW, ImageH, ImageStep) == false )
				{
					if ( true == bShowMessage )
					{
						Error = CastPtr->GetErrorString();
						JetAPI::ShowMessageBox(Error);
					}
					::DeleteFile(Filename);
				}				
			}
		}		
	}	
#endif//PHASE_CTRL_DISABLE
	return true;
}
//-------------------------------------------------------------------------------------//
int CAOIDataCollect::GetMessageReturn() const//訊息結果
{
	return m_MessageReturn;
}
//-------------------------------------------------------------------------------------//
void CAOIDataCollect::SetMessageReturn(int val)//訊息結果
{
	m_MessageReturn = val;
}
//-------------------------------------------------------------------------------------//	
CString CAOIDataCollect::GetMessageInfo(UINT &nType, UINT &nIDHelp) const//設定訊息
{
	nType = m_MessageType;
	nIDHelp = m_MessageIDHelp;
	return m_MessageString;	
}
//----------------------------------------------------------------------------//
void CAOIDataCollect::SetMessageInfo(LPCTSTR Str, UINT nType, UINT nIDHelp)//設定訊息	
{
	m_MessageType = nType;
	m_MessageIDHelp = nIDHelp;
	m_MessageString = Str;	
	SetMessageReturn(IDYES);
}
//----------------------------------------------------------------------------//
int CAOIDataCollect::ShowMessageSync(LPCTSTR lpszText, UINT nType, UINT nIDHelp)
{
	SetMessageInfo(lpszText, nType, nIDHelp);
	if ( SendMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_EXEC_SHOW_MESSAGE_WND, 0) == false )
	{	return IDYES; }
	return GetMessageReturn();
}
//-------------------------------------------------------------------------------------//
int CAOIDataCollect::ShowMessage(int ErrorCode,MSG_MB_TYPE BoxType,MSG_MB_ICON_TYPE BoxIcon,MSG_MB_BTN BoxBtn,LPCTSTR Content,bool bSaveFile, bool bShowMSG)
{
	CString Name;
	CString Section;
	CString KeyName,KeyString;
	char ReturnString[250]="";
	DWORD Number=0;
	
	const int nBoxType = BoxType;
	const int nBoxIcon = BoxIcon;
	const int nBoxBtn = BoxBtn;
	UINT BoxParameter=BoxType;
	int Result=0;

	BoxParameter=nBoxType;
	BoxParameter = BoxParameter|nBoxIcon;
	BoxParameter = BoxParameter|nBoxBtn;

	if( NULL!=Content )//if no content, get the Alarm.ini index data
	{	
		if ( ErrorCode != 0 )
		{	KeyString.Format(_T("%s(Code:%d))"),Content,ErrorCode);	}
		else
		{	KeyString.Format(_T("%s"),Content);		}
	}
	if ( true == bSaveFile )
	{	SaveErrMessage(KeyString);	}
	//m_ErrorString = KeyString;
	SetErrorString_Locked(KeyString);
	if ( true == bShowMSG ) 
	{
		LPCTSTR TitleName = ::AfxGetAppName();
		//Result = this->JETMessageBox(NULL, KeyString, TitleName, BoxParameter|MB_TASKMODAL|MB_TOPMOST);	//LockScreen - Vic 20140804
		AddWaitUserInputCount();
		::MessageBox(NULL, KeyString, TitleName, BoxParameter|MB_TASKMODAL|MB_TOPMOST);	
		ReleaseWaitUserInputCount();
		if ( CheckWaitUserInputCountZero() )
		{	RegistUserLastInputTickCount();	}	
	}   
	// record error message	
	return Result;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveErrMessage(LPCTSTR Content)
{
	if ( SaveErrMessageFn(Content) == false )
	{
		SetSystemExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveErrMessageFn(LPCTSTR Content)
{
	FILE *fp;	   
	CString tp;
	CString  Name;
	TCHAR TMode[32] = _T("");	
	CString tYear, tMon, tDay, tHour, tMin, tSec;
	CString KeyString = Content;
	CString MainFolder = GetAOIDirectory();	
	JetAPI::GetTime(tp,CTime::GetCurrentTime());
	tYear = tp.Mid(0, 4);
	tMon  = tp.Mid(4, 2);
	tDay  = tp.Mid(6, 2);
	tHour = tp.Mid(8, 2);
	tMin  = tp.Mid(10, 2);
	tSec  = tp.Mid(12, 2);
	_tcscpy(TMode, _T("a+"));
	JetAPI::ModifyOpenFileMode_Write(TMode);
	Name.Format(_T("%s\\message_%s%s.err"), MainFolder, (LPCTSTR)tYear, (LPCTSTR)tMon);
	if( (fp=_tfopen(Name,TMode))!=NULL)
	{
	#ifndef OFFLINE_VERSION
		_ftprintf(fp,_T("%s/%s/%s,%s:%s:%s  Online::%s\n"),(LPCTSTR)tYear, (LPCTSTR)tMon, (LPCTSTR)tDay
				, (LPCTSTR)tHour, (LPCTSTR)tMin, (LPCTSTR)tSec,(LPCTSTR)KeyString);
	#else
		_ftprintf(fp,_T("%s/%s/%s,%s:%s:%s  Offline::%s\n"),(LPCTSTR)tYear, (LPCTSTR)tMon, (LPCTSTR)tDay
				, (LPCTSTR)tHour, (LPCTSTR)tMin, (LPCTSTR)tSec, (LPCTSTR)KeyString);
	#endif
		fclose(fp);
	}
	if ( FN_DISABLE != m_SystemParameter.m_SendDebugViewString )
	{	JetAPI::SendDebugString(KeyString); }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveLogMessage(LPCTSTR pMessage)
{
#ifdef _SEND_DEBUG_STRING
	if ( FN_DISABLE != m_SystemParameter.m_SendDebugViewString )
	{
		CString DebugString;
		CString Context = pMessage;
		DebugString.Format(_T("Log::%s"), Context);
		JetAPI::SendDebugString(DebugString);
	}
#endif//_SEND_DEBUG_STRING

	if ( -1 != m_LogIdx_CustomerLogFile )
	{	LogManager.AddLogMessage(m_LogIdx_CustomerLogFile, pMessage);	}

	if ( LogManager.AddLogMessage(m_LogIdx_LogFile, pMessage) == true )
	{	return true; }

	m_ErrorString = _T("CAOIDataCollect::SaveLogMessage Fault");
	SetSystemExceptionCode_FileWrite();
	return false;

	this->LockGlobal();	
	CString tp;
	CString Result;
	CString filename;	
	TCHAR TMode[32] = _T("");
	_tcscpy(TMode, _T("a+"));
	JetAPI::ModifyOpenFileMode_Write(TMode);
	JetAPI::GetTime(tp,CTime::GetCurrentTime());
	filename.Format(_T("%s\\%s_%s_%s_%s.txt"), GetAOILogDirectory(), _T("Log"),tp.Mid(0,4), tp.Mid(4,2), tp.Mid(6,2));
	FILE *pfile = ::_tfopen(filename, TMode);
	if ( pfile == NULL ) 
	{
		this->m_ErrorString.Format(_T("Error, No Open Log Message File (%s)"), filename);
		JetAPI::ShowMessageBox(this->m_ErrorString);		
		this->UnlockGlobal();
		return false;
	}	
	
	/*
	int i = 0;
	int IDLen = (int)(::strlen(m_User.sID));
	char NewID[TEXT_SIZE] = "";
	::strcpy(NewID, m_User.sID);	
	if ( IDLen < 16 )
	{
		for ( i=IDLen; i<16; i++ )
		{	NewID[i] = '-';	}
		NewID[i] = '\0';
	}
	*/
	CString NewID = AOI3D_VENDOR;//_T("JET");	
	CString HostIP = m_SystemParameter.m_IPHostComputer;
	
#ifdef OFFLINE_VERSION	
	Result.Format(_T("%s/%s/%s,%s:%s:%s_Offline[%s]_%s %s"),tp.Mid(0,4),tp.Mid(4,2),tp.Mid(6,2)
			,tp.Mid(8,2),tp.Mid(10,2),tp.Mid(12,2), HostIP, NewID, pMessage);		
#else
	Result.Format(_T("%s/%s/%s,%s:%s:%s_Inline[%s]_%s- %s"),tp.Mid(0,4),tp.Mid(4,2),tp.Mid(6,2)
			,tp.Mid(8,2),tp.Mid(10,2),tp.Mid(12,2), HostIP, NewID, pMessage);		
#endif
	
	_ftprintf(pfile,_T("%s\n"), (LPCTSTR)Result);

	::fclose(pfile);
	pfile = NULL;
	this->UnlockGlobal();
	return true;
}
