//----------------------------------------------------------------------------//
bool CAOIDataCollect::DeleteCurrentProcess()//刪除現在狀態檔案
{
	BackupCurrentProcess();
	LogManager.DeleteLogFile(m_LogIdx_CurrentProcess);
	return true;

	CString filename;		
	filename.Format(_T("%s\\%s.txt"), GetAOILogDirectory(), CURRENT_PROCESS_FILENAME);
	::DeleteFile(filename);
	return true;
}
//----------------------------------------------------------------------------//
bool CAOIDataCollect::BackupCurrentProcess()//備份現在狀態檔案
{
#ifndef OFFLINE_VERSION
	if ( FN_DISABLE == GetSystemParameter().m_SaveCurrentProcessMessage ) { return true; }
	if ( FN_DISABLE == GetSystemParameter().m_BackupCurrentProcessMessage ) { return true; }

	CString filename;	
	CString filename2;		
	CString FileFolder;		
	CString MainFilename = CURRENT_PROCESS_FILENAME;
	const unsigned int LogIdx = m_LogIdx_CurrentProcess;
	LogManager.FlushLogNodeMsgToFile(LogIdx);
	FileFolder.Format(_T("%s\\%s"), GetAOILogDirectory(), _T("CurrentProcess"));
	::CreateDirectory(FileFolder, NULL);
	//CLogManager::LockLogManager();	
	if ( LogManager.GetLogFilePathName(LogIdx, filename) == false )
	{	filename.Format(_T("%s\\%s.txt"), GetAOILogDirectory(), MainFilename);	}
	filename2.Format(_T("%s\\%s.txt"), FileFolder, MainFilename);
	::CopyFile(filename, filename2, FALSE);	
	//CLogManager::UnlockLogManager();

	TCHAR TMode[32] = _T("");
	_tcscpy(TMode, _T("r"));
	JetAPI::ModifyOpenFileMode_Read(TMode);	
	FILE *pfile = ::_tfopen(filename2, TMode);
	if ( NULL == pfile )
	{	return true; }

	const size_t TxtSize = 256;
	TCHAR TextLine[TxtSize] = _T("");
	if ( NULL == ::_fgetts(TextLine, TxtSize, pfile) )
	{		
		::fclose(pfile); pfile = NULL;
		::Sleep(0);
		::DeleteFile(filename2);
		return true;
	}
	::fclose(pfile); pfile = NULL;	
	//2025/03/13,17:07:08.421_Online Camera[1]::LoadCameraINIFile
	const size_t Len = _tcslen(TextLine);
	if ( Len < 20 )
	{	
		::DeleteFile(filename2);	
		return true;
	}
	size_t idx=0;	
	TCHAR sDay[TxtSize];
	TCHAR sDayTime[TxtSize];
	::memset(sDay, 0x00, sizeof(sDay));
	::memset(sDayTime, 0x00, sizeof(sDayTime));
	for ( size_t i=0; i<Len; i++ )
	{
		if ( 0 == _istdigit(TextLine[i]) )
		{	continue; }
		sDay[idx] = TextLine[i];
		sDayTime[idx] = TextLine[i];
		idx ++;
		//YYYYMMDDhhmmss
		if ( idx >= 14 )
		{	break; }
	}
	if ( idx < 14 )
	{	
		::DeleteFile(filename2);	
		return true;	
	}
	CString filename3;	
	CString FileFolder2;
	sDay[8] = _T('\0');
	sDayTime[idx] = _T('\0');

	FileFolder2.Format(_T("%s\\%s"), FileFolder, sDay);
	::CreateDirectory(FileFolder2, NULL);
	::Sleep(0);
	filename3.Format(_T("%s\\%s_%s.txt"), FileFolder2, MainFilename, sDayTime);
	::CopyFile(filename2, filename3, FALSE);	
	::Sleep(0);
	::DeleteFile(filename2);
#endif//OFFLINE_VERSION
	return true;
}
//----------------------------------------------------------------------------//
bool CAOIDataCollect::BackupCurrentProcess_Error()//備份現在狀態檔案
{
	CString Time;
	CString filename;	
	CString filename2;	
	CString FileFolder;	
	CString MainFilename = CURRENT_PROCESS_FILENAME;
	JetAPI::GetTime(Time,CTime::GetCurrentTime());
	FileFolder.Format(_T("%s\\%s"), GetAOILogDirectory(), _T("Error"));
	::CreateDirectory(FileFolder, NULL);

	LogManager.GetLogFilePathName(m_LogIdx_CurrentProcess, filename);
	filename2.Format(_T("%s\\%s_%s.txt"), FileFolder, MainFilename, Time);
	::CopyFile(filename, filename2, FALSE);
	return true;
	
	filename.Format(_T("%s\\%s.txt"), GetAOILogDirectory(), MainFilename);
	filename2.Format(_T("%s\\%s_%s.txt"), FileFolder, MainFilename, Time);
	::CopyFile(filename, filename2, FALSE);
	return true;
}
//----------------------------------------------------------------------------//
bool CAOIDataCollect::SaveCurrentProcess(const char *pContext)//儲存現在狀態
{	
	if ( FN_DISABLE == this->m_SystemParameter.m_SaveCurrentProcessMessage ) { return true; }

#ifdef _SEND_DEBUG_STRING
	if ( FN_DISABLE != m_SystemParameter.m_SendDebugViewString )
	{
		CString DebugString;
		CString Context = pContext;
		DebugString.Format(_T("Proc::%s"), Context);
		JetAPI::SendDebugString(DebugString);
	}
#endif//_SEND_DEBUG_STRING

	if ( LogManager.AddLogMessage(m_LogIdx_CurrentProcess, pContext) == true )
	{	return true; }

	m_ErrorString = _T("CAOIDataCollect::SaveCurrentProcess Fault");
	SetSystemExceptionCode_FileWrite();
	return false;

	if ( true == GetIsSystemReleased() ) { return true; }	
	this->LockGlobal();
	CString filename;	
	TCHAR TMode[32] = _T("");
	_tcscpy(TMode, _T("a+"));
	JetAPI::ModifyOpenFileMode_Write(TMode);
	filename.Format(_T("%s\\%s.txt"), GetAOILogDirectory(), CURRENT_PROCESS_FILENAME);
	FILE *pfile = ::_tfopen(filename, TMode);
	if ( pfile == NULL ) 
	{
		this->UnlockGlobal();			
		this->m_ErrorString.Format(_T("Error, No Open Current File (%s)"), filename);
		JetAPI::ShowMessageBox(this->m_ErrorString);
		return false;	
	}	
	CString tp, Result;
	CString context=pContext;
	JetAPI::GetTime(tp,CTime::GetCurrentTime());	
	Result.Format(_T("%s/%s/%s,%s:%s:%s %s"),tp.Mid(0,4),tp.Mid(4,2),tp.Mid(6,2)
			,tp.Mid(8,2),tp.Mid(10,2),tp.Mid(12,2), context);
	
	_ftprintf(pfile,_T("%s\n"),Result);

	::fclose(pfile);
	pfile = NULL;
	this->UnlockGlobal();
	return true;
}
