bool CAOIDataCollect::CreateNewFolder(LPCTSTR Folder)//建立AOI資料夾
{
	CString str;
	bool    IsOK = true;	
	const bool bShowMSG = true;
	const bool bSaveFile = true;	
	if ( JetAPI::IsDiskDrive(Folder) == false )
	{
		if ( JetAPI::CreateFolder(Folder) == FALSE )
		{
			if ( JetAPI::IsFolderExist(Folder) == false )
			{
				str.Format(_T("Error, Create Directory Fault\n(%s)"), Folder);
				this->ShowMessage(0, MSG_MB_OK, MSG_MB_ICONSTOP, MSG_MB_DEFBUTTON1, str, bSaveFile, bShowMSG);
				IsOK = false;
			}
		}
	}
	else
	{
		if ( JetAPI::IsFolderExist(Folder) == false )
		{
			str.Format(_T("Error, Check Directory Fault\n(%s)"), Folder);
			this->ShowMessage(0, MSG_MB_OK, MSG_MB_ICONSTOP, MSG_MB_DEFBUTTON1, str, bSaveFile, bShowMSG);
			IsOK = false;
		}
	}
	return IsOK;
}
