bool CAOIDataCollect::CreateAOITempDirectory()//建立暫存資料夾
{		
	CString TempFolder;
	CString TempProjectFolder;
	CString TempFolderOld = m_AOITempDirectory;
	CString TempProjectFolderOld = m_AOITempProjectDirectory;
	CString BaseFolder = m_SystemParameter.m_AOIBaseTempDirectory;
#ifndef OFFLINE_VERSION
	TempFolder.Format(_T("%s\\%s"), BaseFolder, _T("Inline"));
	TempProjectFolder.Format(_T("%s\\%s"), TempFolder, _T("Project"));
#else
	TempFolder.Format(_T("%s\\%s"), BaseFolder, _T("Offline"));
	TempProjectFolder.Format(_T("%s\\%s"), TempFolder, _T("Project"));
#endif//OFFLINE_VERSION
	if ( CreateNewFolder(BaseFolder) == false )
	{	return false; }
	if ( CreateNewFolder(TempFolder) == false )
	{	return false; }	
	if ( JetAPI::IsFolderExist(TempFolder) == false )
	{
		m_ErrorString.Format(_T("Error, Temp Folder Does Not Exist [%s]"), TempFolder);
		return false; 
	}
	::CreateDirectory(TempProjectFolder, NULL);
	if ( JetAPI::IsFolderExist(TempProjectFolder) == false )
	{
		m_ErrorString.Format(_T("Error, Temp Project Folder Does Not Exist [%s]"), TempProjectFolder);
		return false; 
	}
	m_AOITempDirectory = TempFolder;
	m_AOITempProjectDirectory = TempProjectFolder;
	JetAPI::TCHARCopy(TempFolder, m_AOITempDirectoryA, sizeof(m_AOITempDirectoryA), m_AOITempDirectoryW, sizeof(m_AOITempDirectoryW));

	if ( TempFolderOld.CompareNoCase(TempFolder) != 0 ) 
	{	JetAPI::RemoveFolder(TempFolderOld);	}
	if ( TempProjectFolderOld.CompareNoCase(TempProjectFolder) != 0 ) 
	{	JetAPI::RemoveFolder(TempProjectFolderOld);	}
	return true;
}
