//-------------------------------------------------------------------------------------//
DWORD CAOIDataCollect::GetComputerCPUCoreNumber() const
{ 
	int ComputerCPUCoreNumber=m_ComputerCPUCoreNumber;
	const int CpuMaxCountUsed=GetSystemParameter().m_CpuMaxCountUsed;
	if ( CpuMaxCountUsed > 0 )
	{	ComputerCPUCoreNumber = MIN(CpuMaxCountUsed, ComputerCPUCoreNumber);	}
	return ComputerCPUCoreNumber; 
}
//-------------------------------------------------------------------------------------//
void CAOIDataCollect::CalcThreadAffinityMask()//計算執行緒的CPU親和性
{
	DWORD_PTR CpuUseMask=0;		
	const int CpuMaxCountUsed = GetSystemParameter().m_CpuMaxCountUsed;
	if ( 0 == CpuMaxCountUsed )
	{	CpuUseMask = (DWORD_PTR)(-1);	}
	else
	{
		DWORD_PTR Tmp = 0;
		CpuUseMask = 0;		
		for ( int i=0; i<CpuMaxCountUsed; i++ )
		{
			if ( 0 == i )
			{	Tmp = 1; }
			else
			{	Tmp *= 2; }
			CpuUseMask += Tmp;
		}
	}
	m_ThreadAffinityMask = (DWORD_PTR)(-1);
	m_ThreadAffinityMask &= CpuUseMask;
	m_ThreadAffinityMask_Backup = m_ThreadAffinityMask;
	const int ProcIdleCnt = GetSystemParameter().m_MTCount_ProcIdle;
	if ( 0 == ProcIdleCnt )
	{	return; }
	const DWORD_PTR CpuCoreCount = GetComputerCPUCoreNumber();
	if ( CpuCoreCount < 3 )
	{	return ; }
	if ( ProcIdleCnt >= CpuCoreCount )
	{	return; }
	if ( ProcIdleCnt >= CpuMaxCountUsed )
	{	return;	}

	int i=0;
	int Prod=1;
	int Remove=0;
	DWORD_PTR ThreadAffinityMask = m_ThreadAffinityMask;
	for ( i=0; i<ProcIdleCnt; i++ )
	{
		if ( 0 == i )
		{	Prod = 1; }
		else
		{	Prod *= 2; }
		Remove += Prod;
	}
	ThreadAffinityMask ^= Remove;//剃除前2個核心數
	if ( 0 == ThreadAffinityMask )
	{	return;	}
	m_ThreadAffinityMask = ThreadAffinityMask;
	//m_ThreadAffinityMask = 0xF00;
	m_ThreadAffinityMask_Backup = m_ThreadAffinityMask;
	return;
}
