bool CAOIDataCollect::SaveWndUIParam(LPCTSTR Section, LPCTSTR KeyName, LPCTSTR Default)
{
	if ( SaveWndUIParamFn(Section, KeyName, Default) == false )
	{
		SetSystemExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveWndUIParamFn(LPCTSTR Section, LPCTSTR KeyName, LPCTSTR Default)
{
	CString strKey;
	CString strSection;
	CString strDefault;
	CString strResult;	
	CString INIFileName;
	CString strFolder = GetAOIDirectory();	
	CString ShortName = AOI3D_APP_CAT("UIParam.INI");
	if ( NULL==Section || NULL==KeyName || NULL==Default )
	{
		this->m_ErrorString.Format(_T("Error, SaveWndUIParam Fault"));
		return false;
	}	
	INIFileName.Format(_T("%s\\%s"), strFolder, ShortName);	

	strSection = Section;
	strDefault = Default;
	strKey.Format(_T("{%s}"), KeyName);
	if ( SaveINIData(strSection, strKey, strDefault, INIFileName, m_ErrorString) == false )
	{	return false;	}			
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadWndUIParam(LPCTSTR Section, LPCTSTR KeyName, LPCTSTR Default, CString &String)
{
	if ( LoadWndUIParamFn(Section, KeyName, Default, String) == false )
	{
		SetSystemExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadWndUIParamFn(LPCTSTR Section, LPCTSTR KeyName, LPCTSTR Default, CString &String)
{
	CString strKey;
	CString strSection;
	CString strDefault;
	CString strResult;	
	CString INIFileName;
	CString strFolder = GetAOIDirectory();
	CString ShortName = AOI3D_APP_CAT("UIParam.INI");
	const size_t TextLen = 256;
	TCHAR TextBuf[TextLen] = _T("");
	if ( NULL==Section || NULL==KeyName || NULL==Default )
	{
		this->m_ErrorString.Format(_T("Error, LoadWndUIParam Fault"));
		return false;
	}	
	INIFileName.Format(_T("%s\\%s"), strFolder, ShortName);	

	strSection = Section;
	strDefault = Default;
	strKey.Format(_T("{%s}"), KeyName);

	if ( LoadINIData(strSection, strKey, strDefault, TextBuf, TextLen, INIFileName, true, m_ErrorString) == false )
	{
		SaveINIData(strSection, strKey, strDefault, INIFileName, m_ErrorString);
		String = strDefault;
		return true;
	}		
	String = TextBuf;	
	return true;
}
