//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::GetUILanguageString(LPCTSTR Section, LPCTSTR Key, LPCTSTR Default, CString &String)
{
	CString strKey;
	CString strSection;
	CString strDefault;
	CString strResult;	
	CString INIFileName;
	CString strFolder = GetAOIDirectory();

	const size_t TextLen = 256;
	TCHAR TextBuf[TextLen] = _T("");

	if ( NULL==Section || NULL==Key || NULL==Default )
	{
		this->m_ErrorString.Format(_T("Error, GetUILanguageString Fault"));
		return false;
	}
	
	//INI File
	switch ( this->m_SystemParameter.m_MultiLanguageMode )
	{
	case MULTI_LANGUAGE_CHINESE_TRAD:
		INIFileName.Format(_T("%s\\%s"), strFolder, _T("LANGUAGE_UI_CT.INI"));
		break;
	case MULTI_LANGUAGE_CHINESE_SIMP:
		INIFileName.Format(_T("%s\\%s"), strFolder, _T("LANGUAGE_UI_CS.INI"));		
		break;
	case MULTI_LANGUAGE_LOCAL:
		INIFileName.Format(_T("%s\\%s"), strFolder, _T("LANGUAGE_UI_LC.INI"));		
		break;
	default:
		INIFileName.Format(_T("%s\\%s"), strFolder, _T("LANGUAGE_UI_EN.INI"));		
		break;
	}	

	strSection = Section;
	strDefault = Default;
	strKey.Format(_T("{%s}"), Key);

	if ( LoadINIData(strSection, strKey, strDefault, TextBuf, TextLen, INIFileName, true, m_ErrorString) == false )
	{
		SaveINIData(strSection, strKey, strDefault, INIFileName, m_ErrorString);
		String = strDefault;
		return true;
	}		
	String = TextBuf;	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CreateSystemDirectory()//建立系統路徑
{
	bool    IsOK = true;
	CString str;
	CString Folder;
	const bool bSaveFile=true;;
	const bool bShowMSG=true;
	const TSystemParameter &SystemParam=GetSystemParameter();
	const CString AOIFolder = SystemParam.m_AOIDirectory;

	IsOK = true;
	Folder = SystemParam.m_AOIDirectory;	
	if ( CreateNewFolder(Folder) == true )
	{	JetAPI::TCHARCopy(Folder, m_AOIDirectoryA, sizeof(m_AOIDirectoryA), m_AOIDirectoryW, sizeof(m_AOIDirectoryW));	}	

	//預設模組資料夾
	IsOK = true;
	Folder.Format(_T("%s\\%s"), AOIFolder, _T("DefaultModel"));
	if ( CreateNewFolder(Folder) == true )
	{	
		m_AOIDefaultModelDirectory = Folder;
		JetAPI::TCHARCopy(Folder, m_AOIDefaultModelDirectoryA, sizeof(m_AOIDefaultModelDirectoryA), m_AOIDefaultModelDirectoryW, sizeof(m_AOIDefaultModelDirectoryW));	
	}

	//暫存資料夾
	IsOK = true;
	Folder = SystemParam.m_AOIBaseTempDirectory;	
	if ( CreateNewFolder(Folder) == true )
	{	CreateAOITempDirectory();	}
	
	IsOK = true;
	Folder = SystemParam.m_AOILogDirectory;	
	if ( CreateNewFolder(Folder) == true )
	{	JetAPI::TCHARCopy(Folder, m_AOILogDirectoryA, sizeof(m_AOILogDirectoryA), m_AOILogDirectoryW, sizeof(m_AOILogDirectoryW)); }	

	//專案資料夾	
	Folder = SystemParam.m_AOIProjectFolder;	
	CreateNewFolder(Folder);
	SetOpenProjectDirectory(Folder);	

	//統計資料資料夾
	Folder = SystemParam.m_AOIStaticDataFolder;
	CreateNewFolder(Folder);

	//文字報告資料夾
	Folder = SystemParam.m_AOITextReportFolder;
	CreateNewFolder(Folder);

	//結果資料夾	
	Folder = SystemParam.m_AOIResultFolder;	
	CreateNewFolder(Folder);

	//線上調機資料夾	
	Folder = SystemParam.m_OnlineTuningFolder;	
	CreateNewFolder(Folder);

	//線上條碼資料夾	
	Folder = SystemParam.m_OnlineBarcodeFolder;	
	CreateNewFolder(Folder);	

	//線上離線編程資料夾	
	Folder = SystemParam.m_OnlineOfflineFolder;	
	CreateNewFolder(Folder);

	//專案檢測底圖資料夾	
	Folder = SystemParam.m_ProjectTestMapFolder;	
	CreateNewFolder(Folder);

	//專案檢測底圖資料夾-暫存
	Folder = SystemParam.m_ProjectTestMapFolderTemp;	
	CreateNewFolder(Folder);

	//專案檢測底圖資料夾-備份
	Folder = SystemParam.m_ProjectTestMapFolderBackup;	
	CreateNewFolder(Folder);

	//監控狀態資料夾	
	Folder = SystemParam.m_MonitorStatusFolder;	
	CreateNewFolder(Folder);

	//客戶訊息資料夾
	Folder = SystemParam.m_CustomerLogFolder;	
	CreateNewFolder(Folder);

	//客戶報告資料夾	
	Folder = SystemParam.m_CustomerReportFolder;	
	CreateNewFolder(Folder);	

	//條碼檔案資料夾
	Folder = SystemParam.m_BarcodeFileFolder_LA;	
	CreateNewFolder(Folder);
	Folder = SystemParam.m_BarcodeFileFolder_LB;	
	CreateNewFolder(Folder);
	
	//AI檔案輸出資料夾
	Folder = SystemParam.m_AIFileExportFolder;	
	CreateNewFolder(Folder);	

	//AI影像輸出資料夾
	Folder = SystemParam.m_AIImageExportFolder;	
	CreateNewFolder(Folder);	

	//檢測追蹤資料夾
	Folder = SystemParam.m_AOITestTrackFolder;	
	CreateNewFolder(Folder);	

	//訊息中控資料夾
	Folder = GetAOILogControlCenterDirectory();	
	CreateNewFolder(Folder);

	if ( FN_ENABLE == SystemParam.m_AiModelServerEnabled )
	{
		//AI模型檔案資料夾-傳送
		Folder = SystemParam.m_AiModelFileFolderSend;	
		CreateNewFolder(Folder);

		//AI模型檔案資料夾-接收
		Folder = SystemParam.m_AiModelFileFolderRecv;	
		CreateNewFolder(Folder);
	}

	//伺服器資料夾
	IsOK = true;
	Folder = SystemParam.m_AOIServerFolder;	
	m_AOIServerProjectFolder.Format(_T("%s\\%s"), Folder, _T("Project"));
	m_AOIServerLibraryFolder.Format(_T("%s\\%s"), Folder, _T("Library"));	
	if ( CreateNewFolder(Folder) == true )
	{		
		Folder = m_AOIServerProjectFolder;
		if ( ::CreateDirectory(Folder, NULL) == FALSE )
		{
			if ( JetAPI::IsFolderExist(Folder) == false )
			{
				str.Format(_T("Error, Create Directory Fault\n(%s)"), Folder);
				this->ShowMessage(0, MSG_MB_OK, MSG_MB_ICONSTOP, MSG_MB_DEFBUTTON1, str, bSaveFile, bShowMSG);
				IsOK = false;
			}
		}
		Folder = m_AOIServerLibraryFolder;
		if ( ::CreateDirectory(Folder, NULL) == FALSE )
		{
			if ( JetAPI::IsFolderExist(Folder) == false )
			{
				str.Format(_T("Error, Create Directory Fault\n(%s)"), Folder);
				this->ShowMessage(0, MSG_MB_OK, MSG_MB_ICONSTOP, MSG_MB_DEFBUTTON1, str, bSaveFile, bShowMSG);
				IsOK = false;
			}
		}
	}	
	return true;
}
