bool CAOIDataCollect::VerifyJsonString(LPCTSTR Text)//驗證Json字串
{
	const bool bSucc=JetAPI::CheckJSONStringT(Text);
	if ( false == bSucc )
	{	
		CString str=_T("Error, Verify JSON String Fault");
		str = LoadMultiLanguageString(str, str);
		m_ErrorString.Format(_T("%s\n[%s]"), str, Text);		
		return false;
	}
	return bSucc;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckProjectParamNeedToVerifyJsonString(PROJECT_PARAM_ID ParamID) const//確認專案參數需要驗證Json字串
{
	if ( GetVerifyJsonStringEnabled() == false )
	{	return false; }

	bool bVerify=false;
	switch ( ParamID )
	{
	case PROJECT_PARAM_MODULE_NAME://專案機種名稱
	case PROJECT_PARAM_WORDK_NUMBER://專案工單號碼
		bVerify = true;
		break;
	default:
		bVerify = false;
		break;
	}
	return bVerify;
}
