//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckNeedAutoRetry(ONLINE_STATE_MODE OnlineStateMode, TASK_MODE &TaskMode)//確認是否需要自動重測
{
	TaskMode = GetTaskMode();					
	const bool bIsRepeatTest = GetIsRepeatTestUI();
	const int AutoRetryCount = GetAutoRetryCount();
	const bool bIsEnableAutoRetry = GetIsEnableAutoRetry();
	const bool bIsIgnoreAutoRetry = GetIsIgnoreAutoRetry();
	const int AutoRetryMaxCount = GetSystemParameter().m_AutoRetryMaxCount;	
	const TASK_STATE_MODE  TaskStateMode = GetOnlineTaskState();	
	
	if ( 0 == AutoRetryMaxCount )
	{	return false; }
	if ( false == bIsEnableAutoRetry )
	{	return false; }
	if ( true == bIsIgnoreAutoRetry )
	{	return false; }
	if ( AutoRetryCount >= AutoRetryMaxCount )
	{	return false; }
	if ( TASK_TUNING_PROJECT == TaskMode )
	{
		if ( false == bIsRepeatTest )
		{	return false; }
		else
		{	return true; }		
	}		
	if ( TASK_INSPECT_PROJECT == TaskMode )
	{
		if ( TASK_STATE_TO_STOP==TaskStateMode || TASK_STATE_NONE==TaskStateMode ) 
		{	return false; }
		else
		{
			bool Inspecting = false;
			switch ( OnlineStateMode )
			{
			case ONLINE_STATE_PROJECT_MARK:
			case ONLINE_STATE_PROJECT_OPEN_CODE:
			case ONLINE_STATE_INSPECTION_START:
			case ONLINE_STATE_INSPECTION_WAITING:
			case ONLINE_STATE_INSPECT_FD_PANEL:
			case ONLINE_STATE_INSPECT_FD_BOARD:
			case ONLINE_STATE_INSPECT_BARCODE:
			case ONLINE_STATE_INSPECT_PROJECT:
				Inspecting = true;
				break;
			default:
				Inspecting = false;
				break;
			}
			if ( false == Inspecting )
			{	return false; }
			return true; 
		}
	}	
	return false;
}
