//-------------------------------------------------------------------------------------//
MULTI_PROJECT_TEST_ORDER_MODE CAOIDataCollect::CheckMultiProjectTestOrderMode()//確認多專案檢測順序模式
{	
	MULTI_PROJECT_TEST_ORDER_MODE Mode=GetSystemParameter().m_MultiProjectTestOrderMode;
	if ( MULTI_PROJECT_TEST_ORDER_NONE == Mode ) 
	{
		SetMultiProjectTestOrderMode(Mode);
		return Mode; 
	}
	
	LANE_ID LaneID;
	int     LaneRunCount=0;
	bool bMultiProject=false;
	size_t ProjectCount=0;		
	LANE_WORK_MODE LaneWorkMode;		
	std::vector<CAOIProject*> LaneProjectList;
	const bool bMultiLaneModeOff=CheckMultiLaneMode_Off();

	LaneID = LANE_ID_A;
	LaneWorkMode = GetLaneWorkMode(LaneID);
	if ( LANE_WORK_RUN==LaneWorkMode || true==bMultiLaneModeOff )
	{
		LaneRunCount ++;
		if ( BuildLaneProjectList(LaneID, LaneProjectList) == true )
		{	
			ProjectCount = LaneProjectList.size(); 
			if ( ProjectCount > 1 )
			{	bMultiProject = true; }
		}
	}

	LaneID = LANE_ID_B;
	LaneWorkMode = GetLaneWorkMode(LaneID);
	if ( LANE_WORK_RUN==LaneWorkMode || true==bMultiLaneModeOff )
	{
		LaneRunCount ++;
		if ( BuildLaneProjectList(LaneID, LaneProjectList) == true )
		{	
			ProjectCount = LaneProjectList.size(); 
			if ( ProjectCount > 1 )
			{	bMultiProject = true; }
		}
	}

	if ( false == bMultiProject )
	{	
		Mode = MULTI_PROJECT_TEST_ORDER_NONE;	
		SetMultiProjectTestOrderMode(Mode);
		return Mode;
	}
	
	bool bSupportMultiLane=true;//支援雙軌模式
	if ( false == bSupportMultiLane )
	{
		if ( LaneRunCount > 1 )//雙軌模式無法切出出板與進板, 所以無法輪流檢測
		{	
			Mode = MULTI_PROJECT_TEST_ORDER_BY_MARK;	
			SetMultiProjectTestOrderMode(Mode);
			return Mode;
		}	
	}

	if ( MULTI_PROJECT_TEST_ORDER_ONE_CYCLE_A_B==Mode || MULTI_PROJECT_TEST_ORDER_ONE_CYCLE_B_A==Mode )
	{
	#ifdef TB_SYSTEM_DEBUG
		Mode = MULTI_PROJECT_TEST_ORDER_NONE;
	#endif//TB_SYSTEM_DEBUG
	#ifdef TB_SYSTEM_ENABLE
		Mode = MULTI_PROJECT_TEST_ORDER_NONE;
	#endif//TB_SYSTEM_ENABLE
	}
	SetMultiProjectTestOrderMode(Mode);	
	return Mode;
}
