//-------------------------------------------------------------------------------------/
bool CAOIDataCollect::SetJetMemoryLevel()//設定記憶體層級 
{
	const size_t BaseLevel    = 2048;
	const size_t BMPHeader    = sizeof(BITMAPINFOHEADER);//40 bytes
	const size_t BMPTable     = 256*sizeof(RGBQUAD);//1024 bytes
	const size_t BMPExtra     = BMPHeader+BMPTable;//1064 bytes	
	const size_t ImageWHM     = CameraCtrl.GetCameraGrayImageSize()*sizeof(IMAGE_DATA);	
	const size_t ImageWHC     = CameraCtrl.GetCameraColorImageSize()*sizeof(IMAGE_DATA);		
	const size_t ImageWHM_D2   = ImageWHM/2;//1/2 mono fov image size
	const size_t ImageWHC_D2   = ImageWHC/2;//1/2 colr fov image size
	const size_t ImageWHM_D4   = ImageWHM/4;//1/4 mono fov image size
	const size_t ImageWHC_D4   = ImageWHC/4;//1/4 colr fov image size	
	const size_t ImageWHM_D8   = ImageWHM/8;//1/8 mono fov image size
	const size_t ImageWHC_D8   = ImageWHC/8;//1/8 colr fov image size	
	const size_t ImageWHM_D16  = ImageWHM/16;//1/16 mono fov image size
	const size_t ImageWHC_D16  = ImageWHC/16;//1/16 colr fov image size	
	const size_t ImageWHM_D32  = ImageWHM/32;//1/32 mono fov image size
	const size_t ImageWHC_D32  = ImageWHC/32;//1/32 colr fov image size	
	const size_t ImageWHM_D64  = ImageWHM/64;//1/64 mono fov image size
	const size_t ImageWHC_D64  = ImageWHC/64;//1/64 colr fov image size	

	const size_t ImageWHM_M02  = ImageWHM*2;//2 mono fov image size
	const size_t ImageWHC_M02  = ImageWHC*2;//2 colr fov image size
	const size_t ImageWHM_M04  = ImageWHM*4;//4 mono fov image size
	const size_t ImageWHC_M04  = ImageWHC*4;//4 colr fov image size		
	const size_t ImageWHM_M05  = ImageWHM*5;//5 mono fov image size
	const size_t ImageWHC_M05  = ImageWHC*5;//5 colr fov image size		
	const size_t ImageWHM_M07  = ImageWHM*7;//7 mono fov image size
	const size_t ImageWHC_M07  = ImageWHC*7;//7 colr fov image size		
	const size_t ImageWHM_M08  = ImageWHM*8;//8 mono fov image size
	const size_t ImageWHC_M08  = ImageWHC*8;//8 colr fov image size	
	const size_t ImageWHM_M11  = ImageWHM*11;//11 mono fov image size
	const size_t ImageWHC_M11  = ImageWHC*11;//11 colr fov image size	
	const size_t ImageWHM_M13  = ImageWHM*13;//13 mono fov image size
	const size_t ImageWHC_M13  = ImageWHC*13;//13 colr fov image size	
	const size_t ImageWHM_M17  = ImageWHM*17;//17 mono fov image size
	const size_t ImageWHC_M17  = ImageWHC*17;//17 colr fov image size	
	const size_t ImageWHM_M19  = ImageWHM*19;//19 mono fov image size
	const size_t ImageWHC_M19  = ImageWHC*19;//19 colr fov image size	

	//const size_t SM_ROI_Size  = (SM_ROI_WIDTH*2)*(SM_ROI_LENGTH*2);//FOV Mark Image and Spatial Mapping Image Size

	std::vector<size_t> sizeList;	
	sizeList.push_back(BaseLevel);

	///*
//	sizeList.push_back(SM_ROI_Size);
	sizeList.push_back(ImageWHM_D64+BMPExtra);//20260415
	sizeList.push_back(ImageWHM_D32+BMPExtra);//20260415
	sizeList.push_back(ImageWHM_D16+BMPExtra);//20260415
	sizeList.push_back(ImageWHM_D8+BMPExtra);//20230809
	sizeList.push_back(ImageWHM_D4+BMPExtra);//20230809
	sizeList.push_back(ImageWHM_D2+BMPExtra);
	sizeList.push_back(ImageWHM+BMPExtra);
	sizeList.push_back(ImageWHC_D2+BMPExtra);
	sizeList.push_back(ImageWHC+BMPExtra);
	sizeList.push_back(ImageWHC+ImageWHM+BMPExtra);
//	sizeList.push_back(ImageWHM_D2+BMPExtra);
//	sizeList.push_back(ImageWHC_D2+BMPExtra);
//	sizeList.push_back(ImageWHM_D4+BMPExtra);
//	sizeList.push_back(ImageWHC_D4+BMPExtra);
	sizeList.push_back(ImageWHM_M02+BMPExtra);//unsigned short
	sizeList.push_back(ImageWHM_M04+BMPExtra);//int or float
	sizeList.push_back(ImageWHM_M05+BMPExtra);//
	sizeList.push_back(ImageWHM_M07+BMPExtra);//
	sizeList.push_back(ImageWHM_M08+BMPExtra);//double
	sizeList.push_back(ImageWHM_M11+BMPExtra);//
	sizeList.push_back(ImageWHM_M13+BMPExtra);//
	sizeList.push_back(ImageWHM_M17+BMPExtra);//
	//*/

	std::sort(sizeList.begin(), sizeList.end());
	
	size_t  i=0;
	size_t  memSize=0;
	const  size_t size = sizeList.size();
	JetMemory.set_basic_memory_size(ImageWHM);
	JetMemory.set_extra_memory_size(BMPExtra);
	JetMemory.recalc_layout_memory_size();
	for ( i=0; i<size; i++ )
	{
		memSize = sizeList[i];	
		JetMemory.add_memory_size(memSize);	
	}

	CString filename;
	filename.Format(_T("%s\\%s"), GetAOITempDirectory(), _T("JetMemorySize.txt"));
	JetMemory.save_memory_size_list(filename);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SetCudaMemoryLevel()//設定Cuda記憶體層級 
{
#ifdef CUDA_USE
	//Cude通常是整張影像處理, 因此給予整張影像尺寸的倍數即可
	const size_t BMPExtra     = 0;//BMPHeader+BMPTable;//1064 bytes	
	const size_t CastParam    = sizeof(TCastParam);
	const size_t ImageWHM     = CameraCtrl.GetCameraGrayImageSize()*sizeof(IMAGE_DATA);	
	const size_t ImageWHC     = CameraCtrl.GetCameraColorImageSize()*sizeof(IMAGE_DATA);		
	const size_t ImageWHM_D2   = ImageWHM/2;//1/2 mono fov image size
	const size_t ImageWHC_D2   = ImageWHC/2;//1/2 colr fov image size
	const size_t ImageWHM_D4   = ImageWHM/4;//1/4 mono fov image size
	const size_t ImageWHC_D4   = ImageWHC/4;//1/4 colr fov image size	

	const size_t ImageWHM_M02  = ImageWHM*2;//2 mono fov image size
	const size_t ImageWHC_M02  = ImageWHC*2;//2 colr fov image size
	const size_t ImageWHM_M04  = ImageWHM*4;//4 mono fov image size
	const size_t ImageWHC_M04  = ImageWHC*4;//4 colr fov image size		
	const size_t ImageWHM_M05  = ImageWHM*5;//5 mono fov image size
	const size_t ImageWHC_M05  = ImageWHC*5;//5 colr fov image size		
	const size_t ImageWHM_M07  = ImageWHM*7;//7 mono fov image size
	const size_t ImageWHC_M07  = ImageWHC*7;//7 colr fov image size		
	const size_t ImageWHM_M08  = ImageWHM*8;//8 mono fov image size
	const size_t ImageWHC_M08  = ImageWHC*8;//8 colr fov image size	
	const size_t ImageWHM_M11  = ImageWHM*11;//11 mono fov image size
	const size_t ImageWHC_M11  = ImageWHC*11;//11 colr fov image size	
	const size_t ImageWHM_M13  = ImageWHM*13;//13 mono fov image size
	const size_t ImageWHC_M13  = ImageWHC*13;//13 colr fov image size	
	const size_t ImageWHM_M17  = ImageWHM*17;//17 mono fov image size
	const size_t ImageWHC_M17  = ImageWHC*17;//17 colr fov image size	
	const size_t ImageWHM_M19  = ImageWHM*19;//19 mono fov image size
	const size_t ImageWHC_M19  = ImageWHC*19;//19 colr fov image size	

	std::vector<size_t> sizeList;		
	sizeList.push_back(CastParam);
	sizeList.push_back(ImageWHM_D2+BMPExtra);
	sizeList.push_back(ImageWHM+BMPExtra);
	sizeList.push_back(ImageWHC_D2+BMPExtra);
	sizeList.push_back(ImageWHC+BMPExtra);
	sizeList.push_back(ImageWHC+ImageWHM+BMPExtra);
//	sizeList.push_back(ImageWHM_D2+BMPExtra);
//	sizeList.push_back(ImageWHC_D2+BMPExtra);
//	sizeList.push_back(ImageWHM_D4+BMPExtra);
//	sizeList.push_back(ImageWHC_D4+BMPExtra);
	sizeList.push_back(ImageWHM_M02+BMPExtra);//unsigned short
	sizeList.push_back(ImageWHM_M04+BMPExtra);//int or float
	sizeList.push_back(ImageWHM_M05+BMPExtra);//
	sizeList.push_back(ImageWHM_M07+BMPExtra);//
	sizeList.push_back(ImageWHM_M08+BMPExtra);//double
	sizeList.push_back(ImageWHM_M11+BMPExtra);//
	sizeList.push_back(ImageWHM_M13+BMPExtra);//
	sizeList.push_back(ImageWHM_M17+BMPExtra);//

	std::sort(sizeList.begin(), sizeList.end());
	
	size_t i=0, memSize=0;
	const size_t size = sizeList.size();

	CudaFunc.ClearCudeBufferSizeList();
	for ( i=0; i<size; i++ )
	{
		memSize = sizeList[i];	
		CudaFunc.AddCudeBufferSize(memSize);
	}
	CudaFunc.LayoutCudeBufferSizeList();
	
#ifndef OFFLINE_VERSION
	size_t TestCount = 32;//4Cast x 8Frame	
	if ( CudaFunc.TestCudaBuffer(ImageWHM, TestCount) == false )
	{
		this->m_ErrorString = CudaFunc.GetErrorString();
		return false;
	}	
#endif//OFFLINE_VERSION	
	
#endif//CUDA_USE
	return true;
}
