void CAOIDataCollect::SetRibbonTuneGroupCmdID(UINT value)
{
	if ( m_RibbonTuneGroupCmdID == value ) { return ; }
	switch ( value)
	{
	case ID_TUNE_SELECTED_MODEL:
		m_RibbonTuneGroupCmdID = ID_TUNE_SELECTED_MODEL;
		m_RibbonTuneGroupCmdText = _T("ID_TUNE_SELECTED_MODEL");
		break;
	case ID_TUNE_SELECTED_COMPONENT:
		m_RibbonTuneGroupCmdID = ID_TUNE_SELECTED_COMPONENT;
		m_RibbonTuneGroupCmdText = _T("ID_TUNE_SELECTED_COMPONENT");
		break;
	case ID_TUNE_SELECTED_PART_NUMBER:
		m_RibbonTuneGroupCmdID = ID_TUNE_SELECTED_PART_NUMBER;
		m_RibbonTuneGroupCmdText = _T("ID_TUNE_SELECTED_PART_NUMBER");
		break;
	case ID_TUNE_SELECTED_MODEL_GROUP:
		m_RibbonTuneGroupCmdID = ID_TUNE_SELECTED_MODEL_GROUP;
		m_RibbonTuneGroupCmdText = _T("ID_TUNE_SELECTED_MODEL_GROUP");
		break;
	case ID_TUNE_INSPECTION:
	default:
		m_RibbonTuneGroupCmdID = ID_TUNE_INSPECTION;
		m_RibbonTuneGroupCmdText = _T("ID_TUNE_INSPECTION");
		break;
	}
	PostMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_UPDATE_RIBBON_UI_TEXT, LPARAM_UPDATE_RIBBON_TUNE_GROUP_TEXT);
}
//-------------------------------------------------------------------------------------//
void CAOIDataCollect::SetRibbonDefaultWndCmdID(UINT value)
{
	if ( m_RibbonDefaultWndCmdID == value ) { return ; }
	switch ( value)
	{
	default:
	case MENU_MODEL_EDIT_ADD_ALL_WND:	
		m_RibbonDefaultWndCmdID = MENU_MODEL_EDIT_ADD_ALL_WND;
		m_RibbonDefaultWndCmdText = _T("MENU_MODEL_EDIT_ADD_ALL_WND");
		break;
	case MENU_MODEL_EDIT_ADD_ALL_WND_V2:
		m_RibbonDefaultWndCmdID = MENU_MODEL_EDIT_ADD_ALL_WND_V2;
		m_RibbonDefaultWndCmdText = _T("MENU_MODEL_EDIT_ADD_ALL_WND_V2");
		break;		
	}
	PostMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_UPDATE_RIBBON_UI_TEXT, LPARAM_UPDATE_RIBBON_DEFAULT_WND_GROUP_TEXT);
}
