//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SwitchMultiLanguageWnd(CWnd *WndPtr, LPCTSTR Section, UINT ID, LPCTSTR Text, bool bCtrlID)
{
	if ( NULL==WndPtr || WndPtr->GetSafeHwnd()==NULL )
	{	return false; }

	CString LabelText, NewLabelText;	
	if ( IDOK == ID )
	{
		NewLabelText = AOIDataDefine.GetWndOKText();
		WndPtr->SetDlgItemText(ID, NewLabelText);	
		return true;
	}
	if ( IDCANCEL == ID )
	{
		NewLabelText = AOIDataDefine.GetWndCancelText();
		WndPtr->SetDlgItemText(ID, NewLabelText);	
		return true;
	}
	if ( false==bCtrlID )
	{	WndPtr->GetWindowText(LabelText);	}
	else
	{	WndPtr->GetDlgItemText(ID, LabelText); }
	if ( GetUILanguageString(Section, Text, LabelText, NewLabelText) == false )
	{	return false; }
	if ( false==bCtrlID)
	{	WndPtr->SetWindowText(NewLabelText);	}
	else
	{	WndPtr->SetDlgItemText(ID, NewLabelText); }	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckApplicationVersion(CString &Filename, CString &VersionS)//確認系統版本
{
	//取得程式版本	
	TCHAR cPath[2048]=_T("");
	TCHAR cPath2[2048]=_T("");
	DWORD dwHandle=0,InfoSize=0, Res=0;
	CString strVersion=_T("");
	Res = ::GetModuleFileName(NULL,cPath,sizeof(cPath));
	if ( Res == 0 ) { return false; }
	if ( JetAPI::ExtractMainFileNameNoPath(cPath, cPath2, sizeof(cPath2)) == true )
	{	Filename = cPath2;	}
	InfoSize = GetFileVersionInfoSize(cPath,&dwHandle); 
	if ( InfoSize == 0 ) { return false; }
	
	TCHAR *InfoBuf = new TCHAR[InfoSize];
	if ( InfoBuf == NULL ) { return false; }

	if ( GetFileVersionInfo(cPath,0,InfoSize,InfoBuf) == FALSE ) 
	{
		delete[] InfoBuf; InfoBuf=NULL;
		return false; 
	}
	unsigned int  cbTranslate = 0; 
	// Structure used to store enumerated languages and code pages. 
	struct LANGANDCODEPAGE 
	{
		WORD wLanguage;
		WORD wCodePage;
	} *lpTranslate; 
	// Read the list of languages and code pages. 
	if ( VerQueryValue(InfoBuf, _T("\\VarFileInfo\\Translation"),	(LPVOID*)&lpTranslate, &cbTranslate) == FALSE )
	{	
		delete[] InfoBuf; InfoBuf=NULL;
		return false; 
	}

	// Read the file description for each language and code page.
	unsigned int i;
	void *lpBuffer=NULL;
	unsigned int dwBytes=0;
	unsigned int Count = cbTranslate/sizeof(struct LANGANDCODEPAGE);
	for( i=0; i<Count; i++ )
	{
		TCHAR SubBlock[200]=_T("");
		wsprintf( SubBlock,
			TEXT("\\StringFileInfo\\%04x%04x\\FileVersion"),
			lpTranslate[i].wLanguage,
			lpTranslate[i].wCodePage);
			
		lpBuffer=NULL;
		dwBytes=0;
		// Retrieve file description for language and code page "i". 
		VerQueryValue(InfoBuf, SubBlock, &lpBuffer, &dwBytes); 
		//strVersion=(char *)lpBuffer;
		strVersion=(TCHAR *)lpBuffer;		
	}
	delete[] InfoBuf; InfoBuf=NULL;		
	VersionS = strVersion;
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SystemReleaseStep(SYSTEM_INITIAL_STEP Step)//系統初始化
{	
	bool IsOK = true;
	CString str;	
	switch ( Step )
	{
	case SYSTEM_INITIAL_CAMERA:
		CameraCtrl.StopAllCameraGrab();
		SaveInitialReleaseLog(_T("Start to Release Camera"));		
		if ( CameraCtrl.ReleaseAllCamera() == false )
		{
			IsOK = false;
			this->m_ErrorString = CameraCtrl.GetErrorString();
		}
		break;
	case SYSTEM_INITIAL_MOTION_XYZ:
		SaveInitialReleaseLog(_T("Start to Release Motion XYZ"));
		if ( MotionCtrlPtr->ReleaseMotion() == false )
		{
			IsOK = false;
			this->m_ErrorString = MotionCtrlPtr->GetErrorString();
		}		
		break;
	case SYSTEM_INITIAL_PLC:
		SaveInitialReleaseLog(_T("Start to Disconnect PLC"));
		if ( PlcCtrlPtr->PLC_Disconnect() == false )
		{
			IsOK = false;
			this->m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
		}
		break;
	case SYSTEM_INITIAL_LIGHT_CTRL:
		SaveInitialReleaseLog(_T("Start to Disconnect Light Ctrl Board"));
		if ( LightCtrlBoard.DisConnect() == false )
		{
			IsOK = false;
			this->m_ErrorString = LightCtrlBoard.GetErrorString();
		}
		break;
	case SYSTEM_INITIAL_PHASE_CTRL:
		SaveInitialReleaseLog(_T("Start to Disconnect 3D Ctrl Board"));
		if ( Light3DCtrl.ExecLight3DCastDisconnect() == false )
		{
			IsOK = false;
			this->m_ErrorString = Light3DCtrl.GetErrorString();
		}
		break;
	case SYSTEM_INITIAL_IMAGE_LIB_EURESYS:
		SaveInitialReleaseLog(_T("Start to Release Euresys Library"));
		break;
	case SYSTEM_INITIAL_IMAGE_LIB_MIM_LIB:
		SaveInitialReleaseLog(_T("Start to Release Mim Library"));
		break;
	case SYSTEM_INITIAL_IMAGE_LIB_DTK_LIB:
		SaveInitialReleaseLog(_T("Start to Release DTK Library"));
		CDtkBarcode::FreeDTKLibrary();
		break;
	case SYSTEM_INITIAL_IMAGE_LIB_HON_LIB:
		SaveInitialReleaseLog(_T("Start to Release Honeywell Library"));
		HoneywellBarcodeSdk.HoneywellSwiftDecoder_Destroy();
		break;
	case SYSTEM_INITIAL_ITS_COMM:
	#ifndef MES_DISABLE
		SaveInitialReleaseLog(_T("Start to Disconnect ITS Comm"));
		if ( GetMES_CommunicationEnabled() == true )
		{
			if ( GetMES_SecsGemEnabled()==true )
			{	ExecMESComm_SetControlStateMode(MES_EQP_CTRL_STATE_OFFLINE);	}
			ExecMESComm_SetMachineStatus(ONLINE_STATE_APP_CLOSE);
		}
		::Sleep(250);
		MES_OBJ.DisconnectMESLinker();		
	#endif//MES_DISABLE
		break;	
	case SYSTEM_INITIAL_AI_SERVER:		
		SaveInitialReleaseLog(_T("Start to Disconnect AI Server"));
		break;
	case SYSTEM_INITIAL_BARCODE_DEVICE:
		SaveInitialReleaseLog(_T("Start to Destroy Barcode Device"));
		IsOK = DestroyBarcodeDevice();
		break;
	default:
		IsOK = false;
		this->m_ErrorString.Format(_T("Error Not Define Initial Step(%d)"), Step);
		break;
	}	
	return IsOK;	
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SystemInitializeStep(SYSTEM_INITIAL_STEP Step)//系統釋放
{
	bool IsOK = true;
	int     val;
	CString str;	
	const TSystemParameter &SysParam = GetSystemParameter();
	switch ( Step )
	{
	case SYSTEM_INITIAL_CAMERA:
		SaveInitialReleaseLog(_T("Start to Initialize Camera"));
		if ( CameraCtrl.InitialAllCamera() == false )
		{
			IsOK = false;
			this->m_ErrorString = CameraCtrl.GetErrorString();
		}
		else
		{
		#ifndef	LIGHT_CTRL_DISABLE
			CameraCtrl.SetAllCameraExternalTrigger();
		#else
			CameraCtrl.SetAllCameraInternalTrigger();
		#endif//LIGHT_CTRL_DISABLE			
		}
		break;
	case SYSTEM_INITIAL_MOTION_XYZ:
		SaveInitialReleaseLog(_T("Start to Initialize Motion XYZ"));
		if ( MotionCtrlPtr->InitialMotion() == false )
		{
			IsOK = false;
			this->m_ErrorString = MotionCtrlPtr->GetErrorString();
		}		
		break;
	case SYSTEM_INITIAL_PLC:
		SaveInitialReleaseLog(_T("Start to Connect PLC"));
		str = PlcCtrlPtr->GetPLCConnectParam();//取得PLC連線參數		
		if ( PlcCtrlPtr->PLC_ConnectTo(str) == false )
		{
			IsOK = false;
			this->m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
		}
	#ifndef OFFLINE_VERSION
		PlcCtrlPtr->PushDownStopBtn();	::Sleep(100);
		PlcCtrlPtr->PushDownResetBtn();		
		PlcCtrlPtr->TurnOffStageAlarm(LANE_ID_A);
		PlcCtrlPtr->TurnOffStageAlarm(LANE_ID_B);
		PlcCtrlPtr->TurnOffInspectAlarm(LANE_ID_A);
		PlcCtrlPtr->TurnOffInspectAlarm(LANE_ID_B);
		PlcCtrlPtr->SetLastStationLineMode(SysParam.m_LastStationLineMode);
		if ( LANE_WORK_DISABLE == SysParam.m_LaneWorkMode_LA ) { PlcCtrlPtr->SetConveryerEnabled_LA(false); }
		else { PlcCtrlPtr->SetConveryerEnabled_LA(true); }
		if ( LANE_WORK_DISABLE == SysParam.m_LaneWorkMode_LB ) { PlcCtrlPtr->SetConveryerEnabled_LB(false); }
		else { PlcCtrlPtr->SetConveryerEnabled_LB(true); }
		PlcCtrlPtr->PushDownStartBtn();
	#endif//OFFLINE_VERSION
		break;
	case SYSTEM_INITIAL_LIGHT_CTRL:		
		SaveInitialReleaseLog(_T("Start to Connect Light Ctrl Board"));
		if ( LightCtrlBoard.Connect() == false )
		{
			IsOK = false;
			this->m_ErrorString = LightCtrlBoard.GetErrorString();
		}
		break;
	case SYSTEM_INITIAL_PHASE_CTRL:
		SaveInitialReleaseLog(_T("Start to Connect 3D Ctrl Board"));
		if ( Light3DCtrl.ExecLight3DCastConnect() == false )
		{
			IsOK = false;
			this->m_ErrorString = Light3DCtrl.GetErrorString();
		}
		break;
	case SYSTEM_INITIAL_IMAGE_LIB_EURESYS:
	#ifdef EVISION_USE
		SaveInitialReleaseLog(_T("Start to Initialize Euresys Library"));
		if ( CEvsAPI::CheckLicenses() == false )
		{
			IsOK = false;
			this->m_ErrorString = CEvsAPI::GetErrorString();
		}
		else
		{				
			if ( CEvsAPI::InitialApi() == false )
			{
				IsOK = false;
				this->m_ErrorString = CEvsAPI::GetErrorString();	
			}
		}
	#endif//EVISION_USE
		break;
	case SYSTEM_INITIAL_IMAGE_LIB_MIM_LIB:
	#ifdef MIM_LIB_USE
		SaveInitialReleaseLog(_T("Start to Initialize Mim Library"));
		if ( CMimAPI::CheckLicenses() == false )
		{
			IsOK = false;
			this->m_ErrorString = CMimAPI::GetErrorString();
		}
		else
		{	
			if ( CMimAPI::InitialApi() == false )
			{
				IsOK = false;
				this->m_ErrorString = CMimAPI::GetErrorString();
			}
		}
	#endif//MIM_LIB_USE
		break;
	case SYSTEM_INITIAL_IMAGE_LIB_DTK_LIB:
	#ifdef DTK_BARCODE_USE
		SaveInitialReleaseLog(_T("Start to Initialize DTK Library"));
		if ( CDtkBarcode::LoadDTKLibrary(str) == false )
		{
			IsOK = false;
			this->m_ErrorString = str;
		}
		else
		{
			CDtkBarcode::LoadDTKIniFile(); 
			CDtkBarcode::SaveDTKIniFile();			
		}
	#endif//DTK_BARCODE_USE
		break;
	case SYSTEM_INITIAL_IMAGE_LIB_HON_LIB:
	#ifdef HON_BARCODE_USE
		SaveInitialReleaseLog(_T("Start to Initialize Honeywell Library"));
		HoneywellBarcodeSdk.LoadHonIniFile();
		HoneywellBarcodeSdk.SaveHonIniFile();
		if ( HoneywellBarcodeSdk.CheckHonLicenseKey()==false ||
			 HoneywellBarcodeSdk.HoneywellSwiftDecoder_Create()==false )
		{
			IsOK = false;			
			str = HoneywellBarcodeSdk.GetErrorString();			
			m_ErrorString = str;
		}		
	#endif//HON_BARCODE_USE
		break;
	case SYSTEM_INITIAL_ITS_COMM:
	#ifndef MES_DISABLE		
		if ( GetMES_CommunicationEnabled() == true )
		{
			SaveInitialReleaseLog(_T("Start to Connect ITS Comm"));
			if ( MES_OBJ.ConnectMESLinker() == false )
			{
				IsOK = false;
				this->m_ErrorString = MES_OBJ.GetErrorString();
			}			
			else
			{	
				bool bMesSucc=true;
				if ( GetMES_SecsGemEnabled()==true )
				{	bMesSucc = ExecMESComm_SetControlStateMode(MES_EQP_CTRL_STATE_OFFLINE);	}

				if ( true == bMesSucc )
				{	bMesSucc = ExecMESComm_SetMachineStatus(ONLINE_STATE_APP_OPEN);	}
				if ( true == bMesSucc )
				{	bMesSucc = ExecMESComm_ProcessID(MES_STATAUS_AOI_INSPECTION_STOP_CMD);	}
			}
		}
	#endif//MES_DISABLE
		break;	
	case SYSTEM_INITIAL_AI_SERVER:
		if ( FN_ENABLE == GetSystemParameter().m_AiModelServerEnabled )
		{
			SaveInitialReleaseLog(_T("Start to Connect AI Server"));
			CString AiServerName=GetSystemParameter().m_AiModelServerFilename;
			if ( AiServerName.GetLength() > 0 )
			{	HINSTANCE hinstITS=::ShellExecute(NULL, _T("open"), AiServerName, NULL, NULL, SW_SHOW);	}
		}
		break;
	case SYSTEM_INITIAL_BARCODE_DEVICE:	
		SaveInitialReleaseLog(_T("Start to Create Barcode Device"));
		if ( CreateBarcodeDevice() == false )
		{	IsOK = false;	}	
		break;
	default:
		IsOK = false;
		this->m_ErrorString.Format(_T("Error Not Define Initial Step(%d)"), Step);
		break;
	}	
	return IsOK;
}
//-------------------------------------------------------------------------------------//
void CAOIDataCollect::BuildCameraIDList(std::vector<CAMERA_ID> &List)
{
	List.clear();
	const size_t MaxCnt=MAX_CAMERA_COUNT;
	if ( List.size() < MaxCnt )
	{	List.push_back(CAMERA_ID_1); }
	return ;

	if ( List.size() < MaxCnt )
	{	List.push_back(CAMERA_ID_2); }
	if ( List.size() < MaxCnt )
	{	List.push_back(CAMERA_ID_3); }
	if ( List.size() < MaxCnt )
	{	List.push_back(CAMERA_ID_4); }
	if ( List.size() < MaxCnt )
	{	List.push_back(CAMERA_ID_5); }
	if ( List.size() < MaxCnt )
	{	List.push_back(CAMERA_ID_6); }
	if ( List.size() < MaxCnt )
	{	List.push_back(CAMERA_ID_7); }
	if ( List.size() < MaxCnt )
	{	List.push_back(CAMERA_ID_8); }	
	return;
}
