//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SetFovResolutionMode(int Mode)//設定視野解析度模式
{	
#ifdef _DEBUG
	//return true;
#endif//_DEBUG
	TCalibrationParameter &CaliParam=GetCalibrationParameter();
	switch ( Mode )
	{
	case FOV_RESOLUTION_020:
	case FOV_RESOLUTION_025:
	case FOV_RESOLUTION_030:
	case FOV_RESOLUTION_050:
	case FOV_RESOLUTION_055:
	case FOV_RESOLUTION_060:
	case FOV_RESOLUTION_065:
	case FOV_RESOLUTION_070:
	case FOV_RESOLUTION_072:
	case FOV_RESOLUTION_075:
	case FOV_RESOLUTION_078:
	case FOV_RESOLUTION_080:
	case FOV_RESOLUTION_100:
	case FOV_RESOLUTION_110:
	case FOV_RESOLUTION_120:
	case FOV_RESOLUTION_130:
	case FOV_RESOLUTION_150:
	case FOV_RESOLUTION_160:
	case FOV_RESOLUTION_180:
	case FOV_RESOLUTION_200:
	#ifndef OFFLINE_VERSION
		CaliParam.m_ResolutionMode = Mode;
	#else
		CaliParam.m_ResolutionMode_Offline = Mode;
	#endif//OFFLINE_VERSION
		break;
	default:
		break;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
double CAOIDataCollect::GetFovResolutionValue() const//取得視野解析度-理論解析度
{
	const TCalibrationParameter &CaliParam=GetCalibrationParameter();
#ifndef OFFLINE_VERSION
	return GetFovResolutionValueFn(CaliParam.m_ResolutionMode);
#else
	return GetFovResolutionValueFn(CaliParam.m_ResolutionMode_Offline);
#endif//OFFLINE_VERSION
}
//-------------------------------------------------------------------------------------//
double CAOIDataCollect::GetFovResolutionValueFn(int Mode) const//取得視野解析度-理論解析度
{
	double Resolution = 10.0;
	switch ( Mode )
	{
	case FOV_RESOLUTION_020:	Resolution =  2.0;	break;
	case FOV_RESOLUTION_025:	Resolution =  2.5;	break;
	case FOV_RESOLUTION_030:	Resolution =  3.0;	break;
	case FOV_RESOLUTION_050:	Resolution =  5.0;	break;
	case FOV_RESOLUTION_055:	Resolution =  5.5;	break;
	case FOV_RESOLUTION_060:	Resolution =  6.0;	break;
	case FOV_RESOLUTION_065:	Resolution =  6.5;	break;
	case FOV_RESOLUTION_070:	Resolution =  7.0;	break;
	case FOV_RESOLUTION_072:	Resolution =  7.2;	break;
	case FOV_RESOLUTION_075:	Resolution =  7.5;	break;		
	case FOV_RESOLUTION_078:	Resolution =  7.8;	break;
	case FOV_RESOLUTION_080:	Resolution =  8.0;	break;
	case FOV_RESOLUTION_100:	Resolution = 10.0;	break;
	case FOV_RESOLUTION_110:    Resolution = 11.0;  break;
	case FOV_RESOLUTION_120:    Resolution = 12.0;  break;
	case FOV_RESOLUTION_130:    Resolution = 13.0;  break;
	case FOV_RESOLUTION_150:	Resolution = 15.0;	break;
	case FOV_RESOLUTION_160:	Resolution = 16.0;	break;
	case FOV_RESOLUTION_180:	Resolution = 18.0;	break;		
	case FOV_RESOLUTION_200:	Resolution = 20.0;	break;
	default:
		break;
	}	
	return Resolution;
}
