//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::GetFovStageRegionReal(TREGION4D &Region)//取得視野實際範圍
{
	double     FOVWum=0;
	double     FOVHum=0;
	TPOINT3D   StagePos;	
	const bool OfflineMode = GetOfflineMode();

	GetFovSizeReal(FOVWum, FOVHum);
	MotionCtrlPtr->GetCurrentPos(StagePos.x, StagePos.y, StagePos.z, OfflineMode);
	Region.minX = StagePos.x-(FOVWum*0.5);
	Region.maxX = StagePos.x+(FOVWum*0.5);
	Region.minY = StagePos.y-(FOVHum*0.5);
	Region.maxY = StagePos.y+(FOVHum*0.5);	
	return true;
}
