//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapStagePtToCamera(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, const TPOINT2D &Res, const TPOINT2D &StagePos, const TPOINT2D &StageCp, TPOINT2D &ImagePos, const THREAD_ID ThreadID)//機台對應到影像
{
	const double ImageW2 = (double)(ImageW*0.5);
	const double ImageH2 = (double)(ImageH*0.5);	
	const double StageOffsetX = StagePos.x-StageCp.x;
	const double StageOffsetY = StagePos.y-StageCp.y;
	const double ImageOffsetX = StageOffsetX/Res.x;
	const double ImageOffsetY = StageOffsetY/Res.y;	
	const bool SignX = GetStageSignPositiveX();
	const bool SignY = GetStageSignPositiveY();

	if ( false == SignX ) 
	{	ImagePos.x = ImageW2-ImageOffsetX; }
	else
	{	ImagePos.x = ImageW2+ImageOffsetX;	}

	//ImagePos.y = ImageH2+ImageOffsetY;
	if ( true == SignY ) //向上為負
	{	ImagePos.y = ImageH2-ImageOffsetY;	}
	else//向下為負		
	{	ImagePos.y = ImageH2+ImageOffsetY;	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapStageRectToCamera(CAMERA_ID CameraID, const TRECT4D &StageRect, const TPOINT2D &StageCp, TRECT4D &ImageRect, const THREAD_ID ThreadID)//機台對應到影像
{
	TPOINT2D   Res;
	IMAGE_SIZE ImageW=0;
	IMAGE_SIZE ImageH=0;	
	this->GetCameraImageInfo(CameraID, ImageW, ImageH, Res);	
	return MapStageRectToCamera(ImageW, ImageH, Res, StageRect, StageCp, ImageRect, ThreadID);
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapStageRectToCamera(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, const TPOINT2D &Res, const TRECT4D &StageRect, const TPOINT2D &StageCp, TRECT4D &ImageRect, const THREAD_ID ThreadID)//機台對應到影像
{
	const bool SignX = GetStageSignPositiveX();
	const bool SignY = GetStageSignPositiveY();
	const double ImageW2 = (double)(ImageW*0.5);
	const double ImageH2 = (double)(ImageH*0.5);		
	const double StageOffsetX1 = StageRect.left-StageCp.x;
	const double StageOffsetY1 = StageRect.top-StageCp.y;
	const double StageOffsetX2 = StageRect.right-StageCp.x;
	const double StageOffsetY2 = StageRect.bottom-StageCp.y;
	const double ImageOffsetX1 = StageOffsetX1/Res.x;
	const double ImageOffsetY1 = StageOffsetY1/Res.y;
	const double ImageOffsetX2 = StageOffsetX2/Res.x;
	const double ImageOffsetY2 = StageOffsetY2/Res.y;
	const double ImageOffsetXMin = MIN(ImageOffsetX1, ImageOffsetX2);
	const double ImageOffsetXMax = MAX(ImageOffsetX1, ImageOffsetX2);
	const double ImageOffsetYMin = MIN(ImageOffsetY1, ImageOffsetY2);
	const double ImageOffsetYMax = MAX(ImageOffsetY1, ImageOffsetY2);
	if ( false == SignX ) 
	{	
		//ImagePos.x = ImageW2-ImageOffsetX; 
		ImageRect.left = ImageW2-ImageOffsetXMax;
		ImageRect.right = ImageW2-ImageOffsetXMin;
	}
	else
	{	
		//ImagePos.x = ImageW2+ImageOffsetX;	
		ImageRect.left = ImageW2+ImageOffsetXMin;
		ImageRect.right = ImageW2+ImageOffsetXMax;
	}

	//ImagePos.y = ImageH2+ImageOffsetY;
	if ( true == SignY ) //向上為負
	{	
		//ImagePos.y = ImageH2-ImageOffsetY;	
		ImageRect.top = ImageH2-ImageOffsetYMax;
		ImageRect.bottom = ImageH2-ImageOffsetYMin;
	}
	else//向下為負		
	{	
		//ImagePos.y = ImageH2+ImageOffsetY;	
		ImageRect.top = ImageH2+ImageOffsetYMin;
		ImageRect.bottom = ImageH2+ImageOffsetYMax;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapStageRegionToCamera(CAMERA_ID CameraID, const TREGION4D &StageRgn, const TPOINT2D &StageCp, TREGION4D &ImageRgn, const THREAD_ID ThreadID)//機台對應到影像
{
	TPOINT2D   Res;
	IMAGE_SIZE ImageW=0;
	IMAGE_SIZE ImageH=0;	
	this->GetCameraImageInfo(CameraID, ImageW, ImageH, Res);	
	return MapStageRegionToCamera(ImageW, ImageH, Res, StageRgn, StageCp, ImageRgn, ThreadID);
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapStageRegionToCamera(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, const TPOINT2D &Res, const TREGION4D &StageRgn, const TPOINT2D &StageCp, TREGION4D &ImageRgn, const THREAD_ID ThreadID)//機台對應到影像
{
	double ImagePtX1 = 0;
	double ImagePtY1 = 0;
	double ImagePtX2 = 0;
	double ImagePtY2 = 0;
	const bool   SingX = GetStageSignPositiveX();
	const bool   SingY = GetStageSignPositiveY();
	const double ImageW2 = (double)(ImageW*0.5);
	const double ImageH2 = (double)(ImageH*0.5);	
	const double StageOffsetX1 = StageRgn.minX-StageCp.x;
	const double StageOffsetY1 = StageRgn.minY-StageCp.y;
	const double StageOffsetX2 = StageRgn.maxX-StageCp.x;
	const double StageOffsetY2 = StageRgn.maxY-StageCp.y;
	const double ImageOffsetX1 = StageOffsetX1/Res.x;
	const double ImageOffsetY1 = StageOffsetY1/Res.y;
	const double ImageOffsetX2 = StageOffsetX2/Res.x;
	const double ImageOffsetY2 = StageOffsetY2/Res.y;	

	if ( true == SingX )
	{
		ImagePtX1 = ImageW2+ImageOffsetX1;
		ImagePtX2 = ImageW2+ImageOffsetX2;
	}
	else
	{
		ImagePtX1 = ImageW2-ImageOffsetX1;
		ImagePtX2 = ImageW2-ImageOffsetX2;
	}

	if ( true == SingY )
	{
		ImagePtY1 = ImageH2-ImageOffsetY1;
		ImagePtY2 = ImageH2-ImageOffsetY2;
	}
	else
	{
		ImagePtY1 = ImageH2+ImageOffsetY1;
		ImagePtY2 = ImageH2+ImageOffsetY2;	
	}

	ImageRgn.minX = MIN(ImagePtX1, ImagePtX2);
	ImageRgn.maxX = MAX(ImagePtX1, ImagePtX2);
	ImageRgn.minY = MIN(ImagePtY1, ImagePtY2);
	ImageRgn.maxY = MAX(ImagePtY1, ImagePtY2);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapStageCornerToCamera(CAMERA_ID CameraID, const TPOINT2D CornerPt[], const TPOINT2D &StageCp, TPOINT2D ImagePt[], const THREAD_ID ThreadID)//機台4端點對應到影像四點
{
	TPOINT2D   Res;
	IMAGE_SIZE ImageW=0;
	IMAGE_SIZE ImageH=0;	
	this->GetCameraImageInfo(CameraID, ImageW, ImageH, Res);	

	if ( this->MapStagePtToCamera(ImageW, ImageH, Res, CornerPt[0], StageCp, ImagePt[0], ThreadID) == false )
	{
		ImagePt[0].x = ImagePt[1].x = ImagePt[2].x = ImagePt[3].x = 0;
		ImagePt[0].y = ImagePt[1].y = ImagePt[2].y = ImagePt[3].y = 0;		
		return false;
	}
	
	if ( this->MapStagePtToCamera(ImageW, ImageH, Res, CornerPt[1], StageCp, ImagePt[1], ThreadID) == false )
	{
		ImagePt[0].x = ImagePt[1].x = ImagePt[2].x = ImagePt[3].x = 0;
		ImagePt[0].y = ImagePt[1].y = ImagePt[2].y = ImagePt[3].y = 0;		
		return false;
	}

	if ( this->MapStagePtToCamera(ImageW, ImageH, Res, CornerPt[2], StageCp, ImagePt[2], ThreadID) == false )
	{
		ImagePt[0].x = ImagePt[1].x = ImagePt[2].x = ImagePt[3].x = 0;
		ImagePt[0].y = ImagePt[1].y = ImagePt[2].y = ImagePt[3].y = 0;		
		return false;
	}

	if ( this->MapStagePtToCamera(ImageW, ImageH, Res, CornerPt[3], StageCp, ImagePt[3], ThreadID) == false )
	{
		ImagePt[0].x = ImagePt[1].x = ImagePt[2].x = ImagePt[3].x = 0;
		ImagePt[0].y = ImagePt[1].y = ImagePt[2].y = ImagePt[3].y = 0;		
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapStageCornerToCamera(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, const TPOINT2D &Res, const TPOINT2D CornerPt[], const TPOINT2D &StageCp, TPOINT2D ImagePt[], const THREAD_ID ThreadID)//機台4端點對應到影像四點
{
	if ( this->MapStagePtToCamera(ImageW, ImageH, Res, CornerPt[0], StageCp, ImagePt[0], ThreadID) == false )
	{
		ImagePt[0].x = ImagePt[1].x = ImagePt[2].x = ImagePt[3].x = 0;
		ImagePt[0].y = ImagePt[1].y = ImagePt[2].y = ImagePt[3].y = 0;		
		return false;
	}
	
	if ( this->MapStagePtToCamera(ImageW, ImageH, Res, CornerPt[1], StageCp, ImagePt[1], ThreadID) == false )
	{
		ImagePt[0].x = ImagePt[1].x = ImagePt[2].x = ImagePt[3].x = 0;
		ImagePt[0].y = ImagePt[1].y = ImagePt[2].y = ImagePt[3].y = 0;		
		return false;
	}

	if ( this->MapStagePtToCamera(ImageW, ImageH, Res, CornerPt[2], StageCp, ImagePt[2], ThreadID) == false )
	{
		ImagePt[0].x = ImagePt[1].x = ImagePt[2].x = ImagePt[3].x = 0;
		ImagePt[0].y = ImagePt[1].y = ImagePt[2].y = ImagePt[3].y = 0;		
		return false;
	}

	if ( this->MapStagePtToCamera(ImageW, ImageH, Res, CornerPt[3], StageCp, ImagePt[3], ThreadID) == false )
	{
		ImagePt[0].x = ImagePt[1].x = ImagePt[2].x = ImagePt[3].x = 0;
		ImagePt[0].y = ImagePt[1].y = ImagePt[2].y = ImagePt[3].y = 0;		
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapStageCornerToCameraPt(CAMERA_ID CameraID, const TPOINT2D CornerPt[],  const TPOINT2D &StageCp, POINT ImagePt[], const THREAD_ID ThreadID)//機台4端點對應到影像四點
{
	TPOINT2D ImagePtd[4];	
	ImagePt[0].x = ImagePt[1].x = ImagePt[2].x = ImagePt[3].x = 0;
	ImagePt[0].y = ImagePt[1].y = ImagePt[2].y = ImagePt[3].y = 0;

	if ( this->MapStageCornerToCamera(CameraID, CornerPt, StageCp, ImagePtd, ThreadID) == false )
	{	return false; }

	
	//使用四捨五入會有跳動的問題	
	/*
	ImagePt[0].x = JetAPI::Round(ImagePtd[0].x);
	ImagePt[0].y = JetAPI::Round(ImagePtd[0].y);

	ImagePt[1].x = JetAPI::Round(ImagePtd[1].x);
	ImagePt[1].y = JetAPI::Round(ImagePtd[1].y);

	ImagePt[2].x = JetAPI::Round(ImagePtd[2].x);
	ImagePt[2].y = JetAPI::Round(ImagePtd[2].y);

	ImagePt[3].x = JetAPI::Round(ImagePtd[3].x);
	ImagePt[3].y = JetAPI::Round(ImagePtd[3].y);
	*/
	
	
	//相同方向使用Ceil，相反方向使用Floor
	ImagePt[0].x = JetAPI::Ceil(ImagePtd[0].x);
	ImagePt[0].y = JetAPI::Floor(ImagePtd[0].y);

	ImagePt[1].x = JetAPI::Ceil(ImagePtd[1].x);
	ImagePt[1].y = JetAPI::Floor(ImagePtd[1].y);

	ImagePt[2].x = JetAPI::Ceil(ImagePtd[2].x);
	ImagePt[2].y = JetAPI::Floor(ImagePtd[2].y);

	ImagePt[3].x = JetAPI::Ceil(ImagePtd[3].x);
	ImagePt[3].y = JetAPI::Floor(ImagePtd[3].y);
	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapCameraPtToStage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, const TPOINT2D &Res, const TPOINT2D &ImagePt, const TPOINT2D &StageCp, TPOINT2D &StagePt, const THREAD_ID ThreadID)//相機影像對應到機台
{	
	const double ImageW2 = ImageW/2;
	const double ImageH2 = ImageH/2;	

	const double ImageOffsetX = ImagePt.x-ImageW2;
	const double ImageOffsetY = ImagePt.y-ImageH2;
	const double StageOffsetX = ImageOffsetX*Res.x;
	const double StageOffsetY = ImageOffsetY*Res.y;
	const bool SignX = GetStageSignPositiveX();
	const bool SignY = GetStageSignPositiveY();

	if ( false == SignX )
	{	StagePt.x = StageCp.x-StageOffsetX; }
	else
	{	StagePt.x = StageCp.x+StageOffsetX; }

	//StagePt.y = StageCp.y+StageOffsetY;
	if ( true == SignY )
	{	//向上為負
		StagePt.y = StageCp.y-StageOffsetY; 
	}
	else
	{	//向下為負
		StagePt.y = StageCp.y+StageOffsetY; 
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapCameraRectToStage(CAMERA_ID CameraID, const TRECT4D &ImageRect, const TPOINT2D &StageCp, TRECT4D &StageRect, const THREAD_ID ThreadID)//相機影像對應到機台
{
	double     ResX=10;
	double     ResY=10;	
	IMAGE_SIZE ImageW=0;
	IMAGE_SIZE ImageH=0;	
	this->GetCameraImageInfo(CameraID, ImageW, ImageH, ResX, ResY);	
	
	const double ImageW2 = (double)(ImageW/2.0);
	const double ImageH2 = (double)(ImageH/2.0);	

	const double ImageOffsetX1 = ImageRect.left-ImageW2;
	const double ImageOffsetY1 = ImageRect.top-ImageH2;
	const double ImageOffsetX2 = ImageRect.right-ImageW2;
	const double ImageOffsetY2 = ImageRect.bottom-ImageH2;
	const double StageOffsetX1 = ImageOffsetX1*ResX;
	const double StageOffsetY1 = ImageOffsetY1*ResY;
	const double StageOffsetX2 = ImageOffsetX2*ResX;
	const double StageOffsetY2 = ImageOffsetY2*ResY;
	const bool SignX = GetStageSignPositiveX();
	const bool SignY = GetStageSignPositiveY();

	if ( false == SignX )
	{	
		StageRect.left = StageCp.x-StageOffsetX1;
		StageRect.right = StageCp.x-StageOffsetX2;
	}
	else
	{
		StageRect.left = StageCp.x+StageOffsetX1;
		StageRect.right = StageCp.x+StageOffsetX2;		
	}

	if ( true == SignY )
	{	//向上為負
		StageRect.top   = StageCp.y-StageOffsetY1;
		StageRect.bottom = StageCp.y-StageOffsetY2;
	}
	else
	{	//向下為負
		StageRect.top   = StageCp.y+StageOffsetY1;
		StageRect.bottom = StageCp.y+StageOffsetY2;		
	}
	return true;
}
