//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapCameraRegionToStage(CAMERA_ID CameraID, const TREGION4D &ImageRgn, const TPOINT2D &StageCp, TREGION4D &StageRgn, const THREAD_ID ThreadID)//相機影像對應到機台
{	
	double     ResX=10;
	double     ResY=10;	
	IMAGE_SIZE ImageW=0;
	IMAGE_SIZE ImageH=0;
	this->GetCameraImageInfo(CameraID, ImageW, ImageH, ResX, ResY);	
	
	const double ImageW2 = (double)(ImageW/2.0);
	const double ImageH2 = (double)(ImageH/2.0);	

	const double ImageOffsetX1 = ImageRgn.minX-ImageW2;
	const double ImageOffsetY1 = ImageRgn.minY-ImageH2;
	const double ImageOffsetX2 = ImageRgn.maxX-ImageW2;
	const double ImageOffsetY2 = ImageRgn.maxY-ImageH2;
	const double StageOffsetX1 = ImageOffsetX1*ResX;
	const double StageOffsetY1 = ImageOffsetY1*ResY;
	const double StageOffsetX2 = ImageOffsetX2*ResX;
	const double StageOffsetY2 = ImageOffsetY2*ResY;
	const bool SignX = GetStageSignPositiveX();
	const bool SignY = GetStageSignPositiveY();

	if ( false == SignX )
	{	
		StageRgn.minX = StageCp.x-StageOffsetX1;
		StageRgn.maxX = StageCp.x-StageOffsetX2;
	}
	else
	{
		StageRgn.minX = StageCp.x+StageOffsetX1;
		StageRgn.maxX = StageCp.x+StageOffsetX2;
	}
	if ( true == SignY )
	{	//向上為負
		StageRgn.minY = StageCp.y-StageOffsetY1;
		StageRgn.maxY = StageCp.y-StageOffsetY2;
	}
	else
	{	//向下為負
		StageRgn.minY = StageCp.y+StageOffsetY1;
		StageRgn.maxY = StageCp.y+StageOffsetY2;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapCameraRegionToStage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, const TPOINT2D &Res, const TREGION4D &ImageRgn, const TPOINT2D &StageCp, TREGION4D &StageRgn, const THREAD_ID ThreadID)//相機影像對應到機台
{		
	const double ImageW2 = (double)(ImageW/2.0);
	const double ImageH2 = (double)(ImageH/2.0);
	const double ImageOffsetX1 = ImageRgn.minX-ImageW2;
	const double ImageOffsetY1 = ImageRgn.minY-ImageH2;
	const double ImageOffsetX2 = ImageRgn.maxX-ImageW2;
	const double ImageOffsetY2 = ImageRgn.maxY-ImageH2;
	const double StageOffsetX1 = ImageOffsetX1*Res.x;
	const double StageOffsetY1 = ImageOffsetY1*Res.y;
	const double StageOffsetX2 = ImageOffsetX2*Res.x;
	const double StageOffsetY2 = ImageOffsetY2*Res.y;
	const bool SignX = GetStageSignPositiveX();
	const bool SignY = GetStageSignPositiveY();

	if ( false == SignX )
	{	
		StageRgn.minX = StageCp.x-StageOffsetX1;
		StageRgn.maxX = StageCp.x-StageOffsetX2;
	}
	else
	{
		StageRgn.minX = StageCp.x+StageOffsetX1;
		StageRgn.maxX = StageCp.x+StageOffsetX2;
	}
	if ( true == SignY )
	{	//向上為負
		StageRgn.minY = StageCp.y-StageOffsetY1;
		StageRgn.maxY = StageCp.y-StageOffsetY2;
	}
	else
	{	//向下為負
		StageRgn.minY = StageCp.y+StageOffsetY1;
		StageRgn.maxY = StageCp.y+StageOffsetY2;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapCameraPtToStage(CAMERA_ID CameraID, const TPOINT2D &ImagePt, const TPOINT2D &StageCp, TPOINT2D &StagePt, const THREAD_ID ThreadID)//座標轉換至機台座標係-2
{
	TPOINT2D   Res;
	IMAGE_SIZE ImageW=0;
	IMAGE_SIZE ImageH=0;	
	this->GetCameraImageInfo(CameraID, ImageW, ImageH, Res);	
	return MapCameraPtToStage(ImageW, ImageH, Res, ImagePt, StageCp, StagePt, ThreadID);	
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapCameraCornerToStage(CAMERA_ID CameraID, const TPOINT2D CornerPt[], const TPOINT2D &StageCp, TPOINT2D StagePt[], const THREAD_ID ThreadID)//相機影像4點對應到機台4點
{
	TPOINT2D     Res;
	IMAGE_SIZE   ImageW=0;
	IMAGE_SIZE   ImageH=0;	
	this->GetCameraImageInfo(CameraID, ImageW, ImageH, Res);	
	if ( this->MapCameraPtToStage(ImageW, ImageH, Res, CornerPt[0], StageCp, StagePt[0], ThreadID) == false )
	{
		StagePt[0].x = StagePt[1].x = StagePt[2].x = StagePt[3].x = 0;
		StagePt[0].y = StagePt[1].y = StagePt[2].y = StagePt[3].y = 0;		
		return false;
	}

	if ( this->MapCameraPtToStage(ImageW, ImageH, Res, CornerPt[1], StageCp, StagePt[1], ThreadID) == false )
	{
		StagePt[0].x = StagePt[1].x = StagePt[2].x = StagePt[3].x = 0;
		StagePt[0].y = StagePt[1].y = StagePt[2].y = StagePt[3].y = 0;		
		return false;
	}

	if ( this->MapCameraPtToStage(ImageW, ImageH, Res, CornerPt[2], StageCp, StagePt[2], ThreadID) == false )
	{
		StagePt[0].x = StagePt[1].x = StagePt[2].x = StagePt[3].x = 0;
		StagePt[0].y = StagePt[1].y = StagePt[2].y = StagePt[3].y = 0;		
		return false;
	}

	if ( this->MapCameraPtToStage(ImageW, ImageH, Res, CornerPt[3], StageCp, StagePt[3], ThreadID) == false )
	{
		StagePt[0].x = StagePt[1].x = StagePt[2].x = StagePt[3].x = 0;
		StagePt[0].y = StagePt[1].y = StagePt[2].y = StagePt[3].y = 0;		
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapImageOffsetToCad(const TPOINT2D &ImgPos, const TPOINT2D &Res, TPOINT2D &CadPos)//影像偏差量轉成Cad偏差量
{
	CadPos.x =  (ImgPos.x*Res.x);
	CadPos.y = -(ImgPos.y*Res.y);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapStageAngleToCad(double StageAngle, double &CadAngle)
{
	const bool SignX = GetStageSignPositiveX();
	const bool SignY = GetStageSignPositiveY();
	CadAngle = StageAngle;
	if ( false == SignX )	
	{	CadAngle = JetAPI::MirrorXAxisAngle(CadAngle);	}
	if ( false == SignY )	
	{	CadAngle = JetAPI::MirrorYAxisAngle(CadAngle);	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapStageOffsetPtToCad(const TPOINT2D &PosStage, TPOINT2D &PosCad)
{
	const bool SignX = GetStageSignPositiveX();
	const bool SignY = GetStageSignPositiveY();
	if ( true == SignX )
	{	PosCad.x =  PosStage.x;	}
	else
	{	PosCad.x = -PosStage.x;	}
	if ( true == SignY )
	{	PosCad.y = PosStage.y;	}
	else
	{	PosCad.y = -PosStage.y;	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapStageOffsetRgnToCad(const TREGION4D &RgnStage, TREGION4D &RgnCad)
{
	const bool SignX = GetStageSignPositiveX();
	const bool SignY = GetStageSignPositiveY();
	if ( true == SignX )
	{	
		RgnCad.minX =  MIN(RgnStage.minX, RgnStage.maxX);
		RgnCad.maxX =  MAX(RgnStage.minX, RgnStage.maxX);
	}
	else
	{	
		RgnCad.minX = MIN(-RgnStage.minX, -RgnStage.maxX);
		RgnCad.maxX = MAX(-RgnStage.minX, -RgnStage.maxX);
	}
	if ( true == SignY )
	{	
		RgnCad.minY = MIN(RgnStage.minY, RgnStage.maxY);
		RgnCad.maxY = MAX(RgnStage.minY, RgnStage.maxY);
	}
	else
	{	
		RgnCad.minY = MIN(-RgnStage.minY, -RgnStage.maxY);
		RgnCad.maxY = MAX(-RgnStage.minY, -RgnStage.maxY);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MapCadAngleToStage(double CadAngle, double &StageAngle)
{
	const bool SignX = GetStageSignPositiveX();
	const bool SignY = GetStageSignPositiveY();
	StageAngle = CadAngle;
	if ( false == SignX )	
	{	StageAngle = JetAPI::MirrorXAxisAngle(StageAngle);	}

	if ( false == SignY )	
	{	StageAngle = JetAPI::MirrorYAxisAngle(StageAngle);	}
	return true;
}
