//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ReleaseResource()//釋放資源
{
	//設定取像完畢, 避免其他執行緒卡住
	CString str;
	CString AppName = GetAppFilename();//::AfxGetAppName();	
	CString strVersion = m_SystemParameter.m_AppVersion;
	SaveAOIMonitorStatus(MONITOR_STATUS_CLOSE, NULL);

	SaveInitialReleaseLog(_T("Start to Clear Temp Folder"));
	str = GetAOITempDirectory();
	JetAPI::ClearFolder(str);
	
	SetIsSystemReleased(true);
	SaveInitialReleaseLog(_T("Start to Clear Temp Wnd List"));
	ClearTempWndList();	

	SaveInitialReleaseLog(_T("Start to Destory Model Pre View Ptr"));
	DestroyModelPreViewPtr();

	SaveInitialReleaseLog(_T("Start to Release Model UniFrame List"));
	ReleaseModelUniFrameList();

	SaveInitialReleaseLog(_T("Start to Release Field UniFrame List"));
	ReleaseFieldUniFrameList();	

	SaveInitialReleaseLog(_T("Start to Clear Land ProjectList LA"));
	ClearLaneProjectList_LA();

	SaveInitialReleaseLog(_T("Start to Clear Land ProjectList LB"));
	ClearLaneProjectList_LB();

	SaveInitialReleaseLog(_T("Start to Clear ProjectList"));
	ClearProjectPtrList();	

	SaveInitialReleaseLog(_T("Start to Clear Open Project BarcodeList"));
	ClearOpenProjectBarcodeList();

	SaveInitialReleaseLog(_T("Start to Destroy Open Project Obj"));
	if ( NULL != m_OpenProjectProjectObj )
	{	AOIObjManager.DestroyProjectObj(m_OpenProjectProjectObj);  }
	m_OpenProjectProjectObj = NULL;

	SaveInitialReleaseLog(_T("Start to Destroy Model Pen"));
	CAOIModel::DestroyModelPen();

	SaveInitialReleaseLog(_T("Start to Delete All Thread"));
	DeleteAllThread();	

	SaveInitialReleaseLog(_T("Start to Delete Fd Lock"));
	CAOIFd::DeleteFdLock();

	SaveInitialReleaseLog(_T("Start to Delete Rgn Lock"));
	CAOIRgn::DeleteRgnLock();

	SaveInitialReleaseLog(_T("Start to Delete Fov Lock"));
	CAOIFov::DeleteFovLock();

	SaveInitialReleaseLog(_T("Start to Delete Mark Lock"));
	CAOIMark::DeleteMarkLock();

	SaveInitialReleaseLog(_T("Start to Delete Slice Lock"));
	CAOISlice::DeleteSliceLock();	

	SaveInitialReleaseLog(_T("Start to Delete Field Lock"));
	CAOIField::DeleteFieldLock();	

	SaveInitialReleaseLog(_T("Start to Delete Frame Lock"));
	CAOIFrame::DeleteFrameLock();	

	SaveInitialReleaseLog(_T("Start to Release Frame Share Buffer"));
	CAOIFrame::ReleaseFrameShareBuffer();

	SaveInitialReleaseLog(_T("Start to Delete DTK Barcode Lock"));
	CDtkBarcode::DeleteDTKBarcodeLock();	

	SaveInitialReleaseLog(_T("Start to Delete Honeywell Barcode Lock"));
	HoneywellBarcodeSdk.DeleteHonBarcodeLock();

#ifdef ZLIB_USE
	SaveInitialReleaseLog(_T("Start to Delete Jet Zip Lock"));
	CJetZip::DeleteJetZipLock();
#endif//

	SaveInitialReleaseLog(_T("Start to Release 3D Unwarpping All Buffer"));
	Calc3DUnWarpping.ReleaseAllBuffer();	

	str.Format(_T("=========%s End (Version:%s)=========="), AppName, strVersion);
	ShowMessage(0,  MSG_MB_OK, MSG_MB_ICONSTOP, MSG_MB_DEFBUTTON1, str, true, false);
	SaveLogMessage(str);	
	LogOperCtrl.SaveLogOper_SystemContent(str);
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	SetIsSystemReleasedDone(true);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::RegisterLogFile()//註冊訊息檔案
{
	CString strTime;
	bool    bSaveHeader=true;
	CString Vendor = AOI3D_VENDOR;//_T("JET");
	const TSystemParameter &SysParam=m_SystemParameter;
	CString HostIP = m_SystemParameter.m_IPHostComputer;
	CString LogFolder, LogFilename, LogExtName, LogBackup;
	JetAPI::GetTime(strTime, CTime::GetCurrentTime());

	LogManager.StopLogManagerThread(true);
	bSaveHeader=true;
	LogFolder = GetAOILogDirectory();
#ifndef OFFLINE_VERSION
	LogFilename = _T("Log_Online");
#else
	LogFilename = _T("Log_Offline");
#endif//OFFLINE_VERSION
	LogExtName = _T("TXT");
	LogBackup.Format(_T("[%s]-[%s]"), HostIP, Vendor);
	m_LogIdx_LogFile = LogManager.AddLogFile(LogFolder, LogFilename, LogExtName, LogBackup, CLogNode::LOG_FILENAME_BY_DATE, bSaveHeader);

	LogFolder = GetAOILogDirectory();
	bSaveHeader=true;
	LogFilename = AOI_MOVING_TIME_FILENAME;
	LogExtName = _T("TXT");
	LogBackup = _T("");
	m_LogIdx_MovingTime = LogManager.AddLogFile(LogFolder, LogFilename, LogExtName, LogBackup, CLogNode::LOG_FILENAME_FIX, bSaveHeader);

	LogFolder = GetAOIDirectory();
	bSaveHeader=true;
	LogFilename = CURRENT_PROCESS_FILENAME;
	LogExtName = _T("TXT");	
	LogBackup.Format(_T("[%s]-[%s]"), HostIP, Vendor);
	m_LogIdx_CurrentProcess = LogManager.AddLogFile(LogFolder, LogFilename, LogExtName, LogBackup, CLogNode::LOG_FILENAME_FIX, bSaveHeader);

	//訊息操作
	bSaveHeader=false;	
	LogFolder = GetAOILogOperDirectory();
	::CreateDirectory(LogFolder, NULL);
	LogFilename = _T("LogOper");
	LogExtName = _T("TXT");	
	LogBackup = _T("");
	m_LogIdx_LogOper = LogManager.AddLogFile(LogFolder, LogFilename, LogExtName, LogBackup, CLogNode::LOG_FILENAME_BY_DATE, bSaveHeader);

	//機台中央控制訊息
	bSaveHeader=true;
	LogFolder = GetAOILogControlCenterDirectory();
	LogFilename = _T("ControlCenter");
	LogExtName = _T("TXT");	
	LogBackup.Format(_T("[%s]-[%s]"), HostIP, Vendor);
	m_LogIdx_ControlCenter = LogManager.AddLogFile(LogFolder, LogFilename, LogExtName, LogBackup, CLogNode::LOG_FILENAME_BY_DATE, bSaveHeader);	

	//客戶訊息
	bSaveHeader=true;
	LogFolder = SysParam.m_CustomerLogFolder;
	LogFilename = _T("Log");
	LogExtName = _T("TXT");	
	LogBackup.Format(_T("[%s]-[%s]"), HostIP, Vendor);
	if ( LogFolder.CompareNoCase(GetAOILogDirectory()) == 0 )
	{	m_LogIdx_CustomerLogFile = -1; }
	else
	{	m_LogIdx_CustomerLogFile= LogManager.AddLogFile(LogFolder, LogFilename, LogExtName, LogBackup, CLogNode::LOG_FILENAME_BY_DATE, bSaveHeader);		}	

	MotionCtrlPtr->RegisterMotionCurrentProcessFile();
	CameraCtrl.RegisterAllCameraCurrentProcessFile();
	AOIExceptionCodeCtrl.RegisterAOIExceptionLogFile();

	BackupMovingTimeMsg();
	BackupCurrentProcess();
	LogManager.SetThreadDwellTime(250);
	LogManager.StartLogManagerThread(true);
	return true;
}
