//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckObjListInitialized()//確認Obj列表是否初始化
{	
	size_t       i=0, j=0;	
	size_t       FieldRgnCount=0;
	size_t       FrameSliceCount=0;	
	CAOIRgn*     RgnPtr = NULL;
	CAOIFov*     FovPtr = NULL;
	CAOISlice*   SlicePtr = NULL;	
	CAOIField*   FieldPtr = NULL;
	CAOIFrame*   FramePtr = NULL;
	
	REGION_CALC_STATE    RgnCalcState;
	SLICE_FILL_STATE     SliceFillState;	
	FRAME_MERGE_STATE    FrameMergeStage;
	FIELD_CALC_STATE     FieldCalcState;
	const bool   OfflineMode = GetOfflineMode();
	const size_t RgnCount = m_RgnPtrList.size();
	const size_t FovCount = m_FovPtrList.size();
	const size_t SliceCount = m_SlicePtrList.size();	
	const size_t FieldCount = m_FieldPtrList.size();
	const size_t FrameCount = m_FramePtrList.size();
	
	for ( i=0; i<RgnCount; i++ )
	{
		RgnPtr = m_RgnPtrList[i];
		if ( NULL == RgnPtr ) { continue; }
		RgnCalcState = RgnPtr->GetRgnCalcState();
		if ( REGION_CALC_NONE != RgnCalcState )
		{
			this->m_ErrorString.Format(_T("Error, Rgn Calc State is not Initialized [%d]"), i+1);
			return false; 
		}
	}

	for ( i=0; i<SliceCount; i++ )
	{
		SlicePtr = m_SlicePtrList[i];
		if ( NULL == SlicePtr ) { continue; }
		SliceFillState = SlicePtr->GetSliceFillState();
		if ( SLICE_FILL_NONE != SliceFillState )
		{
			this->m_ErrorString.Format(_T("Error, Slice Fill State is not Initialized [%d]"), i+1);
			return false; 
		}
	}

	for ( i=0; i<FrameCount; i++ )
	{
		FramePtr = m_FramePtrList[i];
		if ( NULL == FramePtr ) { continue; }
		FrameMergeStage = FramePtr->GetFrameMergeState();
		if ( FRAME_MERGE_NONE!=FrameMergeStage && FRAME_MERGE_DONE!=FrameMergeStage )
		{
			this->m_ErrorString.Format(_T("Error, Frame Merge State is not Initialized [%d]"), i+1);
			return false; 
		}
		if ( false == OfflineMode )
		{
			FrameSliceCount = FramePtr->GetFrameSliceCount();
			if ( 1 > FrameSliceCount )
			{
				this->m_ErrorString.Format(_T("Error, Frame has no slice count [%d]"), i+1);
				return false; 
			}
			for ( j=0; j<FrameSliceCount; j++ )
			{
				SlicePtr = FramePtr->GetFrameSlicePtr(j, false);
				j = j;
			}
		}	
	}

	for ( i=0; i<FieldCount; i++ )
	{
		FieldPtr = m_FieldPtrList[i];
		if ( NULL == FieldPtr ) { continue; }
		FieldCalcState = FieldPtr->GetFieldCalcState();
		if ( FIELD_CALC_NONE != FieldCalcState )
		{
			this->m_ErrorString.Format(_T("Error, Field Calc State is not Initialized [%d]"), i+1);
			return false; 
		}
		/*
		FieldRgnCount = FieldPtr->GetFieldRgnPtrCount();
		if ( 0 == FieldRgnCount )
		{
			this->m_ErrorString.Format(_T("Error, Field Rgn Count is Zero [%d]"), i+1);
			return false; 
		}
		*/
	}
	return true;	
}
