//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecAutoRetry(TASK_MODE &TaskMode)//執行自動重測
{
	CString       str = GetErrorString();
	CAOIProject  *ProjectPtr = GetActiveProject();
	const LANE_ID LaneID = GetActiveLaneID();	
	const int AutoRetryCount = GetAutoRetryCount();
	const int AutoRetryMaxCount = GetSystemParameter().m_AutoRetryMaxCount;	

	SaveLogMessage(str);
	SaveMovingTimeMsg(str);
	ShowMessage(0, MSG_MB_OK, MSG_MB_ICONSTOP, MSG_MB_DEFBUTTON1, str, true, false);			

	str.Format(_T("Error, Auto Retry Count=%d/%d"), AutoRetryCount+1, AutoRetryMaxCount);
	SaveLogMessage(str);
	SaveMovingTimeMsg(str);
	ShowMessage(0, MSG_MB_OK, MSG_MB_ICONSTOP, MSG_MB_DEFBUTTON1, str, true, false);
	
	for ( int i=0; i<DLP_CHANNEL_COUNT; i++ )
	{
		CString strKey;
		bool bDlpReset=LightCtrlBoard.CheckDLPNotReadySignalFault(i);
		if ( false == bDlpReset ) { continue; }		
		LIGHT_3D_CAST_ID CastID=Light3DCtrl.GetLight3DCastIDByIndex(i);			
		LIGHT_3D_CLS_PTR CastPtr=Light3DCtrl.GetLight3DCastPtr(CastID);
		if ( NULL == CastPtr ) { continue; }

		strKey.Format(_T("Exec DLP%d Software Reset"), i+1);

		str = strKey;
		SaveLogMessage(str);
		ShowMessage(0, MSG_MB_OK, MSG_MB_ICONSTOP, MSG_MB_DEFBUTTON1, str, true, false);
		if ( CastPtr->ExecDLPSoftwareReset(3000) == false )
		{
			CString Err=CastPtr->GetErrorString();
			str.Format(_T("%s Fault[%s]"), strKey, Err);
			SaveLogMessage(str);
			ShowMessage(0, MSG_MB_OK, MSG_MB_ICONSTOP, MSG_MB_DEFBUTTON1, str, true, false);
		}
	}	

	AddAutoRetryCount();			
	SetIsSystemException(false);
	SetIsGetSystemExceptionMsg(false);	
	LightCtrlBoard.ClearAll();
	SetIsNeedResetLightCtrlDLP(true);
	SetIsNeedGrabFiducial(true, LaneID);
	SetOnlineStateMode(ONLINE_STATE_INSPECTION_STOP);
	SetOnlineStateMode_Lane(ONLINE_STATE_INSPECTION_STOP, LaneID);	

	const ONLINE_STATE_MODE NewOnlineStateMode = ONLINE_STATE_INSPECTION_START;
	if ( NULL != ProjectPtr )
	{	
		ProjectPtr->SetProjectIsException(false);	
		ProjectPtr->IdleProjectSaveFieldThread(true);
		ProjectPtr->IdleProjectCopyFileThread(true);		
	}	
	if ( TASK_TUNING_PROJECT == TaskMode )
	{
		str.Format(_T("Start to Auto Retry Count=%d/%d [Tuning Project]\n"), AutoRetryCount+1, AutoRetryMaxCount);
		SaveErrMessage(str);
		SetIsAskRepeatTest(false);
		//PostMainFrameWndMessage(WM_COMMAND, ID_TUNE_INSPECTION, NULL); 
		SetIsLockUIWnd(true);
		SetTaskMode(TaskMode);
		SetIsOnAutoRetry(true);
		SetInspectingMode(INSPECTING_TUNNING);		
		SetOnlineStateMode(NewOnlineStateMode);		
		SetOnlineStateMode_Lane(NewOnlineStateMode, LaneID);	
		ProjectPtr->SetProjectOnlineStateMode(NewOnlineStateMode);
		PostMainFrameWndMessage(MSG_EDIT_MAIN_VIEW_WND, WPARAM_SET_DRAW_PROJECT_MODE, LPARAM_DRAW_PROJECT_MODE_INSPECTING);				
		if ( ExecInspectionProjectTuning() == false )
		{			
			SetIsLockUIWnd(false);
			SetIsOnAutoRetry(false);
			PostMainFrameWndMessage(MSG_EDIT_MAIN_VIEW_WND, WPARAM_SET_DRAW_PROJECT_MODE, LPARAM_DRAW_PROJECT_MODE_NORMAL);
			return false;	
		}
	}		
	if ( TASK_INSPECT_PROJECT == TaskMode )
	{
		str.Format(_T("Start to Auto Retry Count=%d/%d [Inspect Project]\n"), AutoRetryCount+1, AutoRetryMaxCount);
		SaveErrMessage(str);
		SaveMovingTimeMsg(str);
		//PostMainFrameWndMessage(WM_COMMAND, ID_ONLINE_RUN, NULL);//訊號會掉		
		if ( SetupAllLightSetting() == false )
		{	return false;	}
		SetIsLockUIWnd(true);
		SetTaskMode(TaskMode);
		SetIsOnAutoRetry(true);
		SetInspectingMode(INSPECTING_ONLINE);
		SetOnlineStateMode(NewOnlineStateMode);
		SetOnlineStateMode_Lane(NewOnlineStateMode, LaneID);	
		ProjectPtr->SetProjectOnlineStateMode(NewOnlineStateMode);		
		PostMainFrameWndMessage(MSG_EDIT_MAIN_VIEW_WND, WPARAM_SET_DRAW_PROJECT_MODE, LPARAM_DRAW_PROJECT_MODE_INSPECTING);
		if ( ExecInspectionProjectOnline() == false )
		{
			SetIsLockUIWnd(false);
			SetIsOnAutoRetry(false);
			PostMainFrameWndMessage(MSG_EDIT_MAIN_VIEW_WND, WPARAM_SET_DRAW_PROJECT_MODE, LPARAM_DRAW_PROJECT_MODE_NORMAL);
			return false;
		}		
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecSystemException(WPARAM wParam, LPARAM lParam)//解出系統異常訊息
{
	//LockThread();
	const bool IsGetSystemExceptionMsg = GetIsGetSystemExceptionMsg();		
	if ( true == IsGetSystemExceptionMsg ) 
	{	
		//UnlockThread();
		return true; 
	}

	const bool IsOnlineRunLock=GetIsOnlineRunLock();
	if ( true == IsOnlineRunLock )
	{	return true; }	
	const bool OnlineRunLock=CheckIsOnlineRunLock();
	if ( true == OnlineRunLock )
	{
		CString ErrorString;		
		DecodeSystemException(wParam, lParam, ErrorString);	
		SetIsOnlineRunLock(true);
		SetErrorString_OnlineRun(ErrorString);
		return true;
	}	

	TASK_MODE     TaskMode = GetTaskMode();
	//const LANE_ID LaneID = GetActiveLaneID();	
	const LANE_ID LaneID = GetExceptionLaneID();
	CAOIProject  *ProjectPtr = GetActiveProject();	
	ONLINE_STATE_MODE OnlineStateMode = GetOnlineStateMode();	
	const bool NeedAutoRetry = CheckNeedAutoRetry(OnlineStateMode, TaskMode);//注意要在系統復歸之前

	SetIsSystemException(true);
	SetIsGetSystemExceptionMsg(true);	

	//::Sleep(2500);//暫停一下
	//UnlockThread();
	::Sleep(1000);//暫停一下
	
	CString str;
	CString ErrorString;
	DecodeSystemException(wParam, lParam, ErrorString);	
	IdleAllThread(true);
	//SaveGrabListStats();
	RemoveAllPtrList();		
	AOIExceptionCodeCtrl.SetAOIExceptionCode_Others(ErrorString);
	AOI_EXCEPTION_CODE ExceptionCode=AOIExceptionCodeCtrl.GetAOILastExceptionCode();	
#ifdef AOI_EXCEPTION_CODE_USE
	str = ErrorString;
	ErrorString.Format(_T("%s[Code:%05d]"), str, ExceptionCode);
#endif//AOI_EXCEPTION_CODE_USE	
	SetErrorString_Locked(ErrorString);

	if ( NULL != ProjectPtr ) 
	{			
		ProjectPtr->ClearProjectFdImageBuffer();
		ProjectPtr->ClearProjectAllTempObjects(); 
		ProjectPtr->RemoveProjectTestTrackFolder();
		ProjectPtr->SetProjectConveyerPreRunRunning(false);
		ProjectPtr->SetProjectOnlineStateMode(ONLINE_STATE_INSPECTION_STOP);
	}	
	if ( true == NeedAutoRetry )
	{
		if ( ExecAutoRetry(TaskMode) == true ) 
		{	return true; }
	}
	PlcCtrlPtr->TurnOnStageAlarm(LaneID);
	PlcCtrlPtr->UpdateTowerLightState_Stop();
	SaveLogMessage(m_ErrorString);
	ExecMESComm_SetAOIExceptionCode(m_ErrorString);
	ShowMessage(0, MSG_MB_OK, MSG_MB_ICONSTOP, MSG_MB_DEFBUTTON1, m_ErrorString, true, true);	
	SetAutoRetryCount(0);
	SetIsOnAutoRetry(false);
	SetIsEnableAutoRetry(false);
	SetIsIgnoreAutoRetry(false);

	BackupMovingTimeMsg_Error();
	BackupCurrentProcess_Error();
	TurnOnConveyerSensorPower();
	PlcCtrlPtr->TurnOffStageAlarm(LaneID);
	PlcCtrlPtr->WriteOnInspection(LaneID, false);	
	ExecBarcodeDeviceEndReading(LaneID);

	ClearMarkObjList();

	SetIsLockUIWnd(false);
	SetIsAllCalcThreadStop(false);
	//SetIsSystemException(false);	
	SetOnlineTaskCancel(true);
	SetOnlineStateNode(_T(""), LANE_ID_A);
	SetOnlineStateNode(_T(""), LANE_ID_B);
	SetSaveModelBkImage(false);
	SetIsNeedGrabFiducial(true);	
	SetIsNeedResetOKNGSignal(true);
	SetIsNeedResetLightCtrlDLP(true);	
	SetIsGetSystemExceptionMsg(false);
	SetOnlineOpenProjectFinish(false);
	SetOnlineTaskState(TASK_STATE_IDLE);
	SetThreadGrabMode(THREAD_GRAB_NONE);		
	ResetOnlineOpenProjectCameraBarcodeTestState();
	SetOnlineStateMode(ONLINE_STATE_INSPECTION_STOP);
	SaveAOIMonitorStatus(MONITOR_STATUS_ERROR, ErrorString);		
	//JetAPI::ShowMessageBox(GetErrorString());	
	SetProjectLightSetting(ProjectPtr);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::DecodeSystemException(WPARAM wParam, LPARAM lParam, CString &str)//解出系統異常訊息
{
	DWORD Res = 0;		
	CString tmpErr, UniErr;
	bool    IsError=false;
	bool    IsErrPLC=false;
	bool    IsErrCamera=false;
	bool    IsErrMotion=false;

	str = m_ErrorString;
	Res = lParam&LPARAM_SYSTEM_EXCEPTION_CAMERA;
	if ( Res != 0 ) 
	{	
		IsErrCamera=true;
		CAMERA_ID CameraID = CCameraCtrl::GetCaemraIDFromWParam(wParam);
		if ( str.GetLength() == 0 ) 
		{	str = CameraCtrl.GetCameraErrorString(CameraID);	}
		else
		{	str.Format(_T("\n %s"), CameraCtrl.GetCameraErrorString(CameraID));	}
	}

	Res = lParam&LPARAM_SYSTEM_EXCEPTION_MOTION;
	if ( Res != 0 ) 
	{	
		IsErrMotion=true;
		if ( str.GetLength() == 0 ) 
		{	str = MotionCtrlPtr->GetErrorString();	}
		else
		{	str.Format(_T("\n %s"), MotionCtrlPtr->GetErrorString());	}
	}

	Res = lParam&LPARAM_SYSTEM_EXCEPTION_PLC;
	if ( Res != 0 ) 
	{	
		IsErrPLC = true;
		if ( str.GetLength() == 0 ) 
		{	str = PlcCtrlPtr->GetPLCErrorString();	}
		else
		{	str.Format(_T("\n %s"), PlcCtrlPtr->GetPLCErrorString());	}
	}

#ifndef LIGHT_CTRL_DISABLE
	Res = lParam&LPARAM_SYSTEM_EXCEPTION_LIGHT;
	if ( true==IsErrCamera || 0!=Res )
	{
		tmpErr = str;
		LightCtrlBoard.CheckLightCtrlBoardError(IsError, UniErr);
		//if ( true == IsError )
		{	str.Format(_T("%s\n%s"), tmpErr, UniErr); }
	}
#endif//LIGHT_CTRL_DISABLE
	/*
	Res = lParam&LPARAM_SYSTEM_EXCEPTION_LIGHT;
	if ( Res != 0 ) 
	{	
		if ( str.GetLength() == 0 ) 
		{	str = CameraCtrl.GetErrorString();	}
		else
		{	str.Format(_T("\n %s"), CameraCtrl.GetErrorString());	}
	}
	*/
	return true;
}
//-------------------------------------------------------------------------------------//
CAOIProject* CAOIDataCollect::GetProjectPtr(size_t idx, bool check)//取得專案指標
{
	if ( true == check )
	{
		const size_t Count = GetProjectPtrCount();
		if ( idx >= Count ) { return NULL; }
	}
	return m_ProjectPtrList[idx];
}
//-------------------------------------------------------------------------------------//
CAOIProject* CAOIDataCollect::GetProjectPtrByFilename(LPCTSTR filename)//取得專案指標
{
	size_t       i = 0;	
	CString      ProjectShowName;
	CAOIProject *ProjectPtr=NULL;
	const size_t Count = GetProjectPtrCount();
	for ( i=0; i<Count; i++ )
	{
		ProjectPtr = GetProjectPtr(i, false);
		if ( NULL == ProjectPtr ) { continue; }
		ProjectShowName = ProjectPtr->GetProjectShowName();
		if ( ProjectShowName.CompareNoCase(filename) != 0 )
		{	continue; }
		return ProjectPtr;
	}
	return NULL;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::AddProjectPtr(CAOIProject* Ptr, bool clone)//增加專案指標
{
	if ( NULL == Ptr ) { return false; }
	CAOIProject *NewProject = Ptr;
	if ( true == clone )
	{	NewProject = Ptr->CloneProjectObj();	}
	if ( NULL == NewProject ) { return false; }
	
	size_t       i = 0;
	const size_t Count = GetProjectPtrCount();
	for ( i=0; i<Count; i++ )
	{
		if ( NULL != m_ProjectPtrList[i] )
		{	m_ProjectPtrList[i]->SetProjectSelected(false);	}
	}
	m_ProjectPtrList.push_back(NewProject);
	NewProject->SetProjectIndex(Count);
	NewProject->SetProjectSelected(true);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::GetProjectNameList(std::vector<CString> &List, bool bFullName)//取得專案檔名列表
{
	size_t       i = 0;	
	CString      Name;
	CString      ProjectShowName;
	CAOIProject *ProjectPtr=NULL;
	const size_t Count = GetProjectPtrCount();
	for ( i=0; i<Count; i++ )
	{
		ProjectPtr = GetProjectPtr(i, false);
		if ( NULL == ProjectPtr ) { continue; }
		ProjectShowName = ProjectPtr->GetProjectShowName();
		if ( true == bFullName )
		{	List.push_back(ProjectShowName);	}
		else
		{
			JetAPI::ExtractFileNameNoPath(ProjectShowName, Name);
			List.push_back(Name);
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::DestroyProjectSelected()//刪除被選到的專案
{
	size_t i = 0;
	unsigned int  index = 0;
	CAOIProject *ProjectPtr = NULL;
	std::vector<CAOIProject*> ProjectPtrList = this->m_ProjectPtrList;
	
	index = 0;
	this->m_ProjectPtrList.clear();
	const size_t ProjectCount = ProjectPtrList.size();
	for ( i=0; i<ProjectCount; i++ )
	{
		ProjectPtr = ProjectPtrList[i];
		if ( NULL == ProjectPtr ) { continue; }
		if ( ProjectPtr->GetProjectSelected() == true )
		{
			AOIObjManager.DestroyProjectObj(ProjectPtrList[i]);			
			ProjectPtr = NULL;
			continue;
		}

		ProjectPtr->SetProjectIndex(index);
		m_ProjectPtrList.push_back(ProjectPtr);
		index ++;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SelectAllProjects(bool bSelected)//選取所有專案
{
	size_t i = 0;	
	CAOIProject *ProjectPtr = NULL;	
	const size_t ProjectCount = CAOIDataCollect::GetProjectPtrCount();
	for ( i=0; i<ProjectCount; i++ )
	{
		ProjectPtr = CAOIDataCollect::GetProjectPtr(i, false);
		if ( NULL == ProjectPtr ) { continue; }
		ProjectPtr->SetProjectSelected(bSelected);		
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CloneProjectNewModel(CAOIProject* ProjectPtr, CAOIModel *ModelPtr, CAOIModel *&NewModelPtr)//複製模組成新的
{	
	if ( CheckProjectPtr(ProjectPtr) == false )
	{	return false; }
	if ( NULL == ModelPtr ) { return true; }
	MODEL_TYPE ModelType = ModelPtr->GetModelType();
	if ( MODEL_TYPE_NULL == ModelType ) { return true; }

	CString str;
	CString NewModelName;
	CString NewGroupName;
	CString ModelName=ModelPtr->GetModelName();
	CString GroupName=ModelPtr->GetModelGroupName();
	
	CString      strValue;
	CString      strLabel;
	CString      strCaption;	
	TBarcodeInfo BarcodeInfo;
	CInputBoxWnd InputBox;

	ModelName.MakeUpper();
	GroupName.MakeUpper();
	NewModelName = ModelName;
	NewGroupName = GroupName;

	strCaption = _T("Set Group Name");
	strCaption = LoadMultiLanguageString(strCaption, strCaption);	
	strLabel = AOIDataDefine.GetGroupText();	
	while ( true )
	{
		MODEL_TYPE ModelTypeExist;
		strValue = NewGroupName;
		InputBox.SetParam1(strCaption, strLabel, strValue);
		if ( InputBox.DoModal() == IDCANCEL )
		{	return true;	}
		NewGroupName = InputBox.m_DataEdit1;
		ModelTypeExist = ProjectPtr->CheckProjectModelGroupNameModelType(NewGroupName);
		if ( ModelType == ModelTypeExist )
		{	break; }
		if ( MODEL_TYPE_NULL == ModelTypeExist )
		{	break; }
		continue;
	};	
	
	strCaption = _T("Set Model Name");
	strCaption = LoadMultiLanguageString(strCaption, strCaption);	
	strLabel = AOIDataDefine.GetModelText();	
	while ( true )
	{	
		strValue = NewModelName;
		InputBox.SetParam1(strCaption, strLabel, strValue);
		if ( InputBox.DoModal() == IDCANCEL )
		{	return true;	}
		NewModelName = InputBox.m_DataEdit1;
		if ( ProjectPtr->CheckProjectModelNameExist(NewModelName) == true )
		{	continue; }
		break;
	};	
	
	CAOIModel *ModelPtr_New = ProjectPtr->CloneProjectModel(ModelName, NewModelName);
	if ( NULL == ModelPtr_New )
	{
		m_ErrorString = ProjectPtr->GetErrorString();
		return false;	
	}
	NewModelPtr = ModelPtr_New;
	ModelPtr_New->SetModelGroupName(NewGroupName);
	ModelPtr_New->SetupkModelModifiedDateTime();
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ChceckProjectFileNameExist(unsigned int ExcludeIndex, LPCTSTR pfilename)//確認專案名稱存在	
{
	if ( NULL == pfilename ) { return false; }

	size_t       i=0;
	CString      ShowName;
	CAOIProject *ProjectPtr = NULL;
	const size_t ProjectCount = GetProjectPtrCount();

	for ( i=0; i<ProjectCount; i++ )
	{
		if ( i == ExcludeIndex ) { continue; }
		ProjectPtr = GetProjectPtr(i, false);
		if ( NULL == ProjectPtr ) { continue; }
		ShowName = ProjectPtr->GetProjectShowName();
		if ( ShowName.CompareNoCase(pfilename) == 0 ) 
		{	return true; }
	}
	return false;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ApplyProjectParameterToSystem(CAOIProject* ProjectPtr)//套用專案參數至系統內
{
	if ( NULL == ProjectPtr ) { return true; }
	LANE_ID LaneID = GetActiveLaneID();
	MULTI_LANE_MODE    MultiLaneMode = CheckMultiLaneMode();
	const double dMaxH  = ProjectPtr->GetProjectSpaceMaxHeight();
	const double dLevel = ProjectPtr->GetProjectSpaceBaseHeight();
	const int RatioMode = ProjectPtr->GetProjectSpaceToGrayRatioMode();
	TProjectParameter &ProjectParam = ProjectPtr->GetProjectParameter();
	PCB_OUT_MODE       PCBOutMode=ProjectParam.m_PCBOutMode;//PCB出板模式	
	DEFECT_HANDLE_MODE DefectHandleMode = ProjectParam.m_DefectHandleMode;//檢出異常處理模式	
	BARCODE_INPUT_TYPE BarcodeInputType=ProjectParam.m_BarcodeInputType;//條碼輸入樣式	
	BARCODE_DEVICE_GRAB_MODE   BarcodeDeviceGrabMode=ProjectParam.m_BarcodeDeviceGrabMode;//固定條碼機讀取模式
	int                EnableConveyerPreRun = ProjectParam.m_EnableConveyerPreRun;//軌道提前運轉功能		
	switch ( BarcodeInputType )
	{
	case BARCODE_INPUT_DISABLED://關閉
		break;
	case BARCODE_INPUT_DEVICE://外接條碼機
		switch ( BarcodeDeviceGrabMode )
		{
		case BARCODE_DEVICE_GRAB_BEFORE_PCB_IN://進板前
			if ( PCB_OUT_LANE_AUTO == PCBOutMode )
			{	PCBOutMode = PCB_OUT_NORMAL; }
			break;
		case BARCODE_DEVICE_GRAB_WHILE_PCB_IN://進板中
			if ( PCB_OUT_LANE_AUTO == PCBOutMode )
			{	PCBOutMode = PCB_OUT_NORMAL; }
			break;
		case BARCODE_DEVICE_GRAB_AFTER_PCB_IN://進板後
			break;
		case BARCODE_DEVICE_GRAB_BEFORE_INSPECT://檢測前
			break;
		}
		break;
	case BARCODE_INPUT_HANDHELD://手持條碼機
		if ( PCB_OUT_LANE_AUTO == PCBOutMode )
		{	PCBOutMode = PCB_OUT_NORMAL; }
		break;	
	}

	//std::vector<CAOIProject*> LaneProjectList;	
	TSystemParameter &SysParam = GetSystemParameter();
	const bool bDualRunMode = CheckDualRunMode();//20230425		
	if ( MULTI_LANE_2==MultiLaneMode && false==bDualRunMode )	
	{	PCBOutMode = PCB_OUT_LANE_AUTO; }	

	SetSpaceMaxHeight(dMaxH);
	SetSpaceBaseHeight(dLevel);	
	SetSpaceToGrayRatioMode(RatioMode);
	SetLanePCBOutMode(LaneID, PCBOutMode);//PCB出板模式	
	SetLaneDefectHandleMode(LaneID, DefectHandleMode);
	SetEnableConveyerPreRun(EnableConveyerPreRun);//軌道提前運轉功能

	//About DLP Param	
	const bool bLoadParam = false;		
	const int DLPLEDColor = ProjectParam.m_ProjectDlpLedColor;	
	SetSystemDlpLedColor(DLPLEDColor);//DLP燈源顏色
	Light3DCtrl.SetAllLight3DLEDColor(DLPLEDColor);	
	if ( Light3DCtrl.LoadAllLight3DCastParameter(bLoadParam) == false )
	{
		m_ErrorString = Light3DCtrl.GetErrorString();
		JetAPI::ShowMessageBox(m_ErrorString);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ApplySystemParameterToAllProject()//套用系統參數至所有專案參數內
{	
	size_t       i=0;
	bool         IsOK=true;
	CString      strError;
	CString      strErrorTemp;
	CAOIProject *ProjectPtr = NULL;
	const size_t ProjectCount = GetProjectPtrCount();
	m_ErrorString = _T("");
	for ( i=0; i<ProjectCount; i++ )
	{
		ProjectPtr = GetProjectPtr(i, false);
		if ( NULL == ProjectPtr ) { continue; }
		if ( ProjectPtr->BuildProjectImageConfig() == false )
		{
			strError = ProjectPtr->GetErrorString();
			if ( m_ErrorString.GetLength() == 0 ) 
			{	m_ErrorString = strError; }
			else
			{
				strErrorTemp = m_ErrorString;
				m_ErrorString.Format(_T("%s\n%s"), strErrorTemp, strError);
			}
			IsOK = false;
		}
	}
	return IsOK;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::GetProjectBarcodeFilename(LANE_ID LaneID, bool bSave, CString &Filename)//取得專案條碼檔案名稱
{	
	CString ShortName;
	CString Folder = GetAOIDirectory();	
	switch ( LaneID )
	{
	case LANE_ID_B: 
		ShortName = _T("ProjectBarcodeFileLB.TXT");
		Folder = GetSystemParameter().m_BarcodeFileFolder_LB;
		break;
	default:
	case LANE_ID_A: 
		ShortName = _T("ProjectBarcodeFileLA.TXT");
		Folder = GetSystemParameter().m_BarcodeFileFolder_LA;
		break;
	}

	if ( true == bSave )
	{
		Filename.Format(_T("%s\\%s"), Folder, ShortName);
		return true;
	}

	CString ExtName=_T("TXT");
	std::vector<WIN32_FIND_DATA> FileList;
	JetAPI::ListFilesInFolder(Folder, ExtName, FileList);

	size_t i=0;
	const size_t FileCount=FileList.size();
	if ( 0 == FileCount )
	{
		m_ErrorString = _T("Error, No Project Barcode File");
		return false;
	}

	time_t   WriteTime;
	time_t   tLastWriteTime;

	ShortName=_T("");
	for ( i=0; i<FileCount; i++ )
	{
		JetAPI::FileTimeToTimet(FileList[i].ftLastWriteTime, WriteTime);
		if ( ShortName.GetLength()==0 || WriteTime<tLastWriteTime )
		{
			tLastWriteTime = WriteTime;
			ShortName = FileList[i].cFileName;			
		}
	}
	Filename.Format(_T("%s\\%s"), Folder, ShortName);
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckProjectFrameUniqueIDValid(CAOIProject *ProjectPtr)//確認專案影像唯一碼有效
{
	if ( CheckProjectPtr(ProjectPtr) == false ) { return false; }	
	std::vector<unsigned int> FrameUniqueIDList;	
	ProjectPtr->CloneProjectFrameUniqueIDList(FrameUniqueIDList);

	unsigned int FrameUniqueID=0;
	const size_t FrameUniqueIDCount=FrameUniqueIDList.size();
	for ( size_t i=0; i<FrameUniqueIDCount; i++ )
	{
		FrameUniqueID = FrameUniqueIDList[i];
		TFrameParam *FrameParamPtr=GetSystemFrameParamPtrByUniqueID(FrameUniqueID);
		if ( NULL == FrameParamPtr ) 
		{	return false; }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ModifyProjectFrameUniqueIDList(CAOIProject *ProjectPtr)//修改專案影像唯一碼列表
{
	if ( CheckProjectPtr(ProjectPtr) == false ) { return false; }

	std::vector<unsigned int> FrameUniqueIDList;
	std::vector<unsigned int> FrameUniqueIDListNew;	
	ProjectPtr->CloneProjectFrameUniqueIDList(FrameUniqueIDList);

	unsigned int FrameUniqueID=0;
	const size_t FrameUniqueIDCount=FrameUniqueIDList.size();
	for ( size_t i=0; i<FrameUniqueIDCount; i++ )
	{
		FrameUniqueID = FrameUniqueIDList[i];
		TFrameParam *FrameParamPtr=GetSystemFrameParamPtrByUniqueID(FrameUniqueID);
		if ( NULL == FrameParamPtr ) 
		{	continue; }
		FrameUniqueIDListNew.push_back(FrameUniqueID);
	}
	const size_t FrameUniqueIDCountNew=FrameUniqueIDListNew.size();
	if ( 0 == FrameUniqueIDCountNew )
	{
		m_ErrorString.Format(_T("Error, ModifyProjectFrameUniqueIDList Fault"));
		return false;
	}
	ProjectPtr->SetProjectFrameUniqueIDList(FrameUniqueIDListNew);
	return true;
}
