bool CAOIDataCollect::SetProjectHasModified(WPARAM wParam, CAOIProject *ProjectPtr)
{
	if ( NULL == ProjectPtr ) { return true; }	
	switch ( wParam )
	{	
	case VK_DELETE:
	case VK_LEFT:
	case VK_RIGHT:
	case VK_UP:
	case VK_DOWN:
		ProjectPtr->SetProjectHasModified(true);
		break;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SetProjectHasModified(WPARAM wParam, CAOIProject *ProjectPtr, const std::vector<TActiveObj> &ObjList)
{
	if ( NULL == ProjectPtr ) { return true; }
	if ( 0 == ObjList.size() ) { return true; }
	return SetProjectHasModified(wParam, ProjectPtr);
}
