size_t CAOIDataCollect::GetProjectPtrCount()//取得專案數量
{
	return m_ProjectPtrList.size();
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ClearActiveProject()//清除作業中專案
{
	size_t       i=0;
	unsigned int ProjectIndex=0;
	CAOIProject *ProjectPtr = NULL;	
	CAOIProject *ActiveProjectPtr = GetActiveProject();	
	std::vector<CAOIProject*>  TmpProjectPtrList=m_ProjectPtrList;//專案指標列表	
	const size_t Count = TmpProjectPtrList.size();
	if ( NULL == ActiveProjectPtr ) { return true; }
	LogOperCtrl.SaveLogProjectClose(ActiveProjectPtr, ActiveProjectPtr->GetProjectShowName());	

	ProjectIndex = 0;
	m_ProjectPtrList.clear();
	for ( i=0; i<Count; i++ )
	{
		ProjectPtr = TmpProjectPtrList[i];
		if ( NULL == ProjectPtr )	{	continue;	}
		if ( ProjectPtr == ActiveProjectPtr ) { continue; }		
		ProjectPtr->SetProjectIndex(ProjectIndex);
		m_ProjectPtrList.push_back(ProjectPtr);
		ProjectIndex ++;
	}	
	ActiveProjectPtr->CloseProject();
	AOIObjManager.DestroyProjectObj(ActiveProjectPtr);

	m_ActiveProjectPtr = NULL;	
	const size_t ProjectCount = GetProjectPtrCount();		
	if ( ProjectCount > 0 ) 
	{	SetActiveProjectIndex(0); }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ClearProjectPtrList()//清除專案指標列表
{
	size_t       i = 0;
	CAOIProject *ProjectPtr = NULL;
	const size_t Count = GetProjectPtrCount();
	for ( i=0; i<Count; i++ )
	{
		ProjectPtr = m_ProjectPtrList[i];
		if ( NULL == ProjectPtr )	{	continue;	}
		ProjectPtr->CloseProject();
		AOIObjManager.DestroyProjectObj(ProjectPtr);
		m_ProjectPtrList[i] = NULL;
	}
	m_ActiveProjectPtr = NULL;
	m_ProjectPtrList.clear();
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveOpenProjectBarcodeFile()//儲存開啟專案條碼檔案
{
	if ( SaveOpenProjectBarcodeFileFn() == false )
	{
		SetSystemExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveOpenProjectBarcodeFileFn()//儲存開啟專案條碼檔案
{	
	CString str;			
	CString FilenameTemp;
	CString Folder = GetAOITempDirectory();
	CString filename=GetOpenProjectBarcodeFilename();	
	CAOIProject *ProjectPtr = GetOpenProjectProjectPtr();
	if ( NULL == ProjectPtr ) { return true; }
	FilenameTemp.Format(_T("%s\\%s"), Folder, _T("OpenProjectBarcode.tmp"));
	if ( ProjectPtr->SaveProjectFile(FilenameTemp) == false )
	{	
		::DeleteFile(FilenameTemp);
		m_ErrorString = ProjectPtr->GetErrorString();
		return false; 
	}
	::CopyFile(FilenameTemp, filename, FALSE);
	::DeleteFile(FilenameTemp);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadOpenProjectBarcodeFile()//載入開啟專案條碼檔案
{
	if ( LoadOpenProjectBarcodeFileFn() == false )
	{
		SetSystemExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadOpenProjectBarcodeFileFn()//載入開啟專案條碼檔案
{
	CString str;
	CString FilenameTemp;
	CString Folder = GetAOITempDirectory();
	CString filename = GetOpenProjectBarcodeFilename();		
	if ( NULL == m_OpenProjectProjectObj )
	{
		m_OpenProjectProjectObj = AOIObjManager.CreateProjectObj();
		if ( NULL == m_OpenProjectProjectObj )
		{	return false;	}
	}
	m_OpenProjectProjectObj->ClearProjectAllBarcodes();	
	m_OpenProjectProjectObj->SetProjectShowName(filename);
	m_OpenProjectProjectObj->DeleteProjectCopyFileThread();
	m_OpenProjectProjectObj->DeleteProjectSaveFieldThread();

	std::vector<unsigned int> FrameUniqueIDList;
	m_OpenProjectProjectObj->SetProjectMapIndex(0);
	m_OpenProjectProjectObj->GetProjectFrameUniqueIDList(FrameUniqueIDList);
	RemoveUniqueIDListByUniqueID(FrameUniqueIDList, FRAME_UNIQUE_ID_DLP);
	if ( m_OpenProjectProjectObj->BuildProjectImageConfig(FrameUniqueIDList) == false )
	{	return false; }
	TProjectParameter &ProjectParam = m_OpenProjectProjectObj->GetProjectParameter();
	ProjectParam.m_ProjectModuleName = _T("Open Project Barcode");		

	if ( JetAPI::IsFileExist(filename) == false )
	{	return true; }

	FilenameTemp.Format(_T("%s\\%s"), Folder, _T("OpenProjectBarcode.tmp"));
	::CopyFile(filename, FilenameTemp, FALSE);
	if ( m_OpenProjectProjectObj->LoadProjectFile(FilenameTemp) == false )
	{
		::DeleteFile(FilenameTemp);
		m_ErrorString = m_OpenProjectProjectObj->GetErrorString();
		return false;
	}
	::DeleteFile(FilenameTemp);
	m_OpenProjectProjectObj->SetProjectShowName(filename);
	return true;
}
//-------------------------------------------------------------------------------------//
CString CAOIDataCollect::GetOpenProjectBarcodeFilename()//取得開啟專案條碼檔名
{
	CString Filename;
	CString Folder = GetAOIDirectory();
	Filename.Format(_T("%s\\%s"), Folder, _T("OnlineOpenProjectBarcode.dat"));
	return Filename;
}
