//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::AddOpenProjectBarcode(CAOIBarcode* Ptr, bool bClone)//加入開啟專案條碼
{	
	if ( NULL == Ptr ) { return false; }
	CAOIProject *ProjectPtr = GetOpenProjectProjectPtr();
	if ( NULL == ProjectPtr ) { return false; }
	CAOIBarcode *BarcodePtr = Ptr;	
	if ( true == bClone )
	{	BarcodePtr = Ptr->CloneBarcodeObj();	}
	if ( NULL == BarcodePtr )
	{	return false;	}
	ProjectPtr->AddProjectBarcodePtr(BarcodePtr, false);
	return true;
}
