//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecPrepareFrameImageSetting(const std::vector<TFrameParam> &FrameParamList, bool ResetLight)//執行Frame畫面的取像
{
	m_GrabSliceParamList.clear();
	m_GrabFrameParamList.clear();
	std::vector<TSliceParam> SliceParamList;
	if ( BuildSliceParamListByFrameList(FrameParamList, SliceParamList) == false )
	{	return false; }

	if ( ExecPrepareSliceImageSetting(SliceParamList, ResetLight) == false )
	{	return false; }

	m_GrabSliceParamList = SliceParamList;//單1影像參數列表
	m_GrabFrameParamList = FrameParamList;//影像參數列表	
	return true;
}
//-------------------------------------------------------------------------------------//
SLICE_FUNC_MODE CAOIDataCollect::CheckSliceFuncModeBasicMode(SLICE_FUNC_MODE SliceFuncMode) const//確認Slice函式的基本模式
{
	SLICE_FUNC_MODE BasicMode=SliceFuncMode;
	switch ( SliceFuncMode )
	{	
	case SLICE_FUNC_3D_4STEP_2EXP_A:		BasicMode = SLICE_FUNC_3D_4STEP_1EXP_A;	break;
	case SLICE_FUNC_3D_4STEP_2STEP_2EXP:	BasicMode = SLICE_FUNC_3D_4STEP_2STEP_1EXP;	break;
	case SLICE_FUNC_3D_4STEP_4STEP_2EXP:	BasicMode = SLICE_FUNC_3D_4STEP_4STEP_1EXP;	break;
	case SLICE_FUNC_3D_4STEP_4STEP_2LIGHT:	BasicMode = SLICE_FUNC_3D_4STEP_4STEP_1EXP;	break;
	case SLICE_FUNC_3D_4STEP_4GC_2EXP:		BasicMode = SLICE_FUNC_3D_4STEP_4GC_1EXP;	break;
	case SLICE_FUNC_3D_4STEP_4GC_2LIGHT:	BasicMode = SLICE_FUNC_3D_4STEP_4GC_1EXP;	break;
	case SLICE_FUNC_3D_4STEP_5GC_2EXP:		BasicMode = SLICE_FUNC_3D_4STEP_5GC_1EXP;	break;
	case SLICE_FUNC_3D_4STEP_5GC_2LIGHT:	BasicMode = SLICE_FUNC_3D_4STEP_5GC_1EXP;	break;
	case SLICE_FUNC_3D_4STEP_6GC_2EXP:		BasicMode = SLICE_FUNC_3D_4STEP_6GC_1EXP;	break;
	case SLICE_FUNC_3D_4STEP_6GC_2LIGHT:	BasicMode = SLICE_FUNC_3D_4STEP_6GC_1EXP;	break;
	default:		
		break;
	}
	return BasicMode;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckSliceFuncModeDlpUse2Exp(SLICE_FUNC_MODE SliceFuncMode) const//確認Slice函式的雙曝光模式
{
	const int ExpCount=CheckFrameExpCountBySliceFuncMode(SliceFuncMode);
	if ( 1 == ExpCount ) { return false; }	
	return true;
}
//-------------------------------------------------------------------------------------//
int CAOIDataCollect::CheckSliceFuncModeDlpPatternMode(SLICE_FUNC_MODE SliceFuncMode) const//確認Slice函式的DLP樣板模式
{
	int PatternMode=0;
	switch ( SliceFuncMode )
	{
	case SLICE_FUNC_3D_4STEP_1EXP_A:	PatternMode=DLP_PATTERN_SEQUENCE_4_4_1;	break;
	case SLICE_FUNC_3D_2STEP_2STEP_1EXP:	PatternMode = DLP_PATTERN_SEQUENCE_2_2_M;	break;
	case SLICE_FUNC_3D_4STEP_2STEP_1EXP:	PatternMode = DLP_PATTERN_SEQUENCE_4_2_M;	break;
	case SLICE_FUNC_3D_4STEP_4STEP_1EXP:	PatternMode = DLP_PATTERN_SEQUENCE_4_4_M;	break;
	case SLICE_FUNC_3D_4STEP_4GC_1EXP:		PatternMode = DLP_PATTERN_SEQUENCE_4_4GC_M;	break;
	case SLICE_FUNC_3D_4STEP_5GC_1EXP:		PatternMode = DLP_PATTERN_SEQUENCE_4_5GC_M;	break;
	case SLICE_FUNC_3D_4STEP_6GC_1EXP:		PatternMode = DLP_PATTERN_SEQUENCE_4_6GC_M;	break;
	case SLICE_FUNC_3D_4STEP_2EXP_A:		PatternMode = DLP_PATTERN_SEQUENCE_4_4_1_2;	break;
	case SLICE_FUNC_3D_4STEP_2STEP_2EXP:	PatternMode = DLP_PATTERN_SEQUENCE_4_2_M_2;	break;
	case SLICE_FUNC_3D_4STEP_4STEP_2EXP:	PatternMode = DLP_PATTERN_SEQUENCE_4_4_M_2;	break;
	case SLICE_FUNC_3D_4STEP_4STEP_2LIGHT:	PatternMode = DLP_PATTERN_SEQUENCE_4_4_M;	break;
	case SLICE_FUNC_3D_4STEP_4GC_2EXP:		PatternMode = DLP_PATTERN_SEQUENCE_4_4GC_M2;break;
	case SLICE_FUNC_3D_4STEP_4GC_2LIGHT:	PatternMode = DLP_PATTERN_SEQUENCE_4_4GC_M;	break;
	case SLICE_FUNC_3D_4STEP_5GC_2EXP:		PatternMode = DLP_PATTERN_SEQUENCE_4_5GC_M2;break;
	case SLICE_FUNC_3D_4STEP_5GC_2LIGHT:	PatternMode = DLP_PATTERN_SEQUENCE_4_5GC_M;	break;
	case SLICE_FUNC_3D_4STEP_6GC_2EXP:		PatternMode = DLP_PATTERN_SEQUENCE_4_6GC_M2;break;
	case SLICE_FUNC_3D_4STEP_6GC_2LIGHT:	PatternMode = DLP_PATTERN_SEQUENCE_4_6GC_M;	break;
	default:
		PatternMode = 0;
		break;
	}
	return PatternMode;
}
//-------------------------------------------------------------------------------------//
int CAOIDataCollect::CheckSliceFuncModeDlpPatternCountAll(SLICE_FUNC_MODE SliceFuncMode) const//確認Slice函式的DLP樣板數
{
	const int LightCnt=CheckFrameLightCountBySliceFuncMode(SliceFuncMode);//燈源電流次數
	const int PatternCountOnce=CheckSliceFuncModeDlpPatternCountOnce(SliceFuncMode);//每次同燈源電流下的樣板張數
	const int PatternCountAll=LightCnt*PatternCountOnce;
	return PatternCountAll;

	int PatternCount=0;
	switch ( SliceFuncMode )
	{
	case SLICE_FUNC_3D_4STEP_1EXP_A:		PatternCount = 4;	break;
	case SLICE_FUNC_3D_4STEP_4STEP_1EXP:	PatternCount = 8;	break;
	case SLICE_FUNC_3D_2STEP_2STEP_1EXP:	PatternCount = 5;	break;
	case SLICE_FUNC_3D_4STEP_2STEP_1EXP:	PatternCount = 6;	break;
	case SLICE_FUNC_3D_4STEP_4GC_1EXP:		PatternCount = 8;	break;
	case SLICE_FUNC_3D_4STEP_5GC_1EXP:		PatternCount = 9;	break;
	case SLICE_FUNC_3D_4STEP_6GC_1EXP:		PatternCount =10;	break;

	case SLICE_FUNC_3D_4STEP_2EXP_A:		PatternCount = 8;	break;
	case SLICE_FUNC_3D_4STEP_4STEP_2EXP:	PatternCount =16;	break;	
	case SLICE_FUNC_3D_4STEP_2STEP_2EXP:	PatternCount =12;	break;
	case SLICE_FUNC_3D_4STEP_4GC_2EXP:		PatternCount =16;	break;
	case SLICE_FUNC_3D_4STEP_5GC_2EXP:		PatternCount =18;	break;
	case SLICE_FUNC_3D_4STEP_6GC_2EXP:		PatternCount =20;	break;

	case SLICE_FUNC_3D_4STEP_4STEP_2LIGHT:	PatternCount =16;	break;
	case SLICE_FUNC_3D_4STEP_4GC_2LIGHT:	PatternCount =16;	break;
	case SLICE_FUNC_3D_4STEP_5GC_2LIGHT:	PatternCount =18;	break;
	case SLICE_FUNC_3D_4STEP_6GC_2LIGHT:	PatternCount =20;	break;
	default:
		PatternCount = 0;
		break;
	}
	return PatternCount;
}
