//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckSliceFuncModeDecodePhaseMode(int ImageCount, SLICE_FUNC_MODE SliceFuncMode, DECODE_PHASE_MODE &DecodeMode)//確認解相位模式
{	
	switch ( ImageCount )
	{
	case 3:		
		DecodeMode = DECODE_PHASE_3STEP_1;
		break;
	case 4:		
		DecodeMode = DECODE_PHASE_4STEP_1;
		break;
	case 5:
		if ( SLICE_FUNC_3D_2STEP_2STEP_1EXP == SliceFuncMode)
		{	DecodeMode = DECODE_PHASE_2_2STEP_2;	}
		else
		{	DecodeMode = DECODE_PHASE_5STEP_1;	}
		break;
	case 6:		
		if ( SLICE_FUNC_3D_4STEP_2STEP_1EXP == SliceFuncMode)
		{	DecodeMode = DECODE_PHASE_4_2STEP_2;	}
		else
		{	DecodeMode = DECODE_PHASE_3_3STEP_2;	}	
		break;
	case 8:
		if ( SLICE_FUNC_3D_4STEP_4GC_1EXP == SliceFuncMode)
		{	DecodeMode = DECODE_PHASE_4STEP_4GC_2;	}
		else
		{	DecodeMode = DECODE_PHASE_4_4STEP_2;	}
		break;
	case 9:
		DecodeMode = DECODE_PHASE_4STEP_5GC_2;			
		break;
	case 10:
		if ( SLICE_FUNC_3D_4STEP_6GC_1EXP == SliceFuncMode)
		{	DecodeMode = DECODE_PHASE_4STEP_6GC_2;	}
		else
		{	DecodeMode = DECODE_PHASE_5_5STEP_2;	}
		break;
	default:
		DecodeMode = DECODE_PHASE_NONE;
		m_ErrorString.Format(_T("Error, CheckDecodePhaseMode Fault (ImageCount=%d, Slice Func Mode=%d"), ImageCount, SliceFuncMode);
		return false;
		break;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckSliceFuncModeDecodePhaseModeExp2(int ImageCount, SLICE_FUNC_MODE SliceFuncMode, DECODE_PHASE_MODE &DecodeMode)//確認解相位模式
{
	DecodeMode = DECODE_PHASE_NONE;
	switch ( ImageCount )
	{
	case 6:		
		DecodeMode = DECODE_PHASE_3STEP_1;
		break;
	case 8:
		DecodeMode = DECODE_PHASE_4STEP_1;
		break;
	case 10:
		if (SLICE_FUNC_3D_2STEP_2STEP_1EXP == SliceFuncMode)// SLICE_FUNC_3D_2_2STEP_2EXP
		{	DecodeMode = DECODE_PHASE_2_2STEP_2;	}
		else
		{	DecodeMode = DECODE_PHASE_5STEP_1;	}
		break;
	case 12:	
		if ( SLICE_FUNC_3D_4STEP_2STEP_2EXP == SliceFuncMode )
		{	DecodeMode = DECODE_PHASE_4_2STEP_2;	}
		else
		{	DecodeMode = DECODE_PHASE_3_3STEP_2;	}
		break;
	case 16:
		if ( SLICE_FUNC_3D_4STEP_4GC_2EXP==SliceFuncMode || SLICE_FUNC_3D_4STEP_4GC_2LIGHT==SliceFuncMode )
		{	DecodeMode = DECODE_PHASE_4STEP_4GC_2;	}
		else
		{	DecodeMode = DECODE_PHASE_4_4STEP_2;	}
		break;
	case 18:
		if ( SLICE_FUNC_3D_4STEP_5GC_2EXP==SliceFuncMode || SLICE_FUNC_3D_4STEP_5GC_2LIGHT==SliceFuncMode )
		{	DecodeMode = DECODE_PHASE_4STEP_5GC_2;	}		
		break;
	case 20:
		if ( SLICE_FUNC_3D_4STEP_6GC_2EXP==SliceFuncMode || SLICE_FUNC_3D_4STEP_6GC_2LIGHT==SliceFuncMode )
		{	DecodeMode = DECODE_PHASE_4STEP_6GC_2;	}		
		else
		{	DecodeMode = DECODE_PHASE_5_5STEP_2;	}
		break;	
	default:
		DecodeMode = DECODE_PHASE_NONE;		
		break;
	}
	if ( DECODE_PHASE_NONE == DecodeMode )
	{
		m_ErrorString.Format(_T("Error, CheckDecodePhaseModeExp2 Fault (ImageCount=%d, Slice Func Mode=%d"), ImageCount, SliceFuncMode);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveCastParamImageList(const TCastParam &CastParam, LPCTSTR Folder)//儲存投光圖像列表
{
	if ( SaveCastParamImageListFn(CastParam, Folder) == false )
	{
		SetSystemExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveCastParamImageListFn(const TCastParam &CastParam, LPCTSTR Folder)//儲存投光圖像列表
{
	size_t i=0;
	const size_t MaxCnt=32;
	IMAGE_PTR PtrList[MaxCnt]={NULL};	
	for ( i=0; i<MaxCnt; i++ )
	{	PtrList[i] = NULL;	}

	i=0;
	if ( NULL !=CastParam.PtrA1 ) { PtrList[i++]=CastParam.PtrA1; }
	if ( NULL !=CastParam.PtrA2 ) { PtrList[i++]=CastParam.PtrA2; }
	if ( NULL !=CastParam.PtrA3 ) { PtrList[i++]=CastParam.PtrA3; }
	if ( NULL !=CastParam.PtrA4 ) { PtrList[i++]=CastParam.PtrA4; }
	if ( NULL !=CastParam.PtrA5 ) { PtrList[i++]=CastParam.PtrA5; }	
	if ( NULL !=CastParam.PtrB1 ) { PtrList[i++]=CastParam.PtrB1; }
	if ( NULL !=CastParam.PtrB2 ) { PtrList[i++]=CastParam.PtrB2; }
	if ( NULL !=CastParam.PtrB3 ) { PtrList[i++]=CastParam.PtrB3; }
	if ( NULL !=CastParam.PtrB4 ) { PtrList[i++]=CastParam.PtrB4; }
	if ( NULL !=CastParam.PtrB5 ) { PtrList[i++]=CastParam.PtrB5; }	
	if ( NULL !=CastParam.PtrB6 ) { PtrList[i++]=CastParam.PtrB6; }	

	if ( NULL !=CastParam.PtrC1 ) { PtrList[i++]=CastParam.PtrC1; }
	if ( NULL !=CastParam.PtrC2 ) { PtrList[i++]=CastParam.PtrC2; }
	if ( NULL !=CastParam.PtrC3 ) { PtrList[i++]=CastParam.PtrC3; }
	if ( NULL !=CastParam.PtrC4 ) { PtrList[i++]=CastParam.PtrC4; }
	if ( NULL !=CastParam.PtrC5 ) { PtrList[i++]=CastParam.PtrC5; }	
	if ( NULL !=CastParam.PtrD1 ) { PtrList[i++]=CastParam.PtrD1; }
	if ( NULL !=CastParam.PtrD2 ) { PtrList[i++]=CastParam.PtrD2; }
	if ( NULL !=CastParam.PtrD3 ) { PtrList[i++]=CastParam.PtrD3; }
	if ( NULL !=CastParam.PtrD4 ) { PtrList[i++]=CastParam.PtrD4; }
	if ( NULL !=CastParam.PtrD5 ) { PtrList[i++]=CastParam.PtrD5; }	
	if ( NULL !=CastParam.PtrD6 ) { PtrList[i++]=CastParam.PtrD6; }	

	bool bSucc=true;
	CString str;
	CString strFolder;
	const size_t Cnt=i;
	IMAGE_SIZE BitCount=8;
	IMAGE_SIZE ImageW=CastParam.ImageW;
	IMAGE_SIZE ImageH=CastParam.ImageH;
	IMAGE_SIZE ImageStep=CastParam.ImageStep;

	strFolder.Format(_T("%s\\Cast%02d"), Folder, CastParam.CastID);
	CreateDirectory(strFolder, NULL);
	for ( i=0; i<Cnt; i++ )
	{
		str.Format(_T("%s\\Image_%04d.PNG"), strFolder, i+1);
		if ( NULL == PtrList[i] ) { continue; }
		if ( ImageAPI.SaveImage(str, ImageW, ImageH, ImageStep, BitCount, PtrList[i], true) == false )
		{	
			bSucc = false;
			SetErrorString(ImageAPI.GetImageApiErrorString());
		}
	}
	return bSucc;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::BuildCastParam(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, int ImgPtrCount, int SliceFuncMode, IMAGE_PTR ImgPtr[], LIGHT_3D_CAST_ID CastID, TCastParam &CastParam)//建立投光參數
{
	int PhaseMode = 0;	
	const char fnName[] = "CAOIDataCollect::BuildCastParam";
	const TSystemParameter &SysParam = GetSystemParameter();
	const TCalibrationParameter &CaliParam = GetCalibrationParameter();	
	const int DLPLEDColor = GetSystemDlpLedColor();
	const int DLPExposureTime_us = CaliParam.m_DLPExposureTime_us;
	const int DLPExposureTime2_us = CaliParam.m_DLPExposureTime2_us;

	CString   CastName = AOIDataDefine.GetLight3DCastIDText(CastID);
	CastParam.ExpCount = 1;
	CastParam.PerA = SysParam.m_PhasePeriod1;
	CastParam.PerB = SysParam.m_PhasePeriod2;
	
	CastParam.ImageW = ImageW;
	CastParam.ImageH = ImageH;
	CastParam.ImageStep = ImageStep;
	CastParam.ImageCount = ImgPtrCount;

	CastParam.CastID = CastID;
	CastParam.ExpTimeA = DLPExposureTime_us;
	CastParam.ExpTimeB = DLPExposureTime2_us;	
	CastParam.HeightBuildMode = SysParam.m_PhaseConvertHeightMode;
	
	switch ( ImgPtrCount )
	{
	case 3:			
		CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];
		PhaseMode = LIGHT3D_PHASE_3_3_1;
		CastParam.DecodeMode = DECODE_PHASE_3STEP_1;
		break;
	case 4:
		CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];	CastParam.PtrA4 = ImgPtr[3];
		PhaseMode = LIGHT3D_PHASE_4_4_1;
		CastParam.DecodeMode = DECODE_PHASE_4STEP_1;
		break;
	case 5:
		if ( SLICE_FUNC_3D_2STEP_2STEP_1EXP == SliceFuncMode)
		{
			CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];
			CastParam.PtrB1 = ImgPtr[2];	CastParam.PtrB2 = ImgPtr[3];	CastParam.PtrB3 = ImgPtr[4];//Average
			PhaseMode = LIGHT3D_PHASE_2_2_M;
			CastParam.DecodeMode = DECODE_PHASE_2_2STEP_2;
		}
		else
		{
			CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];	CastParam.PtrA4 = ImgPtr[3];	CastParam.PtrA5 = ImgPtr[4];
			PhaseMode = LIGHT3D_PHASE_5_5_1;
			CastParam.DecodeMode = DECODE_PHASE_5STEP_1;
		}
		break;
	case 6:		
		if ( SLICE_FUNC_3D_4STEP_2STEP_1EXP == SliceFuncMode)
		{
			CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];	CastParam.PtrA4 = ImgPtr[3];
			CastParam.PtrB1 = ImgPtr[4];	CastParam.PtrB2 = ImgPtr[5];
			PhaseMode = LIGHT3D_PHASE_4_2_M;
			CastParam.DecodeMode = DECODE_PHASE_4_2STEP_2;
		}
		else
		{
			CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];
			CastParam.PtrB1 = ImgPtr[3];	CastParam.PtrB2 = ImgPtr[4];	CastParam.PtrB3 = ImgPtr[5];
			PhaseMode = LIGHT3D_PHASE_3_3_M;			
			CastParam.DecodeMode = DECODE_PHASE_3_3STEP_2;
		}	
		break;
	case 8:
		CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];	CastParam.PtrA4 = ImgPtr[3];
		CastParam.PtrB1 = ImgPtr[4];	CastParam.PtrB2 = ImgPtr[5];	CastParam.PtrB3 = ImgPtr[6];	CastParam.PtrB4 = ImgPtr[7];
		if ( SLICE_FUNC_3D_4STEP_4GC_1EXP==SliceFuncMode || SLICE_FUNC_3D_4STEP_4GC_2LIGHT==SliceFuncMode )
		{
			PhaseMode = LIGHT3D_PHASE_4_4GC_M;
			CastParam.DecodeMode = DECODE_PHASE_4STEP_4GC_2; 
		}
		else
		{
			PhaseMode = LIGHT3D_PHASE_4_4_M;
			CastParam.DecodeMode = DECODE_PHASE_4_4STEP_2;	
		}
		break;
	case 9:
		CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];	CastParam.PtrA4 = ImgPtr[3];
		CastParam.PtrB1 = ImgPtr[4];	CastParam.PtrB2 = ImgPtr[5];	CastParam.PtrB3 = ImgPtr[6];	CastParam.PtrB4 = ImgPtr[7];	CastParam.PtrB5 = ImgPtr[8];
		//if ( SLICE_FUNC_3D_4STEP_5GC_1EXP==SliceFuncMode || SLICE_FUNC_3D_4STEP_5GC_2LIGHT==SliceFuncMode )
		PhaseMode = LIGHT3D_PHASE_4_5GC_M;
		CastParam.DecodeMode = DECODE_PHASE_4STEP_5GC_2;			
		break;
	case 10:
		if ( SLICE_FUNC_3D_4STEP_6GC_1EXP==SliceFuncMode || SLICE_FUNC_3D_4STEP_6GC_2LIGHT==SliceFuncMode )
		{
			CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];	CastParam.PtrA4 = ImgPtr[3];
			CastParam.PtrB1 = ImgPtr[4];	CastParam.PtrB2 = ImgPtr[5];	CastParam.PtrB3 = ImgPtr[6];	CastParam.PtrB4 = ImgPtr[7];	CastParam.PtrB5 = ImgPtr[8];	CastParam.PtrB6 = ImgPtr[9];
			PhaseMode = LIGHT3D_PHASE_4_6GC_M;
			CastParam.DecodeMode = DECODE_PHASE_4STEP_6GC_2;	
		}
		else
		{
			CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];	CastParam.PtrA4 = ImgPtr[3];	CastParam.PtrA5 = ImgPtr[4];
			CastParam.PtrB1 = ImgPtr[5];	CastParam.PtrB2 = ImgPtr[6];	CastParam.PtrB3 = ImgPtr[7];	CastParam.PtrB4 = ImgPtr[8];	CastParam.PtrB5 = ImgPtr[9];
			PhaseMode = LIGHT3D_PHASE_5_5_M;			
			CastParam.DecodeMode = DECODE_PHASE_5_5STEP_2;
		}
		break;
	default:
		return false;
		break;
	}

	TPhaseNoiseParam NoiseParam;
	const size_t BufferSize = ImageAPI.CalcBufferSize(ImageStep, ImageH);
	GetPhaseNoiseDefineParam(NoiseParam);
	const int   nSmoothFilterSize = NoiseParam.PhaseSmoothFilter;
	const BOOL  bCheckSmoothFilter = (BOOL)(NoiseParam.PhaseNoiseDef&PHASE_NOSIE_SMOOTH_FILTER);
	if ( FALSE!=bCheckSmoothFilter && nSmoothFilterSize>0 )
	{
		IMAGE_PTR    SrcPtr = NULL;
		IMAGE_PTR    BufferPtr = NULL;		
		const int    KerSize = nSmoothFilterSize*2+1;
		switch ( PhaseMode )
		{
		case LIGHT3D_PHASE_2_2_M:
			break;
		case LIGHT3D_PHASE_4_4_M:
			if ( JetMemory.alloc_func(BufferSize, BufferPtr, fnName, "BufferPtr") == true )
			{
				SrcPtr = CastParam.PtrB1;
				if ( NULL != SrcPtr )
				{
					if ( ImageAPI.SmoothGrayImage3(ImageW, ImageH, ImageStep, SrcPtr, KerSize, BufferPtr) == true )
					{	::memcpy(SrcPtr, BufferPtr, BufferSize);	}
				}
				SrcPtr = CastParam.PtrB2;
				if ( NULL != SrcPtr )
				{
					if ( ImageAPI.SmoothGrayImage3(ImageW, ImageH, ImageStep, SrcPtr, KerSize, BufferPtr) == true )
					{	::memcpy(SrcPtr, BufferPtr, BufferSize);	}
				}
				SrcPtr = CastParam.PtrB3;
				if ( NULL != SrcPtr )
				{
					if ( ImageAPI.SmoothGrayImage3(ImageW, ImageH, ImageStep, SrcPtr, KerSize, BufferPtr) == true )
					{	::memcpy(SrcPtr, BufferPtr, BufferSize);	}
				}
				SrcPtr = CastParam.PtrB4;
				if ( NULL != SrcPtr )
				{
					if ( ImageAPI.SmoothGrayImage3(ImageW, ImageH, ImageStep, SrcPtr, KerSize, BufferPtr) == true )
					{	::memcpy(SrcPtr, BufferPtr, BufferSize);	}
				}
				SrcPtr = CastParam.PtrB5;
				if ( NULL != SrcPtr )
				{
					if ( ImageAPI.SmoothGrayImage3(ImageW, ImageH, ImageStep, SrcPtr, KerSize, BufferPtr) == true )
					{	::memcpy(SrcPtr, BufferPtr, BufferSize);	}
				}
				JetMemory.free_func(BufferPtr);
			}
			break;
		case LIGHT3D_PHASE_4_2_M_2:
			break;
		case LIGHT3D_PHASE_4_4_M_2:
			break;
		case LIGHT3D_PHASE_4_4GC_M_2:
			break;
		case LIGHT3D_PHASE_4_5GC_M_2:
			break;
		case LIGHT3D_PHASE_4_6GC_M_2:
			break;
		}
	}

	PHASE_PTR BasePhasePtr = NULL;
	IMAGE_SIZE PhaseW=0, PhaseH=0, PhaseStep=0;
	if ( Light3DCtrl.GetLight3DPhaseZero(CastID, PhaseMode, DLPLEDColor, PhaseW, PhaseH, PhaseStep, BasePhasePtr) == false )
	{
		m_ErrorString.Format(_T("%s [%s]"), Light3DCtrl.GetErrorString(), CastName);
		return false;	
	}
	if ( ImageW!=PhaseW || ImageH!=PhaseH || ImageStep!=PhaseStep )
	{
		m_ErrorString.Format(_T("Error, %s, Image[Phase] Size Exception (%d, %d, %d) != (%d, %d, %d)"), CastName, ImageW, ImageH, ImageStep, PhaseW, PhaseH, PhaseStep);
		return false; 
	}

	IMAGE_SIZE SpaceW=0, SpaceH=0, SpaceStep=0;
	SPACE_PTR KPtr = NULL;		
	if ( Light3DCtrl.GetLight3DPhaseFactor(CastID, PhaseMode, DLPLEDColor, SpaceW, SpaceH, SpaceStep, KPtr) == false )
	{
		m_ErrorString.Format(_T("%s [%s]"), Light3DCtrl.GetErrorString(), CastName);
		return false;	
	}
	if ( ImageW!=SpaceW || ImageH!=SpaceH || ImageStep!=SpaceStep )
	{
		m_ErrorString.Format(_T("Error, %s Image[Space] Size Exception (%d, %d, %d) != (%d, %d, %d)"), CastName, ImageW, ImageH, ImageStep, SpaceW, SpaceH, SpaceStep);
		return false; 
	}
	CastParam.ZeroPhasePtr = BasePhasePtr;
	CastParam.HeightFactorPtr = KPtr;

	if ( JetMemory.alloc_func(BufferSize, CastParam.PtrMask, fnName, "CastParam.PtrMask") == false || 
		 JetMemory.alloc_func(BufferSize, CastParam.PtrSpace, fnName, "CastParam.PtrSpace") == false )
	{
		JetMemory.free_func(CastParam.PtrMask);
		JetMemory.free_func(CastParam.PtrSpace);
		return false;
	}

	double Gamma=1.0;
	if ( Light3DCtrl.GetLight3DImageGamma(CastID, Gamma) == false )
	{
		m_ErrorString.Format(_T("%s [%s]"), Light3DCtrl.GetErrorString(), CastName);
		return false;	
	}
	CastParam.Gamma = Gamma;

	//高度係數
	if ( Light3DCtrl.GetLight3DHeightFactor(CastID, CastParam.HeightFactor0, CastParam.HeightFactor1, CastParam.HeightFactor2) == false )
	{
		m_ErrorString.Format(_T("%s [%s]"), Light3DCtrl.GetErrorString(), CastName);
		return false;	
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::BuildCastParam2Exp(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, int ImgPtrCount, int SliceFuncMode, IMAGE_PTR ImgPtr[], LIGHT_3D_CAST_ID CastID, TCastParam &CastParam)//建立投光參數
{
	int PhaseMode = 0;	
	const char fnName[] = "CAOIDataCollect::BuildCastParam2Exp";
	const TSystemParameter &SysParam = GetSystemParameter();
	const TCalibrationParameter &CaliParam = GetCalibrationParameter();		
	const int DLPLEDColor = GetSystemDlpLedColor();
	const int DLPExposureTime_us = CaliParam.m_DLPExposureTime_us;
	const int DLPExposureTime2_us = CaliParam.m_DLPExposureTime2_us;

	CString   CastName = AOIDataDefine.GetLight3DCastIDText(CastID);
	CastParam.ExpCount = 2;
	CastParam.PerA = SysParam.m_PhasePeriod1;
	CastParam.PerB = SysParam.m_PhasePeriod2;
	
	CastParam.ImageW = ImageW;
	CastParam.ImageH = ImageH;
	CastParam.ImageStep = ImageStep;
	CastParam.ImageCount = ImgPtrCount;

	CastParam.CastID = CastID;
	CastParam.ExpTimeA = DLPExposureTime_us;
	CastParam.ExpTimeB = DLPExposureTime2_us;	
	CastParam.ExpTimeC = DLPExposureTime_us;
	CastParam.ExpTimeD = DLPExposureTime2_us;	
	CastParam.HeightBuildMode = SysParam.m_PhaseConvertHeightMode;

	switch ( ImgPtrCount )
	{
	case 6:
		CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];
		CastParam.PtrC1 = ImgPtr[3];	CastParam.PtrC2 = ImgPtr[4];	CastParam.PtrC3 = ImgPtr[5];
		PhaseMode = LIGHT3D_PHASE_3_3_1_2;
		CastParam.DecodeMode = DECODE_PHASE_3STEP_1;
		break;
	case 8:
		CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];	CastParam.PtrA4 = ImgPtr[3];
		CastParam.PtrC1 = ImgPtr[4];	CastParam.PtrC2 = ImgPtr[5];	CastParam.PtrC3 = ImgPtr[6];	CastParam.PtrC4 = ImgPtr[7];
		PhaseMode = LIGHT3D_PHASE_4_4_1_2;
		CastParam.DecodeMode = DECODE_PHASE_4STEP_1;
		break;
	case 10:
		if (SLICE_FUNC_3D_2STEP_2STEP_1EXP == SliceFuncMode)// SLICE_FUNC_3D_2_2STEP_2EXP
		{
			CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];
			CastParam.PtrB1 = ImgPtr[2];	CastParam.PtrB2 = ImgPtr[3];	CastParam.PtrB3 = ImgPtr[4];
			CastParam.PtrC1 = ImgPtr[5];	CastParam.PtrC2 = ImgPtr[6];
			CastParam.PtrD1 = ImgPtr[7];	CastParam.PtrD2 = ImgPtr[8];	CastParam.PtrD3 = ImgPtr[9];
			PhaseMode = LIGHT3D_PHASE_2_2_M_2;
			CastParam.DecodeMode = DECODE_PHASE_2_2STEP_2;
		}
		else
		{
			CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];	CastParam.PtrA4 = ImgPtr[3];	CastParam.PtrA5 = ImgPtr[4];
			CastParam.PtrC1 = ImgPtr[5];	CastParam.PtrC2 = ImgPtr[6];	CastParam.PtrC3 = ImgPtr[7];	CastParam.PtrC4 = ImgPtr[8];	CastParam.PtrC5 = ImgPtr[9];
			PhaseMode = LIGHT3D_PHASE_5_5_1_2;
			CastParam.DecodeMode = DECODE_PHASE_5STEP_1;
		}
		break;
	case 12:	
		if ( SLICE_FUNC_3D_4STEP_2STEP_2EXP == SliceFuncMode )
		{
			CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];	CastParam.PtrA4 = ImgPtr[3];
			CastParam.PtrB1 = ImgPtr[4];	CastParam.PtrB2 = ImgPtr[5];
			CastParam.PtrC1 = ImgPtr[6];	CastParam.PtrC2 = ImgPtr[7];	CastParam.PtrC3 = ImgPtr[8];	CastParam.PtrC4 = ImgPtr[9];
			CastParam.PtrD1 = ImgPtr[10];	CastParam.PtrD2 = ImgPtr[11];			
			PhaseMode = LIGHT3D_PHASE_4_2_M_2;
			CastParam.DecodeMode = DECODE_PHASE_4_2STEP_2;
		}
		else
		{
			CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];
			CastParam.PtrB1 = ImgPtr[3];	CastParam.PtrB2 = ImgPtr[4];	CastParam.PtrB3 = ImgPtr[5];
			CastParam.PtrC1 = ImgPtr[6];	CastParam.PtrC2 = ImgPtr[7];	CastParam.PtrC3 = ImgPtr[8];
			CastParam.PtrD1 = ImgPtr[9];	CastParam.PtrD2 = ImgPtr[10];	CastParam.PtrD3 = ImgPtr[11];
			PhaseMode = LIGHT3D_PHASE_3_3_M_2;
			CastParam.DecodeMode = DECODE_PHASE_3_3STEP_2;
		}
		break;
	case 16:
		CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];	CastParam.PtrA4 = ImgPtr[3];
		CastParam.PtrB1 = ImgPtr[4];	CastParam.PtrB2 = ImgPtr[5];	CastParam.PtrB3 = ImgPtr[6];	CastParam.PtrB4 = ImgPtr[7];
		CastParam.PtrC1 = ImgPtr[8];	CastParam.PtrC2 = ImgPtr[9];	CastParam.PtrC3 = ImgPtr[10];	CastParam.PtrC4 = ImgPtr[11];
		CastParam.PtrD1 = ImgPtr[12];	CastParam.PtrD2 = ImgPtr[13];	CastParam.PtrD3 = ImgPtr[14];	CastParam.PtrD4 = ImgPtr[15];
		if ( SLICE_FUNC_3D_4STEP_4GC_2EXP==SliceFuncMode || SLICE_FUNC_3D_4STEP_4GC_2LIGHT==SliceFuncMode )
		{
			PhaseMode = LIGHT3D_PHASE_4_4GC_M_2;
			CastParam.DecodeMode = DECODE_PHASE_4STEP_4GC_2;
		}
		else
		{
			PhaseMode = LIGHT3D_PHASE_4_4_M_2;
			CastParam.DecodeMode = DECODE_PHASE_4_4STEP_2;
		}		
		break;
	case 18:
		CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];	CastParam.PtrA4 = ImgPtr[3];
		CastParam.PtrB1 = ImgPtr[4];	CastParam.PtrB2 = ImgPtr[5];	CastParam.PtrB3 = ImgPtr[6];	CastParam.PtrB4 = ImgPtr[7];	CastParam.PtrB5 = ImgPtr[8];
		CastParam.PtrC1 = ImgPtr[9];	CastParam.PtrC2 = ImgPtr[10];	CastParam.PtrC3 = ImgPtr[11];	CastParam.PtrC4 = ImgPtr[12];
		CastParam.PtrD1 = ImgPtr[13];	CastParam.PtrD2 = ImgPtr[14];	CastParam.PtrD3 = ImgPtr[15];	CastParam.PtrD4 = ImgPtr[16];	CastParam.PtrD5 = ImgPtr[17];
		if ( SLICE_FUNC_3D_4STEP_5GC_2EXP==SliceFuncMode || SLICE_FUNC_3D_4STEP_5GC_2LIGHT==SliceFuncMode )
		{
			PhaseMode = LIGHT3D_PHASE_4_5GC_M_2;
			CastParam.DecodeMode = DECODE_PHASE_4STEP_5GC_2;
		}		
		break;
	case 20:
		if ( SLICE_FUNC_3D_4STEP_6GC_2EXP==SliceFuncMode || SLICE_FUNC_3D_4STEP_6GC_2LIGHT==SliceFuncMode )
		{
			CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];	CastParam.PtrA4 = ImgPtr[3];;
			CastParam.PtrB1 = ImgPtr[4];	CastParam.PtrB2 = ImgPtr[5];	CastParam.PtrB3 = ImgPtr[6];	CastParam.PtrB4 = ImgPtr[7];	CastParam.PtrB5 = ImgPtr[8];	CastParam.PtrB6 = ImgPtr[9];
			CastParam.PtrC1 = ImgPtr[10];	CastParam.PtrC2 = ImgPtr[11];	CastParam.PtrC3 = ImgPtr[12];	CastParam.PtrC4 = ImgPtr[13];
			CastParam.PtrD1 = ImgPtr[14];	CastParam.PtrD2 = ImgPtr[15];	CastParam.PtrD3 = ImgPtr[16];	CastParam.PtrD4 = ImgPtr[17];	CastParam.PtrD5 = ImgPtr[18];	CastParam.PtrD6 = ImgPtr[19];
			PhaseMode = LIGHT3D_PHASE_4_6GC_M_2;
			CastParam.DecodeMode = DECODE_PHASE_4STEP_6GC_2;
		}
		else
		{
			CastParam.PtrA1 = ImgPtr[0];	CastParam.PtrA2 = ImgPtr[1];	CastParam.PtrA3 = ImgPtr[2];	CastParam.PtrA4 = ImgPtr[3];	CastParam.PtrA5 = ImgPtr[4];
			CastParam.PtrB1 = ImgPtr[5];	CastParam.PtrB2 = ImgPtr[6];	CastParam.PtrB3 = ImgPtr[7];	CastParam.PtrB4 = ImgPtr[8];	CastParam.PtrB5 = ImgPtr[9];
			CastParam.PtrC1 = ImgPtr[10];	CastParam.PtrC2 = ImgPtr[11];	CastParam.PtrC3 = ImgPtr[12];	CastParam.PtrC4 = ImgPtr[13];	CastParam.PtrC5 = ImgPtr[14];
			CastParam.PtrD1 = ImgPtr[15];	CastParam.PtrD2 = ImgPtr[16];	CastParam.PtrD3 = ImgPtr[17];	CastParam.PtrD4 = ImgPtr[18];	CastParam.PtrD5 = ImgPtr[19];
			PhaseMode = LIGHT3D_PHASE_5_5_M_2;
			CastParam.DecodeMode = DECODE_PHASE_5_5STEP_2;
		}
		break;	
	default:
		PhaseMode = 0;		
		break;
	}
	if ( 0 == PhaseMode )
	{
		m_ErrorString.Format(_T("Error, CAOIDataCollect::BuildCastParam2Exp Fault"));
		return false;
	}

	TPhaseNoiseParam NoiseParam;
	const size_t BufferSize = ImageAPI.CalcBufferSize(ImageStep, ImageH);
	GetPhaseNoiseDefineParam(NoiseParam);
	const int   nSmoothFilterSize = NoiseParam.PhaseSmoothFilter;
	const BOOL  bCheckSmoothFilter = (BOOL)(NoiseParam.PhaseNoiseDef&PHASE_NOSIE_SMOOTH_FILTER);
	if ( FALSE!=bCheckSmoothFilter && nSmoothFilterSize>0 )
	{
		IMAGE_PTR    SrcPtr = NULL;
		IMAGE_PTR    BufferPtr = NULL;		
		const int    KerSize = nSmoothFilterSize*2+1;
		switch ( PhaseMode )
		{
		case LIGHT3D_PHASE_2_2_M_2:
			break;
		case LIGHT3D_PHASE_4_2_M_2:
			break;
		case LIGHT3D_PHASE_4_4_M_2:
			if ( JetMemory.alloc_func(BufferSize, BufferPtr, fnName, "BufferPtr") == true )
			{
				SrcPtr = CastParam.PtrB1;
				if ( NULL != SrcPtr )
				{
					if ( ImageAPI.SmoothGrayImage3(ImageW, ImageH, ImageStep, SrcPtr, KerSize, BufferPtr) == true )
					{	::memcpy(SrcPtr, BufferPtr, BufferSize);	}
				}
				SrcPtr = CastParam.PtrB2;
				if ( NULL != SrcPtr )
				{
					if ( ImageAPI.SmoothGrayImage3(ImageW, ImageH, ImageStep, SrcPtr, KerSize, BufferPtr) == true )
					{	::memcpy(SrcPtr, BufferPtr, BufferSize);	}
				}
				SrcPtr = CastParam.PtrB3;
				if ( NULL != SrcPtr )
				{
					if ( ImageAPI.SmoothGrayImage3(ImageW, ImageH, ImageStep, SrcPtr, KerSize, BufferPtr) == true )
					{	::memcpy(SrcPtr, BufferPtr, BufferSize);	}
				}
				SrcPtr = CastParam.PtrB4;
				if ( NULL != SrcPtr )
				{
					if ( ImageAPI.SmoothGrayImage3(ImageW, ImageH, ImageStep, SrcPtr, KerSize, BufferPtr) == true )
					{	::memcpy(SrcPtr, BufferPtr, BufferSize);	}
				}
				SrcPtr = CastParam.PtrB5;
				if ( NULL != SrcPtr )
				{
					if ( ImageAPI.SmoothGrayImage3(ImageW, ImageH, ImageStep, SrcPtr, KerSize, BufferPtr) == true )
					{	::memcpy(SrcPtr, BufferPtr, BufferSize);	}
				}
				JetMemory.free_func(BufferPtr);

				SrcPtr = CastParam.PtrD1;
				if ( NULL != SrcPtr )
				{
					if ( ImageAPI.SmoothGrayImage3(ImageW, ImageH, ImageStep, SrcPtr, KerSize, BufferPtr) == true )
					{	::memcpy(SrcPtr, BufferPtr, BufferSize);	}
				}
				SrcPtr = CastParam.PtrD2;
				if ( NULL != SrcPtr )
				{
					if ( ImageAPI.SmoothGrayImage3(ImageW, ImageH, ImageStep, SrcPtr, KerSize, BufferPtr) == true )
					{	::memcpy(SrcPtr, BufferPtr, BufferSize);	}
				}
				SrcPtr = CastParam.PtrD3;
				if ( NULL != SrcPtr )
				{
					if ( ImageAPI.SmoothGrayImage3(ImageW, ImageH, ImageStep, SrcPtr, KerSize, BufferPtr) == true )
					{	::memcpy(SrcPtr, BufferPtr, BufferSize);	}
				}
				SrcPtr = CastParam.PtrD4;
				if ( NULL != SrcPtr )
				{
					if ( ImageAPI.SmoothGrayImage3(ImageW, ImageH, ImageStep, SrcPtr, KerSize, BufferPtr) == true )
					{	::memcpy(SrcPtr, BufferPtr, BufferSize);	}
				}
				SrcPtr = CastParam.PtrD5;
				if ( NULL != SrcPtr )
				{
					if ( ImageAPI.SmoothGrayImage3(ImageW, ImageH, ImageStep, SrcPtr, KerSize, BufferPtr) == true )
					{	::memcpy(SrcPtr, BufferPtr, BufferSize);	}
				}
				JetMemory.free_func(BufferPtr);				
			}
			break;	
		case LIGHT3D_PHASE_4_4GC_M_2:
			break;
		case LIGHT3D_PHASE_4_5GC_M_2:
			break;
		case LIGHT3D_PHASE_4_6GC_M_2:
			break;
		}
	}

	PHASE_PTR BasePhasePtr = NULL;
	IMAGE_SIZE PhaseW=0, PhaseH=0, PhaseStep=0;
	if ( Light3DCtrl.GetLight3DPhaseZero(CastID, PhaseMode, DLPLEDColor, PhaseW, PhaseH, PhaseStep, BasePhasePtr) == false )
	{
		m_ErrorString.Format(_T("%s [%s]"), Light3DCtrl.GetErrorString(), CastName);
		return false;	
	}
	if ( ImageW!=PhaseW || ImageH!=PhaseH || ImageStep!=PhaseStep )
	{
		m_ErrorString.Format(_T("Error, %s, Image[Phase] Size Exception (%d, %d, %d) != (%d, %d, %d)"), CastName, ImageW, ImageH, ImageStep, PhaseW, PhaseH, PhaseStep);
		return false; 
	}

	IMAGE_SIZE SpaceW=0, SpaceH=0, SpaceStep=0;
	SPACE_PTR KPtr = NULL;		
	if ( Light3DCtrl.GetLight3DPhaseFactor(CastID, PhaseMode, DLPLEDColor, SpaceW, SpaceH, SpaceStep, KPtr) == false )
	{
		m_ErrorString.Format(_T("%s [%s]"), Light3DCtrl.GetErrorString(), CastName);
		return false;	
	}
	if ( ImageW!=SpaceW || ImageH!=SpaceH || ImageStep!=SpaceStep )
	{
		m_ErrorString.Format(_T("Error, %s Image[Space] Size Exception (%d, %d, %d) != (%d, %d, %d)"), CastName, ImageW, ImageH, ImageStep, SpaceW, SpaceH, SpaceStep);
		return false; 
	}
	CastParam.ZeroPhasePtr = BasePhasePtr;
	CastParam.HeightFactorPtr = KPtr;

	if ( JetMemory.alloc_func(BufferSize, CastParam.PtrMask, fnName, "CastParam.PtrMask") == false || 		 
		 JetMemory.alloc_func(BufferSize, CastParam.PtrSpace, fnName, "CastParam.PtrSpace") == false )
	{
		JetMemory.free_func(CastParam.PtrMask);		
		JetMemory.free_func(CastParam.PtrSpace);		
		return false;
	}

	double Gamma=1.0;
	if ( Light3DCtrl.GetLight3DImageGamma(CastID, Gamma) == false )
	{
		m_ErrorString.Format(_T("%s [%s]"), Light3DCtrl.GetErrorString(), CastName);
		return false;	
	}
	CastParam.Gamma = Gamma;

	//高度係數
	if ( Light3DCtrl.GetLight3DHeightFactor(CastID, CastParam.HeightFactor0, CastParam.HeightFactor1, CastParam.HeightFactor2) == false )
	{
		m_ErrorString.Format(_T("%s [%s]"), Light3DCtrl.GetErrorString(), CastName);
		return false;	
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::BuildCastParamArray_Calibration(size_t TotalCount, IMAGE_SIZE ImageW[], IMAGE_SIZE ImageH[], IMAGE_SIZE ImageStep[], IMAGE_PTR ImagePtr[], const TSliceParam &SliceParam, TCastParam CastParam[])//建立投光參數
{	
	CString str;	
	int   idx=0;
	int   i=0, j=0;
	int   DLPIndex=0;
	int   DLPUsdCnt=0;
	const int FrameImageCount=TotalCount;
	const int DLPCastCount=DLP_CAST_COUNT;
	SLICE_FUNC_MODE  SliceFuncMode=SliceParam.SliceFuncMode;
	LIGHT_3D_CAST_ID CastID[DLP_CAST_COUNT]={LIGHT_3D_CAST_00};				
	CheckSliceParamUsed3DCastID(SliceParam.SliceLightTable, CastID);
	const int DLPLightCnt = CheckFrameLightCountBySliceFuncMode(SliceFuncMode);
	const bool bUse2Exp = CheckSliceFuncModeDlpUse2Exp(SliceFuncMode);
	const int  PatternCount = CheckSliceFuncModeDlpPatternCountOnce(SliceFuncMode);
	if ( 0 == PatternCount )
	{
		str.Format(_T("Error, BuildCastParamArray_Calibration Fault [SliceFuncMode=%d]"), SliceFuncMode);
		SetErrorString(str);
		return false;
	}

	bool IsOK = true;
	for ( i=0; i<DLPCastCount; i++ )
	{
		if ( (idx+PatternCount) > FrameImageCount )
		{	break; }
		if ( false == bUse2Exp || 1!=DLPLightCnt )
		{	IsOK = BuildCastParam(ImageW[idx], ImageH[idx], ImageStep[idx], PatternCount, SliceFuncMode, &(ImagePtr[idx]), CastID[DLPIndex], CastParam[DLPIndex]);	}
		else
		{	IsOK = BuildCastParam2Exp(ImageW[idx], ImageH[idx], ImageStep[idx], PatternCount, SliceFuncMode, &(ImagePtr[idx]), CastID[DLPIndex], CastParam[DLPIndex]);	}
		if ( false == IsOK )
		{
			for ( j=0; j<i; j++ )
			{
				JetMemory.free_func(CastParam[j].PtrMask);
				JetMemory.free_func(CastParam[j].PtrSpace);
			}
			return false;
		}		
		idx += PatternCount;
		DLPIndex ++;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecGrabFrameImage(unsigned int FrameUniqueID, FRAME_TYPE &FrameType)//執行Frame畫面的取像
{	//FRAME_UNIQUE_ID_NULL
	const unsigned int FrameParamIndex = (unsigned int)GetSystemFrameParamIndex(FrameUniqueID);
	if ( -1 == FrameParamIndex ) { return FALSE; }
	TFrameParam *FrameParamPtr = CAOIDataCollect::GetSystemFrameParamPtr(FrameParamIndex, false);
	if ( NULL == FrameParamPtr ) { return FALSE; }
	FrameType = FrameParamPtr->FrameType;	
	std::vector<TSliceParam> ParamList;
	if ( BuildSliceParamListByFrameUniqueID(FrameUniqueID, ParamList) == FALSE )
	{	return FALSE;	}
	
	if ( MotionCtrlPtr->WaitForMotionStop() == false )
	{
		this->m_ErrorString = MotionCtrlPtr->GetErrorString();		
		return false;
	}
#ifndef OFFLINE_VERSION
	size_t           i=0, j=0;	
	TSliceParam      SliceParam;
	bool UseDLPID[DLP_CAST_COUNT]={false};
	LIGHT_3D_CAST_ID Light3DID=LIGHT_3D_CAST_00;	
	LIGHT_3D_CLS_PTR Light3DPtr = NULL;
	const size_t SliceParamCount = ParamList.size();
	const int    CurrentID = DLP_LED_CURRENT_ID_01;

	for ( i=0; i<SliceParamCount; i++ )
	{
		SliceParam = (ParamList[i]);
		if ( LIGHT_DLP == SliceParam.SliceLightTable.LightType )
		{
			for (j=0; j<DLP_CAST_COUNT; j++ )
			{
				if ( FN_DISABLE == SliceParam.SliceLightTable.DLPCast[j].OnOffState ) { continue; }
				UseDLPID[j] = true;
			}
		}
	}
	
	for ( j=0; j<DLP_CAST_COUNT; j++ )
	{
		if ( false == UseDLPID[j] ) { continue; }
		Light3DID = CLight3DCtrl::GetLight3DCastIDByIndex(j);
		if ( LIGHT_3D_CAST_00 == Light3DID ) { continue; }		
		Light3DPtr = Light3DCtrl.GetLight3DCastPtr(Light3DID);
		if ( NULL != Light3DPtr )
		{
			int CurRed=0, CurGrn=0, CurBlu=0;
			if ( Light3DPtr->GetDLPParamLEDCurrent(CurRed, CurGrn, CurBlu, CurrentID) == false )
			{
				this->m_ErrorString = Light3DPtr->GetErrorString();
				return false;
			}
			if ( Light3DCtrl.SetLight3DLEDEnabled(Light3DID, true, true, true, true) == false )
			{
				this->m_ErrorString = Light3DCtrl.GetErrorString();			
				return false;
			}
			if ( Light3DCtrl.SetLight3DLEDCurrent(Light3DID, CurRed, CurGrn, CurBlu, CurrentID) == false )
			{
				this->m_ErrorString = Light3DCtrl.GetErrorString();			
				return false;
			}
		}
	}
	if ( CameraCtrl.BatchGrabPrepare2(ParamList, true) == false )
	{
		this->m_ErrorString = CameraCtrl.GetErrorString();			
		return false;
	}
	bool bFinish = false;			
	if ( CameraCtrl.BatchGrabStart2(bFinish) == false )
	{
		this->m_ErrorString = CameraCtrl.GetErrorString();			
		return false;
	}
#else
	#ifdef COLOR_VERTICAL_CAMERA
//		this->PostMessage(BAYER_CAMERA_CALLBACK, NULL, NULL);
	#else
//		this->PostMessage(CAMERA_5_CALLBACK, NULL, NULL);
	#endif
#endif//OFFLINE_VERSION	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecGrabNextUniFrameImage()//執行Frame畫面的取像
{
	if ( MotionCtrlPtr->WaitForMotionStop() == false )
	{
		m_ErrorString = MotionCtrlPtr->GetErrorString();		
		return false;
	}
	if ( CameraCtrl.GetBatchGrabbing() == true )
	{
		SetErrorString(_T("Wait for Camera Grabbing"));		
		return false;
	}
#ifndef LIGHT_CTRL_DISABLE
	bool      bCameraFinish = true;	
	CameraCtrl.ClearAllCameraCount();	
	if ( CameraCtrl.ResetAllCameraRingBuffer() == false )
	{
		m_ErrorString = CameraCtrl.GetErrorString();				
		return false;
	}
	if ( CameraCtrl.BatchIndexReset() == false )
	{
		m_ErrorString = CameraCtrl.GetErrorString();				
		return false;
	}
	const std::vector<TSliceParam> &SliceParamList=CameraCtrl.GetBatchParamList();
	if ( CameraCtrl.SetBatchGrabExpourseTime(SliceParamList) == false )
	{
		m_ErrorString = CameraCtrl.GetErrorString();				
		return false;
	}
	if ( CameraCtrl.BatchGrabStart2(bCameraFinish) == false )
	{		
		m_ErrorString = CameraCtrl.GetErrorString();				
		return false;
	}
#else
	m_ErrorString = _T("Error, ExecGrabNextUniFrameImage Only Support LIGHT_CTRL_ENABLE");
	return false;
#endif//LIGHT_CTRL_DISABLE	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckCanGrabNextUniFrameImage()//確認可以取Frame畫面影像
{
	if ( CameraCtrl.GetBatchGrabbing()==true )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SetProjectLightSetting(CAOIProject* ProjectPtr)//專案燈源設定
{
	if ( NULL == ProjectPtr ) { return false; }
	bool ResetLight = false;   //設定光源與系統
	std::vector<TFrameParam>  ProjectFrameParamList;//影像參數列表
	const int DLPLEDColor = ProjectPtr->GetProjectParameter().m_ProjectDlpLedColor;	

	//ProjectPtr->SwtichProjectOfflineFileMode(OFFLINE_FILE_INSPECTION);	
	ProjectPtr->CloneProjectFrameParamList(ProjectFrameParamList);
	Light3DCtrl.SetAllLight3DLEDColor(DLPLEDColor);	
	if ( ExecPrepareFrameImageSetting(ProjectFrameParamList, ResetLight) == false )
	{	return false;	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SetSliceParam2DCurrent(TSliceParam &Param, int Current) const//設定SliceParam的電流
{
	int i=0;	
	const int ChannelCount=LED_CHANNEL_COUNT;
	for ( i=0; i<ChannelCount; i++ )
	{
		if ( FN_DISABLE == Param.SliceLightTable.LEDChannel[i].OnOffState ) { continue; }		
		Param.SliceLightTable.LEDChannel[i].PowerValue = Current;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::GetSliceParam2DCurrentCmpText(const TSliceParam &ParamBef, const TSliceParam &ParamAft, CString &Str) const//取得SliceParam的2D電流比較文字
{
	int i=0;	
	CString strBef;
	CString strAft;
	CString strTmp;
	CString strTmp2;
	CString strON=_T("ON");
	CString strOFF=_T("OFF");
	bool bFirst=true;	
	const int ChannelCount=LED_CHANNEL_COUNT;
	for ( i=0; i<ChannelCount; i++ )
	{
		if ( FN_DISABLE==ParamBef.SliceLightTable.LEDChannel[i].OnOffState ) { strBef=strOFF; }
		else { strBef = strON; }
		if ( FN_DISABLE==ParamAft.SliceLightTable.LEDChannel[i].OnOffState ) { strAft=strOFF; }
		else { strAft = strON; }
		strTmp.Format(_T("CH_%02d Form [%s] to [%s]"), i+1, strBef, strAft);		
		if ( FN_DISABLE == ParamBef.SliceLightTable.LEDChannel[i].OnOffState ) { continue; }

		strBef.Format(_T("%03d"), ParamBef.SliceLightTable.LEDChannel[i].PowerValue);
		strAft.Format(_T("%03d"), ParamAft.SliceLightTable.LEDChannel[i].PowerValue);
		strTmp.Format(_T("CH_%02d Form [%s] to [%s]"), i+1, strBef, strAft);		
		if ( true == bFirst )
		{	
			bFirst = false;
			Str=strTmp;
			continue;
		}
		strTmp2 = Str;
		Str.Format(_T("%s, %s"), strTmp2, strTmp);
	}	
	return true;
}
