bool CAOIDataCollect::ExecPrepareSliceImageSetting(const std::vector<TSliceParam> &ParamList, bool ResetLight)//執行SliceParam的取像設定
{	
#ifndef OFFLINE_VERSION		
	CString str;
	str.Format(_T("CAOIDataCollect::ExecPrepareSliceImageSetting Start"));
	SaveMovingTimeMsg(str);
	if ( true == ResetLight )
	{
		if ( SetupAllLightSetting() == false )
		{	return false; }
	}

	if ( CameraCtrl.BatchGrabPrepare2(ParamList, false) == false )
	{
		this->m_ErrorString = CameraCtrl.GetErrorString();			
		return false;
	}
	//只準備, 不取像
	//bool bFinish = false;			
	//if ( CameraCtrl.BatchGrabStart2(bFinish) == false )
	//{
	//	this->m_ErrorString = CameraCtrl.GetErrorString();			
	//	return false;
	//}
	str.Format(_T("CAOIDataCollect::ExecPrepareSliceImageSetting End"));
	SaveMovingTimeMsg(str);
#else
	#ifdef COLOR_VERTICAL_CAMERA
//		this->PostMessage(BAYER_CAMERA_CALLBACK, NULL, NULL);
	#else
//		this->PostMessage(CAMERA_5_CALLBACK, NULL, NULL);
	#endif
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SetupAllLightSetting()//設定所有燈原設定
{		
#ifndef OFFLINE_VERSION
	size_t             i=0;
	LIGHT_3D_CLS_PTR   Light3DPtr = NULL;
	LIGHT_3D_CAST_ID   Light3DID = LIGHT_3D_CAST_00;

	CString        str;	
	double         fnTime = 0.0;
	LARGE_INTEGER  fnStart, fnEnd;
	

	const int  NFrames = 1;
	const bool bForce = true;
	const bool bSleep = true;
	const bool DLPMultiTable = true;
	const bool DLPInternalTrigger = false;	
	const int CameraExpTimeus = GetCalibrationParameter().m_ExposureTime_us;

	str.Format(_T("CAOIDataCollect::SetupAllLightSetting Start"));
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	JetAPI::SetFuncTimeStart(fnStart);
	
	if ( CameraCtrl.SetAllCameraExposureTime(CameraExpTimeus) == false )
	{
		m_ErrorString = CameraCtrl.GetErrorString();
		return false;
	}
	if ( CameraCtrl.SetAllCameraExternalTrigger() == false )//設定相機外部觸發
	{
		m_ErrorString = CameraCtrl.GetErrorString();
		return false;
	}	
#if LIGHT_3D_MODE == LIGHT_3D_TI_DLP
	bool  IsOK = true;
	bool  IsOK_DLP[DLP_CAST_COUNT];
	CString Err_DLP[DLP_CAST_COUNT];
	const int CurrentID = DLP_LED_CURRENT_ID_01;		
	std::vector<LIGHT_3D_CAST_ID> CastIDList;
	Light3DCtrl.GetLight3DCastIDList(CastIDList);
	const size_t CastIDCount=CastIDList.size();
	const unsigned int SliceUniqueID3D = SLICE_UNIQUE_ID_DLP;
	TSliceParam *SliceParamPtr = GetSystemSliceParamPtrByUniqueID(SliceUniqueID3D);	
	for ( i=0; i<CastIDCount; i++ )
	{
		IsOK_DLP[i] = true;
		Light3DID = CastIDList[i];
		Light3DPtr = Light3DCtrl.GetLight3DCastPtr(Light3DID);
		if ( NULL == Light3DPtr ) { continue; }
	#ifndef PHASE_CTRL_DISABLE
		Light3DPtr->ClearDLPPatternList();
		if ( Light3DPtr->ExecDLPLightSetting(CurrentID) == false )
		{
			IsOK_DLP[i] = false;
			Err_DLP[i] = Light3DPtr->GetErrorString();
			continue;			
		}
		
		const int DLPLEDColor = Light3DPtr->GetDLPParam().m_LEDColor;
		const int DLPPeriod_us = Light3DPtr->GetDLPParam().m_PeriodTime_us;
		const int DLPExposure_us = Light3DPtr->GetDLPParam().m_ExposureTime_us;		
		if ( i < DLP_CAST_COUNT )
		{
			if ( NULL != SliceParamPtr )
			{	
				const int sCameraExpTimeus = SliceParamPtr->SliceCameraExpTimeus;
				int PhasePatMode = SliceParamPtr->SliceLightTable.DLPCast[i].PhasePatMode;
				if (  sCameraExpTimeus < DLPExposure_us )
				{					
					IsOK_DLP[i] = false;
					Err_DLP[i].Format(_T("Error, Camera Exp. Time[%d] < DLP Exp. Time[%d]"), sCameraExpTimeus, DLPExposure_us);
					continue;					
				}
				if (  sCameraExpTimeus < DLPPeriod_us )
				{
					IsOK_DLP[i] = false;
					Err_DLP[i].Format(_T("Error, Camera Exp. Time[%d] < DLP Period Time[%d]"), sCameraExpTimeus, DLPPeriod_us);					
					continue;					
				}
				//關閉DLP持續投光		
				if ( Light3DPtr->ExecDLPPatBuildSendValidate(PhasePatMode, DLPInternalTrigger, DLPMultiTable, DLPPeriod_us, DLPExposure_us, DLPLEDColor, bSleep, bForce) == false )
				{
					IsOK_DLP[i] = false;
					Err_DLP[i] = Light3DPtr->GetErrorString();
					continue;					
				}	
				if ( Light3DPtr->ExecDLPPattern_Run() == false )
				{
					IsOK_DLP[i] = false;
					Err_DLP[i] = Light3DPtr->GetErrorString();
					continue;
				}
			}
		}
	#endif//PHASE_CTRL_DISABLE
	}

#ifndef PHASE_CTRL_DISABLE
	const bool ResetDlp=true;
	const bool RepeatSetting=true;	
	LIGHT_3D_DEVICE_TYPE  DeviceType;
	m_ErrorString=_T("");
	for ( int i=0; i<CastIDCount; i++ )
	{
		if ( false == IsOK_DLP[i] )
		{
			IsOK = false;
			if ( m_ErrorString.GetLength() == 0 )
			{	m_ErrorString = Err_DLP[i];	}
			else
			{
				str = m_ErrorString;
				m_ErrorString.Format(_T("%s\n%s"), str, Err_DLP[i]);
			}			
		}
	}
	if ( false == IsOK )
	{			
		if ( true==ResetDlp || true==RepeatSetting )
		{	
			IsOK = true;	
			SaveMovingTimeMsg(m_ErrorString);
		}
		else
		{
			JetAPI::ShowMessageBox(m_ErrorString);
			return false;	
		}
	}

	bool  IsOK_DLP2[DLP_CAST_COUNT];
	for ( int i=0; i<CastIDCount; i++ )
	{	IsOK_DLP2[i] = true;	}
	if ( true == ResetDlp )
	{
		for ( int i=0; i<CastIDCount; i++ )
		{
			if ( true == IsOK_DLP[i] )	{	continue; }
			Light3DID = CastIDList[i];
			Light3DPtr = Light3DCtrl.GetLight3DCastPtr(Light3DID);
			if ( NULL == Light3DPtr ) { continue; }			
			DeviceType=Light3DPtr->GetDeviceType();
			if ( LIGHT_3D_DEVICE_DLP4500 != DeviceType )
			{	continue; }
			if ( Light3DPtr->DLPConnect() == false )			
			{
				IsOK_DLP2[i] = false;
				Err_DLP[i] = Light3DPtr->GetErrorString();
				continue;
			}	
		}
	}
	if ( true == RepeatSetting )
	{
		for ( int i=0; i<CastIDCount; i++ )
		{
			if ( true == IsOK_DLP[i] )	{	continue; }
			if ( false == IsOK_DLP2[i] )	{	continue; }			
			Light3DID = CastIDList[i];
			Light3DPtr = Light3DCtrl.GetLight3DCastPtr(Light3DID);
			if ( NULL == Light3DPtr ) { continue; }
			DeviceType=Light3DPtr->GetDeviceType();
			if ( LIGHT_3D_DEVICE_DLP4500 != DeviceType )
			{	continue; }
			IsOK_DLP[i] = true;
		//#ifndef PHASE_CTRL_DISABLE
			Light3DPtr->ClearDLPPatternList();
			if ( Light3DPtr->ExecDLPLightSetting(CurrentID) == false )
			{
				IsOK_DLP[i] = false;
				Err_DLP[i] = Light3DPtr->GetErrorString();				
				continue;
			}

			const int DLPLEDColor = Light3DPtr->GetDLPParam().m_LEDColor;
			const int DLPPeriod_us = Light3DPtr->GetDLPParam().m_PeriodTime_us;
			const int DLPExposure_us = Light3DPtr->GetDLPParam().m_ExposureTime_us;		
			if ( i < DLP_CAST_COUNT )
			{
				if ( NULL != SliceParamPtr )
				{
					const int sCameraExpTimeus = SliceParamPtr->SliceCameraExpTimeus;
					int PhasePatMode = SliceParamPtr->SliceLightTable.DLPCast[i].PhasePatMode;
					if (  sCameraExpTimeus < DLPExposure_us )
					{
						IsOK_DLP[i] = false;
						Err_DLP[i].Format(_T("Error, Camera Exp. Time[%d] < DLP[%d] Exp. Time[%d]"), sCameraExpTimeus, i+1, DLPExposure_us);
						continue;
					}
					if (  sCameraExpTimeus < DLPPeriod_us )
					{
						IsOK_DLP[i] = false;
						Err_DLP[i].Format(_T("Error, Camera Exp. Time[%d] < DLP[%d] Period Time[%d]"), sCameraExpTimeus, i+1, DLPPeriod_us);
						continue;
					}
					//關閉DLP持續投光		
					if ( Light3DPtr->ExecDLPPatBuildSendValidate(PhasePatMode, DLPInternalTrigger, DLPMultiTable, DLPPeriod_us, DLPExposure_us, DLPLEDColor, bSleep, bForce) == false )
					{
						IsOK_DLP[i] = false;
						Err_DLP[i] = Light3DPtr->GetErrorString();	
						continue;
					}	
					if ( Light3DPtr->ExecDLPPattern_Run() == false )
					{
						IsOK_DLP[i] = false;	
						Err_DLP[i] = Light3DPtr->GetErrorString();
						continue;
					}
				}
			}
		//#endif//PHASE_CTRL_DISABLE
		}
	}
#endif//PHASE_CTRL_DISABLE

	m_ErrorString=_T("");
	for ( i=0; i<CastIDCount; i++ )
	{
		if ( false == IsOK_DLP[i] )
		{
			IsOK = false;
			if ( m_ErrorString.GetLength() == 0 )
			{	m_ErrorString = Err_DLP[i];	}
			else
			{
				str = m_ErrorString;
				m_ErrorString.Format(_T("%s\n%s"), str, Err_DLP[i]);
			}			
		}
	}
	if ( false == IsOK )
	{	
		JetAPI::ShowMessageBox(m_ErrorString);
		return false; 
	}
#endif//LIGHT_3D_MODE == LIGHT_3D_TI_DLP
	JetAPI::SetFuncTimeEnd(fnEnd);
	fnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);
	str.Format(_T("CAOIDataCollect::SetupAllLightSetting Time=%.3f ms"), fnTime);
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::AutoSetupAllLightSetting()//自動設定所有燈原設定
{	//20230425
	if ( FN_DISABLE == GetSystemParameter().m_AutoSetupDlpPattern )
	{	return true; }
	LockThread();
	const bool bSucc=AutoSetupAllLightSettingFn();
	UnlockThread();
	return bSucc;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::AutoSetupAllLightSettingFn()//自動設定所有燈原設定
{	
	CString str;
	const bool bDualRunMode = CheckDualRunMode();
	str.Format(_T("CAOIDataCollect::AutoSetupAllLightSetting Start"));
	SaveMovingTimeMsg(str);
	if ( GetIsNeedResetLightCtrlDLP() == false )
	{	return true; }
	if ( false == bDualRunMode )
	{
		if ( SetupAllLightSetting() == false )
		{	return false;	}
	}
	SetIsNeedResetLightCtrlDLP(false);
	str.Format(_T("CAOIDataCollect::AutoSetupAllLightSetting End"));
	SaveMovingTimeMsg(str);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecCaptureProjectMap(CAOIProject *ProjectPtr)//擷取專案底圖
{
	if ( NULL == ProjectPtr ) { return false; }
	CString      str;
	TREGION4D    ProjectRgn;
	unsigned int ProjectMapIndex = 0;	

	str = _T("Capture Project Map Start");	
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	str += _T("\n");	
	TRACE(str);

	ProjectPtr->SetProjectProgramFieldDoNotSave(false);
	if ( ProjectPtr->CheckProjectMapPtr(ProjectMapIndex) == false )
	{
		this->m_ErrorString = ProjectPtr->GetProjectErrorString();
		return false;
	}

	if ( ProjectPtr->CreateProjectCaptureMapObj() == false )
	{
		this->m_ErrorString = ProjectPtr->GetProjectErrorString();
		return false;
	}
	
	if ( ProjectPtr->ResetProjectProgramFrameFileName() == false )	
	{
		this->m_ErrorString = ProjectPtr->GetProjectErrorString();
		return false;
	}
	
	if ( CloneAllPtrList(ProjectPtr) == false )
	{	return false; }
	
	const size_t FieldCount = m_FieldPtrList.size();
	if ( FieldCount > 0 ) 
	{
		CAOIField *FieldPtr = m_FieldPtrList[0];
		double StagePosX = FieldPtr->GetFieldStagePosX();
		double StagePosY = FieldPtr->GetFieldStagePosY();
		MotionCtrlPtr->XYMoveTo(StagePosX, StagePosY);
	}

	m_RgnFinishedCnt = 0;
	m_SliceFinishedCnt = 0;	
	m_FrameFinishedCnt = 0;
	m_FieldCalcFinishedCnt = 0;
	m_FieldMergeFinishedCnt = 0;

	//確認列表狀態	
	const double dMaxH  = ProjectPtr->GetProjectSpaceMaxHeight();
	const double dLevel = ProjectPtr->GetProjectSpaceBaseHeight();
	const int RatioMode = ProjectPtr->GetProjectSpaceToGrayRatioMode();
	const DISTRICT_ID DistrictID = ProjectPtr->GetProjectActDistrictID();
	const bool SaveOfflineImageFiles = ProjectPtr->GetProjectSaveOfflineImageFiles();

	SetSpaceMaxHeight(dMaxH);
	SetSpaceBaseHeight(dLevel);	
	SetSpaceToGrayRatioMode(RatioMode);
	if ( CheckObjListInitialized() == false )
	{	return false;	}

	//是否儲存Offline
	SetSaveOfflineFiles(true);	
	SetSaveOfflineImageFiles(SaveOfflineImageFiles);	
	m_OfflineFolder = ProjectPtr->GetProjectProgramOfflineFolder();
	m_OfflineFileName = AOIDataDefine.GetProjectOfflineFileName(m_OfflineFolder, DistrictID);
	::CreateDirectory(m_OfflineFolder, NULL);
	ProjectPtr->SaveProjectProgramOfflineFile(m_OfflineFileName);	
	
	//先重設定所有燈原狀態
	//if ( this->SetupAllLightSetting() == false )
	//{	return false;	}

#ifndef LIGHT_CTRL_DISABLE
	std::vector<TSliceParam> SliceParamList;
	ProjectPtr->CloneProjectSliceParamList(SliceParamList);
	if ( CameraCtrl.BatchGrabPrepare2(SliceParamList, true) == false )
	{
		this->m_ErrorString = CameraCtrl.GetErrorString();			
		return false;
	}
#endif//LIGHT_CTRL_DISABLE

	SetInspectionDrawing(true);
	SetThreadGrabMode(THREAD_GRAB_PROJECT_MAP);	

	//覆歸循環Buffer的資料
	//CameraCtrl.ClearAllCameraCount();
	CameraCtrl.ResetAllCameraRingBuffer();

	//啟動計算執行緒
	const bool bWaitThread=false;	
	StartSliceFillThread(bWaitThread);//啟動填圖的執行緒	
	StartFrameMergeThread(bWaitThread);//啟動影像的執行緒
	StartFieldMergeThread(bWaitThread);//啟動區域的執行緒
	StartFieldCalcThread(bWaitThread);//啟動區域的執行緒
	//StartRegionCalcThread(bWaitThread);
	StartRegionCalcThread_Partial(bWaitThread);
	if ( false == bWaitThread )
	{
		WaitForSliceFillThreadStart();
		WaitForFrameMergeThreadStart();
		WaitForFieldMergeThreadStart();
		WaitForFieldCalcThreadStart();
		//WaitForRegionCalcThreadStart();
		WaitForRegionCalcThreadStart_Partial();	
	}
	//v1.01.03.234
	const bool AutoReleaseFieldFrame = GetAutoReleaseFieldFrame();
	if ( true == AutoReleaseFieldFrame )
	{	StartFieldFrameReleaseThread(true);	}
	else
	{	StopFieldFrameReleaseThread(true); }

	//啟動運動系統的執行緒
	if ( MotionCtrlPtr->StartMotionThreadStats_GoStop(true) == false )
	{
		this->m_ErrorString = MotionCtrlPtr->GetErrorString();		
		return false;
	}

	const size_t GrabFovCount = GetFovPtrCount();
	if ( MotionCtrlPtr->WaitMotionThreadDone_GoStop(GrabFovCount) == false )
	{
		m_ErrorString = MotionCtrlPtr->GetErrorString();
		return false;//20190506
	}
	
	if ( WaitForRegionCalcThreadFinish() == false )
	{	return false; }			
	if ( WaitForFieldCalcThreadFinish() == false )
	{	return false; }

	SetSaveOfflineFiles(false);
	SetSaveOfflineImageFiles(false);	
	SetInspectionDrawing(false);	
	ProjectPtr->ClearProjectAllTempObjects();

	str = _T("Capture Project Map End");
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	str += _T("\n");	
	TRACE(str);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecAlignProjectPanelFd(CAOIProject *ProjectPtr)//對齊專案定位點
{
	if ( NULL == ProjectPtr ) { return false; }
	CString str;
	str = _T("Align Project Panel Start");	
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	str += _T("\n");	
	TRACE(str);
	const bool MultiFdLight = GetSystemMultiFdLight();	
	ProjectPtr->SetProjectInspectionState(INSPECTION_STATE_FD_PANEL);	
	if ( ProjectPtr->CreateProjectPanelAlignObj(MultiFdLight) == false )
	{	
		m_ErrorString = ProjectPtr->GetProjectErrorString();
		return false;
	}
	if ( CloneAllPtrList(ProjectPtr) == false )
	{	return false; }

	m_RgnFinishedCnt = 0;
	m_SliceFinishedCnt = 0;		
	m_FrameFinishedCnt = 0;	
	m_FieldCalcFinishedCnt = 0;
	m_FieldMergeFinishedCnt = 0;
	SetSaveOfflineImageFiles(false);	

	//確認列表狀態
	const double dMaxH  = ProjectPtr->GetProjectSpaceMaxHeight();
	const double dLevel = ProjectPtr->GetProjectSpaceBaseHeight();		
	const int RatioMode = ProjectPtr->GetProjectSpaceToGrayRatioMode();	
	SetSpaceMaxHeight(dMaxH);
	SetSpaceBaseHeight(dLevel);	
	SetSpaceToGrayRatioMode(RatioMode);
	if ( CheckObjListInitialized() == false )
	{	return false;	}

	const size_t GrabFovCount = GetFovPtrCount();
	if ( 0 == GrabFovCount )
	{
		ProjectPtr->ClearProjectAllTempObjects();
		ProjectPtr->SetProjectTickCountFdFinish();		
		str = _T("Align Project Panel End");
		SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
		str += _T("\n");	
		TRACE(str);	
		return true;
	}
	
	//先重設定所有燈原狀態-拉在外面, 減少設定次數
	//if ( this->SetupAllLightSetting() == false )
	//{	return false;	}

#ifndef LIGHT_CTRL_DISABLE
	std::vector<TSliceParam>  SliceParamList;	
	if ( false == MultiFdLight )
	{
		const unsigned int FrameUniqueID = FRAME_UNIQUE_ID_FD;
		if ( BuildSliceParamListByFrameUniqueID(FrameUniqueID, SliceParamList) == false )	
		{	return false;	}
	}
	else
	{	ProjectPtr->CloneProjectSliceParamList_PanelFd(SliceParamList);	}
	if ( CameraCtrl.BatchGrabPrepare2(SliceParamList, false) == false )
	{
		this->m_ErrorString = CameraCtrl.GetErrorString();
		return false;
	}	
#endif//LIGHT_CTRL_DISABLE

	SetInspectionDrawing(true);
	SetThreadGrabMode(THREAD_GRAB_PANEL_FD);	

	//覆歸循環Buffer的資料
	//CameraCtrl.ClearAllCameraCount();
	CameraCtrl.ResetAllCameraRingBuffer();

	//啟動計算執行緒
	const bool bWaitThread=false;
	StartSliceFillThread(bWaitThread);//啟動填圖的執行緒	
	StartFrameMergeThread(bWaitThread);//啟動影像的執行緒
	StartFieldMergeThread(bWaitThread);//啟動區域的執行緒
	StartFieldCalcThread(bWaitThread);//啟動區域的執行緒
	//StartRegionCalcThread(bWaitThread);
	StartRegionCalcThread_Partial(bWaitThread);	
	if ( false == bWaitThread )
	{
		WaitForSliceFillThreadStart();
		WaitForFrameMergeThreadStart();
		WaitForFieldMergeThreadStart();
		WaitForFieldCalcThreadStart();
		//WaitForRegionCalcThreadStart();
		WaitForRegionCalcThreadStart_Partial();	
	}

	//啟動運動系統的執行緒
	if ( MotionCtrlPtr->StartMotionThreadStats_GoStop(true) == false )
	{
		this->m_ErrorString = MotionCtrlPtr->GetErrorString();		
		return false;
	}	
	if ( MotionCtrlPtr->WaitMotionThreadDone_GoStop(GrabFovCount) == false )
	{
		m_ErrorString = MotionCtrlPtr->GetErrorString();
		return false;//20190506
	}	
	if ( WaitForRegionCalcThreadFinish() == false )
	{	return false; }		
	if ( WaitForFieldCalcThreadFinish() == false )
	{	return false; }

	const bool OfflinMode=false;
	if ( ProjectPtr->CheckProjectFdResult_Panel(OfflinMode) == false )
	{	
		SetIsIgnoreAutoRetry(true);
		m_ErrorString = ProjectPtr->GetErrorString();
		return false;
	}	
	if ( ProjectPtr->CalcProjectStagePosition_Panel() == false )
	{
		SetIsIgnoreAutoRetry(true);
		m_ErrorString = ProjectPtr->GetErrorString();
		return false;
	}
	if ( ProjectPtr->CheckProjectPositionInsideStageLimit() == false )
	{
		SetIsIgnoreAutoRetry(true);
		m_ErrorString = ProjectPtr->GetErrorString();
		return false;
	}

	ProjectPtr->ClearProjectAllTempObjects();
	str = _T("Align Project Panel End");	
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	str += _T("\n");	
	TRACE(str);
	PostMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_PROJECT_SWITCH_MAP, NULL);
	return true;
}
