//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecInspectProjectBarcode(CAOIProject *ProjectPtr, OFFLINE_FILE_MODE OfflineFileMode)//檢測專案條碼
{
	if ( NULL == ProjectPtr ) { return false; }

	CString        str;	
	double         fnTime = 0.0;
	LARGE_INTEGER  fnStart, fnEnd;	
	const bool AutoReleaseFieldFrame = GetAutoReleaseFieldFrame();	

	ProjectPtr->BackupProjectFdNeedToCalculate();
	ProjectPtr->BackupProjectMarkNeedToCalculate();
	ProjectPtr->BackupProjectComponentNeedToCalculate();
	ProjectPtr->SetProjectFdNeedToCalculate(false);
	ProjectPtr->SetProjectMarkNeedToCalculate(false);
	ProjectPtr->SetProjectComponentNeedToCalculate(false);
	ProjectPtr->SetProjectBoardFdNeedToCalculateByBarcode();
	ProjectPtr->SetProjectInspectionState(INSPECTION_STATE_BARCOD);
	if ( ProjectPtr->AssignProjectField(OfflineFileMode) == false )
	{
		SetIsIgnoreAutoRetry(true);
		m_ErrorString = ProjectPtr->GetErrorString();
		return false;
	}
	str = _T("Inspect Project Barcode Start");
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	str += _T("\n");	
	TRACE(str);

	if ( ProjectPtr->CreateProjectInspectionObj(AutoReleaseFieldFrame) == false )	
	{
		SetIsIgnoreAutoRetry(true);
		m_ErrorString = ProjectPtr->GetProjectErrorString();
		return false;
	}	
	if ( CloneAllPtrList(ProjectPtr) == false )
	{	return false; }

	m_RgnFinishedCnt = 0;
	m_SliceFinishedCnt = 0;		
	m_FrameFinishedCnt = 0;
	m_FieldCalcFinishedCnt = 0;
	m_FieldMergeFinishedCnt = 0;

	const size_t RgnCount= m_RgnPtrList.size();
	const size_t FovCount= m_FovPtrList.size();
	const size_t SliceCount= m_SlicePtrList.size();	
	const size_t FieldCount= m_FieldPtrList.size();
	const size_t FrameCount= m_FramePtrList.size();	

	//確認列表狀態
	const double dMaxH  = ProjectPtr->GetProjectSpaceMaxHeight();
	const double dLevel = ProjectPtr->GetProjectSpaceBaseHeight();
	const int RatioMode = ProjectPtr->GetProjectSpaceToGrayRatioMode();
	const DISTRICT_ID DistrictID = ProjectPtr->GetProjectActDistrictID();
	SetSpaceMaxHeight(dMaxH);
	SetSpaceBaseHeight(dLevel);	
	SetSpaceToGrayRatioMode(RatioMode);
	if ( CheckObjListInitialized() == false )
	{	return false;	}	
	
	const size_t GrabFovCount = GetFovPtrCount();
	if ( 0 == GrabFovCount )
	{
		ProjectPtr->ClearProjectAllTempObjects();
		ProjectPtr->SetProjectTickCountCalcFinish();
		ProjectPtr->SetProjectBarcodeNeedToCalculate(false);
		ProjectPtr->RestoreProjectFdNeedToCalculate();
		ProjectPtr->RestoreProjectMarkNeedToCalculate();
		ProjectPtr->RestoreProjectComponentNeedToCalculate();

		str = _T("Inspect Project Barcode End");
		SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
		str += _T("\n");	
		return true;
	}

	if ( ProjectPtr->SetProjectFullMapComponentFinsih() == false )	
	{
		this->m_ErrorString = ProjectPtr->GetProjectErrorString();
		return false;
	}	

	//是否儲存Offline
	bool bSaveOfflineFiles = GetSaveOfflineFiles();	
	SetSaveOfflineImageFiles(bSaveOfflineFiles);
	
	m_OfflineFolder = ProjectPtr->GetProjectInspectionOfflineFolder();
	m_OfflineFileName = AOIDataDefine.GetProjectOfflineFileName(m_OfflineFolder, DistrictID);
	::CreateDirectory(m_OfflineFolder, NULL);			
	ProjectPtr->SetProjectInspectionFrameFileName(m_OfflineFolder);	
	str.Format(_T("CAOIProject::SaveProjectInspectionOfflineFile Start"));
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	JetAPI::SetFuncTimeStart(fnStart);
	ProjectPtr->SaveProjectInspectionOfflineFile(m_OfflineFileName);//1.7 sec, 需要換格式
	JetAPI::SetFuncTimeEnd(fnEnd);
	fnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);
	str.Format(_T("CAOIProject::SaveProjectInspectionOfflineFile Time=%.3f ms"), fnTime);
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	//先重設定所有燈原狀態-拉在外面, 減少設定次數
	//if ( this->SetupAllLightSetting() == false )
	//{	return false;	}

#ifndef LIGHT_CTRL_DISABLE
	str.Format(_T("CCameraCtrl::BatchGrabPrepare2 Start"));
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	JetAPI::SetFuncTimeStart(fnStart);
	std::vector<TSliceParam> SliceParamList;
	ProjectPtr->CloneProjectSliceParamList(SliceParamList);
	if ( CameraCtrl.BatchGrabPrepare2(SliceParamList, false) == false )
	{
		this->m_ErrorString = CameraCtrl.GetErrorString();
		return false;
	}
	JetAPI::SetFuncTimeEnd(fnEnd);
	fnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);
	str.Format(_T("CCameraCtrl::BatchGrabPrepare2 Time=%.3f ms"), fnTime);
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
#endif//LIGHT_CTRL_DISABLE

	SetInspectionDrawing(true);
	SetThreadGrabMode(THREAD_GRAB_BARCODE);	

	//覆歸循環Buffer的資料
	//CameraCtrl.ClearAllCameraCount();
	CameraCtrl.ResetAllCameraRingBuffer();

	//啟動計算執行緒
	const bool bWaitThread=false;
	StartSliceFillThread(bWaitThread);//啟動填圖的執行緒	
	StartFrameMergeThread(bWaitThread);//啟動影像的執行緒
	StartFieldMergeThread(bWaitThread);//啟動區域的執行緒
	StartFieldCalcThread(bWaitThread);//啟動區域的執行緒
	//StartRegionCalcThread(bWaitThread);
	StartRegionCalcThread_Partial(bWaitThread);
	if ( false == bWaitThread )
	{
		WaitForSliceFillThreadStart();
		WaitForFrameMergeThreadStart();
		WaitForFieldMergeThreadStart();
		WaitForFieldCalcThreadStart();
		//WaitForRegionCalcThreadStart();
		WaitForRegionCalcThreadStart_Partial();	
	}
	
	if ( true == AutoReleaseFieldFrame )
	{	StartFieldFrameReleaseThread(true);	}
	else
	{	StopFieldFrameReleaseThread(true); }

	//啟動運動系統的執行緒
	if ( MotionCtrlPtr->StartMotionThreadStats_GoStop(true) == false )
	{
		this->m_ErrorString = MotionCtrlPtr->GetErrorString();		
		return false;
	}	
	
	if ( MotionCtrlPtr->WaitMotionThreadDone_GoStop(GrabFovCount) == false )
	{
		m_ErrorString = MotionCtrlPtr->GetErrorString();
		return false;//20190506
	}
	ProjectPtr->SetProjectTickCountGrabFinish();

	//啟動剩餘的執行緒
	str = _T("Start Full Region Calc Thread");
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	if ( StartRegionCalcThread_Full(true) == false )
	{	return false;	}
	if ( WaitForRegionCalcThreadFinish() == false )
	{	return false; }
	if ( WaitForFieldCalcThreadFinish() == false )
	{	return false; }

	ProjectPtr->ClearProjectFdImageBuffer();
	ProjectPtr->ClearProjectAllTempObjects();
	ProjectPtr->SetProjectTickCountCalcFinish();
	ProjectPtr->SetProjectBarcodeNeedToCalculate(false);
	ProjectPtr->RestoreProjectFdNeedToCalculate();
	ProjectPtr->RestoreProjectMarkNeedToCalculate();
	ProjectPtr->RestoreProjectComponentNeedToCalculate();

	//確認該專案取像是在定位點後
	if ( ProjectPtr->CheckProjectBarcodeCameraGrabAfterFd() == true )
	{
		if ( ExecAnalysisProjectInspection_Barcode(ProjectPtr) == false )
		{	return false; }
	}

	SetInspectionDrawing(false);
	str = _T("Inspect Project Barcode End");
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	str += _T("\n");	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecInspectProjectComponent(CAOIProject *ProjectPtr, OFFLINE_FILE_MODE OfflineFileMode)//檢測專案零件
{
	if ( NULL == ProjectPtr ) { return false; }	

	CString        str;	
	double         fnTime = 0.0;
	LARGE_INTEGER  fnStart, fnEnd;
	const bool AutoReleaseFieldFrame = GetAutoReleaseFieldFrame();	
	const bool bMultiDistrictMode = ProjectPtr->GetProjectMultiDistrictMode();
	const bool bSaveFiledUsingThread=ProjectPtr->GetProjectSaveFiledUsingThread();
	if ( true == bSaveFiledUsingThread )
	{	SetFieldFrameReleaseThreadNeedCheck(false); }
	else
	{	SetFieldFrameReleaseThreadNeedCheck(true); }
	ProjectPtr->SetProjectInspectionState(INSPECTION_STATE_PROJECT);
	if ( ProjectPtr->AssignProjectField(OfflineFileMode) == false )
	{
		this->m_ErrorString = ProjectPtr->GetErrorString();
		return false;
	}

	str = _T("Inspect Project Component Start");
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	str += _T("\n");	
	TRACE(str);

	if ( ProjectPtr->CreateProjectInspectionObj(AutoReleaseFieldFrame) == false )	
	{
		this->m_ErrorString = ProjectPtr->GetProjectErrorString();
		return false;
	}
	
	if ( CloneAllPtrList(ProjectPtr) == false )
	{	return false; }

	m_RgnFinishedCnt = 0;
	m_SliceFinishedCnt = 0;		
	m_FrameFinishedCnt = 0;
	m_FieldCalcFinishedCnt = 0;
	m_FieldMergeFinishedCnt = 0;

	const size_t RgnCount= m_RgnPtrList.size();
	const size_t FovCount= m_FovPtrList.size();
	const size_t SliceCount= m_SlicePtrList.size();	
	const size_t FieldCount= m_FieldPtrList.size();
	const size_t FrameCount= m_FramePtrList.size();	

	//確認列表狀態
	const LANE_ID LaneID = ProjectPtr->GetProjectActLaneID();
	const double dMaxH  = ProjectPtr->GetProjectSpaceMaxHeight();
	const double dLevel = ProjectPtr->GetProjectSpaceBaseHeight();
	const int RatioMode = ProjectPtr->GetProjectSpaceToGrayRatioMode();
	const DISTRICT_ID DistrictID = ProjectPtr->GetProjectActDistrictID();
	SetSpaceMaxHeight(dMaxH);
	SetSpaceBaseHeight(dLevel);	
	SetSpaceToGrayRatioMode(RatioMode);
	if ( CheckObjListInitialized() == false )
	{	return false;	}	
	
	const size_t GrabFovCount = GetFovPtrCount();
	if ( 0==GrabFovCount && false==bMultiDistrictMode )
	{
		ProjectPtr->ClearProjectAllTempObjects();
		ProjectPtr->SetProjectTickCountCalcFinish();		
		str = _T("Inspect Project Component End");
		SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
		str += _T("\n");	
		return true;
	}

	if ( ProjectPtr->SetProjectFullMapComponentFinsih() == false )	
	{
		this->m_ErrorString = ProjectPtr->GetProjectErrorString();
		return false;
	}	

	//是否儲存Offline
	bool bSaveOfflineFiles = GetSaveOfflineFiles();
	SetSaveOfflineImageFiles(bSaveOfflineFiles);
	
	m_OfflineFolder = ProjectPtr->GetProjectInspectionOfflineFolder();
	m_OfflineFileName = AOIDataDefine.GetProjectOfflineFileName(m_OfflineFolder, DistrictID);
	::CreateDirectory(m_OfflineFolder, NULL);			
	ProjectPtr->SetProjectInspectionFrameFileName(m_OfflineFolder);	
	str.Format(_T("CAOIProject::SaveProjectInspectionOfflineFile Start"));
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	JetAPI::SetFuncTimeStart(fnStart);
	ProjectPtr->SaveProjectInspectionOfflineFile(m_OfflineFileName);//1.7 sec, 需要換格式
	JetAPI::SetFuncTimeEnd(fnEnd);
	fnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);
	str.Format(_T("CAOIProject::SaveProjectInspectionOfflineFile Time=%.3f ms"), fnTime);
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);

	//先重設定所有燈原狀態-拉在外面, 減少設定次數
	//if ( this->SetupAllLightSetting() == false )
	//{	return false;	}
	
#ifndef LIGHT_CTRL_DISABLE
	str.Format(_T("CCameraCtrl::BatchGrabPrepare2 Start"));
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	JetAPI::SetFuncTimeStart(fnStart);
	str = _T("Batch Grab Prepare");
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);

	std::vector<TSliceParam> SliceParamList;
	ProjectPtr->CloneProjectSliceParamList(SliceParamList);
	if ( CameraCtrl.BatchGrabPrepare2(SliceParamList, false) == false )
	{
		this->m_ErrorString = CameraCtrl.GetErrorString();
		return false;
	}
	JetAPI::SetFuncTimeEnd(fnEnd);
	fnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);
	str.Format(_T("CCameraCtrl::BatchGrabPrepare2 Time=%.3f ms"), fnTime);
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
#endif//LIGHT_CTRL_DISABLE

	SetInspectionDrawing(true);
	SetThreadGrabMode(THREAD_GRAB_PROJECT_TEST);	

	//覆歸循環Buffer的資料
	//CameraCtrl.ClearAllCameraCount();
	CameraCtrl.ResetAllCameraRingBuffer();

	//啟動計算執行緒	
	const bool bWaitThread=false;
	StartSliceFillThread(bWaitThread);//啟動填圖的執行緒	
	StartFrameMergeThread(bWaitThread);//啟動影像的執行緒
	StartFieldMergeThread(bWaitThread);//啟動區域的執行緒
	StartFieldCalcThread(bWaitThread);//啟動區域的執行緒
	//StartRegionCalcThread(bWaitThread);
	StartRegionCalcThread_Partial(bWaitThread);
	if ( false == bWaitThread )	
	{	
		WaitForSliceFillThreadStart();
		WaitForFrameMergeThreadStart();
		WaitForFieldMergeThreadStart();
		WaitForFieldCalcThreadStart();
		//WaitForRegionCalcThreadStart();
		WaitForRegionCalcThreadStart_Partial();
	}		
	
	if ( true == AutoReleaseFieldFrame )
	{	StartFieldFrameReleaseThread(true);	}
	else
	{	StopFieldFrameReleaseThread(true); }

	//啟動運動系統的執行緒
	if ( MotionCtrlPtr->StartMotionThreadStats_GoStop(true) == false )
	{
		this->m_ErrorString = MotionCtrlPtr->GetErrorString();		
		return false;
	}
	if ( MotionCtrlPtr->WaitMotionThreadDone_GoStop(GrabFovCount) == false )
	{
		m_ErrorString = MotionCtrlPtr->GetErrorString();
		return false;//20190506
	}
	ProjectPtr->SetProjectTickCountGrabFinish();
	PlcCtrlPtr->TurnOffConveyerSensorPower(LaneID, false);
	const double   FocusPos = ProjectPtr->GetProjectFocusPos();
	MotionCtrlPtr->MoveTo(AXIS_Z, FocusPos, MOTION_MOVING_NORMAL, true);

	bool bNeedTestOterhProjects=false;
	TASK_MODE TaskMode = GetTaskMode();
	size_t LaneIndex = GetConveyerAutoRunLaneIdx(LaneID);
	TASK_STATE_MODE TaskStateMode = GetOnlineTaskState();		
	const bool  IsSystemException = GetIsSystemException();
	const bool  ConveyerPreRunEnabled = ProjectPtr->GetProjectConveyerPreRunEnabled();	
	MULTI_PROJECT_TEST_ORDER_MODE MultiProjectTestOrderMode=GetMultiProjectTestOrderMode();
	if ( MULTI_PROJECT_TEST_ORDER_ONE_CYCLE_A_B==MultiProjectTestOrderMode || MULTI_PROJECT_TEST_ORDER_ONE_CYCLE_B_A==MultiProjectTestOrderMode )
	{
		ProjectPtr->SetProjectHasTestInOneCycle(LaneID, true);
		CAOIProject *ProjectPtrInTurn = GetNextProjectByTurnOneCycle(LaneID);
		if ( NULL == ProjectPtrInTurn )
		{	bNeedTestOterhProjects = false; }
		else
		{	bNeedTestOterhProjects = true; }
	}
	if ( TASK_INSPECT_PROJECT!=TaskMode || false==ConveyerPreRunEnabled || TASK_STATE_RUNNING!=TaskStateMode ||true==IsSystemException || true==bNeedTestOterhProjects)
	{	ProjectPtr->SetProjectConveyerPreRunRunning(false);		}
	else
	{	
		if ( StartConveyerAutoRunThread(LaneIndex, ONLINE_STATE_INSPECTION_FINISH, ProjectPtr, true, false) == true )
		{	ProjectPtr->SetProjectConveyerPreRunRunning(true);	}
		else
		{
			ProjectPtr->SetProjectConveyerPreRunRunning(false);
			ProjectPtr->SetProjectTickCountCalcFinish();//設定計算完畢
			ProjectPtr->SetProjectTickCountTestFinish();//設定檢測完畢
			SetConveyerAutoRunProjectPtr(LaneIndex, NULL);
			SetConveyerAutoRunState(LaneIndex, ONLINE_STATE_INSPECTION_STOP);		
		}
	}
	
	//const bool bMultiDistrictMode = ProjectPtr->GetProjectMultiDistrictMode();
	if ( true==bMultiDistrictMode && false==IsSystemException )
	{
		if ( DISTRICT_ID_A == DistrictID )
		{	
			//MoveCameraToBeforePCBInPosition(false); 
			if ( TASK_INSPECT_PROJECT==TaskMode||TASK_TUNING_PROJECT==TaskMode)
			{	StartSimpleJobFn_MoveToDistrict(LaneID, DISTRICT_ID_B, false); }
		}
	}

	//啟動剩餘的執行緒
	str = _T("Start Full Region Calc Thread");
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	SetSaveDebugMessage_RGN(true);
	if ( StartRegionCalcThread_Full(true) == false )
	{	return false;	}		
	if ( WaitForRegionCalcThreadFinish() == false )
	{	return false; }
	if ( WaitForFieldCalcThreadFinish() == false )
	{	return false; }
	if ( WaitForFrameMergeThreadFinish() == false )
	{	return false; }
	if ( WaitForFieldMergeThreadFinish() == false )
	{	return false; }	
	if ( true == AutoReleaseFieldFrame )
	{		
		if ( GetFieldFrameReleaseThreadNeedCheck() == true )
		{
			if ( WaitForFieldFrameReleaseThreadFinish() == false )
			{	return false; }
		}
	}
	else
	{
		ProjectPtr->SetProjectInspectionFieldMustToLoad(false);
		ProjectPtr->SetProjectInspectionFieldBufferReleased(false);
	}
	ProjectPtr->ClearProjectFdImageBuffer();
	ProjectPtr->ClearProjectAllTempObjects();

	if ( ProjectPtr->GetProjectConveyerPreRunRunning() == false )
	{	ProjectPtr->SetProjectTickCountCalcFinish(); }

	SetInspectionDrawing(false);
	str = _T("Inspect Project Component End");
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	str += _T("\n");	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecInspectProjectOffline(CAOIProject *ProjectPtr)//檢測專案離線專案
{
	if ( false == ProjectPtr ) { return false; }
	CString        str;	
	double         fnTime = 0.0;
	LARGE_INTEGER  fnStart, fnEnd;
	const bool AutoReleaseFieldFrame = GetAutoReleaseOfflineFieldFrame();

	str = _T("Inspect Project Component Start");
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	str += _T("\n");	
	TRACE(str);	

	//是否儲存Offline	
	m_OfflineFolder = ProjectPtr->GetProjectOfflineFolder();
	ProjectPtr->SetProjectInspectionState(INSPECTION_STATE_PROJECT);
	if ( ProjectPtr->CreateProjectInspectionObj(AutoReleaseFieldFrame) == false )	
	{
		this->m_ErrorString = ProjectPtr->GetProjectErrorString();
		return false;
	}
	
	if ( CloneAllPtrList(ProjectPtr) == false )
	{	return false; }

	m_RgnFinishedCnt = 0;
	m_SliceFinishedCnt = 0;		
	m_FrameFinishedCnt = 0;
	m_FieldCalcFinishedCnt = 0;
	m_FieldMergeFinishedCnt = 0;

	//確認列表狀態
	const double dMaxH  = ProjectPtr->GetProjectSpaceMaxHeight();
	const double dLevel = ProjectPtr->GetProjectSpaceBaseHeight();
	const int RatioMode = ProjectPtr->GetProjectSpaceToGrayRatioMode();
	SetSpaceMaxHeight(dMaxH);
	SetSpaceBaseHeight(dLevel);	
	SetSpaceToGrayRatioMode(RatioMode);
	if ( CheckObjListInitialized() == false )
	{	return false;	}		
	
	if ( ProjectPtr->SetProjectFullMapComponentFinsih() == false )	
	{
		this->m_ErrorString = ProjectPtr->GetProjectErrorString();
		return false;
	}	

	SetInspectionDrawing(true);	
	SetThreadGrabMode(THREAD_GRAB_PROJECT_TEST);

	if ( true == AutoReleaseFieldFrame )
	{	ExecReleaseFieldFrame(); }

	//啟動計算執行緒	
	this->StartFrameLoadThread(true);//啟動影像的執行緒	
	this->StartFieldCalcThread(true);//啟動區域的執行緒
	this->StartRegionCalcThread_Partial(true);

	if ( true == AutoReleaseFieldFrame )
	{	StartFieldFrameReleaseThread(true);		}
	else
	{	StopFieldFrameReleaseThread(true); }
	
	const size_t GrabFovCount = GetFovPtrCount();
	if ( WaitForFrameLoadThreadFinish() == false )	
	{	return false;	}

	//啟動剩餘的執行緒
	str = _T("Start Full Region Calc Thread");
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	if ( StartRegionCalcThread_Full(true) == false )
	{	return false;	}	
	if ( WaitForRegionCalcThreadFinish() == false )
	{	return false; }	
	if ( WaitForFieldCalcThreadFinish() == false )
	{	return false; }
	if ( WaitForFrameLoadThreadFinish() == false )
	{	return false; }

	if ( true == AutoReleaseFieldFrame ) 
	{
		if ( WaitForFieldFrameReleaseThreadFinish() == false )
		{	return false; }
		//ExecReleaseFieldFrame();
	}

	const bool bMultiDistrictMode = ProjectPtr->GetProjectMultiDistrictMode();
	if ( true == bMultiDistrictMode )
	{
	}
	
	SetInspectionDrawing(false);
	return true;
}
