CString CAOIDataCollect::GetImageConfigIniFilename() const//取得影像組態INI檔名
{
	CString Filename;
	CString ShortName;	
#ifdef TB_SYSTEM_ONLY_BOT
	ShortName = _T("ImageConfig_Bot.INI");
#else
	ShortName = IMAGE_CONFIG_INI_FILE;	
#endif//TB_SYSTEM_ONLY_BOT	
	Filename.Format(_T("%s\\%s"), GetAOIDirectory(), ShortName);		
	return Filename;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CloneSystemSliceParamList_No3D(std::vector<TSliceParam> &ParamList)//取得單次影像表
{
	size_t  i=0;
	std::vector<TSliceParam> &SysSliceParamList=GetSystemSliceParamList();//取得影像表單列表
	const size_t SysSliceCount=SysSliceParamList.size();
	for ( i=0; i<SysSliceCount; i++ )
	{		
		if ( SLICE_UNIQUE_ID_DLP == SysSliceParamList[i].SliceUniqueID ) { continue; }
		ParamList.push_back(SysSliceParamList[i]);	
	}
	return true;
}
