//-------------------------------------------------------------------------------------//
void CAOIDataCollect::BuildSystemFrameParamDefault()//初始化影像表單	
{	
	size_t LightIdx = 0;
	size_t LEDIdx = 0;
	size_t DLPIdx = 0;
	
	TFrameParam Param;
	m_SystemFrameParamList.clear();

	//定位點的燈	
	Param.FrameType = FRAME_GRAY;
	Param.FrameUniqueID = FRAME_UNIQUE_ID_FD;
	Param.FrameImageCount = 1;
	Param.FrameSliceID1 = SLICE_UNIQUE_ID_TOP_R;
	Param.FrameSliceID2 = SLICE_UNIQUE_ID_NULL;
	Param.FrameSliceID3 = SLICE_UNIQUE_ID_NULL;
	//::_tcscpy(Param.FrameName, _T("Fiducial"));
	Param.FrameName = _T("Fiducial");
	m_SystemFrameParamList.push_back(Param);

	//彩色燈	
	Param.FrameType = FRAME_COLOR;
	Param.FrameUniqueID = FRAME_UNIQUE_ID_COLOR;
	Param.FrameImageCount = 3;
	Param.FrameSliceID1 = SLICE_UNIQUE_ID_COLOR_R;
	Param.FrameSliceID2 = SLICE_UNIQUE_ID_COLOR_G;
	Param.FrameSliceID3 = SLICE_UNIQUE_ID_COLOR_B;
	//::_tcscpy(Param.FrameName, _T("Color"));
	Param.FrameName = _T("Color");
	m_SystemFrameParamList.push_back(Param);
	
	//三色燈	
	Param.FrameType = FRAME_COLOR;
	Param.FrameUniqueID = FRAME_UNIQUE_ID_RGB;
	Param.FrameImageCount = 3;
	Param.FrameSliceID1 = SLICE_UNIQUE_ID_RGB_R;
	Param.FrameSliceID2 = SLICE_UNIQUE_ID_RGB_G;
	Param.FrameSliceID3 = SLICE_UNIQUE_ID_RGB_B;
	//::_tcscpy(Param.FrameName, _T("RGB"));
	Param.FrameName = _T("RGB");
	m_SystemFrameParamList.push_back(Param);

	//低燈源
	Param.FrameType = FRAME_COLOR;
	Param.FrameUniqueID = FRAME_UNIQUE_ID_LOW;
	Param.FrameImageCount = 3;
	Param.FrameSliceID1 = SLICE_UNIQUE_ID_LOW_R;
	Param.FrameSliceID2 = SLICE_UNIQUE_ID_LOW_G;
	Param.FrameSliceID3 = SLICE_UNIQUE_ID_LOW_B;	
	Param.FrameName = _T("Low");
	m_SystemFrameParamList.push_back(Param);

	//高燈源
	Param.FrameType = FRAME_COLOR;
	Param.FrameUniqueID = FRAME_UNIQUE_ID_TOP;
	Param.FrameImageCount = 3;
	Param.FrameSliceID1 = SLICE_UNIQUE_ID_TOP_R;
	Param.FrameSliceID2 = SLICE_UNIQUE_ID_TOP_G;
	Param.FrameSliceID3 = SLICE_UNIQUE_ID_TOP_B;	
	Param.FrameName = _T("High");
	m_SystemFrameParamList.push_back(Param);	

	//3D	
	Param.FrameType = FRAME_SPACE;	
	Param.FrameUniqueID = FRAME_UNIQUE_ID_DLP;
	Param.FrameImageCount = 32;
	Param.FrameSliceID1 = SLICE_UNIQUE_ID_DLP;
	Param.FrameSliceID2 = SLICE_UNIQUE_ID_NULL;
	Param.FrameSliceID3 = SLICE_UNIQUE_ID_NULL;
	//::_tcscpy(Param.FrameName, _T("3D"));
	Param.FrameName = _T("3D");	
	m_SystemFrameParamList.push_back(Param);
}
//-------------------------------------------------------------------------------------//
size_t CAOIDataCollect::GetSystemFrameParamCount() const//取得Frame Param數量
{
	return m_SystemFrameParamList.size();;
}
//-------------------------------------------------------------------------------------//
TFrameParam* CAOIDataCollect::GetSystemFrameParamPtr(size_t index, bool bCheck)//取得影像表單指標
{
	if ( true == bCheck ) 
	{
		const size_t Count = m_SystemFrameParamList.size();
		if ( index >= Count ) 
		{	return NULL; }
	}	
	return &(m_SystemFrameParamList[index]);
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::AddSystemFrameParam(const TFrameParam &Param, bool bCheck)//增加Frame Param	
{
	if ( true == bCheck )
	{
		FRAME_TYPE  FrameType = Param.FrameType;
		if ( FRAME_NULL == FrameType )
		{
			this->m_ErrorString.Format(_T("Error, Undefined frame type [%d]"), FrameType);
			return false;
		}

		if ( FRAME_GRAY == FrameType )
		{
			if ( SLICE_UNIQUE_ID_NULL != Param.FrameSliceID2 || SLICE_UNIQUE_ID_NULL != Param.FrameSliceID3 )
			{
				this->m_ErrorString.Format(_T("Error, Gray frame can only set one slice"));
				return false;
			}
		}

		if ( FRAME_BAYER == FrameType )
		{
			if ( SLICE_UNIQUE_ID_NULL != Param.FrameSliceID2 || SLICE_UNIQUE_ID_NULL != Param.FrameSliceID3 )
			{
				this->m_ErrorString.Format(_T("Error, Bayer frame can only set one slice"));
				return false;
			}
		}

		if ( FRAME_SPACE == FrameType )
		{
			if ( SLICE_UNIQUE_ID_NULL != Param.FrameSliceID2 || SLICE_UNIQUE_ID_NULL != Param.FrameSliceID3 )
			{
				this->m_ErrorString.Format(_T("Error, 3D frame can only set one slice"));
				return false;
			}
		}

		if ( FRAME_COLOR == FrameType )
		{
			if ( SLICE_UNIQUE_ID_NULL == Param.FrameSliceID2 || SLICE_UNIQUE_ID_NULL == Param.FrameSliceID3 )
			{
				this->m_ErrorString.Format(_T("Error, Color frame should set three slice"));
				return false;
			}
		}

		TSliceParam *SliceParamPtr = NULL;
		unsigned int UniqueID = 0;

		UniqueID = Param.FrameSliceID1;
		if ( SLICE_UNIQUE_ID_NULL !=  UniqueID )
		{
			SliceParamPtr = CAOIDataCollect::GetSystemSliceParamPtrByUniqueID(UniqueID);
			if ( NULL == SliceParamPtr )
			{
				this->m_ErrorString.Format(_T("Error, Slice 1 ID Exception (%d)"), UniqueID);
				return false;
			}			
		}

		UniqueID = Param.FrameSliceID2;
		if ( SLICE_UNIQUE_ID_NULL !=  UniqueID )
		{
			SliceParamPtr = CAOIDataCollect::GetSystemSliceParamPtrByUniqueID(UniqueID);
			if ( NULL == SliceParamPtr )
			{
				this->m_ErrorString.Format(_T("Error, Slice 2 ID Exception (%d)"), UniqueID);
				return false;
			}			
		}

		UniqueID = Param.FrameSliceID3;
		if ( SLICE_UNIQUE_ID_NULL !=  UniqueID )
		{
			SliceParamPtr = CAOIDataCollect::GetSystemSliceParamPtrByUniqueID(UniqueID);
			if ( NULL == SliceParamPtr )
			{
				this->m_ErrorString.Format(_T("Error, Slice 3 ID Exception (%d)"), UniqueID);
				return false;
			}			
		}
	}
	m_SystemFrameParamList.push_back(Param);
	return true;	
}
//-------------------------------------------------------------------------------------//
TFrameParam* CAOIDataCollect::GetSystemFrameParamPtrByUniqueID(size_t UniqueID)//依據Frame ID來取得Frame Param指標
{	
	size_t i=0;
	TFrameParam *FrameParamPtr = NULL;
	const size_t FrameCount = m_SystemFrameParamList.size();
	for ( i=0; i<FrameCount; i++ )
	{
		FrameParamPtr = &(m_SystemFrameParamList[i]);
		if ( FrameParamPtr->FrameUniqueID == UniqueID )
		{	return FrameParamPtr; }
	}
	this->m_ErrorString.Format(_T("Error, Get Frame Param Ptr Fault [%d]"), UniqueID);
	return NULL;
}
//-------------------------------------------------------------------------------------//
size_t CAOIDataCollect::GetSystemFrameParamIndex(size_t UniqueID)//依據Frame ID來取得Frame Param指標
{
	size_t i=0;
	TFrameParam *FrameParamPtr = NULL;
	const size_t FrameCount = m_SystemFrameParamList.size();
	for ( i=0; i<FrameCount; i++ )
	{
		FrameParamPtr = &(m_SystemFrameParamList[i]);
		if ( FrameParamPtr->FrameUniqueID == UniqueID )
		{	return i; }
	}
	return -1;
}
//-------------------------------------------------------------------------------------//
unsigned int CAOIDataCollect::GetSystemFrameParamFreeUniqueID()//取得Frame Param新的識別碼	
{
	unsigned int i=0, j=0;
	unsigned int UniqueID=FRAME_UNIQUE_ID_USER_DEFINED;	
	TFrameParam *FrameParamPtr = NULL;
	const unsigned int FrameCount = (unsigned int)(m_SystemFrameParamList.size());	
	for ( i=0; i<FrameCount; i++ )
	{
		FrameParamPtr = &(m_SystemFrameParamList[i]);
		if ( FrameParamPtr->FrameUniqueID < FRAME_UNIQUE_ID_USER_DEFINED ) { continue; }
		if ( UniqueID < FrameParamPtr->FrameUniqueID )
		{	UniqueID = FrameParamPtr->FrameUniqueID; }
	}
	UniqueID ++;
	return UniqueID;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckSystemFrameParamFreeUniqueID(unsigned int ID)//確認Frame Param新的識別碼		 
{
	if ( FRAME_UNIQUE_ID_NULL==ID || FRAME_UNIQUE_ID_MAX<ID )
	{
		m_ErrorString.Format(_T("Error, Frame Param Free UniqueID is Invalid[%d]"), ID);
		return false;
	}
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::DeleteSystemFrameParamIndex(size_t index)//刪除Frame Param
{
	TFrameParam *FrameParamPtr = CAOIDataCollect::GetSystemFrameParamPtr(index, true);
	if ( NULL == FrameParamPtr ) { return false; }
	if ( FrameParamPtr->FrameUniqueID < FRAME_UNIQUE_ID_USER_DEFINED ) 
	{
		this->m_ErrorString.Format(_T("Error, Can not delete system default frame param"));
		return false; 
	}

	size_t i=0;
	std::vector<TFrameParam>   TempFrameParamList = m_SystemFrameParamList;//單1影像參數列表
	const size_t FrameCount = TempFrameParamList.size();
	m_SystemFrameParamList.clear();
	for ( i=0; i<FrameCount; i++ )
	{
		if ( i == index ) { continue; }
		m_SystemFrameParamList.push_back(TempFrameParamList[i]);
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::DeleteSystemFrameParamUserDefined()//刪除Frame Param 使用者定義
{
	size_t i=0;
	TFrameParam *FrameParamPtr = NULL;
	std::vector<TFrameParam>   TempFrameParamList = m_SystemFrameParamList;//單1影像參數列表
	const size_t FrameCount = TempFrameParamList.size();
	m_SystemFrameParamList.clear();
	for ( i=0; i<FrameCount; i++ )
	{
		if ( TempFrameParamList[i].FrameUniqueID >= FRAME_UNIQUE_ID_USER_DEFINED ) { continue; } 
		m_SystemFrameParamList.push_back(TempFrameParamList[i]);
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ModifySystemFrameParamIndex(size_t index, const TFrameParam &Param)//修改Frame Param
{
	TFrameParam *FrameParamPtr = CAOIDataCollect::GetSystemFrameParamPtr(index, true);
	if ( NULL == FrameParamPtr ) { return false; }
	/*
	if ( FrameParamPtr->FrameUniqueID < FRAME_UNIQUE_ID_USER_DEFINED ) 
	{
		this->m_ErrorString.Format(_T("Error, Can not modify system default frame param"));
		return false; 
	}
	*/
	const size_t UniqueID = FrameParamPtr->FrameUniqueID;
	m_SystemFrameParamList[index] = Param;
	m_SystemFrameParamList[index].FrameUniqueID = UniqueID;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SetSystemFrameParamList(const std::vector<TFrameParam> &ParamList)//設定Frame Param列表
{
	m_SystemFrameParamList = ParamList;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CloneSystemFrameParamList(std::vector<TFrameParam> &ParamList)//複製Frame Param列表
{
	ParamList = m_SystemFrameParamList;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LimitImageZoomScale(double &ZoomRatio, bool bInverte) const//限制影像縮放比例
{
	const double MaxZoomScale = GetSystemParameter().m_ImageDisplayMaxZoomScale;
	if ( fabs(ZoomRatio) < 0.00001 )
	{	return false; }
	if ( fabs(MaxZoomScale) < 0.00001 )
	{	return false; }	

	double ZoomeValue=ZoomRatio;
	if ( true == bInverte ) { ZoomeValue = 1.0/ZoomRatio; }
	if ( ZoomeValue <= MaxZoomScale )
	{	return false; }
	ZoomeValue = MaxZoomScale;
	if ( false == bInverte )
	{	ZoomRatio = ZoomeValue;	}
	else
	{	ZoomRatio = 1.0/ZoomeValue; }
	return true;
}
//-------------------------------------------------------------------------------------//
IMAGE_DISPLAY_MODE CAOIDataCollect::MapFrameTypeToImageDisplayMode(FRAME_TYPE FrameType)//映射Frame樣式轉成顯示模式
{
	IMAGE_DISPLAY_MODE ImageDisplayMode = GetSystemParameter().m_ImageDisplayMode;
	switch ( FrameType )
	{
	case FRAME_GRAY:	ImageDisplayMode = IMAGE_DISPLAY_GRAY;	break;
	case FRAME_BAYER:	ImageDisplayMode = IMAGE_DISPLAY_BAYER;	break;
	case FRAME_COLOR:	ImageDisplayMode = IMAGE_DISPLAY_COLOR;	break;
	case FRAME_SPACE:	ImageDisplayMode = IMAGE_DISPLAY_GRAY;	break;	
	}
	return ImageDisplayMode;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveSystemFrameParamINI()//儲存影像表單
{
	if ( SaveSystemFrameParamINIFn() == false )
	{
		SetSystemExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveSystemFrameParamINIFn()//儲存影像表單
{
#ifndef OFFLINE_VERSION
	unsigned int i=0, j=0;
	unsigned int idx=0;
	unsigned int LedIdx=0;
	unsigned int CastIdx=0;
	CString str;
	CString Section;
	CString KeyName;
	CString String;
	CString FileName = GetImageConfigIniFilename();
	
	TFrameParam *FrameParamPtr = NULL;
	const size_t FrameCount = m_SystemFrameParamList.size();

	Section = _T("Frame Parameter");	
	KeyName = _T("Frame Count");
	String.Format(_T("%d"), FrameCount);
	if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
	{	return false; }	
	
	idx = 0;
	for ( i=0; i<FrameCount; i++ )
	{
		FrameParamPtr = &(m_SystemFrameParamList[i]);

		idx ++;
		if ( idx < 10 ) 
		{	Section.Format(_T("Frame Node 000%d"), idx);	}
		else if ( idx < 100 )
		{	Section.Format(_T("Frame Node 00%d"), idx);	}
		else if ( idx < 1000 )
		{	Section.Format(_T("Frame Node 0%d"), idx);	}
		else
		{	Section.Format(_T("Frame Node %d"), idx);	}

		//名稱
		KeyName = _T("Frame Name");	
		String = FrameParamPtr->FrameName;
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }	

		//識別碼
		KeyName = _T("Unique ID");
		String.Format(_T("%d"), FrameParamPtr->FrameUniqueID);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }	

		//樣式
		KeyName = _T("Frame Type");
		String.Format(_T("%d"), FrameParamPtr->FrameType);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }	

		//Slice ID 1
		KeyName = _T("Slice Unique ID 1");
		String.Format(_T("%d"), FrameParamPtr->FrameSliceID1);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }	

		//Slice ID 2
		KeyName = _T("Slice Unique ID 2");
		String.Format(_T("%d"), FrameParamPtr->FrameSliceID2);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }	

		//Slice ID 3
		KeyName = _T("Slice Unique ID 3");
		String.Format(_T("%d"), FrameParamPtr->FrameSliceID3);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }

		//Saturated Red
		KeyName = _T("Saturation Red");
		String.Format(_T("%.2f"), FrameParamPtr->FrameSaturationRed);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }

		//Saturated Green
		KeyName = _T("Saturation Green");
		String.Format(_T("%.2f"), FrameParamPtr->FrameSaturationGreen);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }
		
		//Saturated Blue
		KeyName = _T("Saturation Blue");
		String.Format(_T("%.2f"), FrameParamPtr->FrameSaturationBlue);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }
	}	
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadSystemFrameParamINI()//儲存影像表單
{
	if ( LoadSystemFrameParamINIFn() == false )
	{
		SetSystemExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadSystemFrameParamINIFn()//載入影像表單	
{
	//SLICE_UNIQUE_ID_USER_DEFINED
	const size_t textlen = 128;
	unsigned int i=0, j=0;
	unsigned int idx=0;
	unsigned int LedIdx=0;
	unsigned int CastIdx=0;

	int     tempI=0;
	double  tempD=0.0;
	size_t  FrameCount=0;
	TFrameParam FrameParam;		
	CString str;	
	CString Section = _T("");	
	CString KeyName = _T("");
	CString Default = _T("");	
	TCHAR   String[textlen]=_T("");	
	CString FileName = GetImageConfigIniFilename();

	Section = _T("Frame Parameter");

	FrameCount = 0;
	KeyName = _T("Frame Count");	
	Default.Format(_T("%d"), FrameCount);
	if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
	{	FrameCount = ::_ttoi(String); }	

	if ( 0 == FrameCount )
	{	return true; }

	idx = 0;
	m_SystemFrameParamList.clear();
	for ( i=0; i<FrameCount; i++ )
	{	
		FrameParam = TFrameParam();

		idx ++;
		if ( idx < 10 ) 
		{	Section.Format(_T("Frame Node 000%d"), idx);	}
		else if ( idx < 100 )
		{	Section.Format(_T("Frame Node 00%d"), idx);	}
		else if ( idx < 1000 )
		{	Section.Format(_T("Frame Node 0%d"), idx);	}
		else
		{	Section.Format(_T("Frame Node %d"), idx);	}

		//名稱
		KeyName = _T("Frame Name");	
		Default = FrameParam.FrameName;
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	
			FrameParam.FrameName = String;
			//::_tcscpy(FrameParam.FrameName, String); 
		}

		//識別碼
		KeyName = _T("Unique ID");
		Default.Format(_T("%d"), FrameParam.FrameUniqueID);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	FrameParam.FrameUniqueID = ::_ttoi(String); }	

		//樣式
		KeyName = _T("Frame Type");
		Default.Format(_T("%d"), FrameParam.FrameType);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	FrameParam.FrameType = (FRAME_TYPE)::_ttoi(String); }

		//Slice ID 1
		KeyName = _T("Slice Unique ID 1");
		Default.Format(_T("%d"), FrameParam.FrameSliceID1);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	FrameParam.FrameSliceID1 = ::_ttoi(String); }

		//Slice ID 2
		KeyName = _T("Slice Unique ID 2");
		Default.Format(_T("%d"), FrameParam.FrameSliceID2);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	FrameParam.FrameSliceID2 = ::_ttoi(String); }

		//Slice ID 3
		KeyName = _T("Slice Unique ID 3");
		Default.Format(_T("%d"), FrameParam.FrameSliceID3);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	FrameParam.FrameSliceID3 = ::_ttoi(String); }
		
		//Saturated Red
		KeyName = _T("Saturation Red");
		Default.Format(_T("%.2f"), FrameParam.FrameSaturationRed);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	FrameParam.FrameSaturationRed = ::_ttof(String); }

		//Saturated Green
		KeyName = _T("Saturation Green");
		Default.Format(_T("%.2f"), FrameParam.FrameSaturationGreen);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	FrameParam.FrameSaturationGreen = ::_ttof(String); }
		
		//Saturated Blue
		KeyName = _T("Saturation Blue");
		Default.Format(_T("%.2f"), FrameParam.FrameSaturationBlue);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	FrameParam.FrameSaturationBlue = ::_ttof(String); }
	
		m_SystemFrameParamList.push_back(FrameParam);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckImageConfiguration()//確認影像組態狀態
{
	size_t i=0,  j=0;	
	FRAME_TYPE   FrameType;	
	unsigned int SliceID=0;
	unsigned int FrameID=0;
	unsigned int SliceIdx=0;
	unsigned int FrameCount=0;
	unsigned int DLPImageCount=0;
	unsigned int DLPRepeatCount=1;
	unsigned int DLPPhasePatMode=0;	
	TSliceParam *SliceParamPtr1 = NULL;
	TSliceParam *SliceParamPtr2 = NULL;
	TSliceParam *SliceParamPtr3 = NULL;
	TFrameParam *FrameParamPtr = NULL;
	const size_t DLPCastCount = DLP_CAST_COUNT;
	const size_t SliceParamCount = GetSystemSliceParamCount();
	const size_t FrameParamCount = GetSystemFrameParamCount();

	for ( i=0; i<FrameParamCount; i++ )
	{
		FrameParamPtr = GetSystemFrameParamPtr(i, false);
		if ( NULL == FrameParamPtr ) { continue; }

		FrameCount = 0;
		FrameID = FrameParamPtr->FrameUniqueID;
		FrameType = FrameParamPtr->FrameType;

		SliceID = FrameParamPtr->FrameSliceID1;
		if ( FRAME_UNIQUE_ID_NULL != SliceID )
		{
			SliceIdx = GetSystemSliceParamIndexByUniqueID(SliceID);
			SliceParamPtr1 = GetSystemSliceParamPtr(SliceIdx, true);
			//SliceParamPtr1 = GetSystemSliceParamPtrByUniqueID(SliceID);
			if ( NULL == SliceParamPtr1 )
			{
				this->m_ErrorString.Format(_T("Error, Frame param[%d] set exception slice 1[ID:%d]"), i+1, SliceID);
				return false;
			}
			FrameParamPtr->FrameSliceIdx1 = SliceIdx;
		}

		SliceID = FrameParamPtr->FrameSliceID2;
		if ( FRAME_UNIQUE_ID_NULL != SliceID )
		{
			SliceIdx = GetSystemSliceParamIndexByUniqueID(SliceID);
			SliceParamPtr2 = GetSystemSliceParamPtr(SliceIdx, true);
			//SliceParamPtr2 = GetSystemSliceParamPtrByUniqueID(SliceID);
			if ( NULL == SliceParamPtr2 )
			{
				this->m_ErrorString.Format(_T("Error, Frame param[%d] set exception slice 2[ID:%d]"), i+1, SliceID);
				return false;
			}
			FrameParamPtr->FrameSliceIdx2 = SliceIdx;
		}

		SliceID = FrameParamPtr->FrameSliceID3;
		if ( FRAME_UNIQUE_ID_NULL != SliceID )
		{
			SliceIdx = GetSystemSliceParamIndexByUniqueID(SliceID);
			SliceParamPtr3 = GetSystemSliceParamPtr(SliceIdx, true);
			//SliceParamPtr3 = GetSystemSliceParamPtrByUniqueID(SliceID);
			if ( NULL == SliceParamPtr3 )
			{
				this->m_ErrorString.Format(_T("Error, Frame param[%d] set exception slice 3[ID:%d]"), i+1, SliceID);
				return false;
			}
			FrameParamPtr->FrameSliceIdx3 = SliceIdx;
		}	

		switch ( FrameType )
		{
		case FRAME_GRAY:
			if ( FRAME_UNIQUE_ID_NULL != FrameParamPtr->FrameSliceID2 ||
				 FRAME_UNIQUE_ID_NULL != FrameParamPtr->FrameSliceID3 )
			{
				this->m_ErrorString.Format(_T("Error, Gray Frame param[%d] set exception slice"), i+1);
				return false;
			}
			FrameParamPtr->FrameImageCount = 1;
			break;
		case FRAME_BAYER:
			if ( FRAME_UNIQUE_ID_NULL != FrameParamPtr->FrameSliceID2 ||
				 FRAME_UNIQUE_ID_NULL != FrameParamPtr->FrameSliceID3 )
			{
				this->m_ErrorString.Format(_T("Error, Bayer Frame param[%d] set exception slice"), i+1);
				return false;
			}
			FrameParamPtr->FrameImageCount = 1;
			break;
		case FRAME_COLOR:
			if ( FRAME_UNIQUE_ID_NULL == FrameParamPtr->FrameSliceID1 ||
				 FRAME_UNIQUE_ID_NULL == FrameParamPtr->FrameSliceID2 ||
				 FRAME_UNIQUE_ID_NULL == FrameParamPtr->FrameSliceID3 )
			{
				this->m_ErrorString.Format(_T("Error, Color Frame param[%d] set exception slice"), i+1);
				return false;
			}
			FrameParamPtr->FrameImageCount = 3;
			break;
		case FRAME_SPACE:			
			if ( LIGHT_DLP != SliceParamPtr1->SliceLightTable.LightType )
			{
				this->m_ErrorString.Format(_T("Error, 3D Frame param[%d] set exception slice 1 [ID:%d]"), i+1, SliceID);
				return false;
			}			
			DLPPhasePatMode=CheckSliceFuncModeDlpPatternMode(SliceParamPtr1->SliceFuncMode);
			DLPRepeatCount=CheckFrameLightCountBySliceFuncMode(SliceParamPtr1->SliceFuncMode);
			DLPImageCount=CheckSliceFuncModeDlpPatternCountOnce(SliceParamPtr1->SliceFuncMode);

			FrameCount = 0;
			for ( j=0; j<DLPCastCount; j++ )
			{
				SliceParamPtr1->SliceLightTable.DLPCast[j].TriggerCount = DLPImageCount;
				SliceParamPtr1->SliceLightTable.DLPCast[j].PhasePatMode = DLPPhasePatMode;	
				if ( FN_ENABLE == SliceParamPtr1->SliceLightTable.DLPCast[j].OnOffState )
				{	FrameCount += SliceParamPtr1->SliceLightTable.DLPCast[j].TriggerCount; }
			}
			SliceParamPtr1->SliceCameraFrames = FrameCount;
			FrameParamPtr->FrameImageCount = FrameCount;			
			//FrameParamPtr->FrameImageCount = 32;
			break;
		default://FRAME_NULL
			this->m_ErrorString.Format(_T("Error, Frame param[%d] type exception [ID:%d]"), i+1, FrameType);
			return false;
			break;
		}
	}

	return true;
}
