//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecEnhanceDisplayImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const IMAGE_PTR SrcPtr, IMAGE_PTR DstPtr)
{
	if ( NULL==SrcPtr || NULL==DstPtr )
	{	
		this->m_ErrorString.Format(_T("Error, ExecEnhanceDisplayImage Fault (NULL==SrcPtr || NULL==DstPtr)"));
		return false;
	}	
	const char fnName[] = "CAOIDataCollect::ExecEnhanceDisplayImage";
	CString       fnStr;
	LARGE_INTEGER fnEnd;
	LARGE_INTEGER fnStart;
	const bool    bSaveTimeFile=false;
	const TSystemParameter &SysParam = GetSystemParameter();
	const bool IsEnhanceDisplayImage = GetIsEnhanceDisplayImage();
	if ( true == bSaveTimeFile )
	{
		fnStr.Format(_T("CAOIDataCollect::ExecEnhanceDisplayImage Start"));
		SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, fnStr);
		JetAPI::SetFuncTimeStart(fnStart);	
	}
	if ( false == IsEnhanceDisplayImage )
	{
		if ( SrcPtr != DstPtr )
		{
			const size_t BufferSize = ImageAPI.CalcBufferSize(ImageStep, ImageH);
			::memcpy(DstPtr, SrcPtr, sizeof(IMAGE_DATA)*BufferSize);
		}
		if ( true == bSaveTimeFile )
		{
			JetAPI::SetFuncTimeEnd(fnEnd);	
			double fnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);
			fnStr.Format(_T("CAOIDataCollect::ExecEnhanceDisplayImage Time=%.3f ms"), fnTime);
			SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, fnStr);
		}
		return true;
	}
	IMAGE_DISPLAY_ENHANCE_MODE EnhanceMode = SysParam.m_ImageDisplayEnhanceMode;	
	if ( IMAGE_DISPLAY_ENHANCE_GAIN == EnhanceMode )
	{	
		const double Gain  = SysParam.m_ImageDisplayGain;
		if ( ImageAPI.ImageOffsetGain3(ImageW, ImageH, ImageStep, BitCount, SrcPtr, DstPtr, 0, Gain) == false )
		{
			this->m_ErrorString = ImageAPI.GetImageApiErrorString();
			return false;
		}
	}
	else if ( IMAGE_DISPLAY_ENHANCE_GAMMA == EnhanceMode )
	{	
		unsigned char GammaLUT[256]={0};
		const double Gamma = SysParam.m_ImageDisplayGamma;		
		ImageAPI.BuildGammaLookUpTable(Gamma, GammaLUT);
		if ( ImageAPI.ImageApplyLUT3(ImageW, ImageH, ImageStep, BitCount, SrcPtr, GammaLUT, DstPtr) == false )
		{
			this->m_ErrorString = ImageAPI.GetImageApiErrorString();
			return false;
		}
	}
	else if ( IMAGE_DISPLAY_ENHANCE_SHARPNESS_GAIN == EnhanceMode )
	{	
		IMAGE_PTR BufferPtr=NULL;
		const int KernelSize = 3;
		const int Th = SysParam.m_ImageDisplaySharpnessThreshold;
		const int Amount = SysParam.m_ImageDisplaySharpnessAmount;
		const int Radius = SysParam.m_ImageDisplaySharpnessRadius;		
		const size_t BufferSize = ImageAPI.CalcBufferSize(ImageStep, ImageH);
		if ( JetMemory.alloc_func(BufferSize, BufferPtr, fnName, "BufferPtr") == false )
		{
			m_ErrorString = JetMemory.GetErrorString();
			return false;
		}		
		//if ( ImageAPI.SharpnessLaps2Image3(ImageW, ImageH, ImageStep, BitCount, SrcPtr, DstPtr, KernelSize) == false )
		if ( ImageAPI.SharpnessGausImage3(ImageW, ImageH, ImageStep, BitCount, SrcPtr, Radius, Th, Amount, BufferPtr) == false )		
		{	
			JetMemory.free_func(BufferPtr);
			this->m_ErrorString = ImageAPI.GetImageApiErrorString();
			return false;
		}

		const double Gain  = SysParam.m_ImageDisplayGain;
		if ( ImageAPI.ImageOffsetGain3(ImageW, ImageH, ImageStep, BitCount, BufferPtr, DstPtr, 0, Gain) == false )
		{	
			JetMemory.free_func(BufferPtr);
			this->m_ErrorString = ImageAPI.GetImageApiErrorString();
			return false;
		}		
		JetMemory.free_func(BufferPtr);
	}	
	else if ( IMAGE_DISPLAY_ENHANCE_SHARPNESS_GAMMA == EnhanceMode )
	{	
		IMAGE_PTR BufferPtr=NULL;
		const int KernelSize = 3;
		const int Th = SysParam.m_ImageDisplaySharpnessThreshold;
		const int Amount = SysParam.m_ImageDisplaySharpnessAmount;
		const int Radius = SysParam.m_ImageDisplaySharpnessRadius;		
		const size_t BufferSize = ImageAPI.CalcBufferSize(ImageStep, ImageH);
		if ( JetMemory.alloc_func(BufferSize, BufferPtr, fnName, "BufferPtr") == false )
		{
			m_ErrorString = JetMemory.GetErrorString();
			return false;
		}
		//if ( ImageAPI.SharpnessLaps2Image3(ImageW, ImageH, ImageStep, BitCount, SrcPtr, DstPtr, KernelSize) == false )
		if ( ImageAPI.SharpnessGausImage3(ImageW, ImageH, ImageStep, BitCount, SrcPtr, Radius, Th, Amount, BufferPtr) == false )		
		{
			JetMemory.free_func(BufferPtr);
			this->m_ErrorString = ImageAPI.GetImageApiErrorString();
			return false;
		}
		unsigned char GammaLUT[256]={0};
		const double Gamma = SysParam.m_ImageDisplayGamma;		
		ImageAPI.BuildGammaLookUpTable(Gamma, GammaLUT);
		if ( ImageAPI.ImageApplyLUT3(ImageW, ImageH, ImageStep, BitCount, BufferPtr, GammaLUT, DstPtr) == false )
		{	
			JetMemory.free_func(BufferPtr);
			this->m_ErrorString = ImageAPI.GetImageApiErrorString();
			return false;
		}		
		JetMemory.free_func(BufferPtr);
	}
	else if ( IMAGE_DISPLAY_ENHANCE_LOCAL_GAMMA == EnhanceMode )
	{	
		IMAGE_PTR BufferPtr=NULL;
		const int KernelSize=SysParam.m_ImageDisplayLocalGammaCalcSize;//
		const double Gamma=SysParam.m_ImageDisplayLocalGammaScaleVal;		
		const size_t BufferSize = ImageAPI.CalcBufferSize(ImageStep, ImageH);
		if ( JetMemory.alloc_func(BufferSize, BufferPtr, fnName, "BufferPtr") == false )
		{
			m_ErrorString = JetMemory.GetErrorString();
			return false;
		}		
		if ( ImageAPI.LocalGammaImage3(ImageW, ImageH, ImageStep, BitCount, SrcPtr, KernelSize, Gamma, BufferPtr) == false )		
		{
			JetMemory.free_func(BufferPtr);
			this->m_ErrorString = ImageAPI.GetImageApiErrorString();
			return false;
		}
		::memcpy(DstPtr, BufferPtr, sizeof(IMAGE_DATA)*BufferSize);		
		JetMemory.free_func(BufferPtr);
	}
	else
	{	
		if ( ImageAPI.CloneImage3(ImageW, ImageH, ImageStep, BitCount, SrcPtr, DstPtr, false) == false )
		{
			this->m_ErrorString = ImageAPI.GetImageApiErrorString();
			return false;
		}		
	}
	if ( true == bSaveTimeFile )
	{
		JetAPI::SetFuncTimeEnd(fnEnd);	
		double fnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);
		fnStr.Format(_T("CAOIDataCollect::ExecEnhanceDisplayImage Time=%.3f ms"), fnTime);
		SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, fnStr);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::BuildFocusImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const IMAGE_PTR SrcPtr, IMAGE_PTR DstPtr)
{
	bool   IsOK = true;
	const int KerSize = GetSystemParameter().m_CalcFocusSmoothSize;	
	if ( 0 == KerSize ) 
	{	IsOK = ImageAPI.CloneGrayImage3(ImageW, ImageH, ImageStep, SrcPtr, DstPtr, false);	}
	else
	{	IsOK = ImageAPI.SmoothGrayImage3(ImageW, ImageH, ImageStep, SrcPtr, KerSize, DstPtr);	}
	if ( false == IsOK )
	{	m_ErrorString = ImageAPI.GetImageApiErrorString();	}
	return IsOK;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CalcImageFocusValue(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const IMAGE_PTR SrcPtr, const IMAGE_PTR TarPtr, CALC_FOCUS_MODE Mode, const RECT &RoiRect, double &val)//計算影像對焦數據
{
	bool bIsOK = true;
	switch ( Mode ) 
	{	
	case CALC_FOCUS_VARIANCE:
		bIsOK = ImageAPI.CalcGrayImageFocusValue_Variance(ImageW, ImageH, ImageStep, TarPtr, RoiRect, val);
		val *= 10;//修飾給顯示用
		break;
	case CALC_FOCUS_SUM_MODULES_DIFFERENCE:
		bIsOK = ImageAPI.CalcGrayImageFocusValue_SumModulesDifference(ImageW, ImageH, ImageStep, TarPtr, RoiRect, val);
		val *= 100;//修飾給顯示用
		break;
	case CALC_FOCUS_SQUARED_GRADIENT:
		bIsOK = ImageAPI.CalcGrayImageFocusValue_SquaredGradient(ImageW, ImageH, ImageStep, TarPtr, RoiRect, val);
		val *= 50;//修飾給顯示用
		break;
	case CALC_FOCUS_TENENGRAD:
		bIsOK = ImageAPI.CalcGrayImageFocusValue_Tenengrad(ImageW, ImageH, ImageStep, TarPtr, RoiRect, val);
		val *= 50;//修飾給顯示用
		break;
	case CALC_FOCUS_LAPLACIAN:
		bIsOK = ImageAPI.CalcGrayImageFocusValue_Laplacian(ImageW, ImageH, ImageStep, TarPtr, RoiRect, val);
		val *= 100;//修飾給顯示用
		break;
	case CALC_FOCUS_PIXEL_DIFFERENCE:
		bIsOK = ImageAPI.CalcGrayImageFocusValue_PixelDifference(ImageW, ImageH, ImageStep, SrcPtr, TarPtr, RoiRect, val);		
		val *= 80;//修飾給顯示用
		break;
	default:
	case CALC_FOCUS_AMPLITUDE:	
		bIsOK = ImageAPI.CalcGrayImageFocusValue_Amplitude(ImageW, ImageH, ImageStep, TarPtr, RoiRect, val);
		val *= 10;//修飾給顯示用
		break;
	}
	if ( false == bIsOK )
	{	m_ErrorString = ImageAPI.GetImageApiErrorString();	}
	return bIsOK;
}
//-------------------------------------------------------------------------------------//
int CAOIDataCollect::GetPhaseCombinePeriodMode() const//取得相位合併方式
{
	const TSystemParameter &SystemParam = GetSystemParameter();	
	double PhasePeriod_1 = SystemParam.m_PhasePeriod1;
	double PhasePeriod_2 = SystemParam.m_PhasePeriod2;
	double PhasePeriod_Max = MAX(PhasePeriod_1, PhasePeriod_2);
	double PhasePeriod_Min = MIN(PhasePeriod_1, PhasePeriod_2);
	if ( PhasePeriod_Max < (2*PhasePeriod_Min) )//鄰近週期
	{	return COMBINE_PHASE_SIBLING_PERIOD; }
	return COMBINE_PHASE_MAX_MIN_PERIOD;//大小週期	
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::GetPhaseUseGammaCalibration() const//取得相位是否使用Gamma校正
{
	return USE_GAMMA_CALIBRATION;//Check USE_GAMMA_CALIBRATION	
	return false;
}
