	BasePlaneParam.SystemNoiseRange = 120.0;//系統雜訊範圍
	BasePlaneParam.UpperRatio = 1.00;//上範圍比例
	BasePlaneParam.LowerRatio = 1.00;//下範圍比例
	BasePlaneParam.OffsetZ = 0.00;//最後Z軸偏差量
