void CAOIDataCollect::DisableSpaceNoiseFilterParam(TNoiseFilterParam &NoiseFilterParam)//關閉空間雜訊過濾
{
	NoiseFilterParam.DataVoidExpandEnabled = false;//雜訊遮罩外擴啟用	
	NoiseFilterParam.DataFirstFilterMode=DATA_NF_DISABLE;//平滑濾波器啟用
	NoiseFilterParam.DataOverLowFTMode = DATA_NF_DISABLE;//過低濾除啟用	
	NoiseFilterParam.DataHeightFTMode = DATA_NF_DISABLE;//高度濾除模式
	NoiseFilterParam.DataVoidReContructed = false;//雜訊資料重建
	NoiseFilterParam.DataFinalFilterMode = DATA_NF_DISABLE;
	NoiseFilterParam.DataFinalFilterMode2 = DATA_NF_DISABLE;//平滑濾波器啟用
	return;
}
//-------------------------------------------------------------------------------------//
void CAOIDataCollect::GetSpaceNoiseFilterParam(TNoiseFilterParam &NoiseFilterParam) const//取得空間資料雜訊濾除參數
{
	const TSystemParameter &SysParam = GetSystemParameter();
	//基準面
	GetSpaceBasePlaneParam(NoiseFilterParam.BasePlaneParam);	

	//無效點外擴
	NoiseFilterParam.DataVoidExpandSize = SysParam.m_SpaceNoiseDataVoidExpandSize;
	if ( FN_ENABLE == SysParam.m_SpaceNoiseDataVoidExpandEnabed )
	{	NoiseFilterParam.DataVoidExpandEnabled = true; }
	else
	{	NoiseFilterParam.DataVoidExpandEnabled = false; }
	NoiseFilterParam.DataVoidExpandIterCount = 1;
	NoiseFilterParam.DataVoidExpandSpentTime = 0.0;
	
	//首次濾波處理
	NoiseFilterParam.DataFirstFilterSpentTime = 0.0;
	NoiseFilterParam.DataFirstFilterMode = SysParam.m_SpaceNoiseFirstFilterMode;
	NoiseFilterParam.DataFirstFilterPitch = SysParam.m_SpaceNoiseFirstFilterPitch;
	NoiseFilterParam.DataFirstFilterKerSize = SysParam.m_SpaceNoiseFirstKerSize;//9
	NoiseFilterParam.DataFirstFilterUseSize = SysParam.m_SpaceNoiseFirstUseSize;		
	NoiseFilterParam.DataFirstFilterAlphaF = SysParam.m_SpaceNoiseFirstFilterAlphaF;
	NoiseFilterParam.DataFirstFilterAlphaS = SysParam.m_SpaceNoiseFirstFilterAlphaS;
	NoiseFilterParam.DataFirstFilterAlphaM = SysParam.m_SpaceNoiseFirstFilterAlphaM;
	NoiseFilterParam.DataFirstFilterAlphaI = SysParam.m_SpaceNoiseFirstFilterAlphaI;
	NoiseFilterParam.DataFirstFilterThresdhold_Outlier = SysParam.m_SpaceNoiseFirstFilterThresdhold_Outlier;
	NoiseFilterParam.DataFirstFilterSearchOn = SysParam.m_SpaceNoiseFirstFilterSearchOn;

	//將過低的雜訊給設定為0	
	NoiseFilterParam.DataOverLowSpentTime = 0.0;
	NoiseFilterParam.DataOverLowFTMode = SysParam.m_SpaceNoiseOverLowerMode;
	NoiseFilterParam.DataOverLowFTRange = (SysParam.m_SpaceNoiseOverLowerRange);
	NoiseFilterParam.DataOverLowFTLimit = (SysParam.m_SpaceNoiseOverLowerLimit);	
	NoiseFilterParam.DataOverLowFTKerSize = (SysParam.m_SpaceNoiseOverLowerKerSize);
	NoiseFilterParam.DataOverLowFTUseSize = (SysParam.m_SpaceNoiseOverLowerUseSize);
	
	//高度異常濾除	
	NoiseFilterParam.DataHeightFTSpentTime = 0.0;	
	NoiseFilterParam.DataHeightFTMode = SysParam.m_SpaceNoiseHeightAbnormalMode;
	NoiseFilterParam.DataHeightFTPitch = SysParam.m_SpaceNoiseHeightAbnormalPitch;
	NoiseFilterParam.DataHeightFTRange = SysParam.m_SpaceNoiseHeightAbnormalRange;
	NoiseFilterParam.DataHeightFTChkSize = SysParam.m_SpaceNoiseHeightAbnormalChkSize;
	NoiseFilterParam.DataHeightFTKerSize = SysParam.m_SpaceNoiseHeightAbnormalKerSize;
	NoiseFilterParam.DataHeightFTUseSize = SysParam.m_SpaceNoiseHeightAbnormalUseSize;
	NoiseFilterParam.DataHeightFTRepeatCnt = SysParam.m_SpaceNoiseHeightAbnormalRepeatCnt;	
	
	//雜訊重建
	if ( FN_ENABLE == SysParam.m_SpaceNoiseDataVoidReContructedEnabled )
	{	NoiseFilterParam.DataVoidReContructed = true; }
	else
	{	NoiseFilterParam.DataVoidReContructed = false; }	
	NoiseFilterParam.DataVoidReContructedExtSize = (SysParam.m_SpaceNoiseDataVoidReContructedExtSize);;
	NoiseFilterParam.DataVoidRecontructedSpentTime = 0.0;

	//後製濾波處理	
	NoiseFilterParam.DataFinalFilterSpentTime = 0.0;
	NoiseFilterParam.DataFinalFilterMode = SysParam.m_SpaceNoiseFinalFilterMode;
	NoiseFilterParam.DataFinalFilterPitch = SysParam.m_SpaceNoiseFinalPitch;
	NoiseFilterParam.DataFinalFilterKerSize = SysParam.m_SpaceNoiseFinalKerSize;//5	
	NoiseFilterParam.DataFinalFilterUseSize = SysParam.m_SpaceNoiseFinalUseSize;			
	NoiseFilterParam.DataFinalFilterAlphaF = SysParam.m_SpaceNoiseFinalFilterAlphaF;
	NoiseFilterParam.DataFinalFilterAlphaS = SysParam.m_SpaceNoiseFinalFilterAlphaS;
	NoiseFilterParam.DataFinalFilterAlphaM = SysParam.m_SpaceNoiseFinalFilterAlphaM;
	NoiseFilterParam.DataFinalFilterAlphaI = SysParam.m_SpaceNoiseFinalFilterAlphaI;
	NoiseFilterParam.DataFinalFilterThresdhold_Outlier = SysParam.m_SpaceNoiseFinalFilterThresdhold_Outlier;
	NoiseFilterParam.DataFinalFilterSearchOn = SysParam.m_SpaceNoiseFinalFilterSearchOn;

	//後製濾波處理-2
	NoiseFilterParam.DataFinalFilterSpentTime2 = 0.0;
	NoiseFilterParam.DataFinalFilterMode2 = SysParam.m_SpaceNoiseFinalFilterMode2;
	NoiseFilterParam.DataFinalFilterPitch2 = SysParam.m_SpaceNoiseFinalPitch2;
	NoiseFilterParam.DataFinalFilterKerSize2 = SysParam.m_SpaceNoiseFinalKerSize2;//5	
	NoiseFilterParam.DataFinalFilterUseSize2 = SysParam.m_SpaceNoiseFinalUseSize2;			
	NoiseFilterParam.DataFinalFilterAlphaF2 = SysParam.m_SpaceNoiseFinalFilterAlphaF2;
	NoiseFilterParam.DataFinalFilterAlphaS2 = SysParam.m_SpaceNoiseFinalFilterAlphaS2;
	NoiseFilterParam.DataFinalFilterAlphaM2 = SysParam.m_SpaceNoiseFinalFilterAlphaM2;
	NoiseFilterParam.DataFinalFilterAlphaI2 = SysParam.m_SpaceNoiseFinalFilterAlphaI2;
	NoiseFilterParam.DataFinalFilterThresdhold_Outlier2 = SysParam.m_SpaceNoiseFinalFilterThresdhold_Outlier2;
	NoiseFilterParam.DataFinalFilterSearchOn2 = SysParam.m_SpaceNoiseFinalFilterSearchOn2;
	return ;
}
//-------------------------------------------------------------------------------------//
void CAOIDataCollect::SetSpaceNoiseFilterParam(const TNoiseFilterParam &NoiseFilterParam)//設定空間資料雜訊濾除參數	
{
	TSystemParameter &SysParam = GetSystemParameter();
	SysParam.m_SpaceNoiseDataVoidExpandEnabed = NoiseFilterParam.DataVoidExpandEnabled;
	SysParam.m_SpaceNoiseDataVoidExpandSize = NoiseFilterParam.DataVoidExpandSize;

	//初次處理
	SysParam.m_SpaceNoiseFirstFilterMode = NoiseFilterParam.DataFirstFilterMode;
	SysParam.m_SpaceNoiseFirstFilterPitch = NoiseFilterParam.DataFirstFilterPitch;
	SysParam.m_SpaceNoiseFirstKerSize = NoiseFilterParam.DataFirstFilterKerSize;
	SysParam.m_SpaceNoiseFirstUseSize = NoiseFilterParam.DataFirstFilterUseSize;
	SysParam.m_SpaceNoiseFirstFilterAlphaF = NoiseFilterParam.DataFirstFilterAlphaF;
	SysParam.m_SpaceNoiseFirstFilterAlphaS = NoiseFilterParam.DataFirstFilterAlphaS;
	SysParam.m_SpaceNoiseFirstFilterAlphaM = NoiseFilterParam.DataFirstFilterAlphaM;
	SysParam.m_SpaceNoiseFirstFilterAlphaI = NoiseFilterParam.DataFirstFilterAlphaI;
	SysParam.m_SpaceNoiseFirstFilterThresdhold_Outlier = NoiseFilterParam.DataFirstFilterThresdhold_Outlier;
	SysParam.m_SpaceNoiseFirstFilterSearchOn = NoiseFilterParam.DataFirstFilterSearchOn;

	//高度過低判定
	SysParam.m_SpaceNoiseOverLowerMode = NoiseFilterParam.DataOverLowFTMode;
	SysParam.m_SpaceNoiseOverLowerRange = NoiseFilterParam.DataOverLowFTRange;
	SysParam.m_SpaceNoiseOverLowerLimit = NoiseFilterParam.DataOverLowFTLimit;
	SysParam.m_SpaceNoiseOverLowerKerSize = NoiseFilterParam.DataOverLowFTKerSize;
	SysParam.m_SpaceNoiseOverLowerUseSize = NoiseFilterParam.DataOverLowFTUseSize;

	//高度異常判定
	SysParam.m_SpaceNoiseHeightAbnormalMode = NoiseFilterParam.DataHeightFTMode;	
	SysParam.m_SpaceNoiseHeightAbnormalRange = NoiseFilterParam.DataHeightFTRange;
	SysParam.m_SpaceNoiseHeightAbnormalPitch = NoiseFilterParam.DataHeightFTPitch;
	SysParam.m_SpaceNoiseHeightAbnormalChkSize = NoiseFilterParam.DataHeightFTChkSize;
	SysParam.m_SpaceNoiseHeightAbnormalKerSize = NoiseFilterParam.DataHeightFTKerSize;
	SysParam.m_SpaceNoiseHeightAbnormalUseSize = NoiseFilterParam.DataHeightFTUseSize;
	SysParam.m_SpaceNoiseHeightAbnormalRepeatCnt = NoiseFilterParam.DataHeightFTRepeatCnt;
	
	//雜訊重建
	SysParam.m_SpaceNoiseDataVoidReContructedEnabled = NoiseFilterParam.DataVoidReContructed;
	SysParam.m_SpaceNoiseDataVoidReContructedExtSize = NoiseFilterParam.DataVoidReContructedExtSize;

	//最末處理
	SysParam.m_SpaceNoiseFinalFilterMode = NoiseFilterParam.DataFinalFilterMode;
	SysParam.m_SpaceNoiseFinalPitch = NoiseFilterParam.DataFinalFilterPitch;
	SysParam.m_SpaceNoiseFinalKerSize = NoiseFilterParam.DataFinalFilterKerSize;
	SysParam.m_SpaceNoiseFinalUseSize = NoiseFilterParam.DataFinalFilterUseSize;
	SysParam.m_SpaceNoiseFinalFilterAlphaF = NoiseFilterParam.DataFinalFilterAlphaF;
	SysParam.m_SpaceNoiseFinalFilterAlphaS = NoiseFilterParam.DataFinalFilterAlphaS;
	SysParam.m_SpaceNoiseFinalFilterAlphaM = NoiseFilterParam.DataFinalFilterAlphaM;
	SysParam.m_SpaceNoiseFinalFilterAlphaI = NoiseFilterParam.DataFinalFilterAlphaI;
	SysParam.m_SpaceNoiseFinalFilterThresdhold_Outlier = NoiseFilterParam.DataFinalFilterThresdhold_Outlier;
	SysParam.m_SpaceNoiseFinalFilterSearchOn = NoiseFilterParam.DataFinalFilterSearchOn;

	//最末處理-2
	SysParam.m_SpaceNoiseFinalFilterMode2 = NoiseFilterParam.DataFinalFilterMode2;
	SysParam.m_SpaceNoiseFinalPitch2 = NoiseFilterParam.DataFinalFilterPitch2;
	SysParam.m_SpaceNoiseFinalKerSize2 = NoiseFilterParam.DataFinalFilterKerSize2;
	SysParam.m_SpaceNoiseFinalUseSize2 = NoiseFilterParam.DataFinalFilterUseSize2;
	SysParam.m_SpaceNoiseFinalFilterAlphaF2 = NoiseFilterParam.DataFinalFilterAlphaF2;
	SysParam.m_SpaceNoiseFinalFilterAlphaS2 = NoiseFilterParam.DataFinalFilterAlphaS2;
	SysParam.m_SpaceNoiseFinalFilterAlphaM2 = NoiseFilterParam.DataFinalFilterAlphaM2;
	SysParam.m_SpaceNoiseFinalFilterAlphaI2 = NoiseFilterParam.DataFinalFilterAlphaI2;
	SysParam.m_SpaceNoiseFinalFilterThresdhold_Outlier2 = NoiseFilterParam.DataFinalFilterThresdhold_Outlier2;
	SysParam.m_SpaceNoiseFinalFilterSearchOn2 = NoiseFilterParam.DataFinalFilterSearchOn2;

	return;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveObjExecTime(LPCTSTR filename)//儲存物件執行時間
{
	if ( SaveObjExecTimeFn(filename) == false )
	{
		SetSystemExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveObjExecTimeFn(LPCTSTR filename)//儲存物件執行時間
{
	TCHAR TMode[32] = _T("");
	_tcscpy(TMode, _T("w+"));
	JetAPI::ModifyOpenFileMode_Write(TMode);
	FILE *pfile = ::_tfopen(filename, TMode);
	if ( NULL == pfile )
	{
		this->m_ErrorString.Format(_T("Error, Open File Fault (%s)"), filename);
		return false;
	}
	size_t i = 0;
	size_t Count = 0;
	double Time = 0;
	double AveTime = 0;
	double TotalTime = 0;

	//Frame
	CAOIFrame   *FramePtr = NULL;
	const size_t FrameCount = GetFramePtrCount();

	Count = 0;
	AveTime = 0;
	TotalTime = 0.0;
	::_ftprintf(pfile, _T("Frame Merge Time\n"));
	::_ftprintf(pfile, _T("%s, %s\n"), _T("Idx"), _T("Time"));
	for ( i=0; i<FrameCount; i++ )
	{
		FramePtr = GetFramePtr(i, false);
		if ( NULL == FramePtr ) { continue; }
		Time = FramePtr->GetFrameMergeTime();
		TotalTime += Time;
		Count ++;

		::_ftprintf(pfile, _T("%d, %.2f ms\n"), i+1, Time);
	}
	if ( Count > 0 ) 
	{	AveTime = TotalTime/Count;	}
	::_ftprintf(pfile, _T("Ave = %.2f ms\n"), AveTime);
	::_ftprintf(pfile, _T("Total = %.2f ms\n"), TotalTime);

	::fclose(pfile); pfile = NULL;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadSystemSliceParamINI()//載入Slice Param組態檔
{
	if ( LoadSystemSliceParamINIFn() == false )
	{
		SetSystemExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadSystemSliceParamINIFn()//載入Slice Param組態檔
{
	//SLICE_UNIQUE_ID_USER_DEFINED
	const size_t textlen = 128;
	unsigned int i=0, j=0;
	unsigned int idx=0;
	unsigned int LedIdx=0;
	unsigned int CastIdx=0;

	int     tempI=0;
	double  tempD=0.0;
	size_t  SliceCount=0;
	TSliceParam SliceParam;		
	CString str;	
	CString Section = _T("");	
	CString KeyName = _T("");
	CString Default = _T("");	
	TCHAR   String[textlen]=_T("");	
	CString FileName = GetImageConfigIniFilename();
	
	Section = _T("Slice Parameter");
	
	//刪除使用者自行定義的部分
	SliceCount = 0;
	KeyName = _T("Slice Count");	
	Default.Format(_T("%d"), SliceCount);
	if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
	{	SliceCount = ::_ttoi(String); }	

	if ( 0 == SliceCount ) 
	{	return true; }
	
	idx = 0;
	this->m_SystemSliceParamList.clear();	
	for ( i=0; i<SliceCount; i++ )
	{	
		SliceParam = TSliceParam();

		idx ++;
		if ( idx < 10 ) 
		{	Section.Format(_T("Slice Node 000%d"), idx);	}
		else if ( idx < 100 )
		{	Section.Format(_T("Slice Node 00%d"), idx);	}
		else if ( idx < 1000 )
		{	Section.Format(_T("Slice Node 0%d"), idx);	}
		else
		{	Section.Format(_T("Slice Node %d"), idx);	}
		
		//名稱
		KeyName = _T("Slice Name");	
		Default.Format(_T("%s"), SliceParam.SliceName);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	
			SliceParam.SliceName = String; 
			//::_tcscpy(SliceParam.SliceName, String); 
		}

		//識別碼
		KeyName = _T("Unique ID");
		Default.Format(_T("%d"), SliceParam.SliceUniqueID);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	SliceParam.SliceUniqueID = ::_ttoi(String); }
		if ( SLICE_UNIQUE_ID_DLP != SliceParam.SliceUniqueID )
		{	SliceParam.SliceFuncMode = SLICE_FUNC_2D_IMAGE_GRAY; }
		else
		{	SliceParam.SliceFuncMode = SLICE_FUNC_3D_4STEP_4STEP_1EXP; }

		//影像功能模式
		KeyName = _T("Image Func Mode");
		Default.Format(_T("%d"), SliceParam.SliceFuncMode);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	SliceParam.SliceFuncMode = (SLICE_FUNC_MODE)::_ttoi(String); }		
		switch ( SliceParam.SliceFuncMode )
		{
		case SLICE_FUNC_2D_IMAGE_GRAY:
		case SLICE_FUNC_3D_4STEP_1EXP_A:
		case SLICE_FUNC_3D_2STEP_2STEP_1EXP:
		case SLICE_FUNC_3D_4STEP_4STEP_1EXP:
		case SLICE_FUNC_3D_4STEP_2STEP_1EXP:
		case SLICE_FUNC_3D_4STEP_4GC_1EXP:
		case SLICE_FUNC_3D_4STEP_5GC_1EXP:
		case SLICE_FUNC_3D_4STEP_6GC_1EXP:
		case SLICE_FUNC_3D_4STEP_2EXP_A:
		case SLICE_FUNC_3D_4STEP_4STEP_2EXP:
		case SLICE_FUNC_3D_4STEP_2STEP_2EXP:
		case SLICE_FUNC_3D_4STEP_4STEP_2LIGHT:
		case SLICE_FUNC_3D_4STEP_4GC_2EXP:
		case SLICE_FUNC_3D_4STEP_4GC_2LIGHT:
		case SLICE_FUNC_3D_4STEP_5GC_2EXP:
		case SLICE_FUNC_3D_4STEP_5GC_2LIGHT:
		case SLICE_FUNC_3D_4STEP_6GC_2EXP:
		case SLICE_FUNC_3D_4STEP_6GC_2LIGHT:
			break;
		default:
			if ( SLICE_UNIQUE_ID_DLP != SliceParam.SliceUniqueID )
			{	SliceParam.SliceFuncMode = SLICE_FUNC_2D_IMAGE_GRAY; }
			else
			{	SliceParam.SliceFuncMode = SLICE_FUNC_3D_4STEP_4STEP_1EXP; }			
			break;
		}

		//相機編號
		KeyName = _T("Camera ID");
		Default.Format(_T("%d"), SliceParam.SliceCameraID);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	SliceParam.SliceCameraID = (CAMERA_ID)::_ttoi(String); }

		//相機曝光時間 us
		KeyName = _T("Camera Exposure Time us");
		Default.Format(_T("%d"), SliceParam.SliceCameraExpTimeus);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	SliceParam.SliceCameraExpTimeus = ::_ttoi(String); }
		
		//相機每秒取像張數所需時間
		KeyName = _T("Camera Grab Frame Time us");
		Default.Format(_T("%d"), SliceParam.SliceCameraGrabFrameTimeus);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	SliceParam.SliceCameraGrabFrameTimeus = ::_ttoi(String); }
		
		//下次取像間隔時間(Bt=Between)
		KeyName = _T("Next Grab Between Time us");
		Default.Format(_T("%d"), SliceParam.SliceNextGrabBtTimeus);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	SliceParam.SliceNextGrabBtTimeus = ::_ttoi(String); }

		//校正的灰階目標
		KeyName = _T("Target Gray");
		Default.Format(_T("%d"), SliceParam.SliceTargetGray);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	SliceParam.SliceTargetGray = ::_ttoi(String); }

		//驗證誤差
		KeyName = _T("Verify Tolerance");
		Default.Format(_T("%d"), SliceParam.SliceVerifyTolerance);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	SliceParam.SliceVerifyTolerance = ::_ttoi(String); }	

		//影像亮度增益
		KeyName = _T("Gain Value");
		Default.Format(_T("%.2f"), SliceParam.SliceGainValue);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	SliceParam.SliceGainValue = JetAPI::StrToDbl(String); }

		//燈源組態, 燈源樣式
		KeyName = _T("Light Type");
		Default.Format(_T("%d"), SliceParam.SliceLightTable.LightType);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	SliceParam.SliceLightTable.LightType = (LIGHT_TYPE)::_ttoi(String); }

		//LED開啟時間-us
		KeyName = _T("LED Turn On Time us");
		Default.Format(_T("%d"), SliceParam.SliceLightTable.LEDTurnOnTimeus);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	SliceParam.SliceLightTable.LEDTurnOnTimeus = ::_ttoi(String); }
		
		//校正模式
		KeyName = _T("LED Current Calibration Mode");
		Default.Format(_T("%d"), SliceParam.SliceLightTable.LEDCurrCaliMode);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	SliceParam.SliceLightTable.LEDCurrCaliMode = (LED_CURRENT_CALI_MODE)::_ttoi(String); }

		//DLP開啟時間-us			
		KeyName = _T("DLP Cast Turn On Time us");		
		Default.Format(_T("%d"), SliceParam.SliceLightTable.DLPTurnOnTimeus);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
		{	SliceParam.SliceLightTable.DLPTurnOnTimeus = ::_ttoi(String); }

		//燈源組態LED
		for ( j=0; j<LED_CHANNEL_COUNT; j++ )
		{
			LedIdx = j+1;

			//LED燈源強度
			if ( LedIdx < 10 )
			{	KeyName.Format(_T("LED Channel 00%d Power Value"), LedIdx);	}				
			else if ( LedIdx < 100 )
			{	KeyName.Format(_T("LED Channel 0%d Power Value"), LedIdx);	}	
			else 
			{	KeyName.Format(_T("LED Channel %d Power Value"), LedIdx);	}
			Default.Format(_T("%d"), SliceParam.SliceLightTable.LEDChannel[j].PowerValue);
			if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
			{	SliceParam.SliceLightTable.LEDChannel[j].PowerValue = ::_ttoi(String); }

			//LED開關狀態
			if ( LedIdx < 10 )
			{	KeyName.Format(_T("LED Channel 00%d On Off State"), LedIdx);	}				
			else if ( LedIdx < 100 )
			{	KeyName.Format(_T("LED Channel 0%d On Off State"), LedIdx);	}	
			else 
			{	KeyName.Format(_T("LED Channel %d On Off State"), LedIdx);	}
			Default.Format(_T("%d"), SliceParam.SliceLightTable.LEDChannel[j].OnOffState);
			if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
			{	SliceParam.SliceLightTable.LEDChannel[j].OnOffState = ::_ttoi(String); }			
		}

		//燈源組態DLP
		for ( j=0; j<DLP_CAST_COUNT; j++ )
		{
			CastIdx = j+1;

			//DLP開關狀態
			if ( CastIdx < 10 )
			{	KeyName.Format(_T("DLP Cast 00%d On Off State"), CastIdx);	}				
			else if ( CastIdx < 100 )
			{	KeyName.Format(_T("DLP Cast 0%d On Off State"), CastIdx);	}	
			else 
			{	KeyName.Format(_T("DLP Cast %d On Off State"), CastIdx);	}
			Default.Format(_T("%d"), SliceParam.SliceLightTable.DLPCast[j].OnOffState);
			if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
			{	SliceParam.SliceLightTable.DLPCast[j].OnOffState = ::_ttoi(String); }			
			if ( SLICE_UNIQUE_ID_DLP == SliceParam.SliceUniqueID )
			{
				switch ( j )
				{
			#ifdef BYPASS_DLP1_USE
				case 0: SliceParam.SliceLightTable.DLPCast[j].OnOffState = FN_DISABLE; break;
			#endif//BYPASS_DLP1_USE

			#ifdef BYPASS_DLP2_USE
				case 1: SliceParam.SliceLightTable.DLPCast[j].OnOffState = FN_DISABLE; break;
			#endif//BYPASS_DLP2_USE

			#ifdef BYPASS_DLP3_USE
				case 2: SliceParam.SliceLightTable.DLPCast[j].OnOffState = FN_DISABLE; break;
			#endif//BYPASS_DLP3_USE

			#ifdef BYPASS_DLP4_USE
				case 3: SliceParam.SliceLightTable.DLPCast[j].OnOffState = FN_DISABLE; break;
			#endif//BYPASS_DLP4_USE
				default:
					break;
				}				
			}

			//DLP觸發次數-us
			if ( CastIdx < 10 )
			{	KeyName.Format(_T("DLP Cast 00%d Trigger Count"), CastIdx);	}				
			else if ( CastIdx < 100 )
			{	KeyName.Format(_T("DLP Cast 0%d Trigger Count"), CastIdx);	}	
			else 
			{	KeyName.Format(_T("DLP Cast %d Trigger Count"), CastIdx);	}
			Default.Format(_T("%d"), SliceParam.SliceLightTable.DLPCast[j].TriggerCount);
			if ( LoadINIData(Section, KeyName, Default, String, textlen, FileName, false, m_ErrorString) == true ) 	
			{	SliceParam.SliceLightTable.DLPCast[j].TriggerCount = ::_ttoi(String); }

			switch ( SliceParam.SliceLightTable.DLPCast[j].TriggerCount )
			{
			case  4: SliceParam.SliceLightTable.DLPCast[j].PhasePatMode = DLP_PATTERN_SEQUENCE_4_4_2;	break;
			case  5: SliceParam.SliceLightTable.DLPCast[j].PhasePatMode = DLP_PATTERN_SEQUENCE_2_2_M;	break;
			case  6: SliceParam.SliceLightTable.DLPCast[j].PhasePatMode = DLP_PATTERN_SEQUENCE_4_2_M;	break;				
			case  8: SliceParam.SliceLightTable.DLPCast[j].PhasePatMode = DLP_PATTERN_SEQUENCE_4_4_M;	break;
			case 12: SliceParam.SliceLightTable.DLPCast[j].PhasePatMode = DLP_PATTERN_SEQUENCE_4_2_M_2;	break;				
			case 16: 
				if ( SLICE_FUNC_3D_4STEP_4GC_2EXP==SliceParam.SliceFuncMode || SLICE_FUNC_3D_4STEP_4GC_2LIGHT==SliceParam.SliceFuncMode )
				{	SliceParam.SliceLightTable.DLPCast[j].PhasePatMode = DLP_PATTERN_SEQUENCE_4_4GC_M2;	}
				else
				{	SliceParam.SliceLightTable.DLPCast[j].PhasePatMode = DLP_PATTERN_SEQUENCE_4_4_M_2;	}
				break;
			case 18: 
				if ( SLICE_FUNC_3D_4STEP_5GC_2EXP==SliceParam.SliceFuncMode || SLICE_FUNC_3D_4STEP_5GC_2LIGHT==SliceParam.SliceFuncMode )
				{	SliceParam.SliceLightTable.DLPCast[j].PhasePatMode = DLP_PATTERN_SEQUENCE_4_5GC_M2;	}				
				break;
			case 20: 
				if ( SLICE_FUNC_3D_4STEP_6GC_2EXP==SliceParam.SliceFuncMode || SLICE_FUNC_3D_4STEP_6GC_2LIGHT==SliceParam.SliceFuncMode )
				{	SliceParam.SliceLightTable.DLPCast[j].PhasePatMode = DLP_PATTERN_SEQUENCE_4_6GC_M2;	}				
				break;
			default: SliceParam.SliceLightTable.DLPCast[j].PhasePatMode = DLP_PATTERN_SEQUENCE_NONE;	break;
			}
		}

		if ( LIGHT_DLP == SliceParam.SliceLightTable.LightType )
		{
			SliceParam.SliceCameraFrames = 0;
			for ( j=0; j<DLP_CAST_COUNT; j++ )
			{
				if ( FN_DISABLE == SliceParam.SliceLightTable.DLPCast[j].OnOffState ) { continue; }
				SliceParam.SliceCameraFrames += SliceParam.SliceLightTable.DLPCast[j].TriggerCount;
			}
		}
		else
		{	SliceParam.SliceCameraFrames = 1;	}
		//增加新的Slice Param
		m_SystemSliceParamList.push_back(SliceParam);
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveSystemSliceParamINI()//儲存Slice Param組態檔
{
	if ( SaveSystemSliceParamINIFn() == false )
	{
		SetSystemExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveSystemSliceParamINIFn()//儲存Slice Param組態檔	
{	
#ifndef OFFLINE_VERSION
	unsigned int i=0, j=0;
	unsigned int idx=0;
	unsigned int LedIdx=0;
	unsigned int CastIdx=0;
	CString str;
	CString Section;
	CString KeyName;
	CString String;	
	TSliceParam *SliceParamPtr = NULL;
	CString FileName = GetImageConfigIniFilename();
	const size_t SliceCount = m_SystemSliceParamList.size();

	Section = _T("Slice Parameter");

	KeyName = _T("Slice Count");
	String.Format(_T("%d"), SliceCount);
	if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
	{	return false; }	
	
	idx = 0;
	for ( i=0; i<SliceCount; i++ )
	{
		SliceParamPtr = &(m_SystemSliceParamList[i]);

		idx ++;
		if ( idx < 10 ) 
		{	Section.Format(_T("Slice Node 000%d"), idx);	}
		else if ( idx < 100 )
		{	Section.Format(_T("Slice Node 00%d"), idx);	}
		else if ( idx < 1000 )
		{	Section.Format(_T("Slice Node 0%d"), idx);	}
		else
		{	Section.Format(_T("Slice Node %d"), idx);	}
		
		//名稱
		KeyName = _T("Slice Name");	
		String = SliceParamPtr->SliceName;
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }	

		//識別碼
		KeyName = _T("Unique ID");
		String.Format(_T("%d"), SliceParamPtr->SliceUniqueID);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }	

		//影像功能模式
		KeyName = _T("Image Func Mode");
		String.Format(_T("%d"), SliceParamPtr->SliceFuncMode);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }

		//相機編號
		KeyName = _T("Camera ID");
		String.Format(_T("%d"), SliceParamPtr->SliceCameraID);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }	

		//相機曝光時間 us
		KeyName = _T("Camera Exposure Time us");
		String.Format(_T("%d"), SliceParamPtr->SliceCameraExpTimeus);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }	

		//相機每秒取像張數所需時間
		KeyName = _T("Camera Grab Frame Time us");
		String.Format(_T("%d"), SliceParamPtr->SliceCameraGrabFrameTimeus);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }	

		//下次取像間隔時間(Bt=Between)
		KeyName = _T("Next Grab Between Time us");
		String.Format(_T("%d"), SliceParamPtr->SliceNextGrabBtTimeus);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }	

		//校正的灰階目標
		KeyName = _T("Target Gray");
		String.Format(_T("%d"), SliceParamPtr->SliceTargetGray);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }	

		//驗證誤差
		KeyName = _T("Verify Tolerance");
		String.Format(_T("%d"), SliceParamPtr->SliceVerifyTolerance);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }

		//影像亮度增益
		KeyName = _T("Gain Value");
		String.Format(_T("%.2f"), SliceParamPtr->SliceGainValue);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }	

		//燈源組態, 燈源樣式
		KeyName = _T("Light Type");
		String.Format(_T("%d"), SliceParamPtr->SliceLightTable.LightType);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }	

		//LED開啟時間-us
		KeyName = _T("LED Turn On Time us");
		String.Format(_T("%d"), SliceParamPtr->SliceLightTable.LEDTurnOnTimeus);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }	
	
		//校正模式
		KeyName = _T("LED Current Calibration Mode");
		String.Format(_T("%d"), SliceParamPtr->SliceLightTable.LEDCurrCaliMode);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }	

		//DLP開啟時間-us			
		KeyName = _T("DLP Cast Turn On Time us");	
		String.Format(_T("%d"), SliceParamPtr->SliceLightTable.DLPTurnOnTimeus);
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }	

		//燈源組態LED
		for ( j=0; j<LED_CHANNEL_COUNT; j++ )
		{
			LedIdx = j+1;

			//LED燈源強度
			if ( LedIdx < 10 )
			{	KeyName.Format(_T("LED Channel 00%d Power Value"), LedIdx);	}				
			else if ( LedIdx < 100 )
			{	KeyName.Format(_T("LED Channel 0%d Power Value"), LedIdx);	}	
			else 
			{	KeyName.Format(_T("LED Channel %d Power Value"), LedIdx);	}
			String.Format(_T("%d"), SliceParamPtr->SliceLightTable.LEDChannel[j].PowerValue);
			if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
			{	return false; }	

			//LED開關狀態
			if ( LedIdx < 10 )
			{	KeyName.Format(_T("LED Channel 00%d On Off State"), LedIdx);	}				
			else if ( LedIdx < 100 )
			{	KeyName.Format(_T("LED Channel 0%d On Off State"), LedIdx);	}	
			else 
			{	KeyName.Format(_T("LED Channel %d On Off State"), LedIdx);	}
			String.Format(_T("%d"), SliceParamPtr->SliceLightTable.LEDChannel[j].OnOffState);
			if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
			{	return false; }
		}

		//燈源組態DLP
		for ( j=0; j<DLP_CAST_COUNT; j++ )
		{
			CastIdx = j+1;
			bool bSaveOnOffState=true;

			//DLP開關狀態
			if ( CastIdx < 10 )
			{	KeyName.Format(_T("DLP Cast 00%d On Off State"), CastIdx);	}				
			else if ( CastIdx < 100 )
			{	KeyName.Format(_T("DLP Cast 0%d On Off State"), CastIdx);	}	
			else 
			{	KeyName.Format(_T("DLP Cast %d On Off State"), CastIdx);	}
			String.Format(_T("%d"), SliceParamPtr->SliceLightTable.DLPCast[j].OnOffState);
			if ( SLICE_UNIQUE_ID_DLP == SliceParamPtr->SliceUniqueID )			
			{	
				switch ( j )
				{
				case 0:
				#ifdef BYPASS_DLP1_USE
					bSaveOnOffState = false;
				#endif//BYPASS_DLP1_USE
					break;
				case 1:
				#ifdef BYPASS_DLP2_USE
					bSaveOnOffState = false;
				#endif//BYPASS_DLP2_USE
					break;
				case 2:
				#ifdef BYPASS_DLP3_USE
					bSaveOnOffState = false;
				#endif//BYPASS_DLP3_USE
					break;
				case 3:
				#ifdef BYPASS_DLP4_USE
					bSaveOnOffState = false;
				#endif//BYPASS_DLP4_USE
					break;				
				}				
			}
			if ( true == bSaveOnOffState )
			{
				if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
				{	return false; }	
			}
			
			//DLP觸發次數
			if ( CastIdx < 10 )
			{	KeyName.Format(_T("DLP Cast 00%d Trigger Count"), CastIdx);	}				
			else if ( CastIdx < 100 )
			{	KeyName.Format(_T("DLP Cast 0%d Trigger Count"), CastIdx);	}	
			else 
			{	KeyName.Format(_T("DLP Cast %d Trigger Count"), CastIdx);	}
			String.Format(_T("%d"), SliceParamPtr->SliceLightTable.DLPCast[j].TriggerCount);
			if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
			{	return false; }	
		}
	}
#endif//OFFLINE_VERSION
	return true;
}
