//-------------------------------------------------------------------------------------//
size_t CAOIDataCollect::GetSystemSliceParamCount() const//取得Slice Param數量
{	
	return m_SystemSliceParamList.size();
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::AddSystemSliceParam(const TSliceParam &Param, bool bCheck)//增加Slice Param	
{	
	if ( true == bCheck )
	{
		int i=0;
		if ( LIGHT_LED == Param.SliceLightTable.LightType )
		{
			const int MaxCount = LED_CHANNEL_COUNT;
			//Check Use Number
			bool bUsed = false;
			for ( i=0; i<MaxCount; i++ )
			{
				if ( FN_ENABLE == Param.SliceLightTable.LEDChannel[i].OnOffState )
				{	bUsed = true; }
			}
			if ( false == bUsed ) 
			{	
				this->m_ErrorString = _T("Error, No LED channel turn on");
				return false; 
			}

			for ( i=0; i<MaxCount; i++ )
			{
				if ( FN_DISABLE == Param.SliceLightTable.LEDChannel[i].OnOffState )
				{	continue; }
				if ( Param.SliceLightTable.LEDChannel[i].PowerValue > 255 ) 
				{	break; }
			}
			if ( MaxCount != i )
			{
				this->m_ErrorString.Format(_T("Error, LED channel %d power value execption(%d)"), i, Param.SliceLightTable.LEDChannel[i].PowerValue);
				return false; 
			}
			

		}
		else if ( LIGHT_DLP == Param.SliceLightTable.LightType )
		{
			const int MaxCount = DLP_CAST_COUNT;
			//Check Use Number;
			bool bUsed = false;
			for ( i=0; i<MaxCount; i++ )
			{
				if ( FN_ENABLE == Param.SliceLightTable.DLPCast[i].OnOffState )
				{	bUsed = true; }
			}
			if ( false == bUsed ) 
			{
				this->m_ErrorString = _T("Error, No 3D Cast Actived");
				return false; 
			}

			//Check Trigger Camera Count
			for ( i=0; i<MaxCount; i++ )
			{
				if ( FN_DISABLE == Param.SliceLightTable.DLPCast[i].OnOffState )
				{	continue; }
				if ( 0 == Param.SliceLightTable.DLPCast[i].TriggerCount )
				{	break; }
			}
			if ( MaxCount != i )
			{	
				this->m_ErrorString.Format(_T("Error, 3D Cast %d trigger count execption(%d)"), i, Param.SliceLightTable.DLPCast[i].TriggerCount);
				return false; 
			}
		}		
	

	}
	m_SystemSliceParamList.push_back(Param);
	return true;
}
//-------------------------------------------------------------------------------------//
TSliceParam* CAOIDataCollect::GetSystemSliceParamPtrByUniqueID(size_t UniqueID)//依據Slice ID來取得Slice Param指標
{
	size_t i=0;
	TSliceParam *SliceParamPtr = NULL;
	const size_t SliceCount = m_SystemSliceParamList.size();
	for ( i=0; i<SliceCount; i++ )
	{
		SliceParamPtr = &(m_SystemSliceParamList[i]);
		if ( SliceParamPtr->SliceUniqueID == UniqueID )
		{	return SliceParamPtr; }
	}
	this->m_ErrorString.Format(_T("Error, Get Slice Param Ptr Fault [%d]"), UniqueID);
	return NULL;
}
//-------------------------------------------------------------------------------------//
size_t CAOIDataCollect::GetSystemSliceParamIndex(size_t UniqueID)//依據Slice ID來取得Slice Param指標
{
	size_t i=0;
	TSliceParam *SliceParamPtr = NULL;
	const size_t SliceCount = m_SystemSliceParamList.size();
	for ( i=0; i<SliceCount; i++ )
	{
		SliceParamPtr = &(m_SystemSliceParamList[i]);
		if ( SliceParamPtr->SliceUniqueID == UniqueID )
		{	return i; }
	}
	return -1;
}
//-------------------------------------------------------------------------------------//
TSliceParam* CAOIDataCollect::GetSystemSliceParamPtr(size_t idx, bool Check)//依據Slice index來取得Slice Param指標
{
	if ( true == Check )
	{
		const size_t SliceCount = m_SystemSliceParamList.size();
		if ( idx >= SliceCount ) 
		{
			this->m_ErrorString.Format(_T("Error, Get Slice Param Ptr Fault [%d/%d]"), idx, SliceCount);
			return NULL; 
		}
	}
	return &(m_SystemSliceParamList[idx]);	
}
//-------------------------------------------------------------------------------------//
unsigned int CAOIDataCollect::GetSystemSliceParamIndexByUniqueID(size_t UniqueID)//依據Slice ID來取得Slice Param引數
{	
	unsigned int i=0;	
	TSliceParam *SliceParamPtr = NULL;
	const unsigned int SliceCount = (unsigned int)(m_SystemSliceParamList.size());	
	for ( i=0; i<SliceCount; i++ )
	{
		SliceParamPtr = &(m_SystemSliceParamList[i]);
		if ( UniqueID == SliceParamPtr->SliceUniqueID ) { return i; }		
	}	
	this->m_ErrorString.Format(_T("Error, Get Slice Param Index Exception (ID:%d)"), UniqueID);
	return -1;
}
//-------------------------------------------------------------------------------------//
unsigned int CAOIDataCollect::GetSystemSliceParamFreeUniqueID()//取得Slice Param新的識別碼
{
	unsigned int i=0, j=0;
	unsigned int UniqueID=SLICE_UNIQUE_ID_USER_DEFINED;	
	TSliceParam *SliceParamPtr = NULL;
	const unsigned int SliceCount = (unsigned int)(m_SystemSliceParamList.size());	
	for ( i=0; i<SliceCount; i++ )
	{
		SliceParamPtr = &(m_SystemSliceParamList[i]);
		if ( SliceParamPtr->SliceUniqueID < SLICE_UNIQUE_ID_USER_DEFINED ) { continue; }
		if ( UniqueID < SliceParamPtr->SliceUniqueID )
		{	UniqueID = SliceParamPtr->SliceUniqueID; }
	}
	UniqueID ++;
	return UniqueID;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckSystemSliceParamFreeUniqueID(unsigned int ID)//確認Slice Param新的識別碼	
{
	if ( SLICE_UNIQUE_ID_NULL==ID || SLICE_UNIQUE_ID_MAX<ID )
	{
		m_ErrorString.Format(_T("Error, Slice Param Free UniqueID is Invalid[%d]"), ID);
		return false;
	}
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::DeleteSystemSliceParamIndex(size_t index)//刪除Slice Param
{
	TSliceParam *SliceParamPtr = CAOIDataCollect::GetSystemSliceParamPtr(index, true);
	if ( NULL == SliceParamPtr ) { return false; }
	if ( SliceParamPtr->SliceUniqueID < SLICE_UNIQUE_ID_USER_DEFINED ) 
	{
		this->m_ErrorString.Format(_T("Error, Can not delete system default slice param"));
		return false; 
	}

	size_t i=0;
	std::vector<TSliceParam>   TempSliceParamList = m_SystemSliceParamList;//單1影像參數列表
	const size_t SliceCount = TempSliceParamList.size();
	m_SystemSliceParamList.clear();
	for ( i=0; i<SliceCount; i++ )
	{
		if ( i == index ) { continue; }
		m_SystemSliceParamList.push_back(TempSliceParamList[i]);
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::DeleteSystemSliceParamUserDefined()//刪除Slice Param 使用者定義
{	
	size_t i=0;
	TSliceParam *SliceParamPtr = NULL;
	std::vector<TSliceParam>   TempSliceParamList = m_SystemSliceParamList;//單1影像參數列表
	const size_t SliceCount = TempSliceParamList.size();
	m_SystemSliceParamList.clear();
	for ( i=0; i<SliceCount; i++ )
	{
		if ( TempSliceParamList[i].SliceUniqueID >= SLICE_UNIQUE_ID_USER_DEFINED ) { continue; } 
		m_SystemSliceParamList.push_back(TempSliceParamList[i]);
	}	
	return true;
}
