//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::UpdateSystemSliceParamList(const std::vector<TSliceParam> &ParamList)//更新Slice Param列表
{
	std::vector<TSliceParam> SysParamList;
	if ( CloneSystemSliceParamList(SysParamList) == false ) { return false; }

	size_t i=0, j=0;
	const size_t ParamCount=ParamList.size();
	const size_t SysParamCount=SysParamList.size();
	for ( i=0; i<ParamCount; i++ )
	{
		const TSliceParam &ParamRef=ParamList[i];
		for ( j=0; j<SysParamCount; j++ )
		{
			TSliceParam &SysParamRef=SysParamList[j];
			if ( ParamRef.SliceUniqueID != SysParamRef.SliceUniqueID ) { continue; }
			SysParamRef = ParamRef;
			break;
		}
	}
	SetSystemSliceParamList(SysParamList);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CompareSliceParamList(const std::vector<TSliceParam> &List1, const std::vector<TSliceParam> &List2)//比較兩個SliceParam列表是否相等
{
	const size_t Count1=List1.size();
	const size_t Count2=List2.size();
	if ( Count2 != Count1 ) { return false; }
	for ( size_t i=0; i<Count1; i++ )
	{
		const TSliceParam &Param1=List1[i];
		const TSliceParam &Param2=List2[i];
		if ( Param1.SliceUniqueID != Param2.SliceUniqueID ) { return false; }
		if ( Param1.SliceCameraID != Param2.SliceCameraID ) { return false; }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckSliceParamUsed3DCastID(const TLightTable &LightTable, LIGHT_3D_CAST_ID CastID[])//確認SliceParam使用到的CastID
{
	int UsedCnt=0;
	CastID[0] = CastID[1] = CastID[2] = CastID[3] = LIGHT_3D_CAST_00;
	if ( LIGHT_3D_CAST_00 == CastID[UsedCnt] )
	{
		if ( FN_ENABLE==LightTable.DLPCast[0].OnOffState && LightTable.DLPCast[0].TriggerCount > 0 )
		{	
			CastID[UsedCnt] = LIGHT_3D_CAST_01;
			UsedCnt ++;
		}
	}
	if ( LIGHT_3D_CAST_00 == CastID[UsedCnt] )
	{
		if ( FN_ENABLE==LightTable.DLPCast[1].OnOffState && LightTable.DLPCast[1].TriggerCount > 0 )
		{	
			CastID[UsedCnt] = LIGHT_3D_CAST_02;
			UsedCnt ++;
		}
	}
	if ( LIGHT_3D_CAST_00 == CastID[UsedCnt] )
	{
		if ( FN_ENABLE==LightTable.DLPCast[2].OnOffState && LightTable.DLPCast[2].TriggerCount > 0 )
		{	
			CastID[UsedCnt] = LIGHT_3D_CAST_03;
			UsedCnt ++;
		}
	}
	if ( LIGHT_3D_CAST_00 == CastID[UsedCnt] )
	{
		if ( FN_ENABLE==LightTable.DLPCast[3].OnOffState && LightTable.DLPCast[3].TriggerCount > 0 )
		{	
			CastID[UsedCnt] = LIGHT_3D_CAST_04;
			UsedCnt ++;
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::BuildFOVResolutionCombox(CComboBox &Combox, double ShowScale)//建立FOV解析度列表
{
	CString str;
	int     idx=0;
	int     Mode=0;
	double  val=0;	
	DWORD   Param=0;
	bool    bScale=false;
	std::vector<int> ModeList;
	ModeList.push_back(FOV_RESOLUTION_020);
	ModeList.push_back(FOV_RESOLUTION_025);
	ModeList.push_back(FOV_RESOLUTION_030);
	ModeList.push_back(FOV_RESOLUTION_050);
	ModeList.push_back(FOV_RESOLUTION_055);
	ModeList.push_back(FOV_RESOLUTION_060);
	ModeList.push_back(FOV_RESOLUTION_065);
	ModeList.push_back(FOV_RESOLUTION_070);
	ModeList.push_back(FOV_RESOLUTION_072);
	ModeList.push_back(FOV_RESOLUTION_075);	
	ModeList.push_back(FOV_RESOLUTION_078);	
	ModeList.push_back(FOV_RESOLUTION_080);	
	ModeList.push_back(FOV_RESOLUTION_100);
	ModeList.push_back(FOV_RESOLUTION_110);
	ModeList.push_back(FOV_RESOLUTION_120);
	ModeList.push_back(FOV_RESOLUTION_130);
	ModeList.push_back(FOV_RESOLUTION_150);
	ModeList.push_back(FOV_RESOLUTION_160);
	ModeList.push_back(FOV_RESOLUTION_180);
	ModeList.push_back(FOV_RESOLUTION_200);	
	if ( fabs(ShowScale-100) > 0.01 )
	{	
		bScale = true; 
		ShowScale = ShowScale/100.0;
	}
	else
	{	ShowScale = 1.0; }	

	JetAPI::ClearCombox(Combox);
	idx = 0;

	int   i=0;
	const int ModeCount=(int)(ModeList.size());
	for ( i=0; i<ModeCount; i++ )
	{
		Mode = ModeList[i];
		val = GetFovResolutionValueFn(Mode);
		val *= ShowScale; 
		if ( true == bScale )
		{	str.Format(_T("%.1f *"), val);	}
		else
		{	str.Format(_T("%.1f"), val); }	
		Param = Mode;
		Combox.InsertString(-1, str);
		Combox.SetItemData(idx, Param);
		idx ++;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::BuildSliceParamListByFrameList(const std::vector<TFrameParam> &FrameParamList, std::vector<TSliceParam> &SliceParamList)//取得Frame的Slice Param List
{
	SliceParamList.clear();

	size_t       i=0, j=0;
	size_t       TmpSliceParamCount=0;
	size_t       TotalSliceParamCount=0;
	unsigned int FrameUniqueID=0;
	TFrameParam  FrameParam;
	std::vector<TSliceParam> TmpSliceParamList;
	const size_t FrameParamCount = FrameParamList.size();

	TotalSliceParamCount=0;
	for ( i=0; i<FrameParamCount; i++ )
	{
		FrameParam = FrameParamList[i];
		FrameUniqueID = FrameParam.FrameUniqueID;
		TmpSliceParamList.clear();
		if ( BuildSliceParamListByFrameUniqueID(FrameUniqueID, TmpSliceParamList) == false )
		{	return false; }

		TmpSliceParamCount = TmpSliceParamList.size();
		for ( j=0; j<TmpSliceParamCount; j++ )
		{	SliceParamList.push_back(TmpSliceParamList[j]);	}
		TotalSliceParamCount += TmpSliceParamCount;
	}
	const size_t SliceParamCount = SliceParamList.size();
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::RemoveUniqueIDListByUniqueID(std::vector<unsigned int> &UniqueIDList, unsigned int UniqueID)//移除特定ID的Frame Param列表			
{
	size_t      i=0;
	std::vector<unsigned int> TempUniqueIDList = UniqueIDList;
	const size_t UniqueIDCount = TempUniqueIDList.size();
	UniqueIDList.clear();
	for ( i=0; i<UniqueIDCount; i++ )
	{
		if ( UniqueID == TempUniqueIDList[i] )
		{	continue; }
		UniqueIDList.push_back(TempUniqueIDList[i]);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::BuildSliceParamListByFrameUniqueID(unsigned int UniqueID, std::vector<TSliceParam> &SliceParamList)//取得Frame的Slice Param List
{
	TFrameParam *FrameParamPtr = GetSystemFrameParamPtrByUniqueID(UniqueID);//依據Frame ID來取得Frame Param指標
	if ( NULL == FrameParamPtr )	{	return false;	}

	unsigned int  SliceID = -1;	
	unsigned int  SliceIndex = -1;	
	TSliceParam  *SliceParamPtr = NULL;
	
	SliceParamList.clear();

	SliceID = FrameParamPtr->FrameSliceID1;	
	SliceIndex = GetSystemSliceParamIndex(SliceID);
	if ( -1 != SliceIndex )
	{		
		SliceParamPtr = GetSystemSliceParamPtr(SliceIndex, false);	
		if ( NULL != SliceParamPtr )
		{	SliceParamList.push_back(*SliceParamPtr);	}		
	}

	SliceID = FrameParamPtr->FrameSliceID2;
	SliceIndex = GetSystemSliceParamIndex(SliceID);
	if ( -1 != SliceIndex )
	{
		SliceParamPtr = GetSystemSliceParamPtr(SliceIndex, false);
		if ( NULL != SliceParamPtr )
		{	SliceParamList.push_back(*SliceParamPtr);	}
	}

	SliceID = FrameParamPtr->FrameSliceID3;
	SliceIndex = GetSystemSliceParamIndex(SliceID);
	if ( -1 != SliceIndex )
	{
		SliceParamPtr = GetSystemSliceParamPtr(SliceIndex, false);
		if ( NULL != SliceParamPtr )
		{	SliceParamList.push_back(*SliceParamPtr);	}
	}

	const size_t SliceParamCount = SliceParamList.size();
	if ( 0 == SliceParamCount )
	{
		this->m_ErrorString.Format(_T("Error, The FrameParam[%s::%d] no Slice Param Data"), FrameParamPtr->FrameName, UniqueID);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::AddFrameSliceParamListByFrameUniqueID(unsigned int FrameUniqueID, std::vector<TFrameParam> &FrameParamList, std::vector<TSliceParam> &SliceParamList)
{
	size_t                    i = 0;
	unsigned int              SliceIndex = -1;
	unsigned int              SliceUniqueID = SLICE_UNIQUE_ID_NULL;	
	FRAME_TYPE                FrameType = FRAME_GRAY;	
	TSliceParam *SliceParamPtr = NULL;
	TFrameParam *FrameParamPtr = GetSystemFrameParamPtrByUniqueID(FrameUniqueID);
	if ( NULL == FrameParamPtr )
	{
		this->m_ErrorString.Format(_T("Error, Get Frame Param Ptr Fault (FrameID:%d)"), FrameUniqueID);
		return false;
	}	

	TFrameParam FrameParam = *FrameParamPtr;
	SliceUniqueID = FrameParam.FrameSliceID1;
	if ( SLICE_UNIQUE_ID_NULL != SliceUniqueID )
	{
		SliceIndex = GetSystemSliceParamIndexByUniqueID(SliceUniqueID);
		SliceParamPtr = GetSystemSliceParamPtr(SliceIndex, true);
		if ( -1==SliceIndex || NULL==SliceParamPtr ) 
		{
			this->m_ErrorString.Format(_T("Error, Frame Slice Unique ID Exception (FrameID:%d, SliceID:%d)"), FrameParamPtr->FrameUniqueID, SliceUniqueID);
			return false; 
		}			
		FrameParam.FrameSliceIdx1 = SliceIndex;
		SliceParamList.push_back(*SliceParamPtr);
	}

	SliceUniqueID = FrameParam.FrameSliceID2;
	if ( SLICE_UNIQUE_ID_NULL != SliceUniqueID )
	{
		SliceIndex = GetSystemSliceParamIndexByUniqueID(SliceUniqueID);
		SliceParamPtr = GetSystemSliceParamPtr(SliceIndex, true);
		if ( -1==SliceIndex || NULL==SliceParamPtr ) 
		{
			this->m_ErrorString.Format(_T("Error, Frame Slice Unique ID Exception (FrameID:%d, SliceID:%d)"), FrameParamPtr->FrameUniqueID, SliceUniqueID);
			return false; 
		}
		FrameParam.FrameSliceIdx2 = SliceIndex;
		SliceParamList.push_back(*SliceParamPtr);
	}

	SliceUniqueID = FrameParam.FrameSliceID3;
	if ( SLICE_UNIQUE_ID_NULL != SliceUniqueID )
	{
		SliceIndex = GetSystemSliceParamIndexByUniqueID(SliceUniqueID);
		SliceParamPtr = GetSystemSliceParamPtr(SliceIndex, true);
		if ( -1==SliceIndex || NULL==SliceParamPtr ) 
		{
			this->m_ErrorString.Format(_T("Error, Frame Slice Unique ID Exception (FrameID:%d, SliceID:%d)"), FrameParamPtr->FrameUniqueID, SliceUniqueID);
			return false; 
		}
		FrameParam.FrameSliceIdx3 = SliceIndex;
		SliceParamList.push_back(*SliceParamPtr);
	}
	FrameParamList.push_back(FrameParam);	
	return true;
}
