//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::VerifyProjectFilename()//驗證專案檔名
{
	MULTI_LANE_MODE MultiLaneMode=CheckMultiLaneMode();
	if ( MULTI_LANE_1 == MultiLaneMode )
	{
		CAOIProject *ProjectPtr = GetActiveProject();
		if ( CheckProjectPtr(ProjectPtr) == false ) { return false; }
	
		CString Filename=ProjectPtr->GetProjectShowName();
		if ( VerifyProjectFilename(Filename) == false )
		{	return false; }
	}
	if ( MULTI_LANE_2 == MultiLaneMode )
	{
		size_t i=0;
		LANE_ID LaneID;
		const size_t ProjectCount=GetProjectPtrCount();
		for ( i=0; i<ProjectCount; i++ )
		{
			CAOIProject *ProjectPtr = GetProjectPtr(i, false);
			if ( CheckProjectPtr(ProjectPtr) == false ) { continue; }
	
			CString Filename=ProjectPtr->GetProjectShowName();
			if ( ProjectPtr->GetProjectLaneEnable_LA() == true )
			{
				LaneID = LANE_ID_A;
				if ( VerifyProjectFilename(LaneID, Filename) == false )
				{	return false; }
			}
			if ( ProjectPtr->GetProjectLaneEnable_LB() == true )
			{
				LaneID = LANE_ID_B;
				if ( VerifyProjectFilename(LaneID, Filename) == false )
				{	return false; }
			}			
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::VerifyProjectFilename(LPCTSTR filename)//驗證專案檔名
{
	LANE_ID LaneID = GetActiveLaneID();
	if ( VerifyProjectFilename(LaneID, filename) == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::VerifyProjectFilename(LANE_ID LaneID, LPCTSTR filename)//驗證專案檔名
{
	const TSystemParameter &SysParam=GetSystemParameter();
	if ( VERIFY_PROJECT_DISABLE == SysParam.m_VerifyProjectMode )	{ return true; }	
	if ( VERIFY_PROJECT_FILENAME == SysParam.m_VerifyProjectMode )
	{
		CString str;		
		const size_t textlen = 128;
		CString KeyName, Default;
		TCHAR   String[textlen]=_T("");	
		CString Section=_T("CheckProjectInfo");		
		CString Folder=GetAOITempDirectory();		
		CString VerifyFilename = SysParam.m_VerifyProjectFilename;
		
		KeyName.Format(_T("Lane %d"), LaneID);
		if ( LoadINIData(Section, KeyName, Default, String, textlen, VerifyFilename, true, m_ErrorString) == false )
		{	return false; }

		CString MainName;		
		JetAPI::ExtractMainFileNameNoPath(filename, MainName);
		if ( MainName.CollateNoCase(String) != 0 )
		{
			m_ErrorString.Format(_T("Error, Lane %d Verify Filename Fault.\n%s\n%s"), LaneID, String, MainName);
			return false;
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckProjectFilenameValided(LPCTSTR filename)//確認專案檔名是有效檔名
{	
	size_t       i=0;
	CString      str;
	bool         bValid=true;
	const size_t len = ::_tcslen(filename);
	
	for ( i=0; i<len; i++ )
	{
		switch ( filename[i] )
		{		
		case _T(':'):
			if ( 1 != i )
			{	bValid = false; }
			break;
		case _T('<'):			
		case _T('>'):
		case _T('?'):		
		case _T('"'):
		case _T('*'):
		case _T('|'):
		case _T(';'):
		case _T(' '):
		case _T('%'):		
			bValid = false;
			break;
		}
		if ( false == bValid )
		{
			str = _T("Error, the filename exception");
			str = LoadMultiLanguageString(str, str);
			m_ErrorString.Format(_T("%s [NG{%c} at %d]\n%s"), str, filename[i], i+1,filename);
			return false;
		}
	}
	return true;
}
