//-------------------------------------------------------------------------------------//	
void CAOIDataCollect::SetUserLastInputTickCountByMsg(UINT Msg)//使用者上次輸入時間戳記
{
	bool bInput=false;
	switch ( Msg )
	{
	case WM_CHAR:
	//case WM_KEYUP:
	//case WM_KEYDOWN:
		bInput = true;
		break;
	case WM_INPUT:
	//case WM_LBUTTONUP:
	//case WM_RBUTTONUP:
	//case WM_MBUTTONUP:
	case WM_LBUTTONDOWN:
	case WM_RBUTTONDOWN:
	case WM_MBUTTONDOWN:
		bInput = true;
		break;

	//case WM_MOUSEMOVE:
	case WM_MOUSEWHEEL:
		bInput = true;
		break;
	default:
		bInput=false;
		break;
	}
	if ( false == bInput )
	{	return; }
	RegistUserLastInputTickCount();
	return;
}
