bool CAOIDataCollect::CheckOnlineIdleMode(ONLINE_STATE_MODE Mode) const//確認線上為閒置狀態
{
	bool bIdle=false;
	switch ( Mode )
	{
	case ONLINE_STATE_WAIT_FOR_LAST_STATION://等待上一站訊號
	case ONLINE_STATE_WAIT_FOR_NEXT_STATION://等待下一站訊號	
	case ONLINE_STATE_WAIT_FOR_PCB_REMOVED://等待板子移走
		bIdle = true;
		break;
	default:
		bIdle = false;
		break;
	}
	return bIdle;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckOnlineCanAutoStop(ONLINE_STATE_MODE Mode) const//確認線上可以自動停機
{
	bool bCan=false;
	switch ( Mode )
	{
	//case ONLINE_STATE_INSPECTION_STOP://停止檢測
	case ONLINE_STATE_INPUT_BARCODE://輸入條碼-同進同出與自動進出板不會跑這一段
	case ONLINE_STATE_INSPECTION_START://開始檢測	
	case ONLINE_STATE_WAIT_FOR_LAST_STATION://等待上一站訊號
	case ONLINE_STATE_WAIT_FOR_NEXT_STATION://等待下一站訊號	
	case ONLINE_STATE_WAIT_FOR_PCB_REMOVED://等待板子移走
		bCan = true;
		break;
	default:
		bCan = false;
		break;
	}
	return bCan;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckOnlineConveyerAutoRunCanStop(ONLINE_STATE_MODE Mode) const//確認線上軌道自動運轉可以停止
{
	bool bCan=false;
	switch ( Mode )
	{
	case ONLINE_STATE_PCB_READY:
		//case ONLINE_STATE_INSPECTION_STOP://停止檢測
	case ONLINE_STATE_INPUT_BARCODE://輸入條碼-同進同出與自動進出板不會跑這一段
	case ONLINE_STATE_INSPECTION_START://開始檢測	
	case ONLINE_STATE_WAIT_FOR_LAST_STATION://等待上一站訊號
	case ONLINE_STATE_WAIT_FOR_NEXT_STATION://等待下一站訊號	
	case ONLINE_STATE_PCB_IN_FINISH://進板結束
	case ONLINE_STATE_PCB_OUT_FINISH://出板結束
	case ONLINE_STATE_PCB_OUT_INSIDE_FINISH://停側邊結束
	case ONLINE_STATE_PCB_BACK_FINISH://退板結束
	case ONLINE_STATE_PCB_BACK_OUT_FINISH://退出板結束
	case ONLINE_STATE_WAIT_FOR_PCB_REMOVED://等待板子移走
	case ONLINE_STATE_WAIT_FOR_REPAIR_VERIFY://等待維修站確認	
	case ONLINE_STATE_PCB_OUT_IN_FINISH://出板帶進板結束
	case ONLINE_STATE_PCB_AUTO_RUN_FINISH://自動進出板結束
		bCan = true;
		break;
	default:
		bCan = false;
		break;
	}
	return bCan;
}
