//-------------------------------------------------------------------------------------//
ONLINE_STATE_MODE CAOIDataCollect::CheckExecOnlineAutoCalibrationMode() const//確認是否執行在線自動校正	
{
	CSortObj SortObj;	
	std::vector<CSortObj> SortList;
	ONLINE_STATE_MODE OnlineStateMode=ONLINE_STATE_RETURN;

	SortObj.SetSortMode(SORT_BY_TXT);
	if ( CheckExecOnlineAutoCalibration_XYZ_Home() == true )
	{		
		SortObj.SetID(ONLINE_STATE_AUTO_CALIBRATION_XYZ_HOME);
		SortObj.SetValueStr(GetOnlineAutoCalibrationDateTime_XYZ_Home());
		SortList.push_back(SortObj);
	}
	if ( CheckExecOnlineAutoCalibration_2D_Current() == true )
	{		
		SortObj.SetID(ONLINE_STATE_AUTO_CALIBRATION_2D_CURRENT);
		SortObj.SetValueStr(GetOnlineAutoCalibrationDateTime_2D_Current());
		SortList.push_back(SortObj);
	}
	if ( CheckExecOnlineAutoCalibration_3D_Current() == true )
	{	
		SortObj.SetID(ONLINE_STATE_AUTO_CALIBRATION_3D_CURRENT);
		SortObj.SetValueStr(GetOnlineAutoCalibrationDateTime_3D_Current());
		SortList.push_back(SortObj);
	}
	if ( CheckExecOnlineAutoCalibration_3D_ZeroPlane() == true )
	{	
		SortObj.SetID(ONLINE_STATE_AUTO_CALIBRATION_3D_ZERO_PLANE);
		SortObj.SetValueStr(GetOnlineAutoCalibrationDateTime_3D_ZeroPlane());
		SortList.push_back(SortObj);
	}
	if ( CheckExecOnlineAutoCalibration_3D_HeightFactor() == true )
	{	
		SortObj.SetID(ONLINE_STATE_AUTO_CALIBRATION_3D_HEIGHT_FACTOR);
		SortObj.SetValueStr(GetOnlineAutoCalibrationDateTime_3D_HeightFactor());
		SortList.push_back(SortObj);
	}

	const size_t SortCount=SortList.size();
	if ( 0 == SortCount )
	{	return OnlineStateMode; }

	//找尚未校正且時間最前面的編號
	std::sort(SortList.begin(), SortList.end());
	SortObj=SortList[0];
	const int ID=SortObj.GetID();
	OnlineStateMode = (ONLINE_STATE_MODE)(ID); 
	return OnlineStateMode;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckExecOnlineAutoCalibration(TOnlineProcParam &Param)//確認是否執行在線自動校正	
{	
	ONLINE_STATE_MODE OnlineStateMode=CheckExecOnlineAutoCalibrationMode();
	if ( ONLINE_STATE_RETURN == OnlineStateMode )
	{	
		Param.eOnlineStateNew = ONLINE_STATE_PCB_READY;
		return true;
	}
	Param.eOnlineStateNew = OnlineStateMode;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckExecOnlineAutoCalibrationDateTime(LPCTSTR LastTime, DWORD TimeHour) const//確認是否執行在線自動校正日期時間
{
	if ( 0 == TimeHour ) { return true; }
	
	//TimeHour = 100;
	CTime TimeLast;
	char chBuffer[32]="";
	CTime TimeNow=CTime::GetCurrentTime();
	const int nDays=0;
	const int nHours=TimeHour;
	const int nMins=0;
	const int nSecs=0;

	JetAPI::TCHAR2char(LastTime, chBuffer, 32);
	JetAPI::GetTime(chBuffer, TimeLast);	
	
	CTimeSpan TimeSpan(nDays, nHours, nMins, nSecs);
	CTime     TimeNext=TimeLast+TimeSpan;

	CString   DateTimeNext;
	JetAPI::GetTime(DateTimeNext, TimeNext);	

	if ( TimeNext > TimeNow  ) { return false; }	

	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckExecOnlineAutoCalibration_XYZ_Home() const//確認是否執行在線自動校正-XYZ歸零
{
#ifndef ONLINE_AUTO_CALIBRATION_USE
	return false;
#endif//ONLINE_AUTO_CALIBRATION_USE
	const TSystemParameter &SysParam=GetSystemParameter();
	DWORD TimeHour=SysParam.m_OnlineAutoCalibrationPeriod_XYZHome;
	CString LastDateTime=GetOnlineAutoCalibrationDateTime_XYZ_Home();	
	FUNC_EXEC_MODE CalibrationMode=SysParam.m_OnlineAutoCalibrationMode_XYZHome;		
	if ( FUNC_EXEC_OFF == CalibrationMode ) { return false; }	
	if ( 0 == TimeHour ) { return true; }	
	if ( CheckExecOnlineAutoCalibrationDateTime(LastDateTime, TimeHour) == false )
	{	return false; }	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckExecOnlineAutoCalibration_2D_Current() const//確認是否執行在線自動校正-2D電流
{
#ifndef ONLINE_AUTO_CALIBRATION_USE
	return false;
#endif//ONLINE_AUTO_CALIBRATION_USE
	const TSystemParameter &SysParam=GetSystemParameter();
	DWORD TimeHour=SysParam.m_OnlineAutoCalibrationPeriod_2DCurrent;
	CString LastDateTime=GetOnlineAutoCalibrationDateTime_2D_Current();	
	FUNC_EXEC_MODE CalibrationMode=SysParam.m_OnlineAutoCalibrationMode_2DCurrent;		
	if ( FUNC_EXEC_OFF == CalibrationMode ) { return false; }	
	if ( 0 == TimeHour ) { return true; }	
	if ( CheckExecOnlineAutoCalibrationDateTime(LastDateTime, TimeHour) == false )
	{	return false; }	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckExecOnlineAutoCalibration_3D_Current() const//確認是否執行在線自動校正-3D電流
{
#ifdef DISABLE_3D
	return false;
#endif//DISABLE_3D
#ifndef ONLINE_AUTO_CALIBRATION_USE
	return false;
#endif//ONLINE_AUTO_CALIBRATION_USE
	return false;
	const TSystemParameter &SysParam=GetSystemParameter();
	CString LastDateTime=GetOnlineAutoCalibrationDateTime_3D_Current();
	DWORD TimeHour=SysParam.m_OnlineAutoCalibrationPeriod_3DCurrent;
	if ( 0 == TimeHour ) { return true; }
	if ( CheckExecOnlineAutoCalibrationDateTime(LastDateTime, TimeHour) == false )
	{	return false; }	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckExecOnlineAutoCalibration_3D_ZeroPlane() const//確認是否執行在線自動校正-3D相平面
{
#ifdef DISABLE_3D
	return false;
#endif//DISABLE_3D
#ifndef ONLINE_AUTO_CALIBRATION_USE
	return false;
#endif//ONLINE_AUTO_CALIBRATION_USE
	const TSystemParameter &SysParam=GetSystemParameter();
	DWORD TimeHour=SysParam.m_OnlineAutoCalibrationPeriod_3DZeroPlane;
	CString LastDateTime=GetOnlineAutoCalibrationDateTime_3D_ZeroPlane();
	FUNC_EXEC_MODE CalibrationMode=SysParam.m_OnlineAutoCalibrationMode_3DZeroPlane;	
	if ( FUNC_EXEC_OFF == CalibrationMode ) { return false; }	
	if ( 0 == TimeHour ) { return true; }
	if ( CheckExecOnlineAutoCalibrationDateTime(LastDateTime, TimeHour) == false )
	{	return false; }	
	return true;
}
