bool CAOIDataCollect::SaveOnlineAutoCalibrationDateTime_XYZ_Home()//儲存在線自動校正日期時間-XYZ歸零
{
	CString str;
	CString Section;
	CString KeyName;
	CString String;	
	CString Filename = GetSystemParamFilename();		
	Section = GetCalibrationSectionName();
	KeyName = _T("Online Auto Calibration Date Time XYZ Home");
	String.Format(_T("%s"), GetOnlineAutoCalibrationDateTime_XYZ_Home());
	if ( SaveINIData(Section, KeyName, String, Filename, m_ErrorString) == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadOnlineAutoCalibrationDateTime_XYZ_Home()//載入在線自動校正日期時間-XYZ歸零
{
	const size_t textlen = 128;
	CString str;
	CString Section = _T("");	
	CString KeyName = _T("");
	CString Default = _T("");
	TCHAR   String[textlen]=_T("");		
	CString Filename = GetSystemParamFilename();	
	Section = GetCalibrationSectionName();
	KeyName = _T("Online Auto Calibration Date Time XYZ Home");
	Default.Format(_T("%s"), GetOnlineAutoCalibrationDateTime_XYZ_Home());	
	if ( LoadINIData(Section, KeyName, Default, String, textlen, Filename, false, m_ErrorString) == true ) 	
	{	SetOnlineAutoCalibrationDateTime_XYZ_Home(String);	}
	return true;
}
