//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveOnlineAutoCalibrationLog(LPCTSTR Text)//儲存在線自動校正訊息
{
	if ( SaveOnlineAutoCalibrationLogFn(Text) == false )
	{
		SetSystemExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveOnlineAutoCalibrationLogFn(LPCTSTR Text)//儲存在線自動校正訊息
{
	CString LogFolder;
	CString MainFolder=GetAOILogDirectory();
	LogFolder.Format(_T("%s\\%s"), MainFolder, _T("OnlineCalibration"));
	::CreateDirectory(LogFolder, NULL);	
	
	CString tp;
	CString str;
	CString Name;	
	TCHAR TMode[32] = _T("");	
	CString tYear, tMon, tDay, tHour, tMin, tSec;
	CString KeyString = Text;		
	JetAPI::GetTime(tp,CTime::GetCurrentTime());
	tYear = tp.Mid(0, 4);
	tMon  = tp.Mid(4, 2);
	tDay  = tp.Mid(6, 2);
	tHour = tp.Mid(8, 2);
	tMin  = tp.Mid(10, 2);
	tSec  = tp.Mid(12, 2);
	_tcscpy(TMode, _T("a+"));
	JetAPI::ModifyOpenFileMode_Write(TMode);
	Name.Format(_T("%s\\Calibration_%s%s.TXT"), LogFolder, (LPCTSTR)tYear, (LPCTSTR)tMon);

	FILE *pfile=::_tfopen(Name,TMode);
	if ( NULL == pfile ) 
	{	
		str.Format(_T("Error, Open File To Save Fault[%s]"), Name);
		SetErrorString(str);
		return false;
	}
	str.Format(_T("%s/%s/%s,%s:%s:%s  %s"),(LPCTSTR)tYear, (LPCTSTR)tMon, (LPCTSTR)tDay, (LPCTSTR)tHour, (LPCTSTR)tMin, (LPCTSTR)tSec, (LPCTSTR)KeyString);	

	_ftprintf(pfile,_T("%s\n"),(LPCTSTR)str);
	::fclose(pfile);
	return true;
}
