//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CancelGatherColorMode()//取消收集顏色模式
{
	MANIPULATE_MODEL_MODE ManiMode = GetManipulateModelMode();
	if ( MANIPULATE_MODEL_GATHER_COLOR != ManiMode )
	{	return false; }

	ManiMode = GetManipulateModelModeDefault();
	SetManipulateModelMode(ManiMode);	
	SendMainFrameWndMessage(MSG_EDIT_IMAGE_PROCESS_WND, WPARAM_UPDATE_GATHER_COLOR_CHK, NULL);
	return true;	
}
