//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SwitchProjectTaskMode(PROJECT_TASK_MODE value)
{
	if ( m_ProjectTaskMode == value ) { return true; }
	CAOIProject *ProjectPtr = NULL;
	SetProjectTaskMode(value);
	ProjectPtr = GetActiveTaskProject();	
	SetProjectLightSetting(ProjectPtr);
	SendMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_PROJECT_SWITCH, NULL);
	PostCallbackWndMessage(MSG_CAMERA_REGRAB_IMAGE, NULL, NULL);
	return true; 
}
//-------------------------------------------------------------------------------------//
CString CAOIDataCollect::GetProjectReportFilename(CAOIProject *ProjectPtr) const
{
	CString Filename;
	CString ReportText=PROJECT_REPORT_TEXT;			
	if ( NULL != ProjectPtr )
	{	
		CString ProjectName=ProjectPtr->GetProjectFileMainName();
		ReportText.Format(_T("%s_Report.TXT"), ProjectName);	
	}
	Filename.Format(_T("%s\\%s"), GetAOITempDirectory(), ReportText);
	return Filename;
}
