//-------------------------------------------------------------------------------------//
void CAOIDataCollect::CalcSystemMapCoordinate(CMapCoordinate &CTS, CMapCoordinate &STC)
{
	TPOINT2D CadPos1, StagePos1;
	TPOINT2D CadPos2, StagePos2;
	TPOINT2D CadOffset, StageOffset;
	const size_t Num = 2;
	const double SizeW2 = 1000000;//1000mm
	const double SizeH2 = 1000000;//1000mm
	const double Precision = DBL_PRECISION;
	double SrcX[Num] = {0};
	double SrcY[Num] = {0};
	double DstX[Num] = {0};
	double DstY[Num] = {0};

	CadOffset.x = SizeW2;
	CadOffset.y = SizeH2;
	MapCadOffsetPtToStage(CadOffset, StageOffset);

	CadPos1.x = 0-CadOffset.x;
	CadPos1.y = 0-CadOffset.y;
	CadPos2.x = 0+CadOffset.x;
	CadPos2.y = 0+CadOffset.y;

	StagePos1.x = 0-StageOffset.x;
	StagePos1.y = 0-StageOffset.y;
	StagePos2.x = 0+StageOffset.x;
	StagePos2.y = 0+StageOffset.y;

	//Build Cad to Stage Coordinate
	CTS.Identity();//整板的座標轉換-Cad to Stage	
	SrcX[0] = CadPos1.x;	SrcY[0] = CadPos1.y;
	SrcX[1] = CadPos2.x;	SrcY[1] = CadPos2.y;
	DstX[0] = StagePos1.x;	DstY[0] = StagePos1.y;
	DstX[1] = StagePos2.x;	DstY[1] = StagePos2.y;
	CTS.CalcMatrix2D(SrcX, SrcY, DstX, DstY, Num);

	//Build Stage to Cad Coordinate
	STC.Identity();//整板的座標轉換-Stage to Cad	
	SrcX[0] = CadPos1.x;	SrcY[0] = CadPos1.y;
	SrcX[1] = CadPos2.x;	SrcY[1] = CadPos2.y;
	DstX[0] = StagePos1.x;	DstY[0] = StagePos1.y;
	DstX[1] = StagePos2.x;	DstY[1] = StagePos2.y;
	STC.CalcMatrix2D(DstX, DstY, SrcX, SrcY, Num);
	return ;
}
