bool CAOIDataCollect::CheckAIServerIsReady(bool bRealCheck)//確認AI伺服器準備好
{
#ifdef AI_MODEL_USE
	const TSystemParameter &SysParam=GetSystemParameter();
	if ( FN_DISABLE == SysParam.m_AiModelServerEnabled )
	{
		CAOIModel::SetAIServerIsReady(false);
		return true;
	}

	CString strFolderSend=SysParam.m_AiModelFileFolderSend;
	CString strFolderRecv=SysParam.m_AiModelFileFolderRecv;
	if ( JetAPI::IsFolderExist(strFolderSend) == false || 
		 JetAPI::IsFolderExist(strFolderRecv) == false )
	{
		CString str=_T("Error, Check Folder Fault");
		m_ErrorString.Format(_T("%s\nSend:%s\nRecv:%s"), str, strFolderSend, strFolderRecv);
		return false;
	}
	CAOIModel::SetAIServerFolderSend(strFolderSend);
	CAOIModel::SetAIServerFolderRecv(strFolderRecv);
	CAOIModel::SetAIServerTimeout(SysParam.m_AiModelServerTimeout);	
	if ( false == bRealCheck )
	{	CAOIModel::SetAIServerIsReady(true); }
	else
	{
		const bool bSucc = CAOIModel::CheckAIServerIsReady();
		if ( false == bSucc )
		{
			m_ErrorString.Format(_T("Error, Check AI Server Fault"));		
			return false;
		}
	}
#endif//AI_MODEL_USE
	return true;
}
