void CAOIDataCollect::RemoveWndDefectID(WND_DEFECT_ID DefectID, std::vector<WND_DEFECT_ID> &List)//移除檢測框瑕疵代號列表	
{
	std::vector<WND_DEFECT_ID> &Temp=List;
	List.clear();
	for ( size_t i=0; i<Temp.size(); i++ )
	{
		if ( DefectID == Temp[i] ) { continue; }
		List.push_back(Temp[i]);
	}
	return;
}
