void CAOIDataCollect::ReleaseModelUniFrameList()
{	
	m_ModelUniFrameModelPtr = NULL;
	m_ModelUniFrameRgnStage = TREGION4D();
	JetAPI::ClearUniFrameList(m_ModelUniFrameList);
}
//-------------------------------------------------------------------------------------//
CAOIModel* CAOIDataCollect::GetModelUniFrameListModelPtr()
{
	return m_ModelUniFrameModelPtr;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckModelUniFrameListModelPtr(CAOIModel *ModelPtr)
{
	if ( NULL == ModelPtr ) { return false; }
	if ( ModelPtr != m_ModelUniFrameModelPtr ) { return false; }
	const size_t UniFrameCount = m_ModelUniFrameList.size();
	if ( 0 == UniFrameCount ) { return false; }	

	TREGION4D StageRgn;	
	const int Gap = 5;
	//ModelPtr->CalcModelTotalRegionAll();	
	ModelPtr->GetModelTotalRegionStage(StageRgn);
	
	const int nMinX = (int)(::fabs(StageRgn.minX-m_ModelUniFrameRgnStage.minX));
	const int nMinY = (int)(::fabs(StageRgn.minY-m_ModelUniFrameRgnStage.minY));
	const int nMaxX = (int)(::fabs(StageRgn.maxX-m_ModelUniFrameRgnStage.maxX));
	const int nMaxY = (int)(::fabs(StageRgn.maxY-m_ModelUniFrameRgnStage.maxY));
	if ( nMinX>Gap || nMinY>Gap || nMaxX>Gap || nMaxY>Gap )
	{	return false; }

	return true;	
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckModelUniFrameListRegion(const TREGION4D RgnStage)
{
	const size_t UniFrameCount = m_ModelUniFrameList.size();
	if ( 0 == UniFrameCount ) { return false; }
	
	const int Gap = 5;
	const int nMinX = (int)(::fabs(RgnStage.minX-m_ModelUniFrameRgnStage.minX));
	const int nMinY = (int)(::fabs(RgnStage.minY-m_ModelUniFrameRgnStage.minY));
	const int nMaxX = (int)(::fabs(RgnStage.maxX-m_ModelUniFrameRgnStage.maxX));
	const int nMaxY = (int)(::fabs(RgnStage.maxY-m_ModelUniFrameRgnStage.maxY));

	if ( nMinX>Gap || nMinY>Gap || nMaxX>Gap || nMaxY>Gap )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
void CAOIDataCollect::SetModelUniFrameList(CAOIModel *ModelPtr, const TREGION4D RgnStage, const std::vector<TUNI_FRAME> &UniFrameList, bool bClone)//設定模組的影像
{
	const char fnName[] = "CAOIDataCollect::SetModelUniFrameList";
	CAOIDataCollect::ReleaseModelUniFrameList();
	
	size_t i=0;
	size_t BufferSize=0;
	char   varName[64]="";
	TUNI_FRAME UniFrame;
	MASK_PTR   MaskPtr=NULL;
	MASK_PTR   MaskPtrNew=NULL;
	SPACE_PTR  SpacePtr=NULL;
	SPACE_PTR  SpacePtrNew=NULL;
	IMAGE_PTR  ImagePtr=NULL;
	IMAGE_PTR  ImagePtrNew=NULL;
	IMAGE_SIZE ImageW=0, ImageH=0, ImageStep=0, BitCount=0;
	IMAGE_SIZE ImageWOrg=0, ImageHOrg=0, ImageStepOrg=0, BitCountOrg=0;
	unsigned int FrameUniqueID = 0;
	const size_t UniFrameCount = UniFrameList.size();

	m_ModelUniFrameModelPtr = ModelPtr;
	m_ModelUniFrameRgnStage = RgnStage;
	for ( i=0; i<UniFrameCount; i++ )
	{
		ImageW    = UniFrameList[i].ImageW;
		ImageH    = UniFrameList[i].ImageH;
		ImageStep = UniFrameList[i].ImageStep;
		BitCount  = UniFrameList[i].BitCount;
		FrameUniqueID = UniFrameList[i].FrameUniqueID;

		ImagePtr    = UniFrameList[i].ImagePtr;
		MaskPtr    = UniFrameList[i].MaskPtr;		
		SpacePtr    = UniFrameList[i].SpacePtr;		
		BufferSize = ImageAPI.CalcBufferSize(ImageStep, ImageH);

		if ( true == bClone )
		{
			ImagePtrNew = NULL;
			MaskPtrNew = NULL;
			SpacePtrNew = NULL;

			if ( NULL != ImagePtr ) 
			{
				::sprintf(varName, "%s#%d", "ImagePtr", i+1);
				if ( JetMemory.alloc_func(BufferSize, ImagePtrNew, fnName, varName) == false ) 
				{	
					JetMemory.free_func(ImagePtrNew);
					JetMemory.free_func(MaskPtrNew);
					JetMemory.free_func(SpacePtrNew);
					break;
				}
				::memcpy(ImagePtrNew, ImagePtr, sizeof(IMAGE_DATA)*BufferSize);			
			}

			if ( NULL != MaskPtr ) 
			{	
				::sprintf(varName, "%s#%d", "MaskPtr", i+1);
				if ( JetMemory.alloc_func(BufferSize, MaskPtrNew, fnName, varName) == false ) 
				{
					JetMemory.free_func(ImagePtrNew);
					JetMemory.free_func(MaskPtrNew);
					JetMemory.free_func(SpacePtrNew);
					break;
				}
				::memcpy(MaskPtrNew, MaskPtr, sizeof(MASK_DATA)*BufferSize);
			}

			if ( NULL != SpacePtr ) 
			{	
				::sprintf(varName, "%s#%d", "SpacePtr", i+1);
				if ( JetMemory.alloc_func(BufferSize, SpacePtrNew, fnName, varName) == false ) 
				{
					JetMemory.free_func(ImagePtrNew);
					JetMemory.free_func(MaskPtrNew);
					JetMemory.free_func(SpacePtrNew);
					break;
				}
				::memcpy(SpacePtrNew, SpacePtr, sizeof(SPACE_DATA)*BufferSize);
			}
		}
		else
		{
			ImagePtrNew = ImagePtr;
			MaskPtrNew = MaskPtr;
			SpacePtrNew = SpacePtr;
		}
		
		UniFrame.ImageW = ImageW;
		UniFrame.ImageH = ImageH;
		UniFrame.ImageStep = ImageStep;
		UniFrame.BitCount = BitCount;
		UniFrame.ImagePtr = ImagePtrNew;
		UniFrame.MaskPtr = MaskPtrNew;
		UniFrame.SpacePtr = SpacePtrNew;
		UniFrame.FrameUniqueID = FrameUniqueID;
		m_ModelUniFrameList.push_back(UniFrame);
	}
	return;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SetModelUniFrameList(const std::vector<TUNI_FRAME> &UniFrameList)//設定模組的影像
{
	ReleaseModelUniFrameList();
	m_ModelUniFrameList = UniFrameList;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CopyModelUniFrameList(std::vector<TUNI_FRAME> &UniFrameList, bool bClone) const//複製模組的影像
{
	const char fnName[] = "CAOIDataCollect::CopyModelUniFrameList";
	
	bool   IsOK=true;
	size_t i=0;
	size_t BufferSize=0;
	size_t UniFrameCount;
	char   varName[64]="";
	TUNI_FRAME UniFrame;
	MASK_PTR   MaskPtr=NULL;
	MASK_PTR   MaskPtrNew=NULL;
	SPACE_PTR  SpacePtr=NULL;
	SPACE_PTR  SpacePtrNew=NULL;
	IMAGE_PTR  ImagePtr=NULL;
	IMAGE_PTR  ImagePtrNew=NULL;
	IMAGE_SIZE ImageW=0, ImageH=0, ImageStep=0, BitCount=0;
	IMAGE_SIZE ImageWOrg=0, ImageHOrg=0, ImageStepOrg=0, BitCountOrg=0;
	unsigned int FrameUniqueID = 0;
	
	IsOK=true;
	JetAPI::ClearUniFrameList(UniFrameList);	
	UniFrameCount = m_ModelUniFrameList.size();
	for ( i=0; i<UniFrameCount; i++ )
	{
		ImageW    = m_ModelUniFrameList[i].ImageW;
		ImageH    = m_ModelUniFrameList[i].ImageH;
		ImageStep = m_ModelUniFrameList[i].ImageStep;
		BitCount  = m_ModelUniFrameList[i].BitCount;
		FrameUniqueID = m_ModelUniFrameList[i].FrameUniqueID;

		ImagePtr    = m_ModelUniFrameList[i].ImagePtr;
		MaskPtr    = m_ModelUniFrameList[i].MaskPtr;		
		SpacePtr    = m_ModelUniFrameList[i].SpacePtr;
		BufferSize = ImageAPI.CalcBufferSize(ImageStep, ImageH);

		if ( true == bClone )
		{
			ImagePtrNew = NULL;
			MaskPtrNew = NULL;
			SpacePtrNew = NULL;

			if ( NULL != ImagePtr ) 
			{
				::sprintf(varName, "%s#%d", "ImagePtr", i+1);
				if ( JetMemory.alloc_func(BufferSize, ImagePtrNew, fnName, varName) == false ) 
				{	
					IsOK=false;
					JetMemory.free_func(ImagePtrNew);
					JetMemory.free_func(MaskPtrNew);
					JetMemory.free_func(SpacePtrNew);
					break;
				}
				::memcpy(ImagePtrNew, ImagePtr, sizeof(IMAGE_DATA)*BufferSize);			
			}

			if ( NULL != MaskPtr ) 
			{	
				::sprintf(varName, "%s#%d", "MaskPtr", i+1);
				if ( JetMemory.alloc_func(BufferSize, MaskPtrNew, fnName, varName) == false ) 
				{
					IsOK=false;
					JetMemory.free_func(ImagePtrNew);
					JetMemory.free_func(MaskPtrNew);
					JetMemory.free_func(SpacePtrNew);
					break;
				}
				::memcpy(MaskPtrNew, MaskPtr, sizeof(MASK_DATA)*BufferSize);
			}

			if ( NULL != SpacePtr ) 
			{	
				::sprintf(varName, "%s#%d", "SpacePtr", i+1);
				if ( JetMemory.alloc_func(BufferSize, SpacePtrNew, fnName, varName) == false ) 
				{
					IsOK=false;
					JetMemory.free_func(ImagePtrNew);
					JetMemory.free_func(MaskPtrNew);
					JetMemory.free_func(SpacePtrNew);
					break;
				}
				::memcpy(SpacePtrNew, SpacePtr, sizeof(SPACE_DATA)*BufferSize);
			}
		}
		else
		{
			ImagePtrNew = ImagePtr;
			MaskPtrNew = MaskPtr;
			SpacePtrNew = SpacePtr;
		}		
		
		UniFrame.ImageW = ImageW;
		UniFrame.ImageH = ImageH;
		UniFrame.ImageStep = ImageStep;
		UniFrame.BitCount = BitCount;
		UniFrame.FrameUniqueID = FrameUniqueID;

		UniFrame.ImagePtr = ImagePtrNew;
		UniFrame.MaskPtr = MaskPtrNew;
		UniFrame.SpacePtr = SpacePtrNew;
		UniFrameList.push_back(UniFrame);
	}

	if ( false == IsOK )
	{
		if ( true == bClone )
		{	JetAPI::ClearUniFrameList(UniFrameList);	}
		else
		{	UniFrameList.clear(); }
	}
	return IsOK;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CreateModelUniFrameList(CAOIModel *ModelPtr, std::vector<TUNI_FRAME> &ModelUniFrameList, int nAlign, bool bNoFilter)//將Frame的影像列表轉成Model的影像列表	
{
	if ( NULL == ModelPtr ) { return false; }
	size_t   i=0;
	TPOINT2D StageCp;
	TPOINT2D ImageRes;
	CAMERA_ID CameraID = PRIMARY_CAMERA_ID;
	TUNI_FRAME UniFrameList[FRAME_MAX_COUNT];		
	TREGION4D  Region = GetFieldUniFrameStageRegion();
	const size_t UniFrameCount = m_FieldUniFrameList.size();
	const size_t MinUniFrameCount=MIN(UniFrameCount, FRAME_MAX_COUNT);
	for ( i=0; i<MinUniFrameCount; i++ )
	{	UniFrameList[i] = m_FieldUniFrameList[i];	}
	StageCp.x = Region.GetCpX();
	StageCp.y = Region.GetCpY();	
	ImageRes.x = GetCameraResolutionX(CameraID);
	ImageRes.y = GetCameraResolutionY(CameraID);
	if ( CreateModelUniFrameList(UniFrameList, StageCp, ImageRes, ModelPtr, ModelUniFrameList, nAlign, bNoFilter) == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CreateModelUniFrameList(TUNI_FRAME UniFrameList[], const TPOINT2D &StageCP, const TPOINT2D &ImageRes, CAOIModel *ModelPtr, std::vector<TUNI_FRAME> &ModelUniFrameList, int nAlign, bool bNoFilter)//將Frame的影像列表轉成Model的影像列表
{
	if ( NULL == ModelPtr ) { return false; }	
	CAOIProject *ProjectPtr = GetActiveTaskProject();
	if ( CheckProjectPtr(ProjectPtr) == false )
	{	return false; }	

	CString                 str;
	bool                    Exception=false;
	size_t                  i=0, j=0;
	size_t                  UniFrameCount=0;
	IMAGE_SIZE              ImageW=0;
	IMAGE_SIZE              ImageH=0;
	IMAGE_SIZE              ImageStep=0;
	IMAGE_SIZE              BitCount=0;
	IMAGE_PTR               ImagePtr=0;
	MASK_PTR                MaskPtr=0;
	SPACE_PTR               SpacePtr=0;
	unsigned int            FrameUniqueID = 0;

	TPOINT2D                FovCp;
	TREGION4D               CadRgn;
	TREGION4D               ImageRgn;
	TREGION4D               StageRgn;
	RECT                    RoiRect={0};
	IMAGE_SIZE              RoiW=0;
	IMAGE_SIZE              RoiH=0;
	IMAGE_SIZE              RoiStep=0;
	IMAGE_SIZE              RoiBitCount=0;
	IMAGE_PTR               RoiImagePtr=0;
	MASK_PTR                RoiMaskPtr=0;	
	SPACE_PTR               RoiSpacePtr=0;
	IMAGE_PTR               RoiGuidedImagePtr = 0;
	TUNI_FRAME              UniFrame;
	TUNI_FRAME             *UniFramePtr=NULL;
	CAOIComponent          *ComponentPtr=NULL;
	TNoiseFilterParam       FilterParam;
	TNoiseFilterParam       FilterParam2;
	BOOL                    bSave = FALSE;	
	const bool   bOpenMP = true;
	const double ImageScaleX=1.0/ImageRes.x;
	const double ImageScaleY=1.0/ImageRes.y;
	const double SpaceRatio = GetSpaceToGrayRatio();
	const double ComponentAngle = ModelPtr->GetModelAttachedAngle();	
	const bool   IsExceptionAngle = JetAPI::CheckIsExceptionAngle(ComponentAngle);
	
	double          fnTime=0;
	LARGE_INTEGER   fnEnd;
	LARGE_INTEGER   fnStart;

	ComponentPtr = ModelPtr->GetModelComponentPtr();
	if ( NULL != ComponentPtr )
	{	FilterParam2 = ComponentPtr->GetComponentSpaceNoiseFilterParam();	}

	FovCp.x = StageCP.x;
	FovCp.y = StageCP.y;
	//CalcModelTotalRegionAll
	ModelPtr->GetModelTotalRegionStage(StageRgn);
	FilterParam=ModelPtr->GetModelSpaceNoiseFilterParam();	
	ModelPtr->SetModelImageScale(TPOINT2D(ImageScaleX, ImageScaleY));
	if ( true == bNoFilter )
	{
		TurnOffNoiseFilterParam(FilterParam);
		TurnOffNoiseFilterParam(FilterParam2);		
	}

	IMAGE_SIZE     RoiMask2DW=0;
	IMAGE_SIZE     RoiMask2DH=0;
	IMAGE_SIZE     RoiMask2DStep=0;
	IMAGE_SIZE     RoiMask2DBitCount=8;
	MASK_PTR       RoiMask2DPtr=NULL;	
	const double   PanelBasePlane = ModelPtr->GetModelPanelBasePlane();
	const bool SpecMaskEnable_Base = ModelPtr->GetModelMaskEnable_Base();	
	const unsigned int SpecMaskFrameIndex_Base = ModelPtr->GetModelMaskFrameIndex_Base();		
	const int SpecMaskColorLink_Base = ModelPtr->GetModelMaskColorGroupLinkIndex();	

	Exception=false;
	FilterParam.BasePlaneParam.PanelBasePlane=PanelBasePlane;//更新整板基準面參數
	FilterParam.BasePlaneParam.RotatedAngle = 0;
	FilterParam.BasePlaneParam.RotatedSizeW = 0;
	FilterParam.BasePlaneParam.RotatedSizeH = 0;
	if ( NULL != ComponentPtr )
	{
		double    RotatedW=0;
		double    RotatedH=0;
		TREGION4D RotatedRgn;
		TPOINT2D  RotatedCornerPts[4];
		ModelPtr->GetModelTotalCornerPts(RotatedCornerPts);
		JetAPI::RotateCornerPos(-ComponentAngle, RotatedCornerPts);
		JetAPI::CornerPtToRegion(RotatedCornerPts, RotatedRgn);
		RotatedW = RotatedRgn.GetSizeX();
		RotatedH = RotatedRgn.GetSizeY();
		RotatedW = ComponentPtr->GetRgnRoiSizeW();
		RotatedH = ComponentPtr->GetRgnRoiSizeH();
		FilterParam.BasePlaneParam.RotatedAngle = ComponentAngle;		
		FilterParam.BasePlaneParam.RotatedSizeW = (int)(RotatedW/ImageRes.x);
		FilterParam.BasePlaneParam.RotatedSizeH = (int)(RotatedH/ImageRes.y);
	}
	for ( i=0; i<FRAME_MAX_COUNT; i++ )
	{
		UniFramePtr = &(UniFrameList[i]);
		if ( NULL == UniFramePtr ) { continue; }
		if ( NULL == UniFramePtr->ImagePtr ) { continue; }

		ImageW = UniFramePtr->ImageW;
		ImageH = UniFramePtr->ImageH;
		ImageStep = UniFramePtr->ImageStep;
		BitCount = UniFramePtr->BitCount;
		FrameUniqueID = UniFramePtr->FrameUniqueID;
		ImagePtr = UniFramePtr->ImagePtr;
		MaskPtr = UniFramePtr->MaskPtr;
		SpacePtr = UniFramePtr->SpacePtr;		
		if ( MapStageRegionToCamera(ImageW, ImageH, ImageRes, StageRgn, FovCp, ImageRgn) == false )
		{
			Exception = true;
			break;
		}
		JetAPI::Region4DToRect(ImageRgn, RoiRect, false);		
		JetAPI::AdjustRectByAlignW(RoiRect, nAlign);//調成4倍寬
		if ( RoiRect.left<0 || RoiRect.right<0 || RoiRect.top<0 || RoiRect.bottom<0 || 
			 RoiRect.left>=ImageW || RoiRect.right>=ImageW || RoiRect.top>=ImageH || RoiRect.bottom>=ImageH ) 
		{
			Exception = true;
			break;
		}
		RoiW = RoiRect.right-RoiRect.left;
		RoiH = RoiRect.bottom-RoiRect.top;
		RoiBitCount = UniFramePtr->BitCount;
		RoiStep = JetAPI::GetBMPImagePixelsPerLine(RoiW, RoiBitCount, 4);
		if ( 0 == i )
		{	
			CAOIRgn *Rgn=NULL;
			TPOINT2D CadOffset;
			TPOINT2D ImageOffset;
			TSIZE2D  ImageSizeUm;
			TRECT4D  ImageStageRect;
			MapImageSizeToReal(ImageRes, RoiRect, ImageSizeUm);
			MapCameraRectToStage(ImageW, ImageH, ImageRes, RoiRect, FovCp, ImageStageRect);
			StageRgn.SetSize(ImageSizeUm.cx, ImageSizeUm.cy);
			ImageOffset.x = ImageStageRect.GetCpX()-StageRgn.GetCpX();
			ImageOffset.y = ImageStageRect.GetCpY()-StageRgn.GetCpY();
			MapStageOffsetPtToCad(ImageOffset, CadOffset);

			ModelPtr->SetModelImageSize_um(ImageSizeUm);
			ModelPtr->SetModelImageCadOffset_um(CadOffset);
			Rgn = ModelPtr->GetModelAttachedPtr();
			if ( NULL != Rgn )
			{	
				Rgn->SetRgnFrameImageSize_um(ImageSizeUm); 
				Rgn->SetRgnFrameImageCadOffset_um(CadOffset);
			}
		}
		else
		{	i = i; }
		if ( NULL != ImagePtr )
		{	
			if ( ImageAPI.ExtractRoiImage(ImageW, ImageH, ImageStep, BitCount, ImagePtr, RoiRect, RoiStep, RoiImagePtr, false)==false )
			{
				Exception = true;
				break;
			}
		}
		if ( NULL != MaskPtr )
		{	
			if ( ImageAPI.ExtractRoiImage(ImageW, ImageH, ImageStep, BitCount, MaskPtr, RoiRect, RoiStep, RoiMaskPtr, false)==false )
			{
				Exception = true;
				break;
			}
		}
		if ( NULL != SpacePtr )
		{	
			if ( ImageAPI.ExtractSpaceGrayRoiImage(ImageW, ImageH, ImageStep, SpacePtr, RoiRect, RoiStep, RoiSpacePtr, false)==false )
			{
				Exception = true;
				break;
			}
		}

		if ( true==SpecMaskEnable_Base && i==SpecMaskFrameIndex_Base && 24==RoiBitCount )
		{
			RECT      MaskRect={0};
			const int SpecMaskColorLink_Base = ModelPtr->GetModelMaskColorGroupLinkIndex();	
			CColorGroup *ColorGroupPtr = ProjectPtr->GetProjectColorGroupPtr(SpecMaskColorLink_Base, true);			
			MaskRect.left = 0;
			MaskRect.top = 0;
			MaskRect.right = RoiW;
			MaskRect.bottom = RoiH;
			if ( NULL != ColorGroupPtr )
			{
				RoiMask2DBitCount = 8;				
				RoiMask2DStep = JetAPI::GetBMPImagePixelsPerLine(RoiW, RoiMask2DBitCount, 4);				
				JetMemory.free_func(RoiMask2DPtr);
				JetAPI::SetFuncTimeStart(fnStart);
				if ( ImageAPI.ColorImageColorFilter(RoiW, RoiH, RoiStep, RoiImagePtr, *ColorGroupPtr, MaskRect, RoiMask2DStep, RoiMask2DPtr, false, bOpenMP) == true )
				{
					RoiMask2DW = RoiW;
					RoiMask2DH = RoiH;
				}
				JetAPI::SetFuncTimeStart(fnEnd);
				fnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);//計算函式經過時間
				str.Format(_T("CAOIDataCollect::CreateModelUniFrameList#ColorImageColorFilter Time=%.3f ms"), fnTime);
				SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
			}			
		}

		if (GUIDEIMAGE_UNIQUE_ID==FrameUniqueID && NULL == RoiGuidedImagePtr)//20191126, Joe
		{
			if (ImageAPI.GetGuidedImage(RoiW, RoiH, RoiStep, RoiBitCount, RoiImagePtr, RoiGuidedImagePtr) == false)
			{
				JetMemory.free_func(RoiGuidedImagePtr);
				Exception = true;
				break;
			}
		}

		if ( NULL!=SpacePtr && NULL!=RoiMaskPtr )
		{
			MASK_PTR  tmpMaskPtr=NULL;
			SPACE_PTR tmpSpacePtr=NULL;
			if ( RoiW!=RoiMask2DW || RoiH!=RoiMask2DH || RoiStep!=RoiMask2DStep )
			{	JetMemory.free_func(RoiMask2DPtr); }

		#ifdef _DEBUG
			if ( bSave == TRUE )
			{
				if ( NULL != RoiMask2DPtr )
				{
					str.Format(_T("%s\\ModelMask_Base.PNG"), GetAOITempDirectory());
					ImageAPI.SavePNGImage(str, RoiMask2DW, RoiMask2DH, RoiMask2DStep, RoiMask2DBitCount, RoiMask2DPtr, true);
				}
			}
		#endif//_DEBUG		
			const int nOpenMPCnt = CheckOpenMPCount_SpaceFilter(bOpenMP, RoiW*RoiH);			
			ModelPtr->CalcModelBodyOutsideParam(RoiW, RoiH, FilterParam.BasePlaneParam);
			if ( ImageAPI.BuildSpaceData(RoiW, RoiH, RoiStep, RoiSpacePtr, RoiMaskPtr, RoiMask2DPtr, nOpenMPCnt, FilterParam, tmpSpacePtr, tmpMaskPtr, RoiGuidedImagePtr) == false )
			{
				Exception = true;
				break;
			}		
			JetMemory.free_func(RoiMaskPtr);
			JetMemory.free_func(RoiSpacePtr);
			JetMemory.free_func(RoiMask2DPtr);
			RoiMaskPtr = tmpMaskPtr;
			RoiSpacePtr = tmpSpacePtr;
			ModelPtr->SetModelSpaceLeveingParam(FilterParam.BasePlaneParam.NormalX, FilterParam.BasePlaneParam.NormalY, FilterParam.BasePlaneParam.NormalZ);
			SetSpaceBaseHeight(FilterParam.BasePlaneParam.NormalZ);

			if ( ModelPtr->CheckModelUseDataModel() == true )
			{
				bool  bBuild=true;				
				const int   DataModelLevelID=ModelPtr->GetModelDataModelLevelID();
				const bool bBasePlaneValid = ModelPtr->CheckModelPanelBasePlaneParamValid();
				if ( 3 != DataModelLevelID )//使用絕對高度時, 先行判斷基準面是否計算過
				{	bBuild = bBasePlaneValid;	}
				if ( true == bBuild )
				{
					TDataModelParam  DataModelParam;
					if ( ModelPtr->BuildModelDataModelParam(RoiW, RoiH, DataModelParam) == true )
					{	ImageAPI.BuildDataModel(RoiW, RoiH, RoiStep, RoiSpacePtr, RoiMaskPtr, DataModelParam); }
				}
			}

			/*
			//高度轉成灰階
			RECT RoiRect2={0,0,0,0};			
			RoiRect2.left = 0;
			RoiRect2.top = 0;
			RoiRect2.right = (int)(RoiW);
			RoiRect2.bottom = (int)(RoiH);
			JetMemory.free_func(RoiImagePtr);
			if ( ImageAPI.SpaceGrayImageConvertToGray(RoiW, RoiH, RoiStep, RoiSpacePtr, RoiMaskPtr, RoiRect2, RoiStep, RoiImagePtr, SpaceRatio, false) == false )
			{
				Exception = true;
				break;
			}*/
		}
		
		UniFrame.ImageW = RoiW;
		UniFrame.ImageH = RoiH;
		UniFrame.ImageStep = RoiStep;
		UniFrame.BitCount = RoiBitCount;
		UniFrame.ImagePtr = RoiImagePtr;
		UniFrame.MaskPtr = RoiMaskPtr;
		UniFrame.SpacePtr = RoiSpacePtr;
		UniFrame.FrameUniqueID = FrameUniqueID;
		ModelUniFrameList.push_back(UniFrame);
		UniFrame = TUNI_FRAME();
		RoiImagePtr = NULL;
		RoiMaskPtr = NULL;
		RoiSpacePtr = NULL;
	}
	JetMemory.free_func(RoiMask2DPtr);//如果沒有3D資料時
	JetMemory.free_func(RoiGuidedImagePtr);

	if ( true == Exception )
	{	
		JetMemory.free_func(RoiImagePtr);
		JetMemory.free_func(RoiMaskPtr);
		JetMemory.free_func(RoiSpacePtr);

		UniFrameCount = ModelUniFrameList.size();
		for ( j=0; j<UniFrameCount; j++ )
		{
			UniFrame = ModelUniFrameList[j];
			JetMemory.free_func(UniFrame.ImagePtr);
			JetMemory.free_func(UniFrame.MaskPtr);
			JetMemory.free_func(UniFrame.SpacePtr);
		}
		ModelUniFrameList.clear();
		return false;
	}

#ifdef _DEBUG
	bSave = TRUE;
	if ( bSave == TRUE )
	{
		UniFrameCount = ModelUniFrameList.size();
		for ( j=0; j<UniFrameCount; j++ )
		{
			UniFrame = ModelUniFrameList[j];

			RoiW = UniFrame.ImageW;
			RoiH = UniFrame.ImageH;
			RoiStep = UniFrame.ImageStep;
			RoiBitCount = UniFrame.BitCount;
			RoiImagePtr = UniFrame.ImagePtr;
			RoiMaskPtr = UniFrame.MaskPtr;
			RoiSpacePtr = UniFrame.SpacePtr;

			if ( NULL != RoiImagePtr )
			{
				str.Format(_T("%s\\ModelImage%d.PNG"), GetAOITempDirectory(), j+1);
				ImageAPI.SaveImage(str, RoiW, RoiH, RoiStep, RoiBitCount, RoiImagePtr, true);
			}
			if ( NULL != RoiMaskPtr )
			{
				str.Format(_T("%s\\ModelMask%d.PNG"), GetAOITempDirectory(), j+1);
				ImageAPI.SaveImage(str, RoiW, RoiH, RoiStep, RoiBitCount, RoiMaskPtr, true);

				if ( NULL != RoiSpacePtr )
				{
					RECT RoiRect={0, 0, RoiW, RoiH};
					IMAGE_SIZE     RoiBitCount = 8;
					unsigned char *pGray=NULL;
					const IMAGE_SIZE RoiStep = JetAPI::GetBMPImagePixelsPerLine(RoiW, RoiBitCount, 4);
					const double SpaceRatio = GetSpaceToGrayRatio();
					ImageAPI.SpaceGrayImageConvertToGray(RoiW, RoiH, RoiStep, RoiSpacePtr, RoiMaskPtr, RoiRect, RoiStep, pGray, SpaceRatio, false);
					str.Format(_T("%s\\ModelSpace%d.PNG"), GetAOITempDirectory(), j+1);
					ImageAPI.SaveImage(str, RoiW, RoiH, RoiStep, RoiBitCount, pGray, true);
					JetMemory.free_func(pGray);
				}
			}
		}		
	}
#endif//_DEBUG	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::BuildModelUIObjList(CAOIModel *ModelPtr, bool ActiveOnly, std::vector<TActiveObj> &ObjList)//建立模組介面物件列表
{
	ObjList.clear();
	bool CheckAddObj = false;
//	if ( GetIsPressVRKey(m_MultiSelKey) == false )
//	{	CheckAddObj = false;}
//	else
//	{	CheckAddObj = true;	}
	ObjList.clear();
	if ( NULL == ModelPtr ) { return false; }

	CString      str;	
	size_t       i=0, j=0, k=0, s=0;
	size_t       LandCount = 0;	
	size_t       WndCount  = 0;
	size_t       BoxWndCount = 0;
	size_t       WndRoiCount = 0;
	size_t       MaskWndCount = 0;
	CAOIBox     *BoxPtr   = NULL;
	CAOIWnd     *WndPtr   = NULL;
	CAOILand    *LandPtr  = NULL;			
	CAOIWndRoi  *WndRoiPtr  = NULL;
	CAOIWndMask *MaskWndPtr  = NULL;
	TActiveObj   ActiveObj;
	const double ComponentAngle = ModelPtr->GetModelAttachedAngle();
	const bool   IsExceptionAngle = JetAPI::CheckIsExceptionAngle(ComponentAngle);

	bool ModelActiveOnly = true;	
	bool AddModelRect    = true;
	bool bBoxWndSelected = false;
	bool bWndBoxWndSelected = false;
	bool bLandBoxWndSelected = false;	
	bool bWndRoiBoxSelected = false;
	bool bMaskBoxSelected = false;

	ActiveObj.ModelPtr = ModelPtr;	
	ModelActiveOnly = TRUE;
	
	ActiveObj = TActiveObj();
	ActiveObj.ComponentAngle = ComponentAngle;
	ActiveObj.IsExceptionAngle = IsExceptionAngle;	
	ActiveObj.WndPtr     = NULL;
	ActiveObj.LandPtr    = NULL;
	ActiveObj.BoxPtr     = NULL;
	ActiveObj.WndRoiPtr  = NULL;
	ActiveObj.WndMaskPtr = NULL;
	ActiveObj.SetEditabled(true);
	ActiveObj.PassObj    = false;	

	//if ( false == ActiveOnly ) 
	{		
		WndCount = ModelPtr->GetModelWndCount();			
		for ( j=0; j<WndCount; j++ )
		{
			WndPtr = ModelPtr->GetModelWndPtr(j, false);				
			if ( NULL == WndPtr ) { continue; }
			
			BoxPtr = WndPtr->GetWndBoxPtr();			
			if ( NULL == BoxPtr ) { continue; }
			//if ( BoxPtr->GetBoxEnabled() == false ) { continue; }
			if ( BoxPtr->GetBoxVisibled() == false ) 
			{ 
				BoxPtr->SetBoxSelected(false);
				continue; 
			}			
			if ( true == ActiveOnly )
			{
				if ( BoxPtr->GetBoxSelected() == false ) { continue; }
			}
			//子框
			bWndRoiBoxSelected = false;
			WndRoiCount = WndPtr->GetWndRoiWndCount();
			for ( k=0; k<WndRoiCount; k++ )
			{
				WndRoiPtr = WndPtr->GetWndRoiWndPtr(k, false);
				if ( NULL == WndRoiPtr ) { continue; }
				BoxPtr = WndRoiPtr->GetWndRoiBoxPtr();
				if ( NULL == BoxPtr ) { continue; }
				if ( BoxPtr->GetBoxSelected() == true ) 
				{	bWndRoiBoxSelected = true; }

				ActiveObj.ModelPtr   = ModelPtr;
				ActiveObj.WndPtr     = WndPtr;					
				ActiveObj.LandPtr    = NULL;
				ActiveObj.WndRoiPtr  = WndRoiPtr;
				ActiveObj.WndMaskPtr = NULL;
				ActiveObj.BoxPtr     = BoxPtr;				
				ActiveObj.SetEditabled(BoxPtr->GetBoxEditabled());
				ActiveObj.SetSelected(BoxPtr->GetBoxSelected());
				ActiveObj.SetFocused(BoxPtr->GetBoxActived());
				ObjList.push_back(ActiveObj);
			}
			//遮罩框
			bMaskBoxSelected = false;
			MaskWndCount = WndPtr->GetWndMaskWndCount();
			for ( k=0; k<MaskWndCount; k++ )
			{
				MaskWndPtr = WndPtr->GetWndMaskWndPtr(k, false);
				if ( NULL == MaskWndPtr ) { continue; }
				BoxPtr = MaskWndPtr->GetWndMaskBoxPtr();
				if ( NULL == BoxPtr ) { continue; }
				if ( BoxPtr->GetBoxSelected() == true ) 
				{	bMaskBoxSelected = true; }

				ActiveObj.ModelPtr   = ModelPtr;
				ActiveObj.WndPtr     = WndPtr;					
				ActiveObj.LandPtr    = NULL;
				ActiveObj.WndRoiPtr  = NULL;
				ActiveObj.WndMaskPtr = MaskWndPtr;
				ActiveObj.BoxPtr     = BoxPtr;				
				ActiveObj.SetEditabled(BoxPtr->GetBoxEditabled());
				ActiveObj.SetSelected(BoxPtr->GetBoxSelected());
				ActiveObj.SetFocused(BoxPtr->GetBoxActived());
				ObjList.push_back(ActiveObj);
			}			

			BoxPtr = WndPtr->GetWndBoxPtr();	
			ModelActiveOnly = false;
			BoxPtr = WndPtr->GetWndBoxPtr();	
			ActiveObj.ModelPtr   = ModelPtr;
			ActiveObj.WndPtr     = WndPtr;					
			ActiveObj.LandPtr    = NULL;
			ActiveObj.WndRoiPtr  = NULL;
			ActiveObj.WndMaskPtr = NULL;
			ActiveObj.BoxPtr     = BoxPtr;			
			ActiveObj.SetEditabled(BoxPtr->GetBoxEditabled());
			ActiveObj.SetSelected(BoxPtr->GetBoxSelected());
			ActiveObj.SetFocused(BoxPtr->GetBoxActived());
			if ( true==bWndRoiBoxSelected || true==bMaskBoxSelected)
			{	
				ActiveObj.SetSelected(false);
				ActiveObj.SetFocused(false);
			}
			ObjList.push_back(ActiveObj);
		}
	}	

	//if ( false == ActiveOnly ) 
	{
		LandCount = ModelPtr->GetModelLandCount();
		for ( j=0; j<LandCount; j++ )
		{
			LandPtr = ModelPtr->GetModelLandPtr(j, false);			
			if ( NULL == LandPtr ) { continue; }
			for ( k=0; k<5; k++ )
			{				
				switch ( k )
				{				
				case 0:	BoxPtr = LandPtr->GetLandLeadBoxPtr();	break;
				case 1:	BoxPtr = LandPtr->GetLandPadBoxPtr();	break;
				case 2:	BoxPtr = LandPtr->GetLandLeadShoulderBoxPtr();	break;
				case 3:	BoxPtr = LandPtr->GetLandLeadTipBoxPtr();	break;
				case 4:	BoxPtr = LandPtr->GetLandBodyEdgeBoxPtr();	break;
				default:	BoxPtr = NULL;	break;
				}				
				if ( BoxPtr == NULL ) { continue; }
				if ( NULL == BoxPtr ) { continue; }
				if ( BoxPtr->GetBoxEnabled() == false ) { continue; }
				if ( BoxPtr->GetBoxVisibled() == false ) { continue; }				
				if ( true == ActiveOnly )
				{
					if ( BoxPtr->GetBoxSelected() == false ) { continue; }
				}
				ModelActiveOnly = false;
				ActiveObj.ModelPtr   = ModelPtr;
				ActiveObj.WndPtr     = NULL;
				ActiveObj.LandPtr    = LandPtr;
				ActiveObj.WndRoiPtr  = NULL;
				ActiveObj.WndMaskPtr = NULL;
				ActiveObj.BoxPtr     = BoxPtr;				
				ActiveObj.SetEditabled(BoxPtr->GetBoxEditabled());
				ActiveObj.SetSelected(BoxPtr->GetBoxSelected());
				ActiveObj.SetFocused(BoxPtr->GetBoxActived());
				ObjList.push_back(ActiveObj);
			}
		}
	}
	
	AddModelRect    = true;
	if ( true == ActiveOnly )
	{
		if ( (ModelPtr->GetModelBodyBox().GetBoxSelected()==false) || (false==ModelActiveOnly) )
		{	AddModelRect = false;	}
	}		

	if ( true == AddModelRect )
	{
		BoxPtr = ModelPtr->GetModelBodyBoxPtr();
		ActiveObj.ModelPtr   = ModelPtr;		
		ActiveObj.LandPtr    = NULL;
		ActiveObj.BoxPtr     = BoxPtr;		
		ActiveObj.WndPtr     = NULL;
		ActiveObj.WndRoiPtr  = NULL;
		ActiveObj.WndMaskPtr = NULL;
		ActiveObj.ComponentAngle = ComponentAngle;		
		ActiveObj.SetEditabled(BoxPtr->GetBoxEditabled());
		ActiveObj.SetSelected(BoxPtr->GetBoxSelected());
		ActiveObj.SetFocused(BoxPtr->GetBoxActived());
		ObjList.push_back(ActiveObj);
	}	
	return true;
}
