//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SetFieldUniFrameList(const TREGION4D &Region, const std::vector<TUNI_FRAME> &UniFrameList)//設定模組的影像
{
	ReleaseModelUniFrameList();
	ReleaseFieldUniFrameList();
	m_FieldUniFrameRgnStage = Region;
	m_FieldUniFrameList = UniFrameList;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SetFieldUniFrameList(const TREGION4D &Region, const TUNI_FRAME *UniFrameList, size_t Count)//設定模組的影像
{
	if ( NULL == UniFrameList ) { return false; }

	size_t i=0;
	TUNI_FRAME UniFrame;
	ReleaseModelUniFrameList();
	ReleaseFieldUniFrameList();
	m_FieldUniFrameRgnStage = Region;

	for ( i=0; i<Count; i++ )
	{
		UniFrame = UniFrameList[i];
		if ( NULL==UniFrame.MaskPtr && 
			 NULL==UniFrame.ImagePtr && 
			 NULL==UniFrame.PhasePtr && 
			 NULL==UniFrame.SpacePtr )
		{	continue; }
		m_FieldUniFrameList.push_back(UniFrame);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CopyFieldUniFrameList(std::vector<TUNI_FRAME> &UniFrameList, bool bClone) const//複製模組的影像	
{
	const char fnName[] = "CAOIDataCollect::CopyFieldUniFrameList";
	
	bool   IsOK=true;
	size_t i=0;
	size_t BufferSize=0;
	size_t UniFrameCount;
	char   varName[64]="";
	TUNI_FRAME UniFrame;
	MASK_PTR   MaskPtr=NULL;
	MASK_PTR   MaskPtrNew=NULL;
	SPACE_PTR  SpacePtr=NULL;
	SPACE_PTR  SpacePtrNew=NULL;
	IMAGE_PTR  ImagePtr=NULL;
	IMAGE_PTR  ImagePtrNew=NULL;
	IMAGE_SIZE ImageW=0, ImageH=0, ImageStep=0, BitCount=0;
	IMAGE_SIZE ImageWOrg=0, ImageHOrg=0, ImageStepOrg=0, BitCountOrg=0;		
	unsigned int FrameUniqueID = 0;

	IsOK=true;
	JetAPI::ClearUniFrameList(UniFrameList);	
	UniFrameCount = m_FieldUniFrameList.size();
	for ( i=0; i<UniFrameCount; i++ )
	{
		ImageW    = m_FieldUniFrameList[i].ImageW;
		ImageH    = m_FieldUniFrameList[i].ImageH;
		ImageStep = m_FieldUniFrameList[i].ImageStep;
		BitCount  = m_FieldUniFrameList[i].BitCount;
		FrameUniqueID = m_FieldUniFrameList[i].FrameUniqueID;

		ImagePtr    = m_FieldUniFrameList[i].ImagePtr;
		MaskPtr     = m_FieldUniFrameList[i].MaskPtr;		
		SpacePtr    = m_FieldUniFrameList[i].SpacePtr;
		BufferSize = ImageAPI.CalcBufferSize(ImageStep, ImageH);

		if ( true == bClone )
		{
			ImagePtrNew = NULL;
			MaskPtrNew = NULL;
			SpacePtrNew = NULL;

			if ( NULL != ImagePtr ) 
			{
				::sprintf(varName, "%s#%d", "ImagePtr", i+1);
				if ( JetMemory.alloc_func(BufferSize, ImagePtrNew, fnName, varName) == false ) 
				{	
					IsOK=false;
					JetMemory.free_func(ImagePtrNew);
					JetMemory.free_func(MaskPtrNew);
					JetMemory.free_func(SpacePtrNew);
					break;
				}
				::memcpy(ImagePtrNew, ImagePtr, sizeof(IMAGE_DATA)*BufferSize);			
			}

			if ( NULL != MaskPtr ) 
			{	
				::sprintf(varName, "%s#%d", "MaskPtr", i+1);
				if ( JetMemory.alloc_func(BufferSize, MaskPtrNew, fnName, varName) == false ) 
				{
					IsOK=false;
					JetMemory.free_func(ImagePtrNew);
					JetMemory.free_func(MaskPtrNew);
					JetMemory.free_func(SpacePtrNew);
					break;
				}
				::memcpy(MaskPtrNew, MaskPtr, sizeof(MASK_DATA)*BufferSize);
			}

			if ( NULL != SpacePtr ) 
			{	
				::sprintf(varName, "%s#%d", "SpacePtr", i+1);
				if ( JetMemory.alloc_func(BufferSize, SpacePtrNew, fnName, varName) == false ) 
				{
					IsOK=false;
					JetMemory.free_func(ImagePtrNew);
					JetMemory.free_func(MaskPtrNew);
					JetMemory.free_func(SpacePtrNew);
					break;
				}
				::memcpy(SpacePtrNew, SpacePtr, sizeof(SPACE_DATA)*BufferSize);
			}
		}
		else
		{
			ImagePtrNew = ImagePtr;
			MaskPtrNew = MaskPtr;
			SpacePtrNew = SpacePtr;
		}		
		
		UniFrame.ImageW = ImageW;
		UniFrame.ImageH = ImageH;
		UniFrame.ImageStep = ImageStep;
		UniFrame.BitCount = BitCount;
		UniFrame.FrameUniqueID = FrameUniqueID;

		UniFrame.ImagePtr = ImagePtrNew;
		UniFrame.MaskPtr = MaskPtrNew;
		UniFrame.SpacePtr = SpacePtrNew;
		UniFrameList.push_back(UniFrame);
	}

	if ( false == IsOK )
	{
		if ( true == bClone )
		{	JetAPI::ClearUniFrameList(UniFrameList);	}
		else
		{	UniFrameList.clear(); }
	}
	return IsOK;	
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ModifyFieldSpaceImage(std::vector<TUNI_FRAME> &UniFrameList, double nX, double nY, double nZ, double OffsetZ, double OverHigh, double OverLow)//修正灰階影像
{
	size_t i=0;		
	MASK_PTR   MaskPtr=NULL;
	SPACE_PTR  SpacePtr=NULL;
	IMAGE_PTR  ImagePtr=NULL;
	IMAGE_SIZE ImageW=0, ImageH=0, ImageStep=0, BitCount=0;
	const size_t UniFrameCount = UniFrameList.size();
	for ( i=0; i<UniFrameCount; i++ )
	{
		if ( NULL == UniFrameList[i].MaskPtr ) { continue; }
		if ( NULL == UniFrameList[i].SpacePtr ) { continue; }

		ImageW    = UniFrameList[i].ImageW;
		ImageH    = UniFrameList[i].ImageH;
		ImageStep = UniFrameList[i].ImageStep;
		BitCount  = UniFrameList[i].BitCount;		

		ImagePtr    = UniFrameList[i].ImagePtr;
		MaskPtr     = UniFrameList[i].MaskPtr;		
		SpacePtr    = UniFrameList[i].SpacePtr;				
		ImageAPI.ExecSpaceImageLeveling3(ImageW, ImageH, ImageStep, SpacePtr, MaskPtr, nX, nY, nZ, OffsetZ, OverHigh, OverLow, SpacePtr);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CreateTempProjectFile(LPCTSTR filename, CString &TempFileName)//建立暫存的專案
{
	bool    IsOK=false;
	CString str;
	CString BaseFolder;
	CString TempFolder;		
	CString FolderSrc;
	CString FolderDst;
	CString ProjectFolderSrc;
	CString ProjectFolderDst;
	const COPY_HUGE_FILES_MODE CopyHugeFilesMode = GetCopyHugeFilesMode();

	BaseFolder = GetAOITempProjectDirectory();
	TempFileName = AOIDataDefine.GetProjectTempFilename(filename);
	JetAPI::ExtractMainFileName(filename, ProjectFolderSrc);
	JetAPI::ExtractMainFileName(TempFileName, ProjectFolderDst);

	if ( JetAPI::CreateFolder(BaseFolder) == false )
	{
		str.Format(_T("Error, Create Folder Fault(%s)"), BaseFolder);
		SetErrorString(str);
		return false;
	}	
	
	if ( JetAPI::CreateFolder(ProjectFolderDst) == false )
	{
		str.Format(_T("Error, Create Folder Fault(%s)"), ProjectFolderDst);
		SetErrorString(str);
		return false;
	}	
	JetAPI::ClearFolder(ProjectFolderDst);	
	
	HCURSOR hCursor = ::AfxGetApp()->LoadStandardCursor(IDC_WAIT);
	HCURSOR hOldCursor = ::SetCursor(hCursor);

	::Sleep(0);	
	::CopyFile(filename, TempFileName, FALSE);
	::Sleep(0);

	//Copy Fiducial Folder
	FolderSrc = AOIDataDefine.GetProjectFdFolderName(ProjectFolderSrc);
	FolderDst = AOIDataDefine.GetProjectFdFolderName(ProjectFolderDst);
	IsOK = JetAPI::CopyFolderAToFolderB(FolderSrc, FolderDst, false, false, _T(""), -1, -1);
	if ( false == IsOK )
	{
		::SetCursor(hOldCursor);
		str.Format(_T("Error, Copy Fiducial Folder Fault \n(%s -> %s)"), FolderSrc, FolderDst);
		SetErrorString(str);
		return false;
	}

	//Copy Library Folder
	const bool bDeleteDst = false;	
	const bool bDeleteSrc = false;	
	FolderSrc = AOIDataDefine.GetProjectLibraryFolderName(ProjectFolderSrc);
	FolderDst = AOIDataDefine.GetProjectLibraryFolderName(ProjectFolderDst);
	IsOK = JetAPI::HugeCopyFolderAToFolderB(CopyHugeFilesMode, FolderSrc, FolderDst, bDeleteSrc, bDeleteDst, _T(""), -1, -1);	
	if ( false == IsOK )
	{
		::SetCursor(hOldCursor);
		str.Format(_T("Error, Copy Library Folder Fault \n(%s -> %s)"), FolderSrc, FolderDst);
		SetErrorString(str);
		return false;
	}

	//Copy Part Library Folder
	FolderSrc = AOIDataDefine.GetProjectPartLibraryFolderName(ProjectFolderSrc);
	FolderDst = AOIDataDefine.GetProjectPartLibraryFolderName(ProjectFolderDst);
	IsOK = JetAPI::CopyFolderAToFolderB(FolderSrc, FolderDst, false, false, _T(""), -1, -1);
	if ( false == IsOK )
	{
		::SetCursor(hOldCursor);
		str.Format(_T("Error, Copy Part Library Folder Fault \n(%s -> %s)"), FolderSrc, FolderDst);
		SetErrorString(str);
		return false;
	}

	//Copy Field Mark Folder
	FolderSrc = AOIDataDefine.GetProjectFieldMarkFolderName(ProjectFolderSrc);
	FolderDst = AOIDataDefine.GetProjectFieldMarkFolderName(ProjectFolderDst);
	IsOK = JetAPI::CopyFolderAToFolderB(FolderSrc, FolderDst, false, false, _T(""), -1, -1);
	if ( false == IsOK )
	{
		::SetCursor(hOldCursor);
		str.Format(_T("Error, Copy Folder Field Mark Folder Fault \n(%s -> %s)"), FolderSrc, FolderDst);
		SetErrorString(str);
		return false;
	}

	//Copy Oper Log Folder
	FolderSrc = AOIDataDefine.GetProjectOperLogFolderName(ProjectFolderSrc);
	FolderDst = AOIDataDefine.GetProjectOperLogFolderName(ProjectFolderDst);
	IsOK = JetAPI::CopyFolderAToFolderB(FolderSrc, FolderDst, false, false, _T(""), -1, -1);
	if ( false == IsOK )
	{
		::SetCursor(hOldCursor);
		str.Format(_T("Error, Copy Folder Oper Log Folder Fault \n(%s -> %s)"), FolderSrc, FolderDst);
		SetErrorString(str);
		return false;
	}

#ifdef OFFLINE_VERSION
	//Copy System Folder
	FolderSrc = AOIDataDefine.GetProjectSystemFolderName(ProjectFolderSrc);
	FolderDst = AOIDataDefine.GetProjectSystemFolderName(ProjectFolderDst);
	JetAPI::CopyFolderAToFolderB(FolderSrc, FolderDst, false, false, _T(""), -1, -1);
#endif//OFFLINE_VERSION

	//Copy Oter Files
	IsOK = JetAPI::CopyFolderAToFolderB(ProjectFolderSrc, ProjectFolderDst, false, false, _T(""), 0, 1);
	if ( false == IsOK )
	{
		::SetCursor(hOldCursor);
		str.Format(_T("Error, Copy Project Files Fault \n(%s -> %s)"), FolderSrc, FolderDst);
		SetErrorString(str);
		return false;
	}
	//JetAPI::CopyFolderAToFolderB(ProjectFolderSrc, ProjectFolderDst, false, false, _T(""), -1, -1);//Dont copy all Folder
	::SetCursor(hOldCursor);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CloseActiveModel(CAOIModel *ModelPtr)//關閉啟用中的模組
{	
	if ( NULL == ModelPtr ) { return true; }
	MODEL_TYPE ModelType=ModelPtr->GetModelType();
	if ( MODEL_TYPE_NULL == ModelType ) { return true; }

	CAOIComponent *ComponentPtr = ModelPtr->GetModelComponentPtr();
	return CloseActiveComponent(ComponentPtr);
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CloseActiveComponent(CAOIComponent *ComponentPtr)//關閉啟用中的的零件
{
	CAOIProject *ProjectPtr = GetActiveTaskProject();
	if ( NULL == ProjectPtr ) { return true; }
	if ( NULL == ComponentPtr ) { return true; }
	
	SetShowModelLandBox(false);	
	if ( ProjectPtr->CloseProjectActiveComponent(ComponentPtr, true) == false )
	{	
		m_ErrorString = ProjectPtr->GetErrorString();
		return false;
	}
	return true;
}
