bool CAOIDataCollect::CheckAutoSwitchToOnlineRemoteCtrlEnable() const//確認自動切換線上遠端控制啟用
{	
	if ( PlcCtrlPtr->GetPLCExecAlarm() == true ) { return false; }
	if ( GetMES_SecsGemEnabled() == false ) { return false; }
	if ( GetMES_CommunicationEnabled() == false ) { return false; }		
	if ( GetAutoSwitchToOnlineRemoteCtrlEnable() == false ) { return false;	}
	
	const TSystemParameter &SysParam=GetSystemParameter();
	if ( 0==SysParam.m_AutoSwitchToOnlineRemoteCtrlTime || MES_EQP_CTRL_STATE_NONE==SysParam.m_AutoSwitchToOnlineRemoteCtrlMode )
	{	return false;	}
	return true;	
}
//---------------------------------------------------------------------------------//
void CAOIDataCollect::SetAutoSwitchToOnlineRemoteCtrlEnable(bool val)//設定自動切換線上遠端控啟用
{
	m_AutoSwitchToOnlineRemoteCtrlEnable = val;
}
//---------------------------------------------------------------------------------//
bool CAOIDataCollect::GetAutoSwitchToOnlineRemoteCtrlEnable() const//取得自動切換線上遠端控制啟用
{
	return m_AutoSwitchToOnlineRemoteCtrlEnable;
}
//---------------------------------------------------------------------------------//
UINT CAOIDataCollect::GetAutoSwitchToOnlineRemoteCtrlCmdID(MES_EQP_CTRL_STATE_MODE Mode) const//取得自動切換線上遠端控制命令編號
{	
	UINT WndCmdID = 0;	
	switch ( Mode )
	{
	default:					
	case MES_EQP_CTRL_STATE_NONE:		WndCmdID = 0;	break; 
	case MES_EQP_CTRL_STATE_OFFLINE:	WndCmdID=ID_MES_SET_CTRL_STATE_OFFLINE;	break;
	case MES_EQP_CTRL_STATE_LOCAL:		WndCmdID=ID_MES_SET_CTRL_STATE_LOCAL;	break;
	case MES_EQP_CTRL_STATE_REMOTE:		WndCmdID=ID_MES_SET_CTRL_STATE_REMOTE;	break;	
	}
	return WndCmdID;
}
//---------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckMustUpdateMsg(UINT message, WPARAM wParam, LPARAM lParam)//確認是否一定要更新的訊息
{
	bool MustUpdate = false;
	switch ( message )
	{
	case MSG_MAIN_FRAME_MESSAGE:		
		switch ( wParam )
		{
		case WPARAM_PROJECT_NEW:
		case WPARAM_PROJECT_OPEN:
		case WPARAM_PROJECT_CLOSE:
		case WPARAM_PROJECT_SWITCH:
		case WPARAM_PROJECT_CLOSE_ACTIVE_OBJ:
			MustUpdate = true;
			break;		
		}
		break;
	default:
		break;
	}
	return MustUpdate;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::AdjustModelBinaryMaskRect(const RECT &ModelRect, const RECT &WndRect, RECT &MaskRect)//調整模組二值化區域
{	
	const int MaxMaskSize = 1000;//pixel
	const int MaskSizeW=ModelRect.right-ModelRect.left;
	const int MaskSizeH=ModelRect.bottom-ModelRect.top;
	if ( MaskSizeW>MaxMaskSize || MaskSizeH>MaxMaskSize )
	{	
		const int Gap = 128;//pixel
		MaskRect = WndRect;
		::InflateRect(&MaskRect, Gap, Gap);//區域外擴
		//確認遮罩區域是否大於模組區域
		JetAPI::IntersectRect(MaskRect, ModelRect, MaskRect);		
	}	
	else
	{	MaskRect = ModelRect; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MoveStageToFd(CAOIFd *FdPtr, bool bForce)//移動機台至定位點
{
	if ( NULL == FdPtr ) { return true; }
	if ( GetIsLockUIWnd() == true ) { return true; }
	
	if ( false == bForce )
	{
		const bool   OfflineMode = GetOfflineMode();
		MOVE_TO_EVENT_MODE EvenMode = GetMoveToEventMode();
		if ( MOVE_TO_EVENT_SEL_CHANGE!=EvenMode || false==OfflineMode )
		{	return true; }
	}

	TREGION4D StageRgn;
	TPOINT3D  StagePos;
	DRAW_MODEL_MODE DrawModelMode = GetDrawModelMode();
	StagePos = FdPtr->GetFdStagePos();
	FdPtr->GetFdRoiStageRegion(StageRgn);
	return MoveStageTo(StagePos.x, StagePos.y, StageRgn);	
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MoveStageToPanel(CAOIPanel *PanelPtr, bool bForce)//移動機台至單板中心
{
	if ( NULL == PanelPtr ) { return true; }
	if ( GetIsLockUIWnd() == true ) { return true; }	
	if ( false == bForce )
	{
		const bool   OfflineMode = GetOfflineMode();
		MOVE_TO_EVENT_MODE EvenMode = GetMoveToEventMode();
		if ( MOVE_TO_EVENT_SEL_CHANGE!=EvenMode || false==OfflineMode )
		{	return true; }
	}

	TREGION4D StageRgn;
	TPOINT3D  StagePos;	
	double    FovSizeW = 0;
	double    FovSizeH = 0;	
	DISTRICT_ID DistrictID = PanelPtr->GetPanelActDistrictID();
	DRAW_MODEL_MODE DrawModelMode = GetDrawModelMode();
	
	PanelPtr->GetPanelRgnStage(DistrictID, StageRgn);
	StagePos.x = StageRgn.GetCpX();
	StagePos.y = StageRgn.GetCpY();
	const double StageRgnW = StageRgn.GetWidth();
	const double StageRgnH = StageRgn.GetHeight();
	GetFovSizeInner(FovSizeW, FovSizeH);
	//限制尺寸上限
	FovSizeW = MIN(FovSizeW*2, StageRgnW);
	FovSizeH = MIN(FovSizeH*2, StageRgnH);
	StageRgn.SetRgn(StagePos.x, StagePos.y, FovSizeW, FovSizeH);
	return MoveStageTo(StagePos.x, StagePos.y, StageRgn);	
}
