//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MoveStageToInspectionFinishComponent(CAOIProject *ProjectPtr)//移動至專案的檢測結果零件
{
	//設定部分移至CAOIProject::BuildProjectDefectComponentListKernel()
	if ( NULL == ProjectPtr ) { return false; }
	DISTRICT_ID DistrictID = ProjectPtr->GetProjectActDistrictID();
	if ( GetOfflineMode() == true )
	{		
		const size_t DefectCount = ProjectPtr->GetProjectDefectComponentCount(DistrictID);
		if ( DefectCount > 0 ) { return true; }
	}
	CAOIComponent *ComponentPtr = ProjectPtr->GetProjectActiveComponent();	
	if ( NULL == ComponentPtr ) { return false;  }
	if ( ComponentPtr->GetComponentDistrictID() != DistrictID )
	{
		ProjectPtr->ResetProjectActiveIndex();
		return true;
	}

	bool bChanged=false;
	CAOIComponent *MasterPtr=ComponentPtr;
	if ( ComponentPtr->CheckComponentIsAgent() == true )
	{	MasterPtr=ComponentPtr->GetComponentMasterPtr();	}
	if ( MasterPtr->CheckComponentIsMaster() == true )
	{
		if ( MasterPtr->GetComponentResultID_AOI() == RESULT_ID_NONE )
		{	MasterPtr->SetComponentResultPtr(ComponentPtr);	}
		else
		{				
			ComponentPtr = MasterPtr->GetComponentResultPtr();	
			if ( ComponentPtr != MasterPtr )
			{
				bChanged = true;
				ProjectPtr->SetProjectActiveComponent(ComponentPtr);
			}
		}
	}
	
	if ( true == bChanged )
	{	SendMainFrameWndMessage(MSG_EDIT_PART_LIST_WND, WPARAM_BUILD_PART_LIST, LPARAM_BUILD_DOCK_LIST_PART);	}
	SendMainFrameWndMessage(MSG_EDIT_PART_LIST_WND, WPARAM_UPDATE_PART_SELECTED, NULL);
	SendMainFrameWndMessage(MSG_EDIT_RESULT_LIST_WND, WPARAM_UPDATE_RESULT_SELECTED, NULL);
	if ( MoveStageToComponentOrField(ComponentPtr, true) == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MoveStageToComponent(CAOIComponent *ComponentPtr, bool bForce)//移動機台至零件
{
	if ( NULL == ComponentPtr ) { return true; }
	if ( GetIsLockUIWnd() == true ) { return true; }
	
	if ( false == bForce )
	{
		const bool   OfflineMode = GetOfflineMode();
		MOVE_TO_EVENT_MODE EvenMode = GetMoveToEventMode();
		if ( MOVE_TO_EVENT_SEL_CHANGE!=EvenMode || false==OfflineMode )
		{	return true; }
	}
	
	TREGION4D StageRgn;
	TPOINT3D  StagePos;
	TPOINT3D  StageOffset;
	DRAW_MODEL_MODE DrawModelMode = GetDrawModelMode();
	StagePos = ComponentPtr->GetComponentStagePos();
	ComponentPtr->GetComponentRoiStageRegion(StageRgn);		
	if ( DRAW_MODEL_RESULT == DrawModelMode )
	{
		StageOffset.x = ComponentPtr->GetComponentStageOffsetX();
		StageOffset.y = ComponentPtr->GetComponentStageOffsetY();
		StagePos.x += StageOffset.x;
		StagePos.y += StageOffset.y;
	}	
	return MoveStageTo(StagePos.x, StagePos.y, StageRgn);
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MoveStageToComponentField(CAOIComponent *ComponentPtr, bool bForce)//移動機台至零件Fov
{
	if ( NULL == ComponentPtr ) { return true; }
	if ( GetIsLockUIWnd() == true ) { return true; }
	
	if ( false == bForce )
	{
		const bool   OfflineMode = GetOfflineMode();
		MOVE_TO_EVENT_MODE EvenMode = GetMoveToEventMode();
		if ( MOVE_TO_EVENT_SEL_CHANGE!=EvenMode || false==OfflineMode )
		{	return true; }
	}
	
	TREGION4D StageRgn;
	TPOINT3D  StagePos;	
	DRAW_MODEL_MODE DrawModelMode = GetDrawModelMode();
	CAOIField *FieldPtr = ComponentPtr->GetComponentFieldPtr();
	if ( NULL == FieldPtr ) { return true; }	
	StagePos = FieldPtr->GetFieldStagePos();
	ComponentPtr->GetComponentRoiStageRegion(StageRgn);	
	return MoveStageTo(StagePos.x, StagePos.y, StageRgn);
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MoveStageToComponentOrField(CAOIComponent *ComponentPtr, bool bForce)//移動機台至零件或零件Fov
{
	if ( NULL == ComponentPtr ) { return true; }
	if ( GetIsLockUIWnd() == true ) { return true; }
	
	const bool MoveToFieldFirst=true;
	if ( true == MoveToFieldFirst )
	{
		CAOIField *FieldPtr = ComponentPtr->GetComponentFieldPtr();
		if ( NULL != FieldPtr )
		{	return MoveStageToComponentField(ComponentPtr, bForce);	}
	}
	return MoveStageToComponent(ComponentPtr, bForce);
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MoveStageTo(double StageX, double StageY, const TREGION4D &StageRgn)//移動機台至
{	
	if ( MoveStageToAct(StageX, StageY, StageRgn, StageRgn) == false )
	{	return false; }	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MoveStageToAct(double StageX, double StageY, const TREGION4D &StageRgn, const TREGION4D &ActStageRgn)//移動機台至	
{
	if ( GetIsLockUIWnd() == true ) { return true; }		
	const bool OfflineMode = GetOfflineMode();	
	if ( MotionCtrlPtr->XYMoveTo(StageX, StageY, OfflineMode) == false )
	{
		this->m_ErrorString = MotionCtrlPtr->GetErrorString();
		JetAPI::ShowMessageBox(m_ErrorString);
		return false;
	}
	const double RgnX = StageRgn.GetCpX();
	const double RgnY = StageRgn.GetCpY();
	const double RgnW = StageRgn.GetWidth()+500;
	const double RgnH = StageRgn.GetHeight()+500;
	const double ActX = ActStageRgn.GetCpX();
	const double ActY = ActStageRgn.GetCpY();
	const double ActW = ActStageRgn.GetWidth()+500;
	const double ActH = ActStageRgn.GetHeight()+500;
	const double OffsetX = ActX-StageX;
	const double OffsetY = ActY-StageY;
	SetFovSizeMinW(RgnW);
	SetFovSizeMinH(RgnH);
	SetFovPositionX(StageX);
	SetFovPositionY(StageY);
	SetTargetMinSizeW(ActW);
	SetTargetMinSizeH(ActH);
	SetFovTargetOffsetX(OffsetX);
	SetFovTargetOffsetY(OffsetY);
	ReleaseModelUniFrameList();
	ReleaseFieldUniFrameList();
	PostCallbackWndMessage(MSG_CAMERA_REGRAB_IMAGE, NULL, NULL);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ShowStageToAct(double StageX, double StageY, const TREGION4D &StageRgn, const TREGION4D &ActStageRgn)//顯示機台至
{
	if ( GetIsLockUIWnd() == true ) { return true; }

	const double RgnX = StageRgn.GetCpX();
	const double RgnY = StageRgn.GetCpY();
	const double RgnW = StageRgn.GetWidth()+500;
	const double RgnH = StageRgn.GetHeight()+500;
	const double ActX = ActStageRgn.GetCpX();
	const double ActY = ActStageRgn.GetCpY();
	const double ActW = ActStageRgn.GetWidth()+500;
	const double ActH = ActStageRgn.GetHeight()+500;
	const double OffsetX = ActX-StageX;
	const double OffsetY = ActY-StageY;
	SetFovSizeMinW(RgnW);
	SetFovSizeMinH(RgnH);
	SetFovPositionX(StageX);
	SetFovPositionY(StageY);
	SetTargetMinSizeW(ActW);
	SetTargetMinSizeH(ActH);
	SetFovTargetOffsetX(OffsetX);
	SetFovTargetOffsetY(OffsetY);	
	PostCallbackWndMessage(MSG_EDIT_MAIN_VIEW_WND, WPARAM_SHOW_WND_POSITION, NULL);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckServerLibraryQuery(PROJECT_LINK_SERVER_MODE LinkServerMode)//判斷伺服器資料庫是否詢問
{
	bool bQuery = false;
	switch ( LinkServerMode )
	{
	case PROJECT_LINK_SERVER_ENABLE_ALL_ASK:
	case PROJECT_LINK_SERVER_PROJECT_ONLY_ASK:
		bQuery = true;
		break;

	default:
	case PROJECT_LINK_SERVER_DISABLE:
	case PROJECT_LINK_SERVER_ENABLE_ALL:
	case PROJECT_LINK_SERVER_PROJECT_ONLY:	
		bQuery = false;
		break;
	}
	return bQuery;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckServerLibraryEnabled(PROJECT_LINK_SERVER_MODE LinkServerMode)//取得伺服器資料庫是否啟用
{
	bool bEnabled = false;
	switch ( LinkServerMode )
	{
	case PROJECT_LINK_SERVER_ENABLE_ALL:
	case PROJECT_LINK_SERVER_ENABLE_ALL_ASK:
		bEnabled = true;
		break;

	default:
	case PROJECT_LINK_SERVER_DISABLE:
	case PROJECT_LINK_SERVER_PROJECT_ONLY:
	case PROJECT_LINK_SERVER_PROJECT_ONLY_ASK:
		bEnabled = false;
		break;
	}
	return bEnabled;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckServerLibraryCanOnlineTuning(PROJECT_LINK_SERVER_MODE LinkServerMode)//判斷伺服器資料庫可以使用在線調機
{
	//if ( PROJECT_LINK_SERVER_DISABLE != ProjectLinkServerMode )//開啟專案連結伺服器就不使用此功能
	if ( PROJECT_LINK_SERVER_PROJECT_ONLY==LinkServerMode || PROJECT_LINK_SERVER_PROJECT_ONLY_ASK==LinkServerMode )//同專案下使用伺服器更新	
	{	return false; }
	return true;
}
