//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecRemoveProjectRawImage(CAOIProject *ProjectPtr)//移除專案儲存原圖	
{
	if ( CheckProjectPtr(ProjectPtr) == false )
	{	return false; }	
	CString RawFolder=GetSaveProjectRawImageFolder();
	if ( RawFolder.GetLength() == 0 ) { return true; }

	CString        str;	
	CString        Filename;	
	std::vector<CAOIField*> FieldList=m_FieldPtrList;
	std::vector<CAOIFrame*> FrameList=m_FramePtrList;
	const size_t FrameCount=FrameList.size();
	const size_t FieldCount=FieldList.size();
	if ( 0==FrameCount || 0==FieldCount ) { return true; }
	
	TCHAR TMode[32] = _T("w+");	
	JetAPI::ModifyOpenFileMode_Write(TMode);
	Filename.Format(_T("%s\\%s"), RawFolder, _T("NgPartList.txt"));
	FILE *pfile = ::_tfopen(Filename, TMode);
	if ( NULL == pfile )
	{
		str.Format(_T("Error, Open File Fault(%s"), Filename);
		SetErrorString(str);
		return false;	
	}
	
	::_ftprintf(pfile, _T("index, Fov, Panel, Board, Component, Left, Top, Right, Bottom\n"));

	for ( size_t i=0; i<FieldCount; i++ )
	{
		CAOIField *FieldPtr=FieldList[i];
		if ( NULL == FieldPtr ) { continue; }
		FieldPtr->SetFieldTempInt(FN_DISABLE);
		size_t FieldRgnCount=FieldPtr->GetFieldRgnPtrCount();
		for ( size_t j=0; j<FieldRgnCount; j++ )
		{
			CAOIRgn *RgnPtr=FieldPtr->GetFieldRgnPtr(j, false);
			if ( NULL == RgnPtr ) { continue; }
			CAOIRgn   *RgnParent=RgnPtr;
			if ( RgnPtr->GetRgnParent() != NULL )
			{	RgnParent = RgnPtr->GetRgnParent(); }
			AOI_OBJ_TYPE ObjType=RgnParent->GetObjType();			
			if ( AOI_OBJ_COMPONENT != ObjType ) { continue; }
			CAOIComponent *ComponentPtr = dynamic_cast<CAOIComponent*>(RgnParent);
			if ( NULL == ComponentPtr ) { continue; }			
			RESULT_ID ResultID=ComponentPtr->GetComponentResultID_AOI();
			if ( RESULT_ID_NG==ResultID || RESULT_ID_EXCEPTION==ResultID )
			{				
				FieldPtr->SetFieldTempInt(FN_ENABLE);
				RECT RgnRect=RgnPtr->GetRgnFrameImageRect();
				CString ComName=ComponentPtr->GetComponentName();
				const size_t SubRgnCount = RgnPtr->GetRgnSubRgnCount();
				unsigned int FieldIndex=FieldPtr->GetFieldIndex();
				unsigned int BoardIndex=ComponentPtr->GetComponentBoardIndex_Panel();
				unsigned int PanelIndex=ComponentPtr->GetComponentPanelIndex_Project();				
				::_ftprintf(pfile, _T("%d, %d, %d, %d, %s, %d, %d, %d, %d\n"), i+1, FieldIndex+1, PanelIndex+1, BoardIndex, ComName, RgnRect.left, RgnRect.top, RgnRect.right, RgnRect.bottom);
			}
		}
	}
	::fclose(pfile);	pfile=NULL;

	for ( size_t i=0; i<FrameCount; i++ )
	{
		CAOIFrame *FramePtr=FrameList[i];
		if ( NULL == FramePtr ) { continue; }
		bool bSaveRawImage=FramePtr->GetFrameSaveRawImageDone();
		if ( false == bSaveRawImage ) { continue; }
		CAOIField *FieldPtr=FramePtr->GetFrameFieldPtr();
		if ( NULL == FieldPtr ) { continue; }
		if ( FN_ENABLE == FieldPtr->GetFieldTempInt() ) { continue; }

		CString FrameFolder;
		CString FieldName=FieldPtr->GetFieldIndexName();	
		CString FrameName=FramePtr->GetFrameIndexName();		
		FrameFolder.Format(_T("%s\\%s\\%s"), RawFolder, FieldName, FrameName);
		JetAPI::RemoveFolder(FrameFolder);
		FramePtr->SetFrameSaveRawImageDone(false);
	}
	for ( size_t i=0; i<FieldCount; i++ )
	{
		CAOIField *FieldPtr=FieldList[i];
		if ( NULL == FieldPtr ) { continue; }
		if ( FN_ENABLE == FieldPtr->GetFieldTempInt() ) { continue; }

		CString FieldFolder;
		CString FieldName=FieldPtr->GetFieldIndexName();		
		FieldFolder.Format(_T("%s\\%s"), RawFolder, FieldName);
		JetAPI::RemoveFolder(FieldFolder);		
	}
	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::TurnOnConveyerSensorPower(DWORD DelayTime)//開啟軌道感測器電源
{
#ifndef OFFLINE_VERSION	
	const bool bTurnOff=false;
	if ( PlcCtrlPtr->TurnOffConveyerSensorPower_LA(bTurnOff) == false )
	{
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
		return false;	
	}
	if ( PlcCtrlPtr->TurnOffConveyerSensorPower_LB(bTurnOff) == false )
	{
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
		return false;	
	}
	if ( DelayTime > 0 )//稍等一下Sensor運作
	{	::Sleep(DelayTime);	}
	const bool bCheckThread=false;
	if ( PlcCtrlPtr->PLC_ReadConveryerSensor(bCheckThread) == false )
	{
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
		return false;	
	}
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckSystemReady(bool bChkStartLight, bool bAutoReset)//確認系統是否正常
{
	const bool bChkMotionEnb = true;		
#ifndef OFFLINE_VERSION
	if ( CameraCtrl.GetCameraCtrlReady() == false )
	{
		m_ErrorString = CameraCtrl.GetErrorString();
		return false;	
	}
	if ( MotionCtrlPtr->CheckMotionReady(bChkMotionEnb) == false )
	{
		m_ErrorString = MotionCtrlPtr->GetErrorString();
		return false;	
	}
	if ( PlcCtrlPtr->CheckPLCReady(bChkStartLight, bAutoReset) == false )
	{
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
		return false;	
	}
	if ( LightCtrlBoard.CheckIsConnected() == false )
	{
		m_ErrorString = LightCtrlBoard.GetErrorString();
		return false;
	}
	if ( Light3DCtrl.CheckLight3DCastIsConnected() == false )
	{
		m_ErrorString = Light3DCtrl.GetErrorString();
		return false;
	}
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckPCBInside(LANE_ID LaneID)//確認是否有板
{
	PlcCtrlPtr->PLC_ReadConveryerSensor(false);
	const bool PCBStop = PlcCtrlPtr->GetConveryerSensorPCBStop(LaneID);
	if ( true == PCBStop ) { return true; }
	
	CString str;
	switch ( LaneID )
	{
	case LANE_ID_B:	str = _T("Error, there is NO board on the conveyer LB");	break;
	case LANE_ID_A:	str = _T("Error, there is NO board on the conveyer LA");	break;
	}
	m_ErrorString = PlcCtrlPtr->LoadMultiLanguageString(str, str);
	return false;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecTargetCapOnProc(bool bWait)//執行開啟塊規上蓋
{	
	if ( PlcCtrlPtr->TurnOnOffTargetCap(true) == false )
	{
		SetErrorString(PlcCtrlPtr->GetPLCErrorString());
		return false; 
	}
	SetTurnOnOffTargetCapTickCount(::GetTickCount());	
	if ( false == bWait )
	{	return true; }

	if ( WaitForTargetCapOnFinish() == false )
	{	return false; }

	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecTargetCapOffProc(bool bWait)//執行關閉塊規上蓋
{
	if ( PlcCtrlPtr->TurnOnOffTargetCap(false) == false )
	{
		SetErrorString(PlcCtrlPtr->GetPLCErrorString());
		return false; 
	}
	SetTurnOnOffTargetCapTickCount(::GetTickCount());

	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckTargetCapOnFinish()//確認開啟塊規上蓋
{
	DWORD CurTickCount=::GetTickCount();
	DWORD DelayTime=GetTurnOnOffTargetCapDelayTime();
	DWORD ExecTickCount=GetTurnOnOffTargetCapTickCount();
	if ( CurTickCount < ExecTickCount ) { return false; }
	DWORD GapTickCount=CurTickCount-ExecTickCount;
	if ( GapTickCount < DelayTime ) { return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::WaitForTargetCapOnFinish()//等待開啟塊規上蓋完成
{
	DWORD Count=0;	
	const DWORD SleepTime=10;
	const DWORD CheckTime=GetTurnOnOffTargetCapDelayTime()*2;
	const DWORD MaxCount=CheckTime/SleepTime;
	while ( true )
	{
		if ( CheckTargetCapOnFinish() == true )
		{	break; }
		Count ++;
		if ( Count > MaxCount )
		{
			SetErrorString(_T("Error, WaitForTargetCapOnFinish Fault")); 
			return false;
		}
		if ( SleepTime > 0 )
		{	::Sleep(SleepTime); }

	};
	return true;
}
