//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckPCBPositionByCamera(LANE_ID LaneID, bool RightIn, int CheckMode)//用相機確認PC位置
{
	const CAMERA_ID CameraID=PRIMARY_CAMERA_ID;	
	CameraCtrl.SetCameraToSendCallback(CameraID, FALSE);
	const bool IsOK=CheckPCBPositionByCameraFn(LaneID, RightIn, CheckMode, CameraID);
	CameraCtrl.SetCameraToSendCallback(CameraID, TRUE);
	return IsOK;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckPCBPositionByCameraFn(LANE_ID LaneID, bool RightIn, int CheckMode, CAMERA_ID CameraID)//用相機確認PC位置
{
	const char fnName[]="CAOIDataCollect::CheckPCBPositionByCamera";
	std::vector<TSliceParam> SliceParamList;
	const unsigned int SliceUniqueID=SLICE_UNIQUE_ID_TOP_R;
	const TSliceParam *SliceParamPtr=GetSystemSliceParamPtrByUniqueID(SliceUniqueID);
	if ( NULL == SliceParamPtr ) { return false; }

	TSliceParam SliceParam=*SliceParamPtr;
	for ( int i=0; i<LED_CHANNEL_COUNT; i++ )//for Use
	{			
		SliceParam.SliceLightTable.LEDChannel[i].OnOffState = 0;	
		SliceParam.SliceLightTable.LEDChannel[i].PowerValue = 000;	
	}	
	//SliceParam.SliceLightTable.LEDChannel[0].PowerValue = 100;//for Test	
	SliceParamList.push_back(SliceParam);
	const size_t SliceCount=SliceParamList.size();
	if ( 0 == SliceCount )
	{	return true; }		
	
	CString    str;	
	CString    str2;	
	CString    strTmp;		
	CString    Folder;
	CString    Folder2;
	CString    strResult;
	CString    strChannel;
	CString    strTarget;
	CString    strReading;
	IMAGE_SIZE ImageW=0;
	IMAGE_SIZE ImageH=0;
	IMAGE_SIZE ImageStep=0;	
	IMAGE_SIZE BitCount=0;	
	IMAGE_PTR  ImagePtr=NULL;	
	const bool  bSaveImage=false;	
	CAMERA_IMAGE_MODE CameraImageMode=GetCameraImageMode(CameraID);	
	const size_t BufferSize=CameraCtrl.GetCameraColorImageSize(CameraID);

	Folder.Format(_T("%s\\%s"), GetAOITempDirectory(), _T("CheckPCBPositionByCamera"));
	Folder2 = Folder;
	CreateDirectory(Folder, NULL);	
	switch ( CheckMode )
	{
	case CHECK_PCB_PASS_SLOW_POS: Folder += CString(_T("\\SlowDown")); break;
	case CHECK_PCB_EXIT_STOP_POS: Folder += CString(_T("\\StopSensor")); break;
	case CHECK_PCB_PASS_STOP_POS: 
		Folder += CString(_T("\\StopSensor"));
		Folder2 += CString(_T("\\StopSensor2"));
		break;
	}
	CreateDirectory(Folder, NULL);
	JetAPI::ClearFolder(Folder);

	if ( CHECK_PCB_PASS_STOP_POS==CheckMode )
	{
		CreateDirectory(Folder2, NULL);
		JetAPI::ClearFolder(Folder2);
	}

	if ( JetMemory.alloc_func(BufferSize, ImagePtr, fnName, "ImagePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(ImagePtr);		
		return false;
	}		

	if ( CameraCtrl.BatchGrabPrepare2(SliceParamList, true) == false )
	{		
		JetMemory.free_func(ImagePtr);
		SetErrorString(CameraCtrl.GetErrorString());
		return false;
	}

	
	bool IsOK=true;
	int  CheckCount=0;
	bool bFinish = false;	
	const int TotalFrameImageCount = 1;
	DWORD TickCountGap=0;
	DWORD TickCountEnd=GetTickCount();
	DWORD TickCountStart=TickCountEnd;	
	while ( true )
	{
		bFinish = false;		
		if ( CameraCtrl.ClearCameraCount(CameraID) == false )
		{
			JetMemory.free_func(ImagePtr);
			SetErrorString(CameraCtrl.GetErrorString());
			return false;
		}
		if ( CameraCtrl.BatchIndexReset() == false )
		{
			JetMemory.free_func(ImagePtr);
			SetErrorString(CameraCtrl.GetErrorString());
			return false;
		}
		if ( CameraCtrl.BatchGrabStart2(bFinish) == false )
		{
			JetMemory.free_func(ImagePtr);
			SetErrorString(CameraCtrl.GetErrorString());
			return false;
		}			
		if ( CameraCtrl.WaitForCameraImageCallbackCount(CameraID, TotalFrameImageCount) == false )
		{
			JetMemory.free_func(ImagePtr);
			SetErrorString(CameraCtrl.GetErrorString());
			return false;
		}

		if ( CameraCtrl.GetCameraImage3(CameraID, ImageW, ImageH, ImageStep, BitCount, ImagePtr) == false )
		{
			JetMemory.free_func(ImagePtr);
			SetErrorString(CameraCtrl.GetErrorString());
			return false;
		}
		
		if ( true == bSaveImage )
		{
			if ( CHECK_PCB_PASS_SLOW_POS == CheckMode )
			{	str.Format(_T("%s\\PCBInSlow_%03d.PNG"), Folder, CheckCount+1);	}
			else
			{	str.Format(_T("%s\\PCBInStop_%03d.PNG"), Folder, CheckCount+1);	}
			ImageAPI.SaveImage(str, ImageW, ImageH, ImageStep, BitCount, ImagePtr, true);
		}

		switch ( CheckMode )
		{
		case CHECK_PCB_PASS_SLOW_POS:
			IsOK = CheckPCBImage_SlowSensor(ImageW, ImageH, ImageStep, BitCount, ImagePtr, bFinish);
			break;
		case CHECK_PCB_PASS_STOP_POS:
			IsOK = CheckPCBImage_StopSensor(ImageW, ImageH, ImageStep, BitCount, ImagePtr, bFinish);
			break;
		case CHECK_PCB_EXIT_STOP_POS:
			IsOK = CheckPCBImage_StopSensor(ImageW, ImageH, ImageStep, BitCount, ImagePtr, bFinish);
			bFinish = !bFinish;
			break;
		}	
		if ( false == IsOK )
		{
			JetMemory.free_func(ImagePtr);
			return false;
		}
		if ( true == bFinish )
		{	break;	}

		CheckCount ++;
		TickCountEnd=GetTickCount();
		TickCountGap=TickCountEnd-TickCountStart;
		if ( TickCountGap > 5000 )
		{
			switch ( CheckMode )
			{
			default: str=_T("Error, Check PCB Postion Timeout"); break;
			case CHECK_PCB_PASS_SLOW_POS:	str=_T("Error, Check PCB Pass Slow Down Postion Timeout"); break;
			case CHECK_PCB_PASS_STOP_POS:	str=_T("Error, Check PCB Pass Stop Sensor Postion Timeout"); break;
			case CHECK_PCB_EXIT_STOP_POS:	str=_T("Error, Check PCB Exit Stop Sensor Postion Timeout"); break;			
			}	
			SetErrorString(str);
			JetMemory.free_func(ImagePtr);
			return false;
		}
	};

	//調整停板位置	
	bool CheckOK = true;
	TickCountEnd=GetTickCount();
	TickCountStart=TickCountEnd;
	const int MaxCheckCount=CheckCount+10;
	if ( CHECK_PCB_PASS_STOP_POS == CheckMode )
	{		
		double Offset = 0.0;
		double OffsetPre = 0.0;
		int ResultMode=0;
		int   LastDir = 0;		
		double AveGray = 0.0;
		const int ResultMode_AllDark=1;//全暗-只看到PCB
		const int ResultMode_AllWhite=2;//全亮-只看到LED	
		const int DirMode_Stop=0;
		const int DirMode_ToRight=1;
		const int DirMode_ToLeft=2;
		std::vector<CString> InfoList;
		if ( true == RightIn )//設定反向以便於第1次可以作動
		{	LastDir=DirMode_ToLeft;	}
		else
		{	LastDir=DirMode_ToRight;	}
		while ( true )
		{
			bFinish = false;		
			if ( CameraCtrl.ClearCameraCount(CameraID) == false )
			{
				JetMemory.free_func(ImagePtr);
				SetErrorString(CameraCtrl.GetErrorString());
				return false;
			}
			if ( CameraCtrl.BatchIndexReset() == false )
			{
				JetMemory.free_func(ImagePtr);
				SetErrorString(CameraCtrl.GetErrorString());
				return false;
			}
			if ( CameraCtrl.BatchGrabStart2(bFinish) == false )
			{
				JetMemory.free_func(ImagePtr);
				SetErrorString(CameraCtrl.GetErrorString());
				return false;
			}			
			if ( CameraCtrl.WaitForCameraImageCallbackCount(CameraID, TotalFrameImageCount) == false )
			{
				JetMemory.free_func(ImagePtr);
				SetErrorString(CameraCtrl.GetErrorString());
				return false;
			}

			if ( CameraCtrl.GetCameraImage3(CameraID, ImageW, ImageH, ImageStep, BitCount, ImagePtr) == false )
			{
				JetMemory.free_func(ImagePtr);
				SetErrorString(CameraCtrl.GetErrorString());
				return false;
			}
		
			if ( true == bSaveImage )
			{
				if ( CHECK_PCB_PASS_SLOW_POS == CheckMode )
				{	str.Format(_T("%s\\PCBInSlow_%03d.PNG"), Folder, CheckCount+1);	}
				else
				{	str.Format(_T("%s\\PCBInStop_%03d.PNG"), Folder, CheckCount+1);	}
				ImageAPI.SaveImage(str, ImageW, ImageH, ImageStep, BitCount, ImagePtr, true);
			}

			DWORD TickCountCalc=GetTickCount();
			if ( CheckPCBImagePosition_StopSensor(CheckCount, ImageW, ImageH, ImageStep, BitCount, ImagePtr, AveGray, Offset) == false )
			{
				JetMemory.free_func(ImagePtr);
				return false;
			}			
			TickCountCalc = GetTickCount()-TickCountCalc;

			bool bOn = true;			
			bool bExecMotor=false;
			int  nPositive=LastDir;
			if ( AveGray > 250 ) { ResultMode=ResultMode_AllWhite; }
			else if ( AveGray < 85 ) { ResultMode=ResultMode_AllDark; }
			else {	ResultMode = 0;	}

			OffsetPre = Offset;
			const double CalOffset=80;
			const bool bCalOffset=false;
			if ( true == bCalOffset )
			{	
				if ( DirMode_ToRight == LastDir )
				{	OffsetPre += CalOffset;	}
				if ( DirMode_ToLeft == LastDir )
				{	OffsetPre -= CalOffset;	}
			}

			if ( ResultMode_AllWhite == ResultMode )
			{
				if ( true == RightIn )
				{	nPositive = DirMode_ToLeft; }
				else
				{	nPositive = DirMode_ToRight; }				
			}
			else if ( ResultMode_AllDark == ResultMode )
			{
				if ( true == RightIn )
				{	nPositive = DirMode_ToRight; }
				else
				{	nPositive = DirMode_ToLeft; }				
			}
			else
			{
				if ( Offset < 0 )
				{	nPositive = DirMode_ToRight;	}
				else
				{	nPositive = DirMode_ToLeft;	}
			}
			if ( nPositive != LastDir )
			{	bExecMotor = true;	}
			else
			{	bExecMotor = false; }

			TickCountEnd=GetTickCount();

			CString strDir, strMode, strExec, strLastDir;			
			if ( true==bExecMotor )
			{	strExec=_T("Write");	}
			else
			{	strExec=_T("---");	}
			switch ( ResultMode )
			{
			case ResultMode_AllDark: strMode=_T("Dark"); break;
			case ResultMode_AllWhite: strMode=_T("White"); break;
			default:				strMode=_T("Gray");	break;
			}
			switch ( nPositive )
			{
			case DirMode_Stop: strDir=_T("Stop"); break;
			case DirMode_ToRight: strDir=_T("To-Right"); break;
			case DirMode_ToLeft: strDir=_T("To-Left"); break;
			}
			switch ( LastDir )
			{
			case DirMode_Stop: strLastDir=_T("Stop"); break;
			case DirMode_ToRight: strLastDir=_T("To-Right"); break;
			case DirMode_ToLeft: strLastDir=_T("To-Left"); break;
			}

			bFinish = false;
			const double OffsetPass=20.0;
			if ( 0 == ResultMode )
			{
				if ( fabs(OffsetPre) < OffsetPass )
				{	bFinish = true; }
			}			

			bool Debug=false;
			if ( fabs(OffsetPre) < 1.01 )
			{	
				switch ( ResultMode )
				{
				case ResultMode_AllDark:					
					break;
				case ResultMode_AllWhite:					
					break;
				default:
					Debug = true;
					break;
				}
				Debug = false;
			}
			if ( true==Debug )
			{
				if ( false == bSaveImage )//之前沒有存圖的話補存圖
				{
					if ( CHECK_PCB_PASS_SLOW_POS == CheckMode )
					{	str.Format(_T("%s\\PCBInSlow_%03d.PNG"), Folder, CheckCount+1);	}
					else
					{	str.Format(_T("%s\\PCBInStop_%03d.PNG"), Folder, CheckCount+1);	}
					ImageAPI.SaveImage(str, ImageW, ImageH, ImageStep, BitCount, ImagePtr, true);
				}

				double Offset2=0, AveGray2=0;
				CheckPCBImagePosition_StopSensor(CheckCount, ImageW, ImageH, ImageStep, BitCount, ImagePtr, AveGray2, Offset2);				
			}

			str.Format(_T("%d, %u, %u, %.2f, %.2f, %s, %s, %s, %s"), CheckCount+1, TickCountEnd, TickCountCalc, Offset, AveGray, strMode, strLastDir, strDir, strExec);
			InfoList.push_back(str);
			if ( true == bFinish )
			{	break;	}
			
			if ( true == bExecMotor )
			{
				bool bPositive = true;
				if ( DirMode_ToRight == nPositive ) { bPositive = true; }
				else if ( DirMode_ToLeft == nPositive ) { bPositive = false; }
				if ( ExecConveyorMotorRunning(LaneID, bOn, bPositive, true) == false )
				{
					JetMemory.free_func(ImagePtr);						
					return false;
				}				
			}	
			LastDir = nPositive;

			CheckCount ++;			
			TickCountGap=TickCountEnd-TickCountStart;
			if ( TickCountGap > 10000 )			
			//if ( CheckCount > MaxCheckCount )
			{
				CheckOK = false;
				switch ( CheckMode )
				{
				default: str=_T("Error, Check PCB Postion Timeout");	break;
				case CHECK_PCB_PASS_SLOW_POS: str=_T("Error, Check PCB Pass Slow Down Postion Timeout");	break;
				case CHECK_PCB_PASS_STOP_POS: str=_T("Error, Check PCB Pass Stop Sensor Postion Timeout");	break;
				case CHECK_PCB_EXIT_STOP_POS: str=_T("Error, Check PCB Exit Stop Sensor Postion Timeout");	break;
				}
				SetErrorString(str);				
				break;
			}
		};

		FILE *pfile=NULL;
		const size_t InfoCnt=InfoList.size();		
		str.Format(_T("%s\\PCBInStopList.Txt"), Folder2);
		pfile = ::_tfopen(str, _T("w+"));
		if ( NULL != pfile )
		{
			::fprintf(pfile, "index, Count, TickCount, CalcTime, offset, Gray, Mode, Direction, Next-Dir, Cmd\n");
			for ( size_t i=0; i<InfoCnt; i++ )
			{	::_ftprintf(pfile, _T("%d, %s\n"), i+1, InfoList[i]);	}
			::fclose(pfile); pfile=NULL;
		}		
	}

	JetMemory.free_func(ImagePtr);	
	return CheckOK;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckPCBImage_SlowSensor(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, IMAGE_PTR ImagePtr, bool &bFinsih)
{	
	if ( NULL == ImagePtr ) { return false; }

	int WhiteCount=0;
	const int Threshold=240;
	const size_t BufferSize=ImageAPI.CalcBufferSize(ImageStep, ImageH);
	const size_t PassCount=BufferSize*2/4;	
	for ( size_t i=0; i<BufferSize; i++ )
	{
		if ( ImagePtr[i] < Threshold ) { continue; }
		WhiteCount ++;
	}
	if ( WhiteCount < PassCount )
	{	bFinsih = true; }		
	else
	{	bFinsih = false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckPCBImage_StopSensor(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, IMAGE_PTR ImagePtr, bool &bFinsih)
{
	if ( NULL == ImagePtr ) { return false; }

	int WhiteCount=0;
	const int Threshold=240;
	const size_t BufferSize=ImageAPI.CalcBufferSize(ImageStep, ImageH);
	const size_t PassCount=BufferSize*60/100;
	for ( size_t i=0; i<BufferSize; i++ )
	{
		if ( ImagePtr[i] < Threshold ) { continue; }
		WhiteCount ++;
	}
	if ( WhiteCount < PassCount )
	{	bFinsih = true; }		
	else
	{	bFinsih = false; }	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckPCBImagePosition_StopSensor(int LoopCnt, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, IMAGE_PTR ImagePtr, double &AveGray, double &Offset)
{
	if ( NULL == ImagePtr ) { return false; }
	const char fnName[] = "CAOIDataCollect::CheckPCBImagePosition_StopSensor";

	//確認影像中央的垂直上下線段
	RECT Rect;
	std::vector<RECT> RoiList;	
	const size_t ChkRgnH=256;//20%範圍
	const size_t ChkRgnW=ImageW*1/4;//20%範圍
	const size_t ChkRgnH2=ChkRgnH/2;
	const size_t ChkRgnW2=ChkRgnW/2;//20%範圍	
	const IMAGE_SIZE ImageH2=ImageH/2;
	const IMAGE_SIZE ImageW2=ImageW/2;	
	
	Rect.left  = ImageW2-ChkRgnW2;
	Rect.right = ImageW2+ChkRgnW2;

	//Top
	Rect.top=0;
	Rect.bottom=Rect.top+ChkRgnH;
	RoiList.push_back(Rect);

	//Mid
	Rect.top=ImageH2-ChkRgnH2;
	Rect.bottom=ImageH2+ChkRgnH2;
	RoiList.push_back(Rect);

	//Bot	
	Rect.bottom=ImageH;
	Rect.top=Rect.bottom-ChkRgnH;
	RoiList.push_back(Rect);

	size_t i=0, j=0;
	CString str, Folder;
	size_t u=0, v=0, w=0;
	const int nAlign = 4;
	IMAGE_PTR  RoiPtr=NULL;
	IMAGE_PTR  GryPtr=NULL;
	IMAGE_PTR  CalcPtr=NULL;
	IMAGE_PTR  SobelPtr=NULL;
	IMAGE_SIZE RoiW=ChkRgnW;
	IMAGE_SIZE RoiH=ChkRgnH;
	IMAGE_SIZE GryBitCount=8;
	const bool bSaveImage=true;
	std::vector<float> OffsetList;
	std::vector<float> Profile(ChkRgnW+10);
	IMAGE_SIZE RoiStep=JetAPI::GetBMPImagePixelsPerLine(RoiW, BitCount, nAlign);
	IMAGE_SIZE GryStep=JetAPI::GetBMPImagePixelsPerLine(RoiW, GryBitCount, nAlign);	
	const size_t RoiCount=RoiList.size();
	const size_t RoiBufferSize=ImageAPI.CalcBufferSize(RoiStep, RoiH);
	if ( JetMemory.alloc_func(RoiBufferSize, RoiPtr, fnName, "RoiPtr") == false || 
		 JetMemory.alloc_func(RoiBufferSize, GryPtr, fnName, "GryPtr") == false ||
		 JetMemory.alloc_func(RoiBufferSize, SobelPtr, fnName, "SobelPtr") == false )
	{
		JetMemory.free_func(RoiPtr);
		JetMemory.free_func(GryPtr);
		JetMemory.free_func(SobelPtr);
		SetErrorString(_T("Error, CheckPCBImagePosition_StopSensor Fault"));		
		return false;
	}

	Folder.Format(_T("%s\\%s"), GetAOITempDirectory(), _T("CheckPCBPositionByCamera"));
	CreateDirectory(Folder, NULL);
	Folder += CString(_T("\\StopSensor2"));
	CreateDirectory(Folder, NULL);
	//JetAPI::ClearFolder(Folder);

	Offset = 0.0;	
	AveGray = 0.0;	
	for ( i=0; i<RoiCount; i++ )
	{
		if ( i != (RoiCount/2) ) { continue; }

		const RECT &RectRef=RoiList[i];
		if ( ImageAPI.ExtractRoiImage3(ImageW, ImageW, ImageStep, BitCount, ImagePtr, RectRef, RoiStep, RoiPtr, false) == false )
		{
			JetMemory.free_func(RoiPtr);
			JetMemory.free_func(GryPtr);
			JetMemory.free_func(SobelPtr);
			SetErrorString(_T("Error, CheckPCBImagePosition_StopSensor Fault"));
			return false;
		}
		
		if ( GryStep == RoiStep )
		{	CalcPtr = RoiPtr;	}
		else
		{
			CalcPtr = GryPtr;
			if ( ImageAPI.ColorImageToGrayImage3(RoiW, RoiH, RoiStep, RoiPtr, GryStep, GryPtr) == false )
			{
				JetMemory.free_func(RoiPtr);
				JetMemory.free_func(GryPtr);
				JetMemory.free_func(SobelPtr);
				SetErrorString(_T("Error, CheckPCBImagePosition_StopSensor Fault"));
				return false;
			}
		}

		if ( i == (RoiCount/2) )
		{
			unsigned int Ave=0;
			const size_t GryBufferSize=GryStep*RoiH;
			for ( j=0; j<GryBufferSize; j++ )
			{	Ave += (unsigned int)(CalcPtr[j]);	}
			Ave /= GryBufferSize;
			AveGray = Ave;
		}

		//Sobel處理
		if ( ImageAPI.SobelImage3(RoiW, RoiH, RoiStep, GryBitCount, CalcPtr, SobelPtr) == false )
		{
			JetMemory.free_func(RoiPtr);
			JetMemory.free_func(GryPtr);
			JetMemory.free_func(SobelPtr);
			SetErrorString(_T("Error, CheckPCBImagePosition_StopSensor Fault"));
			return false;
		}
		if ( true==bSaveImage )
		{
			if ( i == (RoiCount/2) )
			{
				str.Format(_T("%s\\PCBInStop_%03d_%03d_Calc.PNG"), Folder, LoopCnt+1, i+1);
				ImageAPI.SaveImage(str, RoiW, RoiH, RoiStep, GryBitCount, CalcPtr, true);
				str.Format(_T("%s\\PCBInStop_%03d_%03d_Sobel.PNG"), Folder, LoopCnt+1, i+1);
				//ImageAPI.SaveImage(str, RoiW, RoiH, RoiStep, GryBitCount, SobelPtr, true);
			}
		}
		Profile.clear();
		float Sum=0.0, Val=0, Ave=0;
		for ( u=0; u<RoiW; u++ )
		{	
			Sum = Val = Ave = 0.0;
			for ( v=0; v<RoiH; v++ )
			{
				w=(v*RoiStep)+u;
				Val = SobelPtr[w];
				Sum += Val;
			}
			Ave=Sum/RoiH;
			Profile.push_back(Ave);
		}

		//尋找最高值
		Val = 0.0f;		
		const size_t Count=Profile.size();
		for ( u=0; u<Count; u++ )
		{
			if ( 0==u || Val<Profile[u] )
			{
				v = u;
				Val=Profile[u]; 				
			}
		}

		const float LocX=(float)(v);
		const float LocCpX=(float)(ChkRgnW2);
		Val = LocX-LocCpX;
		OffsetList.push_back(Val);
	}
	
	Offset = 0.0;	
	const size_t OffsetCnt=OffsetList.size();
	if ( OffsetCnt > 0 )
	{
		for ( i=0; i<OffsetCnt; i++ )
		{	Offset += OffsetList[i];	}		
		Offset /= OffsetCnt;			
	}	
	JetMemory.free_func(RoiPtr);
	JetMemory.free_func(GryPtr);
	JetMemory.free_func(SobelPtr);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecClampPcbBeforeTestFunc()//執行檢測前夾板動作
{
	const TSystemParameter &SysParam=GetSystemParameter();
	FUNC_EXEC_MODE ExecMode=SysParam.m_ClampPcbBeforeTestMode;
	if ( FUNC_EXEC_OFF == ExecMode ) { return true; }

	if ( MoveCameraToBeforePCBInPosition(true) == false )
	{	return false; }

	std::vector<LANE_ID> LaneIDList;
	LANE_WORK_MODE LaneWorkMode_LA=GetLaneWorkMode_LA();
	LANE_WORK_MODE LaneWorkMode_LB=GetLaneWorkMode_LB();
	if ( LANE_WORK_RUN == LaneWorkMode_LA )
	{	LaneIDList.push_back(LANE_ID_A);	}
	if ( LANE_WORK_RUN == LaneWorkMode_LB )
	{	LaneIDList.push_back(LANE_ID_B);	}

	size_t     i=0;
	CString    str;
	LANE_ID    LaneID;	
	DWORD      Res=0;
	bool       bAsk=true;
	bool       bClamp=false;	
	bool       bPCBSlow=false;
	bool       bPCBStop=false;	
	bool       bPCBExist=false;		
	const bool bCheckThread = false;
	const size_t LaneCount=LaneIDList.size();

	bAsk=true;
	PlcCtrlPtr->PLC_ReadConveryerSensor(bCheckThread);
	PlcCtrlPtr->PLC_ReadConveryerSignalSend(bCheckThread);	
	for ( i=0; i<LaneCount; i++ )
	{
		bPCBExist=false;
		LaneID = LaneIDList[i];
		bClamp = PlcCtrlPtr->GetConveryerClamp(LaneID);				
		bPCBSlow = PlcCtrlPtr->GetConveryerSensorPCBSlow(LaneID);
		bPCBStop = PlcCtrlPtr->GetConveryerSensorPCBStop(LaneID);		
		if ( true == bPCBStop )
		{	bPCBExist = true;	}		
		if ( true == bClamp ) { continue; }
		if ( false == bPCBExist ) { continue; }

		if ( FUNC_EXEC_AUTO == ExecMode )
		{	bAsk = false;	}
		if ( true == bAsk )
		{
			str=_T("Do you want to Clamp PCB Before Test?");
			str=LoadMultiLanguageString(str, str);
			Res = JetAPI::ShowMessageBox(str, MB_YESNO);
			if ( IDNO == Res )
			{	return true; }			
			bAsk = false;
		}
		PlcCtrlPtr->WriteConveryerClamp(LaneID, true);
	}
	return true;
}
