bool CAOIDataCollect::ExecPCBInByCamera(LANE_ID LaneID)//執行相機進板
{
	PlcCtrlPtr->StopPLCPollingThread();
	const bool IsOK = ExecPCBInByCameraFn(LaneID);
	PlcCtrlPtr->StartPLCPollingThread();
	return IsOK;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecPCBInByCameraFn(LANE_ID LaneID)//執行相機進板
{
	bool bPositive = true;	
	bool bRightSide=false;
	bool bSlowMode = false;	
	const bool bOn=true;
	const bool bOff=false;
	const bool bWait=true;	
	const bool bRightIn = PlcCtrlPtr->GetIsPCBRightInDirection();

	if ( true == bRightIn )
	{	
		bRightSide=false;
		bPositive = false; 
	}
	else
	{
		bRightSide=true;
		bPositive = true; 
	}

	//鬆板
	if ( PlcCtrlPtr->WriteConveryerClamp(LaneID, false) == false )
	{
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString(); 
		return false;
	}

	//Turn On Converyer LED
	if ( PlcCtrlPtr->TurnOnConveryerLED(LaneID, bOn) == false )
	{
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString(); 
		return false;
	}

	//Move To PCB Slow Sensor Position
	if ( MoveCameraToLaneLEDSlowSensorPos(LaneID, bRightSide, bWait) == false )
	{	
		PlcCtrlPtr->TurnOnConveryerLED(LaneID, false);
		return false; 
	}

	bSlowMode = false;
	if ( ExecConveyorMotorRunning(LaneID, bOn, bPositive, bSlowMode) == false )
	{	
		PlcCtrlPtr->TurnOnConveryerLED(LaneID, false);
		return false;
	}		

	//Check Pcb Pass Slow Position	
	if ( CheckPCBPassSlowPosition(LaneID, bRightIn) == false )
	{
		ExecConveyorMotorStop(LaneID);
		PlcCtrlPtr->TurnOnConveryerLED(LaneID, false);
		return false;
	}	

	//Slow Down Converyer Speed
	bSlowMode = true;
	if ( ExecConveyorMotorRunning(LaneID, bOn, bPositive, bSlowMode) == false )
	{	
		ExecConveyorMotorStop(LaneID);
		PlcCtrlPtr->TurnOnConveryerLED(LaneID, false);
		return false;
	}

	//Move To PCB Stop Sensor Position	
	if ( MoveCameraToLaneLEDStopSensorPos(LaneID, bRightSide, bWait) == false )
	{
		ExecConveyorMotorStop(LaneID);
		PlcCtrlPtr->TurnOnConveryerLED(LaneID, false);
		return false; 
	}		

	//Check Pcb Pass Stop Position
	if ( CheckPCBPassStopPosition(LaneID, bRightIn) == false )
	{
		ExecConveyorMotorStop(LaneID);
		PlcCtrlPtr->TurnOnConveryerLED(LaneID, false);
		return false;
	}
		
	ExecConveyorMotorStop(LaneID); 
	PlcCtrlPtr->WriteConveryerClamp(LaneID, true);//夾板	
	PlcCtrlPtr->TurnOnConveryerLED(LaneID, false);
	return true;
}
