//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecPCBInProc(LANE_ID LaneID, bool bWait, bool bStep)//執行進板
{
	if ( CheckLaneWorkMode_Disable(LaneID) == true )
	{	return true; }

	if ( PlcCtrlPtr->CheckPLCReady(false, false ) == false ) 
	{	
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString(); 
		return false;
	}
	const int  UseCameraPcbIn=GetPCBInUseCameraImageMode();
	if ( FN_DISABLE == UseCameraPcbIn )
	{
		if ( MoveCameraToBeforePCBInPosition(true) == false )
		{	return false;	}
	}
	
	bool  bSendLastSignal=false;	
	const bool bCheckThread = false;	
	PlcCtrlPtr->PLC_ReadConveryerSensor(bCheckThread);		
	const bool bPCBIn = PlcCtrlPtr->GetConveryerSensorPCBIn(LaneID);
	const bool bPCBSlow = PlcCtrlPtr->GetConveryerSensorPCBSlow(LaneID);
	const bool bPCBStop = PlcCtrlPtr->GetConveryerSensorPCBStop(LaneID);
	const bool bPCBOut = PlcCtrlPtr->GetConveryerSensorPCBOut(LaneID);	
	if ( true==bPCBIn || true==bPCBSlow || true==bPCBStop || true==bPCBOut )
	{	bSendLastSignal = false;	}
	else
	{	bSendLastSignal = true;	}		
	if ( true == bSendLastSignal )
	{	
		PlcCtrlPtr->WriteSignalToLast(LaneID, true);	
		PostMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_UPDATE_MACHINE_STATES, NULL);
	}

	if ( FN_ENABLE == UseCameraPcbIn )
	{
		if ( ExecPCBInByCamera(LaneID) == false )
		{
			if ( true == bSendLastSignal )
			{	PlcCtrlPtr->WriteSignalToLast(LaneID, false);	}			
			return false;
		}
	}
	else
	{
		if ( PlcCtrlPtr->ExecPCBIn(LaneID, bWait) == false )	
		{	
			if ( true == bSendLastSignal )
			{	PlcCtrlPtr->WriteSignalToLast(LaneID, false);	}
			m_ErrorString = PlcCtrlPtr->GetPLCErrorString(); 
			return false;
		}
	}
	if ( true == bSendLastSignal )
	{	PlcCtrlPtr->WriteSignalToLast(LaneID, false);	}
	if ( true == bStep )
	{
		SetOnlineStateMode(ONLINE_STATE_INSPECTION_STOP);
		SetOnlineStateMode_Lane(ONLINE_STATE_INSPECTION_STOP, LaneID);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecPCBIn2ndProc(LANE_ID LaneID, bool bWait, bool bStep)//執行第2段進板
{	
	if ( CheckLaneWorkMode_Disable(LaneID) == true )
	{	return true; }

	if ( PlcCtrlPtr->CheckPLCReady(false, false ) == false ) 
	{	
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString(); 
		return false;
	}	
	const int  UseCameraPcbIn=GetPCBInUseCameraImageMode();
	if ( FN_DISABLE == UseCameraPcbIn )
	{
		if ( MoveCameraToBeforePCBInPosition(true) == false )
		{	return false;	}
		if ( PlcCtrlPtr->ExecPCBIn2nd(LaneID, bWait) == false )	
		{	
			m_ErrorString = PlcCtrlPtr->GetPLCErrorString(); 
			return false;
		}
	}
	else
	{
		if ( ExecPCBIn2ndByCamera(LaneID) == false )
		{	return false; }
	}
	if ( true == bStep )
	{
		SetOnlineStateMode(ONLINE_STATE_INSPECTION_STOP);
		SetOnlineStateMode_Lane(ONLINE_STATE_INSPECTION_STOP, LaneID);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecPCBIn3rdProc(LANE_ID LaneID, bool bWait, bool bStep)//執行第3段進板
{
	if ( CheckLaneWorkMode_Disable(LaneID) == true )
	{	return true; }

	const int  UseCameraPcbIn=GetPCBInUseCameraImageMode();
	if ( FN_DISABLE == UseCameraPcbIn )
	{
		if ( MoveCameraToBeforePCBInPosition(true) == false )
		{	return false;	}
		if ( PlcCtrlPtr->ExecPCBIn3rd(LaneID, bWait) == false )	
		{	
			m_ErrorString = PlcCtrlPtr->GetPLCErrorString(); 
			return false;
		}
	}
	else
	{
		if ( ExecPCBIn3rdByCamera(LaneID) == false )
		{	return false; }
	}
	if ( true == bStep )
	{
		SetOnlineStateMode(ONLINE_STATE_INSPECTION_STOP);
		SetOnlineStateMode_Lane(ONLINE_STATE_INSPECTION_STOP, LaneID);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecPCBOutProc(LANE_ID LaneID, bool bWait, bool bStep)//執行出板
{
	bool  IsOK = true;
	if ( CheckLaneWorkMode_Disable(LaneID) == true )
	{	return true; }
	if ( false == GetUIEnablePCBOutButton() )
	{	return true;	}
	if ( PlcCtrlPtr->CheckPLCReady(false, false ) == false ) 
	{	
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString(); 
		return false;
	}
	int      i=0;
	CString  str;
	bool    bRecvNextSignal = false;
	bool    bSendToNextSignal=false;
	const bool bCheckThread = false;
	CONNECTED_BUFFER_TYPE NextBufferType = GetSystemParameter().m_NextConnectedBufferType;
	PlcCtrlPtr->PLC_ReadConveryerSensor(bCheckThread);	
	bRecvNextSignal = PlcCtrlPtr->GetNextStationSignal(LaneID);
	if ( CONNECTED_BUFFER_MOVABLE == NextBufferType)
	{
		bool  bNextSignal = false;
		const int SleepTime=50;
		const int SleepCount=200;		
		bSendToNextSignal = true;
		PlcCtrlPtr->WriteSignalToNext(LaneID, true);
		for ( i=0; i<SleepCount; i++ )
		{
			PlcCtrlPtr->PLC_ReadConveryerSensor(bCheckThread);	
			bNextSignal = PlcCtrlPtr->GetNextStationSignal(LaneID);
			if ( true == bNextSignal )
			{	break; }
			if ( SleepTime > 0 )
			{	::Sleep(SleepTime); }
		}		
		bRecvNextSignal = bNextSignal;		
		PlcCtrlPtr->WriteSignalToNext(LaneID, false);
	}
	if ( true == bRecvNextSignal )
	{
		PlcCtrlPtr->WriteSignalToNext(LaneID, true);
		IsOK = PlcCtrlPtr->ExecPCBOut(LaneID, bWait);	
		PlcCtrlPtr->WriteSignalToNext(LaneID, false);
	}
	else
	{	IsOK = PlcCtrlPtr->ExecPCBOutInside(LaneID, bWait);	}	
	if ( false == IsOK )
	{
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString(); 
		return false;		
	}
	if ( true == bStep )
	{
		SetOnlineStateMode(ONLINE_STATE_INSPECTION_STOP);
		SetOnlineStateMode_Lane(ONLINE_STATE_INSPECTION_STOP, LaneID);
	}
	return true;
}
