//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecPCBOutInProc(LANE_ID LaneID, bool bWait, bool bStep)//執行出板帶進板
{	
	if ( CheckLaneWorkMode_Disable(LaneID) == true )
	{	return true; }

	if ( PlcCtrlPtr->CheckPLCReady(false, false ) == false ) 
	{	
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString(); 
		return false;
	}
	const bool LastSignal = PlcCtrlPtr->GetLastStationSignal(LaneID);
	const bool NextSignal = PlcCtrlPtr->GetNextStationSignal(LaneID);
	if ( false==LastSignal || false==NextSignal ) 
	{	return true; }

	if ( MoveCameraToBeforePCBInPosition(true) == false )
	{	return false;	}
	if ( PlcCtrlPtr->ExecPCBOutIn(LaneID, bWait) == false )
	{
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString(); 
		return false;
	}
	if ( true == bStep )
	{
		SetOnlineStateMode(ONLINE_STATE_INSPECTION_STOP);
		SetOnlineStateMode_Lane(ONLINE_STATE_INSPECTION_STOP, LaneID);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecPCBDualRunProc(LANE_ID LaneID, bool bWait, bool bStep, CAOIProject *ProjectPtr, PCB_OUT_DIRECTION eDirection, ONLINE_STATE_MODE StateMode)//執行雙軌出板
{	//20230425	
	bool bSucc=true;
	TEST_RESULT_ID TestResultID = TEST_RESULT_NONE;	
	size_t LaneIndex=GetConveyerAutoRunLaneIdx(LaneID);
	if ( NULL != ProjectPtr )
	{	TestResultID = ProjectPtr->GetProjectResultCurrent().sResultID;	}
	ONLINE_STATE_MODE OnlineStateMode=GetNextOnlineStateMode(StateMode, LaneID, eDirection, TestResultID);	
	bSucc = StartConveyerAutoRunThread(LaneIndex, OnlineStateMode, ProjectPtr, false, true);	
	return bSucc;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecPCBAutoRunProc(LANE_ID LaneID, bool bWait, bool bStep, PCB_OUT_DIRECTION eDirection)//執行自動出板
{	//20230425	
	bool bSucc=true;
	const bool bOn=true;
	PCB_OUT_DIRECTION PCBOutDirection = eDirection;		
	if ( PCB_OUT_DIR_BACKWARD==PCBOutDirection || PCB_OUT_DIR_BACKWARD_OUT==PCBOutDirection )
	{	bSucc = PlcCtrlPtr->ExecPCBAutoBackIn(LaneID, bOn, bWait);	}
	else
	{	bSucc = PlcCtrlPtr->ExecPCBAutoOutIn(LaneID, bOn, bWait);	}	
	if ( bSucc == false )
	{
		SetErrorString(PlcCtrlPtr->GetPLCErrorString());
		return false;
	}
	if ( true == bStep )
	{
		SetOnlineStateMode(ONLINE_STATE_INSPECTION_STOP);
		SetOnlineStateMode_Lane(ONLINE_STATE_INSPECTION_STOP, LaneID);
	}
	return true;
}
