bool CAOIDataCollect::ExecConveyorMotorStop(LANE_ID LaneID)//執行軌道停止
{
	const bool UseV7=GetPCBInUseCameraImageMode_V7();
	if ( true == UseV7 )
	{
		if ( LightCtrlBoard.ExecConveyorMotorStop(LaneID) == false )
		{
			SetErrorString(LightCtrlBoard.GetErrorString());
			return false;
		}	
	}
	else
	{
		if ( PlcCtrlPtr->ExecConveyorMotorStop(LaneID) == false )
		{
			SetErrorString(PlcCtrlPtr->GetPLCErrorString());
			return false;
		}
	}
	return true;
}
