{
	const bool UseV7=GetPCBInUseCameraImageMode_V7();
	if ( true == UseV7 )
	{
		if ( LightCtrlBoard.ExecConveyorMotorRunning(LaneID, On, bPositive, Slow) == false )
		{
			SetErrorString(LightCtrlBoard.GetErrorString());
			return false;
		}
	}
	else
	{
		if ( PlcCtrlPtr->ExecConveyorMotorRunning(LaneID, On, bPositive, Slow) == false )
		{
			SetErrorString(PlcCtrlPtr->GetPLCErrorString());
			return false;
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ResetPCBOKNGSignal(LANE_ID LaneID)//清除OK/NG訊號
{
	CString str;
	CString sOnOff=_T("OFF");
	CString sLaneID=AOIDataDefine.GetLaneIDText(LaneID);
	const bool bTurnOn=false;

	WaitForPCBOKNGSignalOnDelayTime(LaneID);
	str.Format(_T("Set OK/NG Signal %s [%s]"), sOnOff, sLaneID);
	SaveControlCenterLog(str);	
	
	PlcCtrlPtr->WriteOKSignalToNext(LaneID, false); 
	PlcCtrlPtr->WriteNGSignalToNext(LaneID, false); 
	SetPCBOKNGSignalOnTickCount(LaneID, 0);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SendPCBOKNGSignal(LANE_ID LaneID, bool bNG)//發送OK/NG訊號
{	
	CString str;
	CString sOnOff=_T("On");
	CString sLaneID=AOIDataDefine.GetLaneIDText(LaneID);
	if ( true == bNG )
	{	str.Format(_T("Set NG Signal %s [%s]"), sOnOff, sLaneID);		}
	else
	{	str.Format(_T("Set OK Signal %s [%s]"), sOnOff, sLaneID);		}
	SaveControlCenterLog(str);
	
	if ( true == bNG )
	{	PlcCtrlPtr->WriteNGSignalToNext(LaneID, true);		}
	else
	{	PlcCtrlPtr->WriteOKSignalToNext(LaneID, true);		}	
	SetPCBOKNGSignalOnTickCount(LaneID);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecReloadProject(LANE_ID LaneID)//在線重載專案
{
	CAOIProject *ProjectPtr = this->GetActiveProject();
	if ( NULL == ProjectPtr  ) { return true; }	
	//const bool OnlineTuningEnable = ProjectPtr->GetProjectOnlineTuningEnable();
	//if ( false == OnlineTuningEnable ) { return true; }
	
	double  Time=0;
	CString str;
	CString Folder;	
	CString filename;	
	CString tmpfilename;
	CString FileMainName;		
	CString OldFilenameTmp;
	CString OfflineFile;
	CString OfflineFolder;
	CString OfflineFiducial;

	LARGE_INTEGER fnEnd;
	LARGE_INTEGER fnEnd2;
	LARGE_INTEGER fnStart;
	LARGE_INTEGER fnStart2;		
	PROJECT_LINK_SERVER_MODE ProjectLinkServerMode;	
	DISTRICT_ID DistrictID = ProjectPtr->GetProjectActDistrictID();	

	HWND hWnd = GetMainFrameWnd();
	ONLINE_STATE_MODE OnlineState = GetOnlineStateMode();	

	SetOnlineTuningEnable(false);
	if ( ProjectPtr->CheckProjectOnlineTuningEnable() == false )
	{	return true;	}
	SetOnlineTuningEnable(true);	

	bool        bNewProject=false;
	bool        bNewLibrary=false;	
	ProjectLinkServerMode = ProjectPtr->GetProjectParameter().m_ProjectLinkServerMode;
	const bool  bServerLibraryEnabled = CheckServerLibraryEnabled(ProjectLinkServerMode);
	/*
	//確認伺服器相同專案下的共享檔案時間
	if ( ProjectPtr->CheckProjectServerProjectShareFileSavedDateTime(bNewProject) == true )//
	{	
		if ( true == bNewProject )
		{
			if ( ProjectPtr->ReadProjectServerProjectLinkMode(ProjectLinkServerMode) == false )
			{
				m_ErrorString = _T("Error, Read Project Server Link Mode Fault");		
				return false;
			}
			if ( PROJECT_LINK_SERVER_DISABLE != ProjectLinkServerMode )//開啟專案連結伺服器就不使用此功能
			{	return true; }	
		}		
	}
	//確認伺服器下的共享檔案時間
	if ( true == bServerLibraryEnabled )//使用外部資料庫	
	{
		if ( ProjectPtr->CheckProjectServerShareFileSavedDateTime(bNewLibrary) == true )
		{
			if ( true == bNewLibrary )
			{
				ProjectLinkServerMode = ProjectPtr->GetProjectParameter().m_ProjectLinkServerMode;			
				if ( PROJECT_LINK_SERVER_DISABLE != ProjectLinkServerMode )//開啟專案連結伺服器就不使用此功能
				{	return true; }	
			}
		}
	}
	*/
	ProjectLinkServerMode = ProjectPtr->GetProjectParameter().m_ProjectLinkServerMode;			
	if ( CheckServerLibraryCanOnlineTuning(ProjectLinkServerMode) == false )
	{	return true; }	

	if ( ProjectPtr->CheckProjectOfflineSaveFinish() == false )	
	{	return true; }

	SetOnlineStateMode(ONLINE_STATE_PROJECT_RELOAD);	
	SetOnlineStateMode_Lane(ONLINE_STATE_PROJECT_RELOAD, LaneID);
	SendCallbackWndMessage(MSG_EDIT_MAIN_VIEW_WND, WPARAM_REDRAW_VIEW_WND, NULL);
	//if ( NULL != hWnd )
	//{	::SendMessage(hWnd, MSG_MAIN_FRAME_MESSAGE, WPARAM_PROJECT_CLOSE, NULL);	}

	if ( ProjectPtr->GetProjectSaveFiledUsingThread() == true )
	{
		if ( ProjectPtr->IdleProjectSaveFieldThread(true)==false ||
			ProjectPtr->IdleProjectCopyFileThread(true)==false 
		)
		{
			m_ErrorString = ProjectPtr->GetErrorString();		
			return false; 
		}
		if ( WaitForFieldFrameReleaseThreadFinish() == false )
		{	return true; }
	}

	filename = ProjectPtr->GetProjectShowName();
	OldFilenameTmp = ProjectPtr->GetProjectFileName();	

	JetAPI::SetFuncTimeStart(fnStart2);
	JetAPI::SetFuncTimeStart(fnStart);
	if ( CreateTempProjectFile(filename, tmpfilename) == false )
	{	return false;	}
	JetAPI::SetFuncTimeEnd(fnEnd);//設定函式結束時間
	Time = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);//計算函式經過時間
	str.Format(_T("ReloadProject::CreateTempProjectFile Time=%.3f ms"), Time);
	SaveCurrentProcess(str);

	JetAPI::ExtractMainFileName(filename, Folder);
	OfflineFolder = AOIDataDefine.GetProjectOfflineFolderName(Folder);
	OfflineFile = AOIDataDefine.GetProjectOfflineFileName(OfflineFolder, DistrictID);
	OfflineFiducial = AOIDataDefine.GetProjectOfflineFdName(OfflineFolder, DistrictID);

#ifndef OFFLINE_VERSION
	ProjectPtr->ResetProjectOnlineTuningSavedCount();
	ProjectPtr->ClearProjectOnlineTuningFolder();//清除目前線上調機資料夾
#endif//OFFLINE_VERSION

	JetAPI::SetFuncTimeStart(fnStart);
	if ( this->StopLoadRepairFileThread(true) == false ) 
	{	return false;	}
	JetAPI::SetFuncTimeEnd(fnEnd);//設定函式結束時間
	Time = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);//計算函式經過時間
	str.Format(_T("ReloadProject::StopLoadRepairFileThread Time=%.3f ms"), Time);
	SaveCurrentProcess(str);

	JetAPI::SetFuncTimeStart(fnStart);	
	if ( ProjectPtr->ReLoadProjectFile(tmpfilename) == false )
	{	
		m_ErrorString = ProjectPtr->GetErrorString();
		StartLoadRepairFileThread(false);
		return false;
	}
	JetAPI::SetFuncTimeEnd(fnEnd);//設定函式結束時間
	Time = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);//計算函式經過時間
	str.Format(_T("ReloadProject::ReLoadProjectFile Time=%.3f ms"), Time);
	SaveCurrentProcess(str);

	StartLoadRepairFileThread(false);	

	JetAPI::SetFuncTimeStart(fnStart);
	if ( ProjectPtr->BuildProjectImageConfig() == false )
	{	
		m_ErrorString = ProjectPtr->GetErrorString();	
		return false;
	}
	JetAPI::SetFuncTimeEnd(fnEnd);//設定函式結束時間
	Time = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);//計算函式經過時間
	str.Format(_T("ReloadProject::BuildProjectImageConfig Time=%.3f ms"), Time);
	SaveCurrentProcess(str);

	if ( JetAPI::IsFileExist(OfflineFile) == true )
	{
		JetAPI::SetFuncTimeStart(fnStart);
		if ( ProjectPtr->LoadProjectProgramOfflineFile(OfflineFile) == false )
		{	
			m_ErrorString = ProjectPtr->GetErrorString();		
			return false;
		}
		JetAPI::SetFuncTimeEnd(fnEnd);//設定函式結束時間
		Time = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);//計算函式經過時間
		str.Format(_T("ReloadProject::LoadProjectProgramOfflineFile Time=%.3f ms"), Time);
		SaveCurrentProcess(str);

		JetAPI::SetFuncTimeStart(fnStart);
		if ( ProjectPtr->LoadProjectOfflineFdFile(OfflineFiducial) == false )
		{	
			m_ErrorString = ProjectPtr->GetErrorString();		
			return false;
		}
		JetAPI::SetFuncTimeEnd(fnEnd);//設定函式結束時間
		Time = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);//計算函式經過時間
		str.Format(_T("ReloadProject::LoadProjectOfflineFdFile Time=%.3f ms"), Time);
		SaveCurrentProcess(str);
	}

	JetAPI::SetFuncTimeStart(fnStart);
	//ProjectPtr->DeleteProjectTempFile(OldFilenameTmp);	
	//轉入執行緒, 比較快
	AddRemoveFolder_ProjectTemp(OldFilenameTmp);	
	::DeleteFile(OldFilenameTmp);
	JetAPI::SetFuncTimeEnd(fnEnd);//設定函式結束時間
	Time = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);//計算函式經過時間
	str.Format(_T("ReloadProject::DeleteProjectTempFile Time=%.3f ms"), Time);
	SaveCurrentProcess(str);

	JetAPI::SetFuncTimeStart(fnStart);
	ApplyProjectParameterToSystem(ProjectPtr);
	JetAPI::SetFuncTimeEnd(fnEnd);//設定函式結束時間
	Time = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);//計算函式經過時間
	str.Format(_T("ReloadProject::ApplyProjectParameterToSystem Time=%.3f ms"), Time);
	SaveCurrentProcess(str);

	SetOfflineFileName(OfflineFile);
	JetAPI::SetFuncTimeEnd(fnEnd);//設定函式結束時間
	Time = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);//計算函式經過時間
	str.Format(_T("ReloadProject::Others Time=%.3f ms"), Time);
	SaveCurrentProcess(str);

	JetAPI::SetFuncTimeEnd(fnEnd2);//設定函式結束時間
	Time = JetAPI::CalcFuncTimeSpent(fnStart2, fnEnd2);//計算函式經過時間
	str.Format(_T("ReloadProject::All Time=%.3f ms"), Time);
	SaveCurrentProcess(str);

	LogOperCtrl.SaveLogProject(ProjectPtr, str);		

	if ( NULL != hWnd )
	{	::SendMessage(hWnd, MSG_MAIN_FRAME_MESSAGE, WPARAM_PROJECT_SWITCH, NULL);	}

	SetOnlineStateMode(OnlineState);	
	SetOnlineStateMode_Lane(ONLINE_STATE_PROJECT_RELOAD, LaneID);
	SendCallbackWndMessage(MSG_EDIT_MAIN_VIEW_WND, WPARAM_REDRAW_VIEW_WND, NULL);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ClearProjectStatisticBackup(TProjectStatisticBackup &StatisticBackup)//清除專案統計資料
{
	size_t       i=0;
	const size_t ComponentCount = StatisticBackup.ProjectComponentList.size();
	for ( i=0; i<ComponentCount; i++ )
	{
		if ( NULL == StatisticBackup.ProjectComponentList[i] ) { continue; }
		AOIObjManager.DestroyComponentObj(StatisticBackup.ProjectComponentList[i]);
		StatisticBackup.ProjectComponentList[i] = NULL;
	}
	StatisticBackup.ProjectComponentList.clear();
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecReloadServerProject(LANE_ID LaneID)//在線重載伺服器專案
{
	CAOIProject *ProjectPtr = this->GetActiveProject();
	if ( NULL == ProjectPtr  ) { return true; }	

	CString  str;	
	double   Time=0;
	bool     bIsOK = true;
	LARGE_INTEGER fnEnd;
	LARGE_INTEGER fnEnd2;
	LARGE_INTEGER fnStart;
	LARGE_INTEGER fnStart2;			
	PROJECT_LINK_SERVER_MODE ProjectLinkServerMode;	
	ONLINE_STATE_MODE OnlineState = GetOnlineStateMode();	
	bool        bLockFile=false;		
	bool        bNewProject=false;
	bool        bNewLibrary=false;
	ProjectLinkServerMode = ProjectPtr->GetProjectParameter().m_ProjectLinkServerMode;
	const bool  bServerLibraryEnabled = CheckServerLibraryEnabled(ProjectLinkServerMode);

	//確認伺服器相同專案下的共享檔案時間
	ProjectPtr->CheckProjectServerProjectShareFileSavedDateTime(bNewProject);
	if ( true == bServerLibraryEnabled )//使用外部資料庫
	{		
		ProjectPtr->CheckProjectServerShareFileSavedDateTime(bNewLibrary);
		if ( true == bNewLibrary )
		{	bNewProject = false;	}
	}	
	if ( false==bNewLibrary && false==bNewProject )
	{	return true;	}
	if ( ProjectPtr->CreateProjectServerLockFile(bLockFile) == false )
	{
		m_ErrorString = ProjectPtr->GetErrorString();		
		return false; 
	}
	if ( true == bLockFile )
	{	return true; }

	if ( ProjectPtr->GetProjectSaveFiledUsingThread() == true )
	{
		if ( ProjectPtr->IdleProjectSaveFieldThread(true)==false ||
			ProjectPtr->IdleProjectCopyFileThread(true)==false 
			)
		{
			m_ErrorString = ProjectPtr->GetErrorString();		
			return false; 
		}
		if ( WaitForFieldFrameReleaseThreadFinish() == false )
		{	return true; }
	}


	if ( true == bNewProject )
	{	
		if ( ProjectPtr->ReadProjectServerProjectLinkMode(ProjectLinkServerMode) == false )
		{
			ProjectPtr->DeleteProjectServerLockFile();
			m_ErrorString = _T("Error, Read Project Server Link Mode Fault");		
			return false;
		}
		if ( PROJECT_LINK_SERVER_DISABLE == ProjectLinkServerMode )
		{
			ProjectPtr->DeleteProjectServerLockFile();			
			return true; 
		}
		
		if ( StopLoadRepairFileThread(true) == false ) 
		{
			ProjectPtr->DeleteProjectServerLockFile();			
			return false;	
		}	
		SetOnlineStateMode(ONLINE_STATE_PROJECT_RELOAD_SERVER);	
		SetOnlineStateMode_Lane(ONLINE_STATE_PROJECT_RELOAD_SERVER, LaneID);
		SendCallbackWndMessage(MSG_EDIT_MAIN_VIEW_WND, WPARAM_REDRAW_VIEW_WND, NULL);
		JetAPI::SetFuncTimeStart(fnStart2);	

		JetAPI::SetFuncTimeStart(fnStart);
		CString ProjectFoler = GetAOIServerProjectFolder();
		CString LibraryFoler = GetAOIServerLibraryFolder();	
		CreateDirectory(ProjectFoler, NULL);
		CreateDirectory(LibraryFoler, NULL);		
		if ( ProjectPtr->LoadProjectFileFromServerProject(ProjectFoler, LibraryFoler) == false)
		{	
			ProjectPtr->DeleteProjectServerLockFile();			
			m_ErrorString = ProjectPtr->GetErrorString();
			StartLoadRepairFileThread(false);
			return false;
		}
		JetAPI::SetFuncTimeEnd(fnEnd);//設定函式結束時間
		Time = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);//計算函式經過時間
		str.Format(_T("ReloadServerProject::LoadProjectFileFromServerProject Time=%.3f ms"), Time);
		SaveCurrentProcess(str);
	}
	else if ( true == bNewLibrary )
	{
		ProjectLinkServerMode = ProjectPtr->GetProjectParameter().m_ProjectLinkServerMode;		
		if ( PROJECT_LINK_SERVER_DISABLE == ProjectLinkServerMode )
		{
			ProjectPtr->DeleteProjectServerLockFile();			
			return true; 
		}		
		if ( StopLoadRepairFileThread(true) == false ) 
		{
			ProjectPtr->DeleteProjectServerLockFile();			
			return false;	
		}
		SetOnlineStateMode(ONLINE_STATE_PROJECT_RELOAD_SERVER);	
		SetOnlineStateMode_Lane(ONLINE_STATE_PROJECT_RELOAD_SERVER, LaneID);
		SendCallbackWndMessage(MSG_EDIT_MAIN_VIEW_WND, WPARAM_REDRAW_VIEW_WND, NULL);
		JetAPI::SetFuncTimeStart(fnStart2);		
		
		const bool bLoadAll = false;
		const bool bIncNewModel = false;	
		JetAPI::SetFuncTimeStart(fnStart);
		CString LibraryFoler = GetAOIServerLibraryFolder();			
		CreateDirectory(LibraryFoler, NULL);		
		if ( ProjectPtr->LoadProjectLibryFromServerLibrary(LibraryFoler, bIncNewModel, bLoadAll) == false)
		{	
			ProjectPtr->DeleteProjectServerLockFile();			
			m_ErrorString = ProjectPtr->GetErrorString();
			StartLoadRepairFileThread(false);
			return false;
		}
		JetAPI::SetFuncTimeEnd(fnEnd);//設定函式結束時間
		Time = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);//計算函式經過時間
		str.Format(_T("ReloadServerProject::LoadProjectLibryFromServerLibrary Time=%.3f ms"), Time);
		SaveCurrentProcess(str);
	}	
	ProjectPtr->DeleteProjectServerLockFile();	
	StartLoadRepairFileThread(false);			

	JetAPI::SetFuncTimeEnd(fnEnd2);//設定函式結束時間
	Time = JetAPI::CalcFuncTimeSpent(fnStart2, fnEnd2);//計算函式經過時間
	str.Format(_T("ReloadServerProject::All Time=%.3f ms"), Time);
	SaveCurrentProcess(str);

	LogOperCtrl.SaveLogProject(ProjectPtr, str);

	SetOnlineStateMode(OnlineState);	
	SetOnlineStateMode_Lane(OnlineState, LaneID);
	SendCallbackWndMessage(MSG_EDIT_MAIN_VIEW_WND, WPARAM_REDRAW_VIEW_WND, NULL);		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::WriteOfflineSaveFinish(const UUID &uuid, LPCTSTR filename)//寫入離線存檔完成
{	
#ifdef OFFLINE_VERSION	
	CString KeyName;
	CString String;	
	KeyName = _T("Offline Saved");
	String.Format(_T("%d"), FN_ENABLE);
	if ( WriteProjectShareFile(uuid, filename, KeyName, String) == false ) 
	{	return false; }
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckOfflineSaveFinish(const UUID &uuid, LPCTSTR filename)//確認離線存檔完成
{
#ifndef OFFLINE_VERSION
	CString KeyName;
	CString Default;	
	CString String;	
	KeyName = _T("Offline Saved");
	String.Format(_T("%d"), FN_DISABLE);
	Default.Format(_T("%d"), FN_DISABLE);	
	if ( ReadProjectShareFile(uuid, filename, KeyName, Default, String) == false ) 
	{	return false; }

	const int nSaveFinish = _ttoi(String);
	if ( FN_ENABLE == nSaveFinish )
	{	
		WriteProjectShareFile(uuid, filename, KeyName, Default);	
		return true;
	}
	return false;
#endif//OFFLINE_VERSION
	return false;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::WriteProjectShareFile(const UUID &uuid, LPCTSTR PrgName, LPCTSTR KeyName, LPCTSTR Value)//寫入專案共享資料	
{
	if ( WriteProjectShareFileFn(uuid, PrgName, KeyName, Value) == false )
	{
		SetSystemExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::WriteProjectShareFileFn(const UUID &uuid, LPCTSTR PrgName, LPCTSTR KeyName, LPCTSTR Value)//寫入專案共享資料	
{	
	CString Section;	
	CString FileFolder;
	CString IniFilename;
	CString mainFilename;
	TCHAR   strUUID[MAX_JET_PATH]=_T("");
	JetAPI::ExtractFolder(PrgName, FileFolder);
	JetAPI::ExtractMainFileNameNoPath(PrgName, mainFilename);
	IniFilename.Format(_T("%s\\%s"), FileFolder, _T("Project.INI"));
	Section = mainFilename;	
#ifndef _UNICODE
	JetAPI::UUIDToStringA(uuid, strUUID);
#else
	JetAPI::UUIDToStringW(uuid, strUUID);
#endif//_UNICODE
	Section = strUUID;
	if ( SaveINIData(Section, KeyName, Value, IniFilename, m_ErrorString) == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ReadProjectShareFile(const UUID &uuid, LPCTSTR PrgName, LPCTSTR KeyName, LPCTSTR Default, CString &Value)//讀取專案共享資料
{
	if ( ReadProjectShareFileFn(uuid, PrgName, KeyName, Default, Value) == false )
	{
		SetSystemExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ReadProjectShareFileFn(const UUID &uuid, LPCTSTR PrgName, LPCTSTR KeyName, LPCTSTR Default, CString &Value)//讀取專案共享資料
{
	int nSaveFinish = 0;
	CString Section;	
	const size_t StringSize = MAX_JET_PATH;
	TCHAR String[StringSize] = _T("");	
	TCHAR   strUUID[MAX_JET_PATH] = _T("");
	CString FileFolder;
	CString IniFilename;
	CString mainFilename;
	JetAPI::ExtractFolder(PrgName, FileFolder);
	JetAPI::ExtractMainFileNameNoPath(PrgName, mainFilename);

	IniFilename.Format(_T("%s\\%s"), FileFolder, _T("Project.INI"));
	Section = mainFilename;
#ifndef _UNICODE
	JetAPI::UUIDToStringA(uuid, strUUID);
#else
	JetAPI::UUIDToStringW(uuid, strUUID);
#endif//_UNICODE
	Section = strUUID;
	if ( LoadINIData(Section, KeyName, Default, String, StringSize, IniFilename, false, m_ErrorString) == false )
	{	return false; }
	Value = String;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MoveCameraToLaneLEDSlowSensorPos(LANE_ID LaneID, bool RightSide, bool Wait)//移動至PCB減速感測器位置
{	
	double PosX = MotionCtrlPtr->GetMotionLaneLedSlowPosX(LaneID, RightSide);
	double PosY = MotionCtrlPtr->GetMotionLaneLedSlowPosY(LaneID, RightSide);
	MotionCtrlPtr->XYMoveTo(PosX, PosY);
	if ( true == Wait )
	{	MotionCtrlPtr->WaitForMotionStop();	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MoveCameraToLaneLEDStopSensorPos(LANE_ID LaneID, bool RightSide, bool Wait)//移動至PCB停板感測器位置
{	
	double PosX = MotionCtrlPtr->GetMotionLaneLedStopPosX(LaneID, RightSide);
	double PosY = MotionCtrlPtr->GetMotionLaneLedStopPosY(LaneID, RightSide);
	MotionCtrlPtr->XYMoveTo(PosX, PosY);
	if ( true == Wait )
	{	MotionCtrlPtr->WaitForMotionStop();	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MoveCameraToBeforePCBInPosition(bool Wait)//移動至進板前位置
{
	const int MoveCameraBeforePCBIn = GetMoveCameraBeforePCBIn();
	if ( FN_DISABLE == MoveCameraBeforePCBIn ) { return true; }
	
	if ( MotionCtrlPtr->MoveToBeforePCBInPos() == false )
	{
		this->m_ErrorString = MotionCtrlPtr->GetErrorString();
		return false;
	}

	if ( true == Wait )
	{
		if ( MotionCtrlPtr->WaitForMotionStop(false) == false )
		{
			this->m_ErrorString = MotionCtrlPtr->GetErrorString();
			return false;
		}	
	}
	return true;
}
//-------------------------------------------------------------------------------------//
CAOIProject* CAOIDataCollect::GetConveyerFirstProjectPtr(LANE_ID LaneID)//取得軌道上的第1個專案
{
	CAOIProject *ProjectPtr = NULL;	
	const TSystemParameter &SystemParam = GetSystemParameter();
	if ( FN_ENABLE == SystemParam.m_OnlineOpenProjectCameraBarcode )
	{	ProjectPtr = GetOpenProjectProjectPtr();	}
	else
	{	
		MULTI_LANE_MODE MultiLaneMode = CheckMultiLaneMode();
		if ( MULTI_LANE_2 == MultiLaneMode )
		{	ProjectPtr = GetLaneProjectPtr(LaneID, 0, true);	}
		else
		{	ProjectPtr = GetActiveProject();	}			
	}
	return ProjectPtr;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MoveCameraToProjectFocusPos(CAOIProject *ProjectPtr)//移動至專案焦距位置
{
	if ( CheckProjectPtr(ProjectPtr) == false ) { return false; }		
	const double FocusPos = ProjectPtr->GetProjectFocusPos();
	if ( MotionCtrlPtr->MoveTo(AXIS_Z, FocusPos, MOTION_MOVING_NORMAL) == false )
	{
		SetErrorString(MotionCtrlPtr->GetErrorString());
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MoveCameraToConveyerFirstPos(TOnlineProcParam &Param, CAOIProject *ProjectPtr, bool bResetOKNG)
{	
	const LANE_ID LaneID = Param.eLaneID;
	const TASK_MODE TaskMode = Param.eTaskMode;//任務模式
	if ( TASK_INSPECT_PROJECT != TaskMode )
	{	return true; }

	const bool SensorPcbStop = PlcCtrlPtr->GetConveryerSensorPCBStop(LaneID);
	if ( false == SensorPcbStop )
	{	return true; }
	
	ONLINE_STATE_MODE OnlineStateMode_AutoCali=CheckExecOnlineAutoCalibrationMode();
	if ( ONLINE_STATE_RETURN != OnlineStateMode_AutoCali )
	{
		switch ( OnlineStateMode_AutoCali )
		{
		case ONLINE_STATE_AUTO_CALIBRATION_XYZ_HOME:
			if ( ExecOnlineProcAutoCalibration_XYZ_HomeMoveToTarget() == false ) { return false; }
			break;
		case ONLINE_STATE_AUTO_CALIBRATION_2D_CURRENT:
			if ( ExecOnlineProcAutoCalibration_2D_CurrentMoveToTarget() == false ) { return false; }
			break;
		case ONLINE_STATE_AUTO_CALIBRATION_3D_CURRENT:			
		case ONLINE_STATE_AUTO_CALIBRATION_3D_ZERO_PLANE:			
		case ONLINE_STATE_AUTO_CALIBRATION_3D_HEIGHT_FACTOR:
			if ( ExecOnlineProcAutoCalibration_3D_VerifyMoveToTarget() == false ) { return false; }
			break;
		}
		return true;
	}	
	
	if ( NULL == ProjectPtr )
	{	return true; }

	//if ( NULL == ProjectPtr )
	//{	ProjectPtr = GetConveyerFirstProjectPtr(LaneID);	}
	if ( NULL != ProjectPtr )
	{
		LockThread();		
		if ( GetSwitchMultiLine_NextLaneID() == LANE_ID_NULL )
		{
			SetSwitchMultiLine_NextLaneID(LaneID);
			if ( MoveCameraToProjectFirstPos(ProjectPtr, LaneID, DISTRICT_ID_A, bResetOKNG) == false )
			{
				UnlockThread();
				return false; 
			}
		}
		UnlockThread();
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MoveCameraToProjectFirstPos(CAOIProject *ProjectPtr, LANE_ID LaneID, DISTRICT_ID  DistrictID, bool bResetOKNG)//移動至專案第1個位置
{
	if ( CheckProjectPtr(ProjectPtr) == false ) { return false; }

	TPOINT3D     StagePos;		
	const size_t ProjectCount = GetLaneProjectCount(LaneID);
	if ( ProjectPtr->GetProjectFirstStagePos(ProjectCount, DistrictID, StagePos) == true ) 
	{
		MapStagePosLaneByLaneID(StagePos.x, StagePos.y, StagePos.z, LaneID);
		MotionCtrlPtr->XYZMoveTo(StagePos.x, StagePos.y, StagePos.z);	
	}
	if ( true == bResetOKNG )
	{
		SaveControlCenterLog(_T("MoveCameraToProjectFirstPos"));//中控模式不會清除
		ResetPCBOKNGSignal(LaneID, ProjectPtr->GetProjectParameter().m_DefectHandleMode);
		SetIsNeedResetOKNGSignal(false);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecMemoryTest()//記憶體測試
{
	return true;
#ifndef OFFLINE_VERSION
	const size_t Div = 1024;	
	MEMORYSTATUSEX MemStatusKB;
	MEMORYSTATUSEX MemStatusMB;
	MEMORYSTATUSEX MemStatusGB;
	MEMORYSTATUSEX MemStatusBytes;

	::memset(&MemStatusKB, 0x00, sizeof(MEMORYSTATUSEX));
	::memset(&MemStatusMB, 0x00, sizeof(MEMORYSTATUSEX));
	::memset(&MemStatusGB, 0x00, sizeof(MEMORYSTATUSEX));
	::memset(&MemStatusBytes, 0x00, sizeof(MEMORYSTATUSEX));

	MemStatusKB.dwLength = sizeof (MEMORYSTATUSEX);
	MemStatusMB.dwLength = sizeof (MEMORYSTATUSEX);
	MemStatusGB.dwLength = sizeof (MEMORYSTATUSEX);
	MemStatusBytes.dwLength = sizeof (MEMORYSTATUSEX);

	BOOL bRes = ::GlobalMemoryStatusEx(&MemStatusBytes);
	if ( FALSE == bRes ) 
	{
		m_ErrorString.Format(_T("Error, GlobalMemoryStatusEx Fault"));
		return false; 
	}
	MemStatusKB = MemStatusBytes;
	MemStatusKB.ullTotalPhys /= Div;
	MemStatusKB.ullAvailPhys /= Div;
	MemStatusKB.ullTotalPageFile /= Div;
	MemStatusKB.ullAvailPageFile /= Div;
	MemStatusKB.ullTotalVirtual /= Div;
	MemStatusKB.ullAvailVirtual /= Div;
	MemStatusKB.ullAvailExtendedVirtual /= Div;

	MemStatusMB = MemStatusKB;
	MemStatusMB.ullTotalPhys /= Div;
	MemStatusMB.ullAvailPhys /= Div;
	MemStatusMB.ullTotalPageFile /= Div;
	MemStatusMB.ullAvailPageFile /= Div;
	MemStatusMB.ullTotalVirtual /= Div;
	MemStatusMB.ullAvailVirtual /= Div;
	MemStatusMB.ullAvailExtendedVirtual /= Div;

	MemStatusGB = MemStatusMB;
	MemStatusGB.ullTotalPhys /= Div;
	MemStatusGB.ullAvailPhys /= Div;
	MemStatusGB.ullTotalPageFile /= Div;
	MemStatusGB.ullAvailPageFile /= Div;
	MemStatusGB.ullTotalVirtual /= Div;
	MemStatusGB.ullAvailVirtual /= Div;
	MemStatusGB.ullAvailExtendedVirtual /= Div;

	size_t       i=0;
	IMAGE_PTR    ImagePtr=NULL;
#ifdef _X64
	const size_t TestMemorySize = (MemStatusBytes.ullAvailPhys/10)*9;
#else
	const size_t TestMemorySize = (MemStatusBytes.ullAvailVirtual/10)*9;
#endif//_X64
	const IMAGE_SIZE ImageW = GetCameraImageW(PRIMARY_CAMERA_ID);
	const IMAGE_SIZE ImageH = GetCameraImageH(PRIMARY_CAMERA_ID);
	const IMAGE_SIZE BitCount = 24;
	const IMAGE_SIZE ImageStep = JetAPI::GetBMPImagePixelsPerLine(ImageW, BitCount, 4);
	const size_t BufferSize = ImageAPI.CalcBufferSize(ImageStep, ImageH);
	const size_t BufferCount = TestMemorySize/BufferSize;
	std::vector<IMAGE_PTR> ImagePtrList;

	for ( i=0; i<BufferCount; i++ )
	{
		ImagePtr = new IMAGE_DATA[BufferSize];
		if ( NULL == ImagePtr )
		{	break; }
		::memset(ImagePtr, 0x00, sizeof(IMAGE_DATA)*BufferSize);
		ImagePtrList.push_back(ImagePtr);
	}

	const size_t ImagePtrCount = ImagePtrList.size();
	for ( i=0; i<ImagePtrCount; i++ )
	{
		ImagePtr = ImagePtrList[i];
		if ( NULL == ImagePtr ) { continue; }
		delete[] ImagePtr; ImagePtr=NULL;
	}
	ImagePtrList.clear();
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckCanRetrieveCameraImage()//確認是否可以接收相機影像
{
	bool bRetrieve = true;
	return bRetrieve;

	const TASK_MODE TaskMode = GetTaskMode();
	switch ( TaskMode )
	{
	case TASK_PROJECT_MAP://任務-專案底圖
	case TASK_ALIGN_PROJECT://任務-對齊專案
	case TASK_EXPORT_OFFLINE://任務-匯出離線專案
	case TASK_TUNING_PROJECT://任務-檢測調適專案
	case TASK_TUNING_OFFLINE://任務-檢測離線專案
	case TASK_INSPECT_PROJECT://任務-檢測檢測專案
	case TASK_EXPORT_COMPONENT://任務-輸出零件圖
	case TASK_LANE_BYPASS://任務-軌道流片模式
		bRetrieve = false;
		break;
	default:
		bRetrieve = true;
		break;
	}
	return bRetrieve;	
}
