//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ModifyCameraUniFrame(const std::vector<TFrameParam> &FrameParamList)//修正相機通用畫面列表	
{
	LARGE_INTEGER fnEnd;
	LARGE_INTEGER fnStart;
	LARGE_INTEGER End;
	LARGE_INTEGER Start;
	CString      str;
	bool         IsOK = true;
	int          DLPIndex=0;
	size_t       i=0, j=0, k=0;
	size_t       ImgIdx=0;	
	size_t       PatternCount=0;
	size_t       BufferSize=0;	
	size_t       TotalImageCount = 0;
	CAMERA_ID    CameraID;
	RECT         ImageRect={0};
	FRAME_TYPE   FrameType;	
	const size_t MaxImageCount=128;
	const size_t MaxDLPCount = DLP_CAST_COUNT;
	IMAGE_SIZE   ImageW[MaxImageCount]={0};
	IMAGE_SIZE   ImageH[MaxImageCount]={0};
	IMAGE_SIZE   ImageStep[MaxImageCount]={0};
	IMAGE_SIZE   BitCount[MaxImageCount]={0};
	IMAGE_PTR    ImagePtrM=NULL;
	IMAGE_PTR    ImagePtr[MaxImageCount]={NULL};

	TCastParam   CastParam[MaxDLPCount];	
	TFrameParam  FrameParam;
	TSliceParam *SliceParamPtr=NULL;
	double       SliceGainValue=0.0;
	unsigned int FrameImageCount = 0;//影像張數	
	unsigned int SliceUniqueID=SLICE_UNIQUE_ID_NULL;
	const size_t FrameCount = FrameParamList.size();

	long idx=0;
	long Imageidx[MAX_CAMERA_COUNT]={0};
	long ImageCount[MAX_CAMERA_COUNT]={0};
	long RingIndex[MAX_CAMERA_COUNT]={0};
	long RingListSize[MAX_CAMERA_COUNT]={0};	
	if ( 0 == FrameCount ) { return true; }

	str.Format(_T("CAOIDataCollect::ModifyCameraUniFrame Start"));
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	JetAPI::SetFuncTimeStart(fnStart);	
	for ( i=0; i<MaxImageCount; i++ )
	{
		ImageW[i] = 0;
		ImageH[i] = 0;
		ImageStep[i] = 0;
		BitCount[i] = 0;
		ImagePtr[i] = NULL;
	}
	
	for ( i=0; i<MAX_CAMERA_COUNT; i++ )
	{
		CameraID = (CAMERA_ID)(i);
		ImageCount[i] = CameraCtrl.GetImageCallbackCount(CameraID);		
		RingIndex[i] = CameraCtrl.GetCameraRingBufferCurrentIndex(CameraID);
		RingListSize[i]  = CameraCtrl.GetCameraRingBufferListSize(CameraID);

		Imageidx[i] = RingIndex[i];
		Imageidx[i] = Imageidx[i]-ImageCount[i];
		//Imageidx[i] = Imageidx[i]+m_CameraImageReceieveCount;
		if ( Imageidx[i] < 0 ) { Imageidx[i] += RingListSize[i];  }
	}	
	
	for ( i=0; i<FrameCount; i++ )
	{
		FrameParam = FrameParamList[i];	

		for ( j=0; j<MaxImageCount; j++ )
		{	ImagePtr[j] = NULL; }

		FrameType = FrameParam.FrameType;
		FrameImageCount = FrameParam.FrameImageCount;

		ImgIdx=0;
		SliceUniqueID = FrameParam.FrameSliceID1;
		if ( SLICE_UNIQUE_ID_DLP != SliceUniqueID )
		{	
			if ( SLICE_UNIQUE_ID_NULL != SliceUniqueID )
			{
				SliceParamPtr = GetSystemSliceParamPtrByUniqueID(SliceUniqueID);
				if ( NULL != SliceParamPtr )
				{	
					CameraID = SliceParamPtr->SliceCameraID;
					SliceGainValue = SliceParamPtr->SliceGainValue;
					idx = Imageidx[CameraID];
					if ( CameraCtrl.GetCameraRingBufferImage(CameraID, idx, ImageW[ImgIdx], ImageH[ImgIdx], ImageStep[ImgIdx], ImagePtr[ImgIdx]) == false )
					{
						IsOK = false;
						m_ErrorString = CameraCtrl.GetErrorString();
						break; 
					}					
					if ( ImageAPI.GrayImageOffsetGain3(ImageW[ImgIdx], ImageH[ImgIdx], ImageStep[ImgIdx], ImagePtr[ImgIdx], ImagePtr[ImgIdx], 0, SliceGainValue) == false )
					{
						IsOK = false;
						m_ErrorString = ImageAPI.GetImageApiErrorString();
						break; 
					}
					ImgIdx ++;
					Imageidx[CameraID] ++;
				}			               
			}
			SliceUniqueID = FrameParam.FrameSliceID2;
			if ( SLICE_UNIQUE_ID_NULL != SliceUniqueID )
			{
				SliceParamPtr = GetSystemSliceParamPtrByUniqueID(SliceUniqueID);
				if ( NULL != SliceParamPtr )
				{	
					CameraID = SliceParamPtr->SliceCameraID;
					SliceGainValue = SliceParamPtr->SliceGainValue;
					idx = Imageidx[CameraID];
					if ( CameraCtrl.GetCameraRingBufferImage(CameraID, idx, ImageW[ImgIdx], ImageH[ImgIdx], ImageStep[ImgIdx], ImagePtr[ImgIdx]) == false )
					{
						IsOK = false;
						m_ErrorString = CameraCtrl.GetErrorString();
						break;
					}					
					if ( ImageAPI.GrayImageOffsetGain3(ImageW[ImgIdx], ImageH[ImgIdx], ImageStep[ImgIdx], ImagePtr[ImgIdx], ImagePtr[ImgIdx], 0, SliceGainValue) == false )
					{
						IsOK = false;
						m_ErrorString = ImageAPI.GetImageApiErrorString();
						break; 
					}
					ImgIdx ++;
					Imageidx[CameraID] ++;
				}			               
			}
			SliceUniqueID = FrameParam.FrameSliceID3;
			if ( SLICE_UNIQUE_ID_NULL != SliceUniqueID )
			{
				SliceParamPtr = GetSystemSliceParamPtrByUniqueID(SliceUniqueID);
				if ( NULL != SliceParamPtr )
				{	
					CameraID = SliceParamPtr->SliceCameraID;
					SliceGainValue = SliceParamPtr->SliceGainValue;
					idx = Imageidx[CameraID];
					if ( CameraCtrl.GetCameraRingBufferImage(CameraID, idx, ImageW[ImgIdx], ImageH[ImgIdx], ImageStep[ImgIdx], ImagePtr[ImgIdx]) == false )
					{
						IsOK = false;
						m_ErrorString = CameraCtrl.GetErrorString();
						break;
					}					
					if ( ImageAPI.GrayImageOffsetGain3(ImageW[ImgIdx], ImageH[ImgIdx], ImageStep[ImgIdx], ImagePtr[ImgIdx], ImagePtr[ImgIdx], 0, SliceGainValue) == false )
					{
						IsOK = false;
						m_ErrorString = ImageAPI.GetImageApiErrorString();
						break; 
					}
					ImgIdx ++;
					Imageidx[CameraID] ++;
				}
			}
		}
		else
		{
			if ( SLICE_UNIQUE_ID_NULL != SliceUniqueID )
			{
				if ( FRAME_SPACE != FrameType ) 
				{	continue; }

				SliceParamPtr = GetSystemSliceParamPtrByUniqueID(SliceUniqueID);
				if ( NULL != SliceParamPtr )
				{	
					CameraID = SliceParamPtr->SliceCameraID;
					SliceGainValue = SliceParamPtr->SliceGainValue;
					for ( j=0; j<FrameImageCount; j++ )
					{
						idx = Imageidx[CameraID];					
						if ( CameraCtrl.GetCameraRingBufferImage(CameraID, idx, ImageW[ImgIdx], ImageH[ImgIdx], ImageStep[ImgIdx], ImagePtr[ImgIdx]) == false )
						{
							IsOK = false;
							m_ErrorString = CameraCtrl.GetErrorString();						
							break; 
						}						
						if ( ImageAPI.GrayImageOffsetGain3(ImageW[ImgIdx], ImageH[ImgIdx], ImageStep[ImgIdx], ImagePtr[ImgIdx], ImagePtr[ImgIdx], 0, SliceGainValue) == false )
						{
							IsOK = false;
							m_ErrorString = ImageAPI.GetImageApiErrorString();
							break; 
						}
						ImgIdx ++;
						Imageidx[CameraID] ++;
					}			
				}			               
			}
		}
	}
	JetAPI::SetFuncTimeEnd(fnEnd);
	double FnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);
	str.Format(_T("CAOIDataCollect::ModifyCameraUniFrame Time=%.3f ms"), FnTime);
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::RetrieveCameraUniFrame(const std::vector<TFrameParam> &FrameParamList, std::vector<TUNI_FRAME> &UniFrameList)//接收相機通用畫面列表
{	
	LARGE_INTEGER fnEnd;
	LARGE_INTEGER fnStart;
	//LARGE_INTEGER End;
	//LARGE_INTEGER Start;
	CString      str;
	CString      strFolder;
	bool         IsOK = true;
	int          DLPIndex=0;
	size_t       i=0, j=0, k=0;
	size_t       ImgIdx=0;	
	size_t       PatternCount=0;
	size_t       BufferSize=0;	
	size_t       TotalImageCount = 0;
	CAMERA_ID    CameraID;
	RECT         ImageRect={0};
	FRAME_TYPE   FrameType;
	TUNI_FRAME   UniFrame;
	double       FrameSatRed=1.0;
	double       FrameSatGrn=1.0;
	double       FrameSatBlu=1.0;
	const size_t MaxImageCount=128;
	const size_t MaxDLPCount = DLP_CAST_COUNT;	
	IMAGE_SIZE   DeBayerBit=0;
	IMAGE_SIZE   DeBayerStep=0;
	IMAGE_PTR    DeBayerPtr=NULL;
	IMAGE_SIZE   ImageW[MaxImageCount]={0};
	IMAGE_SIZE   ImageH[MaxImageCount]={0};
	IMAGE_SIZE   ImageStep[MaxImageCount]={0};
	IMAGE_SIZE   BitCount[MaxImageCount]={0};
	IMAGE_PTR    ImagePtrM=NULL;
	IMAGE_PTR    ImagePtr[MaxImageCount]={NULL};		
	BAYER_PATTERN_MODE BayerPattern=BAYER_PATTERN_NONE;

	TCastParam   CastParam[MaxDLPCount];	
	MASK_PTR     MaskPtrM=NULL;
	SPACE_PTR    SpacePtrM=NULL;
	TFrameParam  FrameParam;
	TSliceParam *SliceParamPtr=NULL;
	bool         bOpenMP = true;
	double       SliceGainValue=0.0;
	const bool   bSaveRawImage=false;
	unsigned int FrameImageCount = 0;//影像張數	
	unsigned int SliceUniqueID=SLICE_UNIQUE_ID_NULL;
	const size_t FrameCount = FrameParamList.size();	
	const double Precision = DBL_PRECISION;
	const double SpaceRatio = GetSpaceToGrayRatio();	

	long idx=0;
	long Imageidx[MAX_CAMERA_COUNT]={0};
	long ImageCount[MAX_CAMERA_COUNT]={0};
	long RingIndex[MAX_CAMERA_COUNT]={0};
	long RingListSize[MAX_CAMERA_COUNT]={0};
	TPhaseNoiseParam NoiseParam;	
	GetPhaseNoiseDefineParam(NoiseParam);
	if ( 0 == FrameCount ) { return true; }

	char vaName[32]="";
	const char fnName[] = "CAOIDataCollect::RetrieveCameraUniFrame";
	str.Format(_T("CAOIDataCollect::RetrieveCameraUniFrame Start"));
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	JetAPI::SetFuncTimeStart(fnStart);	
	for ( i=0; i<MaxImageCount; i++ )
	{
		ImageW[i] = 0;
		ImageH[i] = 0;
		ImageStep[i] = 0;
		BitCount[i] = 0;
		ImagePtr[i] = NULL;
	}

	for ( i=0; i<MAX_CAMERA_COUNT; i++ )
	{
		CameraID = (CAMERA_ID)(i);		
		ImageCount[i] = CameraCtrl.GetImageCallbackCount(CameraID);		
		RingIndex[i] = CameraCtrl.GetCameraRingBufferCurrentIndex(CameraID);
		RingListSize[i]  = CameraCtrl.GetCameraRingBufferListSize(CameraID);

		Imageidx[i] = RingIndex[i];
		Imageidx[i] = Imageidx[i]-ImageCount[i];
		//Imageidx[i] = Imageidx[i]+m_CameraImageReceieveCount;
		if ( Imageidx[i] < 0 ) { Imageidx[i] += RingListSize[i];  }
	}	

	strFolder.Format(_T("%s\\%s"), GetAOITempDirectory(), _T("RetrieveImage"));
	if ( true == bSaveRawImage )
	{	::CreateDirectory(strFolder, NULL); }
	for ( i=0; i<FrameCount; i++ )
	{
		FrameParam = FrameParamList[i];	

		MaskPtrM  = NULL;
		ImagePtrM = NULL;
		SpacePtrM = NULL;		
		for ( j=0; j<MaxImageCount; j++ )
		{	ImagePtr[j] = NULL; }

		FrameType = FrameParam.FrameType;
		FrameSatRed=FrameParam.FrameSaturationRed;
		FrameSatGrn=FrameParam.FrameSaturationGreen;
		FrameSatBlu=FrameParam.FrameSaturationBlue;
		FrameImageCount = FrameParam.FrameImageCount;		

		JetAPI::InitialUniFrame(UniFrame);
		UniFrame.FrameUniqueID = FrameParam.FrameUniqueID;

		ImgIdx=0;
		SliceUniqueID = FrameParam.FrameSliceID1;
		if ( SLICE_UNIQUE_ID_DLP != SliceUniqueID )
		{	
			if ( SLICE_UNIQUE_ID_NULL != SliceUniqueID )
			{
				SliceParamPtr = GetSystemSliceParamPtrByUniqueID(SliceUniqueID);
				if ( NULL != SliceParamPtr )
				{	
					CameraID = SliceParamPtr->SliceCameraID;
					SliceGainValue = SliceParamPtr->SliceGainValue;
					BayerPattern = CameraCtrl.GetCameraBayerPattern(CameraID);
					idx = Imageidx[CameraID];					
					if ( CameraCtrl.GetCameraRingBufferImage(CameraID, idx, ImageW[ImgIdx], ImageH[ImgIdx], ImageStep[ImgIdx], ImagePtr[ImgIdx]) == false )
					{
						IsOK = false;
						m_ErrorString = CameraCtrl.GetErrorString();
						break; 
					}
					ImgIdx ++;
					Imageidx[CameraID] ++;
				}			               
			}
			SliceUniqueID = FrameParam.FrameSliceID2;
			if ( SLICE_UNIQUE_ID_NULL != SliceUniqueID )
			{
				SliceParamPtr = GetSystemSliceParamPtrByUniqueID(SliceUniqueID);
				if ( NULL != SliceParamPtr )
				{	
					CameraID = SliceParamPtr->SliceCameraID;
					SliceGainValue = SliceParamPtr->SliceGainValue;
					BayerPattern = CameraCtrl.GetCameraBayerPattern(CameraID);
					idx = Imageidx[CameraID];
					if ( CameraCtrl.GetCameraRingBufferImage(CameraID, idx, ImageW[ImgIdx], ImageH[ImgIdx], ImageStep[ImgIdx], ImagePtr[ImgIdx]) == false )
					{
						IsOK = false;
						m_ErrorString = CameraCtrl.GetErrorString();
						break;
					}					
					ImgIdx ++;
					Imageidx[CameraID] ++;
				}			               
			}
			SliceUniqueID = FrameParam.FrameSliceID3;
			if ( SLICE_UNIQUE_ID_NULL != SliceUniqueID )
			{
				SliceParamPtr = GetSystemSliceParamPtrByUniqueID(SliceUniqueID);
				if ( NULL != SliceParamPtr )
				{	
					CameraID = SliceParamPtr->SliceCameraID;
					SliceGainValue = SliceParamPtr->SliceGainValue;
					BayerPattern = CameraCtrl.GetCameraBayerPattern(CameraID);
					idx = Imageidx[CameraID];
					if ( CameraCtrl.GetCameraRingBufferImage(CameraID, idx, ImageW[ImgIdx], ImageH[ImgIdx], ImageStep[ImgIdx], ImagePtr[ImgIdx]) == false )
					{
						IsOK = false;
						m_ErrorString = CameraCtrl.GetErrorString();
						break;
					}					
					ImgIdx ++;
					Imageidx[CameraID] ++;
				}
			}
		}
		else
		{
			if ( SLICE_UNIQUE_ID_NULL != SliceUniqueID )
			{
				if ( FRAME_SPACE != FrameType ) 
				{	continue; }

				SliceParamPtr = GetSystemSliceParamPtrByUniqueID(SliceUniqueID);
				if ( NULL != SliceParamPtr )
				{	
					CameraID = SliceParamPtr->SliceCameraID;
					SliceGainValue = SliceParamPtr->SliceGainValue;
					SLICE_FUNC_MODE  SliceFuncMode=SliceParamPtr->SliceFuncMode;					
					const int DLPExpCnt = CheckFrameExpCountBySliceFuncMode(SliceFuncMode);
					const int DLPLightCnt = CheckFrameLightCountBySliceFuncMode(SliceFuncMode);
					const bool bReSortCameraImage = CheckReSortCameraImage(SliceFuncMode);
					FrameImageCount = FrameImageCount*DLPLightCnt;					
					if ( true == bReSortCameraImage )
					{	
						if ( CameraCtrl.ReSortCameraRingBufferImage(CameraID, *SliceParamPtr) == false )
						{
							IsOK = false;
							m_ErrorString = CameraCtrl.GetErrorString();
							break;
						}
					}
					for ( j=0; j<FrameImageCount; j++ )
					{
						idx = Imageidx[CameraID];					
						if ( CameraCtrl.GetCameraRingBufferImage(CameraID, idx, ImageW[ImgIdx], ImageH[ImgIdx], ImageStep[ImgIdx], ImagePtr[ImgIdx]) == false )
						{
							IsOK = false;
							m_ErrorString = CameraCtrl.GetErrorString();						
							break; 
						}						
						ImgIdx ++;
						Imageidx[CameraID] ++;
					}			
				}			               
			}
		}
		if ( true == bSaveRawImage )
		{
			for ( j=0; j<FrameImageCount; j++ )
			{			
				str.Format(_T("%s\\Frame[%d]_Image[%d].PNG"), strFolder, i+1, j+1);
				ImageAPI.SaveImage(str, ImageW[j], ImageH[j], ImageStep[j], 8, ImagePtr[j], true);
			}
		}

		//Check Image Size
		for ( j=1; j<FrameImageCount; j++ )
		{
			if ( ImageW[j]!=ImageW[0] || ImageH[j]!=ImageH[0] || ImageStep[j]!=ImageStep[0] )
			{
				IsOK = false;
				m_ErrorString.Format(_T("Error, Image Size Exception (%d, %d, %d)!=(%d, %d, %d)"), ImageW[j], ImageH[j], ImageStep[j], ImageW[0], ImageH[0], ImageStep[0]);
				break;
			}
		}

		JetAPI::SizeToRect(ImageW[0], ImageH[0], ImageRect);
		switch ( FrameType )
		{
		case FRAME_GRAY:
			if ( 1 != ImgIdx )
			{
				IsOK = false;
				m_ErrorString.Format(_T("Error, Frame Type dismatch image count [Gray!=%d]"), ImgIdx);
				break;
			}				
			if ( ImageAPI.CloneGrayImage(ImageW[0], ImageH[0], ImageStep[0], ImagePtr[0], ImagePtrM, false) == false )
			{
				IsOK = false;
				m_ErrorString = ImageAPI.GetImageApiErrorString();
				break;
			}
			UniFrame.ImageW    = ImageW[0];
			UniFrame.ImageH    = ImageH[0];
			UniFrame.ImageStep = ImageStep[0];
			UniFrame.BitCount  = 8;
			UniFrame.ImagePtr  = ImagePtrM;
			UniFrameList.push_back(UniFrame);
			break;
		case FRAME_BAYER:
			if ( 1 != ImgIdx )
			{
				IsOK = false;
				m_ErrorString.Format(_T("Error, Frame Type dismatch image count [Bayer!=%d]"), ImgIdx);
				break;
			}
			if ( ExecDebayerImage(fnName, ImageW[0], ImageH[0], ImageStep[0], ImagePtr[0], BayerPattern, DeBayerStep, DeBayerBit, DeBayerPtr) == false )
			{
				IsOK = false;
				break;
			}
			ImagePtrM = DeBayerPtr;
			UniFrame.ImageW    = ImageW[0];
			UniFrame.ImageH    = ImageH[0];
			UniFrame.ImageStep = DeBayerStep;
			UniFrame.BitCount  = DeBayerBit;
			UniFrame.ImagePtr  = ImagePtrM;
			UniFrameList.push_back(UniFrame);
			DeBayerPtr = NULL;
			break;
		case FRAME_COLOR:
			if ( 3 != ImgIdx )
			{
				IsOK = false;
				m_ErrorString.Format(_T("Error, Frame Type dismatch image count [Color!=%d]"), ImgIdx);
				break; 
			}
			UniFrame.BitCount = 24;
			UniFrame.ImageStep = JetAPI::GetBMPImagePixelsPerLine(ImageW[0], UniFrame.BitCount, 4);
			if ( ImageAPI.RGBImageToColorImage(ImageW[0], ImageH[0], ImageStep[0], ImagePtr[0], ImagePtr[1], ImagePtr[2], UniFrame.ImageStep, ImagePtrM, false) == false )
			{
				IsOK = false;
				m_ErrorString = ImageAPI.GetImageApiErrorString();
				break;
			}
			if ( fabs(FrameSatRed-1.0)>Precision || fabs(FrameSatGrn-1.0)>Precision || fabs(FrameSatBlu-1.0)>Precision )
			{	ImageAPI.SaturateColorImage3(ImageW[0], ImageH[0], UniFrame.ImageStep, ImagePtrM, ImagePtrM, FrameSatRed, FrameSatBlu);	}
			UniFrame.ImageW    = ImageW[0];
			UniFrame.ImageH    = ImageH[0];
			UniFrame.ImagePtr  = ImagePtrM;
			UniFrameList.push_back(UniFrame);
			break;
		case FRAME_SPACE:			
			SliceParamPtr = GetSystemSliceParamPtrByUniqueID(SliceUniqueID);
			if ( NULL != SliceParamPtr )
			{
				int   DLPUsdCnt=0;				
				CString Folder = GetAOITempDirectory();
				SLICE_FUNC_MODE  SliceFuncMode=SliceParamPtr->SliceFuncMode;
				LIGHT_3D_CAST_ID CastID[DLP_CAST_COUNT]={LIGHT_3D_CAST_00};

				PatternCount = CheckSliceFuncModeDlpPatternCountAll(SliceFuncMode);
				CheckSliceParamUsed3DCastID(SliceParamPtr->SliceLightTable, CastID);
				const int DLPLightCnt = CheckFrameLightCountBySliceFuncMode(SliceFuncMode);
				const bool bUse2Exp = CheckSliceFuncModeDlpUse2Exp(SliceFuncMode);				
				if ( 0 != PatternCount )
				{
					idx = DLPIndex = 0;
					const bool DumpImage=false;
					for ( j=0; j<FrameImageCount; j++ )
					{
						const int NextIdx=idx+PatternCount;
						if ( NextIdx > FrameImageCount ) { break; }
						if ( false == bUse2Exp )
						{	IsOK = BuildCastParam(ImageW[idx], ImageH[idx], ImageStep[idx], PatternCount, SliceFuncMode, &(ImagePtr[idx]), CastID[DLPIndex], CastParam[DLPIndex]); }
						else
						{	IsOK = BuildCastParam2Exp(ImageW[idx], ImageH[idx], ImageStep[idx], PatternCount, SliceFuncMode, &(ImagePtr[idx]), CastID[DLPIndex], CastParam[DLPIndex]); }
						if ( false == IsOK )
						{	break;	}
						if ( true == DumpImage )
						{	SaveCastParamImageList(CastParam[DLPIndex], Folder);	}

						DLPIndex  ++;
						idx += PatternCount;						
					}
					if ( false == IsOK )
					{	break; }
					if ( false == bUse2Exp )
					{
						switch ( DLPIndex )
						{
						case 1:	IsOK=ImageAPI.PatternCast1ToSpace(ImageW[0], ImageH[0], ImageStep[0], CastParam[0], NoiseParam, bOpenMP, MaskPtrM, SpacePtrM);	break;
						case 2:	IsOK=ImageAPI.PatternCast2ToSpace(ImageW[0], ImageH[0], ImageStep[0], CastParam[0], CastParam[1], NoiseParam, bOpenMP, MaskPtrM, SpacePtrM);	break;
						case 3:	IsOK=ImageAPI.PatternCast3ToSpace(ImageW[0], ImageH[0], ImageStep[0], CastParam[0], CastParam[1], CastParam[2], NoiseParam, bOpenMP, MaskPtrM, SpacePtrM); break;
						case 4:	IsOK=ImageAPI.PatternCast4ToSpace(ImageW[0], ImageH[0], ImageStep[0], CastParam[0], CastParam[1], CastParam[2], CastParam[3], NoiseParam, bOpenMP, MaskPtrM, SpacePtrM); break;
						}
					}
					else
					{						
						switch ( DLPIndex )
						{
						case 1:	IsOK=ImageAPI.PatternCast1ToSpace2Exp(ImageW[0], ImageH[0], ImageStep[0], CastParam[0], NoiseParam, bOpenMP, MaskPtrM, SpacePtrM);	break;
						case 2:	IsOK=ImageAPI.PatternCast2ToSpace2Exp(ImageW[0], ImageH[0], ImageStep[0], CastParam[0], CastParam[1], NoiseParam, bOpenMP, MaskPtrM, SpacePtrM);	break;
						case 3:	IsOK=ImageAPI.PatternCast3ToSpace2Exp(ImageW[0], ImageH[0], ImageStep[0], CastParam[0], CastParam[1], CastParam[2], NoiseParam, bOpenMP, MaskPtrM, SpacePtrM); break;
						case 4:	IsOK=ImageAPI.PatternCast4ToSpace2Exp(ImageW[0], ImageH[0], ImageStep[0], CastParam[0], CastParam[1], CastParam[2], CastParam[3], NoiseParam, bOpenMP, MaskPtrM, SpacePtrM); break;
						}
					}
					if ( false == IsOK )
					{
						m_ErrorString = ImageAPI.GetImageApiErrorString();
						break;
					}
					if ( ImageAPI.SpaceGrayImageConvertToGray(ImageW[0], ImageH[0], ImageStep[0], SpacePtrM, MaskPtrM, ImageRect, ImageStep[0], ImagePtrM, SpaceRatio, false) == false )
					{
						IsOK = false;
						m_ErrorString = ImageAPI.GetImageApiErrorString();
						break;
					}				
					UniFrame.ImageW    = ImageW[0];
					UniFrame.ImageH    = ImageH[0];
					UniFrame.ImageStep = ImageStep[0];
					UniFrame.BitCount  = 8;
					UniFrame.MaskPtr   = MaskPtrM;
					UniFrame.SpacePtr  = SpacePtrM;
					UniFrame.ImagePtr  = ImagePtrM;
					UniFrameList.push_back(UniFrame);					
				}

			}
			break;

		}
		TotalImageCount += FrameParam.FrameImageCount;
	}
	for ( i=0; i<MaxDLPCount; i++ )
	{
		JetMemory.free_func(CastParam[i].PtrMask);
		JetMemory.free_func(CastParam[i].PtrSpace);
	}	
	if ( false == IsOK )
	{	
		JetMemory.free_func(MaskPtrM);
		JetMemory.free_func(SpacePtrM);
		JetMemory.free_func(ImagePtrM);
		JetAPI::ClearUniFrameList(UniFrameList);

		JetAPI::SetFuncTimeEnd(fnEnd);
		double FnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);
		str.Format(_T("CAOIDataCollect::RetrieveCameraUniFrame Time=%.3f ms"), FnTime);
		SaveCurrentProcess(str);
		return false;
	}

	JetAPI::SetFuncTimeEnd(fnEnd);
	double FnTime = JetAPI::CalcFuncTimeSpent(fnStart, fnEnd);
	str.Format(_T("CAOIDataCollect::RetrieveCameraUniFrame Time=%.3f ms"), FnTime);
	SaveMovingTimeMsg(MSG_FILTER_SYSTEM, MSG_LEVEL_HIGH, str);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::GetStagePos(double &PosX, double &PosY, double &PosZ)//取得機台位置, 會考慮是否為Offline
{
	bool  IsOK = true;
	const bool OfflineMode = GetOfflineMode();
	IsOK = MotionCtrlPtr->GetCurrentPos(PosX, PosY, PosZ, OfflineMode);
	if ( false == IsOK )
	{
		m_ErrorString = MotionCtrlPtr->GetErrorString();
		return false;
	}
	return true;
}
