double CAOIDataCollect::GetImageZoomMin() const//取得影像縮放最小
{	
	return  m_ImageParameter.m_ImageZoomMin;
}
//-------------------------------------------------------------------------------------//
double CAOIDataCollect::GetImageZoomMax() const//取得影像縮放最大
{
	return  m_ImageParameter.m_ImageZoomMax;
}
