{
	double val = 0.75;
	return val;
}
//-------------------------------------------------------------------------------------//
double CAOIDataCollect::AdjustImageZoom(double Zoom)//調整影像縮放
{
	const double ZoomMin = GetImageZoomMin();
	const double ZoomMax = GetImageZoomMax();
	if ( Zoom < ZoomMin )
	{	return ZoomMin; }
	if ( Zoom > ZoomMax )
	{	return ZoomMax; }		
	return Zoom;
}
