//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ClearAOILibrary()//清除資料庫
{
	CString str;
	CString LibraryName;
	CString LibraryFolder;
	CString AOIFolder = GetAOIDirectory();

	LibraryName = GetAOILibraryName();
	if ( JetAPI::IsFileExist(LibraryName) == false ) 
	{
		str.Format(_T("Error, the Library is not a file[%s]"), LibraryName);
		JetAPI::ShowMessageBox(str);
		return false;
	}
	
	JetAPI::ExtractFolder(LibraryName, LibraryFolder);		
	if ( LibraryFolder.CompareNoCase(AOIFolder) == 0 ||
		 LibraryFolder.CompareNoCase(_T("C:")) == 0		) 
	{
		str.Format(_T("Error, can not clear the folder [%s]"), LibraryFolder);
		JetAPI::ShowMessageBox(str);
		return false;
	}
	JetAPI::ClearFolder(LibraryFolder);
	return true;
}
//-------------------------------------------------------------------------------------//
CAOIProject* CAOIDataCollect::LoadAOILibrary(LPCTSTR pfilename)//載入資料庫
{
	CAOIProject *ProjectPtr = LoadAOILibraryFn(pfilename);
	if ( NULL == ProjectPtr )
	{
		SetSystemExceptionCode_FileRead();
		return NULL;
	}
	return ProjectPtr;
}
//-------------------------------------------------------------------------------------//
CAOIProject* CAOIDataCollect::LoadAOILibraryFn(LPCTSTR pfilename)//載入資料庫
{
	CString LibraryName;
	CString filenameTmp;		
	CAOIProject *LibraryPtr = NULL;
	
	LibraryName = pfilename;
	if ( JetAPI::IsFileExist(LibraryName) == false )
	{
		m_ErrorString.Format(_T("Error, No AOI Library File [%s]"), LibraryName);
		return NULL;	
	}
	
	LibraryPtr = AOIObjManager.CreateProjectObj();
	if ( NULL == LibraryPtr )
	{	
		m_ErrorString = AOIObjManager.GetErrorString();		
		return LibraryPtr;
	}	
	
	if ( CreateTempProjectFile(LibraryName, filenameTmp) == false )
	{
		AOIObjManager.DestroyProjectObj(LibraryPtr);
		return NULL;
	}

	const bool bLibraryMode = true;
	if ( LibraryPtr->LoadProject(filenameTmp, LibraryName, bLibraryMode) == false )
	{
		m_ErrorString = LibraryPtr->GetErrorString();
		AOIObjManager.DestroyProjectObj(LibraryPtr);
		return NULL;
	}
	return LibraryPtr;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveAOILibraryAs(LPCTSTR pfilename)//另存資料庫
{
	CString LibraryName = GetAOILibraryName();
	if ( LibraryName.CompareNoCase(pfilename) == 0 ) { return true; }

	CString str, str2;
	CString SrcFolder;
	CString DstFolder;

	JetAPI::ExtractMainFileName(pfilename, DstFolder);
	JetAPI::ExtractMainFileName(LibraryName, SrcFolder);	

	::CreateDirectory(DstFolder, NULL);
	JetAPI::CopyFolderAToFolderB(SrcFolder, DstFolder, false, true, _T(""), -1, -1);
	::Sleep(0);
	::CopyFile(LibraryName, pfilename, FALSE);
	::Sleep(0);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ReBuildAOILibrary(LPCTSTR pfilename)//重整資料庫
{
	CString filenameTmp;		
	CString filenameCal;	
	DWORD dwCopyFlag = COPY_PROJECT_FOLDER_NO_OFFLINE;
	CAOIProject *LibraryPtr = NULL;
	CString LibraryName = pfilename;
	CString LibraryMain;
	CString LibraryFolder;	
	const bool bPartialCopy = false;
	const bool bModelBkImage=GetAutoArrangeModelBkImageFiles();

	//LibraryName = GetAOILibraryName();	
	JetAPI::ExtractFolder(LibraryName, LibraryFolder);	
	JetAPI::ExtractMainFileNameNoPath(LibraryName, LibraryMain);

	if ( JetAPI::IsFileExist(LibraryName) == false )
	{
		m_ErrorString.Format(_T("Error, No AOI Library [%s]"), LibraryName);
		return false;		
	}
	
	LibraryPtr = AOIObjManager.CreateProjectObj();
	if ( NULL == LibraryPtr )
	{	
		m_ErrorString = AOIObjManager.GetErrorString();		
		return false;
	}
	
	//ProjectPtr->CheckProjectOfflineSaveFinish();
	if ( CreateTempProjectFile(LibraryName, filenameTmp) == false )
	{
		AOIObjManager.DestroyProjectObj(LibraryPtr);
		return false;
	}

	const bool bLibraryMode = true;	
	if ( LibraryPtr->LoadProject(filenameTmp, LibraryName, true) == false )
	{
		m_ErrorString = LibraryPtr->GetErrorString();
		AOIObjManager.DestroyProjectObj(LibraryPtr);
		return false;
	}
	if ( true == bModelBkImage )
	{
		if ( LibraryPtr->ArrangeProjectLibraryBkImageFiles() == false )
		{
			m_ErrorString = LibraryPtr->GetErrorString();
			AOIObjManager.DestroyProjectObj(LibraryPtr);
			return false;
		}
	}
	
	dwCopyFlag = COPY_PROJECT_FOLDER_LIBRARY;	
	if ( LibraryPtr->SaveProject(filenameTmp, LibraryName, dwCopyFlag, bPartialCopy) == false )
	{
		JetAPI::ShowMessageBox(LibraryPtr->GetErrorString());
		AOIObjManager.DestroyProjectObj(LibraryPtr);
		return false;
	}
	dwCopyFlag = COPY_PROJECT_FOLDER_LIBRARY;
	if ( LibraryPtr->CopyProjectFileToOtherFile(LibraryName, dwCopyFlag) == false )
	{
		JetAPI::ShowMessageBox(LibraryPtr->GetErrorString());
		AOIObjManager.DestroyProjectObj(LibraryPtr);
		return false;
	}
	AOIObjManager.DestroyProjectObj(LibraryPtr);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MergeAOILibrary(CAOIProject *ProjectPtr)//合併資料庫
{		
	CString filenameTmp;		
	CString filenameCal;	
	DWORD dwCopyFlag = COPY_PROJECT_FOLDER_NO_OFFLINE;
	CAOIProject *LibraryPtr = NULL;
	std::vector<TAliasNode> AliasList_All;
	std::vector<TAliasNode> AliasList_Library;
	std::vector<TAliasNode> AliasList_Project;

	CString LibraryName;
	CString LibraryMain;
	CString LibraryFolder;
	CString LibraryAliasFile;
	const bool bPartialCopy = false;

	LibraryName = GetAOILibraryName();	
	JetAPI::ExtractFolder(LibraryName, LibraryFolder);	
	JetAPI::ExtractMainFileNameNoPath(LibraryName, LibraryMain);
	LibraryAliasFile.Format(_T("%s\\%s\\PartNumber.CAL"), LibraryFolder, LibraryMain);	
	
	if ( JetAPI::IsFileExist(LibraryName) == false )
	{
		LibraryPtr = ProjectPtr->CloneProjectObj();
		if ( NULL == LibraryPtr ) 
		{
			m_ErrorString = _T("Error, Clone Project Object Fault");
			return false;
		}
		LibraryPtr->ConvertProjectToLibrary();		
		dwCopyFlag = COPY_PROJECT_FOLDER_LIBRARY;		
		filenameTmp = AOIDataDefine.GetProjectTempFilename(LibraryName);
		if ( LibraryPtr->SaveProject(filenameTmp, LibraryName, dwCopyFlag, bPartialCopy) == false )
		{
			JetAPI::ShowMessageBox(LibraryPtr->GetErrorString());
			AOIObjManager.DestroyProjectObj(LibraryPtr);
			return false;
		}
		dwCopyFlag = COPY_PROJECT_FOLDER_LIBRARY;
		if ( LibraryPtr->CopyProjectFileToOtherFile(LibraryName, dwCopyFlag) == false )
		{
			JetAPI::ShowMessageBox(ProjectPtr->GetErrorString());
			AOIObjManager.DestroyProjectObj(LibraryPtr);
			return false;
		}
		AOIObjManager.DestroyProjectObj(LibraryPtr);

		ProjectPtr->BuildProjectAliasList(AliasList_Project);
		SaveAliasFile(LibraryAliasFile, AliasList_Project);
		return true;
	}
	
	LibraryPtr = AOIObjManager.CreateProjectObj();
	if ( NULL == LibraryPtr )
	{	
		m_ErrorString = AOIObjManager.GetErrorString();		
		return false;
	}
	
	//ProjectPtr->CheckProjectOfflineSaveFinish();
	if ( CreateTempProjectFile(LibraryName, filenameTmp) == false )
	{
		AOIObjManager.DestroyProjectObj(LibraryPtr);
		return false;
	}

	const bool bLibraryMode = true;	
	if ( LibraryPtr->LoadProject(filenameTmp, LibraryName, true) == false )
	{
		m_ErrorString = LibraryPtr->GetErrorString();
		AOIObjManager.DestroyProjectObj(LibraryPtr);
		return false;
	}
	if ( LibraryPtr->MergeProjectLibrary(ProjectPtr) == false )
	{
		m_ErrorString = LibraryPtr->GetErrorString();
		AOIObjManager.DestroyProjectObj(LibraryPtr);
		return false;
	}
	
	dwCopyFlag = COPY_PROJECT_FOLDER_LIBRARY;	
	if ( LibraryPtr->SaveProject(filenameTmp, LibraryName, dwCopyFlag, bPartialCopy) == false )
	{
		JetAPI::ShowMessageBox(LibraryPtr->GetErrorString());
		AOIObjManager.DestroyProjectObj(LibraryPtr);
		return false;
	}
	dwCopyFlag = COPY_PROJECT_FOLDER_LIBRARY;
	if ( LibraryPtr->CopyProjectFileToOtherFile(LibraryName, dwCopyFlag) == false )
	{
		JetAPI::ShowMessageBox(LibraryPtr->GetErrorString());
		AOIObjManager.DestroyProjectObj(LibraryPtr);
		return false;
	}

	AOIObjManager.DestroyProjectObj(LibraryPtr);

	ProjectPtr->BuildProjectAliasList(AliasList_Project);
	if ( LoadAliasFile(LibraryAliasFile, AliasList_Library) == true ) 
	{
		MergeAliasList(AliasList_Library, AliasList_Project, AliasList_All);
		SaveAliasFile(LibraryAliasFile, AliasList_All);
	}
	else
	{	SaveAliasFile(LibraryAliasFile, AliasList_Project); }
	return true;
}
