//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveAOIMonitorStatusFn(MONITOR_STATUS_MODE Status, LPCTSTR Text)//儲存AOI設備監控狀態	
{
	const int SaveMachineMonitorMessage = GetSystemParameter().m_SaveMachineMonitorMessage;
	if ( FN_DISABLE == SaveMachineMonitorMessage ) { return true; }
	

	/*
	[Info]
	Zone=Tapipei
	Building=B
	Floor=3
	Line=L01
	Station=S01
	Time=20170807131145
	Project=
	Status=2
	Message=錯誤訊息
	OP=Vic
	*/
#ifndef OFFLINE_VERSION
	CAOIProject *Project = NULL;
	CString str;
	CString Section;
	CString KeyName;
	CString String;
	CString filename;
	CString filenameTmp;
	CString filenameDst;
	CString DateTime;		
	CString TempFolder = GetAOITempDirectory();	
	CString HostIP = m_SystemParameter.m_IPHostComputer;
	CString FolderDst = m_SystemParameter.m_MonitorStatusFolder;

	str.Format(_T("%s\\%s"), TempFolder, _T("Monitor"));
	::CreateDirectory(str, NULL);
	TempFolder = str;

	Section = _T("Info");	
	Project = GetActiveProject();
	JetAPI::GetTime(DateTime,CTime::GetCurrentTime());
	filename.Format(_T("%s_AOI.INI"), HostIP);
	filenameTmp.Format(_T("%s\\%s"), TempFolder, filename);	
	
	KeyName = _T("Zone");//本機廠區
	String = m_SystemParameter.m_MachineLocation;
	if ( SaveINIData(Section, KeyName, String, filenameTmp, m_ErrorString) == false )
	{	return false; }

	KeyName = _T("Building");//本機棟別
	String = this->m_SystemParameter.m_MachineBuilding;
	if ( SaveINIData(Section, KeyName, String, filenameTmp, m_ErrorString) == false )
	{	return false; }

	KeyName = _T("Floor");//本機樓層
	String = this->m_SystemParameter.m_MachineFloor;
	if ( SaveINIData(Section, KeyName, String, filenameTmp, m_ErrorString) == false )
	{	return false; }

	//m_MachineRoom//本機車間

	KeyName = _T("Line");//本機線別
	String = this->m_SystemParameter.m_MachineLine;
	if ( SaveINIData(Section, KeyName, String, filenameTmp, m_ErrorString) == false )
	{	return false; }

	KeyName = _T("Line LB");//本機線別
	String = this->m_SystemParameter.m_MachineLine_LB;
	if ( SaveINIData(Section, KeyName, String, filenameTmp, m_ErrorString) == false )
	{	return false; }

	KeyName = _T("Station");//本機站別	
	String = this->m_SystemParameter.m_MachineStation;
	if ( SaveINIData(Section, KeyName, String, filenameTmp, m_ErrorString) == false )
	{	return false; }

	KeyName = _T("Station LB");//本機站別	
	String = this->m_SystemParameter.m_MachineStation_LB;
	if ( SaveINIData(Section, KeyName, String, filenameTmp, m_ErrorString) == false )
	{	return false; }

	KeyName = _T("MachineSN");//本機序號	
	String = this->m_SystemParameter.m_MachineSN;
	if ( SaveINIData(Section, KeyName, String, filenameTmp, m_ErrorString) == false )
	{	return false; }

	//m_MachineName//機台型號
	//CString                    m_MachineVendor;//機台廠商
	//CString                    m_MachineAlias;//機台別名

	KeyName = _T("Time");
	String = DateTime;
	if ( SaveINIData(Section, KeyName, String, filenameTmp, m_ErrorString) == false )
	{	return false; }

	KeyName = _T("Project");	
	if ( Project == NULL )
	{	String = _T(""); }
	else
	{	String = Project->GetProjectFileMainName();	}
	if ( SaveINIData(Section, KeyName, String, filenameTmp, m_ErrorString) == false )
	{	return false; }
	
	KeyName = _T("Status");	
	String.Format(_T("%d"), Status);
	if ( SaveINIData(Section, KeyName, String, filenameTmp, m_ErrorString) == false )
	{	return false; }

	KeyName = _T("Message");	
	if ( Text == NULL )
	{	String = _T("");	}
	else
	{	String = Text;	}	
	if ( SaveINIData(Section, KeyName, String, filenameTmp, m_ErrorString) == false )
	{	return false; }	
	
	KeyName = _T("OP");	
	String = GetCurrentUserName();
	if ( SaveINIData(Section, KeyName, String, filenameTmp, m_ErrorString) == false )
	{	return false; }
	
	filenameDst.Format(_T("%s\\%s"), FolderDst, filename);
	::CopyFile(filenameTmp, filenameDst, FALSE);

	const int SaveMachineMonitorMessageWeb = GetSystemParameter().m_SaveMachineMonitorMessageWeb;
	if ( FN_ENABLE == SaveMachineMonitorMessageWeb )
	{
		CString filename2;
		CString FolderDst2;
		CString filenameDst2;
		CString filenameTmp2;
		filename2.Format(_T("%s.INI"), DateTime);
		FolderDst2.Format(_T("%s\\%s_AOI"), FolderDst, HostIP);
		filenameTmp2.Format(_T("%s\\%s"), TempFolder, filename2);	
		::CreateDirectory(FolderDst2, NULL);

		KeyName = _T("Status");	
		String.Format(_T("%d"), Status);
		if ( SaveINIData(Section, KeyName, String, filenameTmp2, m_ErrorString) == false )
		{	return false; }

		KeyName = _T("Message");	
		if ( Text == NULL )
		{	String = _T("");	}
		else
		{	String = Text;	}	
		if ( SaveINIData(Section, KeyName, String, filenameTmp2, m_ErrorString) == false )
		{	return false; }	

		filenameDst2.Format(_T("%s\\%s"), FolderDst2, filename2);
		::CopyFile(filenameTmp2, filenameDst2, FALSE);
	}
#endif//OFFLINE_VERSION
	return true;
}
