//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveAOIMonitorStatusFn(ONLINE_STATE_MODE OnlineStatus, LPCTSTR Text)//儲存AOI設備監控狀態
{
	int     nValue=0;
	LANE_ID LaneID = GetActiveLaneID();
	MONITOR_STATUS_MODE MonitorStatus=MONITOR_STATUS_RETURN;
	switch ( OnlineStatus )
	{
	case ONLINE_STATE_INSPECTION_STOP:		  MonitorStatus=MONITOR_STATUS_STOP;	break;
	case ONLINE_STATE_INPUT_BARCODE:		  MonitorStatus=MONITOR_STATUS_STOP;	break;
	case ONLINE_STATE_PCB_READY:		      MonitorStatus=MONITOR_STATUS_RUN;	break;
	case ONLINE_STATE_PROJECT_MAP:			  MonitorStatus=MONITOR_STATUS_RUN;	break;
	case ONLINE_STATE_PROJECT_MARK:			  MonitorStatus=MONITOR_STATUS_RUN;	break;
	case ONLINE_STATE_PROJECT_OPEN_CODE:      MonitorStatus=MONITOR_STATUS_RUN;	break;
	case ONLINE_STATE_PROJECT_RELOAD:		  MonitorStatus=MONITOR_STATUS_RUN;	break;
	case ONLINE_STATE_PROJECT_RELOAD_SERVER:  MonitorStatus=MONITOR_STATUS_RUN;	break;	
	case ONLINE_STATE_INSPECTION_START:		  MonitorStatus=MONITOR_STATUS_RUN;	break;
	case ONLINE_STATE_INSPECTION_WAITING:	  MonitorStatus=MONITOR_STATUS_RUN;	break;
	case ONLINE_STATE_INSPECT_FD_PANEL:		  MonitorStatus=MONITOR_STATUS_RUN;	break;
	case ONLINE_STATE_INSPECT_FD_BOARD:		  MonitorStatus=MONITOR_STATUS_RUN;	break;
	case ONLINE_STATE_INSPECT_BARCODE:		  MonitorStatus=MONITOR_STATUS_RUN;	break;
	case ONLINE_STATE_INSPECT_PROJECT:		  MonitorStatus=MONITOR_STATUS_RUN;	break;
	case ONLINE_STATE_STATICS_PROJECT:		  MonitorStatus=MONITOR_STATUS_RUN;	break;
	case ONLINE_STATE_INSPECTION_FINISH:	  MonitorStatus=MONITOR_STATUS_RUN;	break;
	case ONLINE_STATE_PROJECT_SWITCH_BY_TURN: MonitorStatus=MONITOR_STATUS_RUN;	break;	
	case ONLINE_STATE_PROJECT_SWITCH_BY_TURN_ONE_CYCLE_RESET: MonitorStatus=MONITOR_STATUS_RUN;	break;
	case ONLINE_STATE_WAIT_FOR_LAST_STATION:  MonitorStatus=MONITOR_STATUS_WAIT_FOR_LAST;	break;
	case ONLINE_STATE_WAIT_FOR_NEXT_STATION:  MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
	case ONLINE_STATE_WAIT_FOR_PCB_REMOVED:	  MonitorStatus=MONITOR_STATUS_STOP;	break;
	case ONLINE_STATE_WAIT_FOR_REPAIR_VERIFY: MonitorStatus=MONITOR_STATUS_STOP;	break;

	case ONLINE_STATE_PCB_IN_START:			  MonitorStatus=MONITOR_STATUS_WAIT_FOR_LAST;	break;
	case ONLINE_STATE_PCB_IN_CHECKING:		  MonitorStatus=MONITOR_STATUS_WAIT_FOR_LAST;	break;
	case ONLINE_STATE_PCB_IN_FINISH:		  MonitorStatus=MONITOR_STATUS_WAIT_FOR_LAST;	break;

	case ONLINE_STATE_PCB_OUT_START:		  MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
	case ONLINE_STATE_PCB_OUT_CHECKING:		  MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
	case ONLINE_STATE_PCB_OUT_FINISH:		  MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;

	case ONLINE_STATE_PCB_OUT_INSIDE_START:	  MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
	case ONLINE_STATE_PCB_OUT_INSIDE_CHECKING: MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
	case ONLINE_STATE_PCB_OUT_INSIDE_FINISH:  MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;

	case ONLINE_STATE_PCB_BACK_START:		  MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
	case ONLINE_STATE_PCB_BACK_CHECKING:	  MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
	case ONLINE_STATE_PCB_BACK_FINISH:		  MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;

	case ONLINE_STATE_PCB_BACK_OUT_START:	  MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
	case ONLINE_STATE_PCB_BACK_OUT_CHECKING:  MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
	case ONLINE_STATE_PCB_BACK_OUT_FINISH:	  MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;

	case ONLINE_STATE_PCB_OUT_IN_START:		  MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
	case ONLINE_STATE_PCB_OUT_IN_CHECKING:	  
		nValue = PlcCtrlPtr->GetConveryerStatus(LaneID);		
		switch ( nValue )
		{
		case PLC_CONVERYER_STATUS_STOP:	MonitorStatus=MONITOR_STATUS_STOP;	break;
		case PLC_CONVERYER_STATUS_PCB_IN_WAITING:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_LAST;	break;
		case PLC_CONVERYER_STATUS_PCB_IN_RUNNING:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_LAST;	break;
		case PLC_CONVERYER_STATUS_PCB_OUT_WAITING:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
		case PLC_CONVERYER_STATUS_PCB_OUT_RUNNING:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
		case PLC_CONVERYER_STATUS_PCB_OUT_FINISH:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
		case PLC_CONVERYER_STATUS_PCB_BACK_RUNNING:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
		default:	MonitorStatus=MONITOR_STATUS_STOP;	break;
		}
		break;
	case ONLINE_STATE_PCB_OUT_IN_FINISH:	  MonitorStatus=MONITOR_STATUS_WAIT_FOR_LAST;	break;

	case ONLINE_STATE_PCB_AUTO_RUN_START:	  MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
	case ONLINE_STATE_PCB_AUTO_RUN_CHECKING:
		nValue = PlcCtrlPtr->GetConveryerStatus(LaneID);		
		switch ( nValue )
		{
		case PLC_CONVERYER_STATUS_STOP:	MonitorStatus=MONITOR_STATUS_STOP;	break;
		case PLC_CONVERYER_STATUS_PCB_IN_WAITING:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_LAST;	break;
		case PLC_CONVERYER_STATUS_PCB_IN_RUNNING:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_LAST;	break;
		case PLC_CONVERYER_STATUS_PCB_OUT_WAITING:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
		case PLC_CONVERYER_STATUS_PCB_OUT_RUNNING:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
		case PLC_CONVERYER_STATUS_PCB_OUT_FINISH:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
		case PLC_CONVERYER_STATUS_PCB_BACK_RUNNING:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
		default:	MonitorStatus=MONITOR_STATUS_STOP;	break;
		}
		break;
	case ONLINE_STATE_PCB_AUTO_RUN_FINISH:	  MonitorStatus=MONITOR_STATUS_WAIT_FOR_LAST;	break;

	case ONLINE_STATE_PCB_DUAL_RUN_START:	  MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
	case ONLINE_STATE_PCB_DUAL_RUN_CHECKING:
		nValue = PlcCtrlPtr->GetConveryerStatus(LaneID);		
		switch ( nValue )
		{
		case PLC_CONVERYER_STATUS_STOP:	MonitorStatus=MONITOR_STATUS_STOP;	break;
		case PLC_CONVERYER_STATUS_PCB_IN_WAITING:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_LAST;	break;
		case PLC_CONVERYER_STATUS_PCB_IN_RUNNING:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_LAST;	break;
		case PLC_CONVERYER_STATUS_PCB_OUT_WAITING:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
		case PLC_CONVERYER_STATUS_PCB_OUT_RUNNING:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
		case PLC_CONVERYER_STATUS_PCB_OUT_FINISH:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
		case PLC_CONVERYER_STATUS_PCB_BACK_RUNNING:	MonitorStatus=MONITOR_STATUS_WAIT_FOR_NEXT;	break;
		default:	MonitorStatus=MONITOR_STATUS_STOP;	break;
		}
		break;
	case ONLINE_STATE_PCB_DUAL_RUN_FINISH:	  MonitorStatus=MONITOR_STATUS_WAIT_FOR_LAST;	break;
	case ONLINE_STATE_PCB_INSPECTION_PAUSE:	  MonitorStatus = MONITOR_STATUS_RUN;	break;
	//case ONLINE_STATE_PCB_INSPECTION_PAUSE:	  MonitorStatus = MONITOR_STATUS_STOP;	break;

	case ONLINE_STATE_AUTO_CALIBRATION_XYZ_HOME:		  MonitorStatus=MONITOR_STATUS_RUN;	break;
	case ONLINE_STATE_AUTO_CALIBRATION_2D_CURRENT:		  MonitorStatus=MONITOR_STATUS_RUN;	break;		
	case ONLINE_STATE_AUTO_CALIBRATION_3D_CURRENT:		  MonitorStatus=MONITOR_STATUS_RUN;	break;		
	case ONLINE_STATE_AUTO_CALIBRATION_3D_ZERO_PLANE:	  MonitorStatus=MONITOR_STATUS_RUN;	break;		
	case ONLINE_STATE_AUTO_CALIBRATION_3D_HEIGHT_FACTOR:  MonitorStatus=MONITOR_STATUS_RUN;	break;

	case ONLINE_STATE_APP_OPEN:				  MonitorStatus=MONITOR_STATUS_STOP;	break;
	case ONLINE_STATE_APP_CLOSE:			  MonitorStatus=MONITOR_STATUS_CLOSE;	break;
	}
	if ( MONITOR_STATUS_RETURN == MonitorStatus )
	{
		m_ErrorString.Format(_T("Error, Monitor Status Exception (%d)"), MonitorStatus);
		return false; 
	}
	
	if ( SaveAOIMonitorStatus(MonitorStatus, Text) == false )
	{	return false; }
	return true;
}
