bool CAOIDataCollect::LoadNameFile(LPCTSTR pfilename, std::vector<std::wstring> &NameList)//載入名稱檔案
{
	if ( LoadNameFileFn(pfilename, NameList) == false )
	{
		SetSystemExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadNameFileFn(LPCTSTR pfilename, std::vector<std::wstring> &NameList)//載入名稱檔案
{
	FILE *pfile = NULL;
	TCHAR TMode[32] = _T("");	

	NameList.clear();
	_tcscpy(TMode, _T("r+"));
	JetAPI::ModifyOpenFileMode_Read(TMode);
	pfile = ::_tfopen(pfilename, TMode);
	if ( pfile == NULL )
	{
		m_ErrorString.Format(_T("Error, open file fault (%s) [Load]"), pfilename);
		return false; 
	}

	int LineIndex = 0;	
	int  Lens = 0;
	int  i=0, j=0;	
	size_t szPartName=0;

	const int TextSize = 1024;
	const wchar_t Delim = L',';	
	wchar_t PartName[TextSize]=L"";	
	wchar_t TextLine[TextSize]=L"";	
	while ( !feof(pfile) )
	{
		LineIndex ++;
		::memset(TextLine,  0x00, sizeof(char)*TextSize);
		if ( ::fgetws(TextLine, TextSize, pfile) == NULL )		
		{	continue;	}
		JetAPI::FilerTextW(TextLine, L"*?|\n\0", PartName, TextSize);		
		szPartName = ::wcslen(PartName);
		if ( 0 == szPartName ) { continue; }		
		::_wcsupr (PartName);				
		NameList.push_back(PartName);
	}
	::fclose(pfile); pfile=NULL;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadAliasFile(LPCTSTR pfilename, std::vector<TAliasNode> &AliasList)//載入別名檔案
{
	if ( LoadAliasFileFn(pfilename, AliasList) == false )
	{
		SetSystemExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LoadAliasFileFn(LPCTSTR pfilename, std::vector<TAliasNode> &AliasList)//載入別名檔案
{	
	FILE *pfile = NULL;
	TCHAR TMode[32] = _T("");	

	AliasList.clear();
	_tcscpy(TMode, _T("r+"));
	JetAPI::ModifyOpenFileMode_Read(TMode);
	pfile = ::_tfopen(pfilename, TMode);
	if ( pfile == NULL )
	{
		m_ErrorString.Format(_T("Error, open file fault (%s) [Load]"), pfilename);
		return false; 
	}

	int LineIndex = 0;	
	int  Lens = 0;
	int  i=0, j=0;
	size_t szModelName=0;
	size_t szPartNumber=0;	

	TAliasNode AliasNode;
	const int TextSize = 1024;
	const wchar_t Delim = L',';
	wchar_t TextLine[TextSize]=L"";
	wchar_t PartNumber[TextSize]=L"";
	wchar_t ModelName[TextSize]=L"";	
	while ( !feof(pfile) )
	{
		LineIndex ++;
		::memset(TextLine,  0x00, sizeof(char)*TextSize);
		if ( ::fgetws(TextLine, TextSize, pfile) == NULL )		
		{	continue;	}
		if ( JetAPI::DecoderTextLine(TextLine, PartNumber, ModelName, Delim) == false )
		{	continue; }

		szModelName = ::wcslen(ModelName);
		szPartNumber = ::wcslen(PartNumber);
		if ( 0==szModelName || 0==szPartNumber ) 
		{	continue; }
		::_wcsupr(ModelName);
		::_wcsupr(PartNumber);
		AliasNode.wsPartNumber = PartNumber;
		AliasNode.wsModelName = ModelName;		
		AliasList.push_back(AliasNode);
	}
	::fclose(pfile); pfile=NULL;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveAliasFile(LPCTSTR pfilename, std::vector<TAliasNode> &AliasList)//儲存別名檔案	
{
	if ( SaveAliasFileFn(pfilename, AliasList) == false )
	{
		SetSystemExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveAliasFileFn(LPCTSTR pfilename, std::vector<TAliasNode> &AliasList)//儲存別名檔案	
{
	FILE *pfile = NULL;
	TCHAR TMode[32] = _T("");
	_tcscpy(TMode, _T("w+"));
	JetAPI::ModifyOpenFileMode_Write(TMode);
	pfile = _tfopen(pfilename, TMode);
	if ( NULL == pfile ) 
	{
		m_ErrorString.Format(_T("Error, Open file fault (%s) [Save]"), pfilename);
		return false;
	}
	size_t       i=0;
	TAliasNode  *AliasNodePtr = NULL;	
	const size_t AliasCount = AliasList.size();
	for ( i=0; i<AliasCount; i++ )
	{
		AliasNodePtr = &(AliasList[i]);		
		::fwprintf(pfile, L"%s,%s\n", AliasNodePtr->wsPartNumber.c_str(), AliasNodePtr->wsModelName.c_str());
	}
	::fclose(pfile); pfile=NULL;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::MergeAliasList(const std::vector<TAliasNode> &List1, const std::vector<TAliasNode> &List2, std::vector<TAliasNode> &AliasList)//合併兩個別名列表
{
	AliasList.clear();
	const size_t AliasCount1 = List1.size();
	const size_t AliasCount2 = List2.size();
	if ( 0==AliasCount1 || 0==AliasCount2 )
	{
		if ( 0 != AliasCount1 ) 
		{	AliasList = List1; }
		if ( 0 != AliasCount2 ) 
		{	AliasList = List2; }
		return true;
	}

	size_t   i=0;
	std::map<std::wstring, std::wstring> Map;
	//因為List2為新資料所以要先放入Map
	for ( i=0; i<AliasCount2; i++ )
	{	Map[List2[i].wsPartNumber] = List2[i].wsModelName;	}
	for ( i=0; i<AliasCount1; i++ )
	{	Map[List1[i].wsPartNumber] = List1[i].wsModelName;	}
	

	TAliasNode AliasNode;
	std::map<std::wstring, std::wstring>::iterator MapIter;
	for ( MapIter=Map.begin(); MapIter!=Map.end(); MapIter++ )
	{
		AliasNode.wsPartNumber = (*MapIter).first; 
		AliasNode.wsModelName  = (*MapIter).second ;
		AliasList.push_back(AliasNode);
	}
	return true;
}
