bool CAOIDataCollect::CheckOpenMPUsed_CalcPhase(int nImageSize) const//確認使用Open MP
{
#ifndef OPEN_MP_USE
	return false;
#endif//OPEN_MP_USE
	if ( m_SystemParameter.m_OpenMPCount_General < 2 ) //0 or 1
	{	return false; }
	if ( nImageSize > 0 ) 
	{
		const int MaxImageSize = 256*256;
		if ( nImageSize < MaxImageSize ) 
		{	return false; }
	}
	return true;
}
