//-------------------------------------------------------------------------------------//
int CAOIDataCollect::CheckOpenMPCount_SpaceFilter(bool bOpenMp, size_t nImageSize) const//Open MP核心數量-空間雜訊
{	
	if ( false == bOpenMp )
	{	return 0; }
	const bool OpenMPUsed = CheckOpenMPUsed_SpaceFilter(nImageSize);
	if ( false == OpenMPUsed )
	{	return 0; }	
	return m_SystemParameter.m_OpenMPCount_General;
}
