bool CAOIDataCollect::CheckDualRunMode() const//確認是否啟用雙軌運轉模式
{	
	bool bUseDualRunMode=false;
	MULTI_LANE_MODE MultiLaneMode=CheckMultiLaneMode();
	if ( MULTI_LANE_2 == MultiLaneMode )
	{	bUseDualRunMode = true;	}
	return bUseDualRunMode;
}
//-------------------------------------------------------------------------------------//
MULTI_LANE_MODE CAOIDataCollect::CheckMultiLaneMode() const//多軌道模式
{
	LANE_WORK_MODE LaneWorkMode_LA = m_SystemParameter.m_LaneWorkMode_LA;
	LANE_WORK_MODE LaneWorkMode_LB = m_SystemParameter.m_LaneWorkMode_LB;
	if ( LANE_WORK_DISABLE == LaneWorkMode_LA || LANE_WORK_DISABLE == LaneWorkMode_LB )
	{
		if ( LANE_WORK_DISABLE != LaneWorkMode_LA || LANE_WORK_DISABLE != LaneWorkMode_LB )
		{	return MULTI_LANE_1;	}
		return MULTI_LANE_OFF;
	}
	return MULTI_LANE_2;	
}
