//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SwitchWorkLane()//切換啟用軌道
{
	if ( CheckMultiLaneMode_Off() == true ) { return true; }
	if ( CheckLaneWorkMode() == false ) { return false; }

	LANE_ID LaneID = GetActiveLaneID();
	LANE_ID NewLaneID = GetActiveLaneID();
	switch ( LaneID )
	{
	case LANE_ID_A:
		switch ( m_SystemParameter.m_LaneWorkMode_LA )
		{
		case LANE_WORK_RUN:
			break;
		case LANE_WORK_BYPASS:
			if ( LANE_WORK_RUN == m_SystemParameter.m_LaneWorkMode_LB )
			{	NewLaneID = LANE_ID_B; }
			break;
		case LANE_WORK_DISABLE:
			NewLaneID = LANE_ID_B;
			break;
		}
		break;
	case LANE_ID_B:
		switch ( m_SystemParameter.m_LaneWorkMode_LB )
		{
		case LANE_WORK_RUN:
			break;
		case LANE_WORK_BYPASS:
			if ( LANE_WORK_RUN == m_SystemParameter.m_LaneWorkMode_LA )
			{	NewLaneID = LANE_ID_A; }
			break;
		case LANE_WORK_DISABLE:
			NewLaneID = LANE_ID_A;
			break;
		}
		break;
	}
	if ( NewLaneID != LaneID )
	{	SetActiveLaneID(NewLaneID);	}

	return true;
}
