void CAOIDataCollect::GetMaskImageColor(unsigned int FrameUniqueID, unsigned char &maskR, unsigned char &maskG, unsigned char &maskB, unsigned char &maskV, unsigned char &Alpha)//取得遮罩影像顏色
{	//20190219
	const TSystemParameter &SystemParam = GetSystemParameter();
	COLORREF MaskColor = SystemParam.m_BinaryMaskColorDefault;
	if ( FRAME_UNIQUE_ID_RGB == FrameUniqueID )
	{	MaskColor = SystemParam.m_BinaryMaskColorRGB;	}
	
	maskR=0xFF;
	maskG=0xFF;
	maskB=0x00;	
	maskV=0xFF;

	maskR = GetRValue(MaskColor);
	maskG = GetGValue(MaskColor);
	maskB = GetBValue(MaskColor);
	Alpha = (unsigned char)(SystemParam.m_BinaryMaskColorAlpha);//2值化遮罩顏色-透明度
}
