bool CAOIDataCollect::AddRemoveFolder_ProjectTemp(LPCTSTR Filename)//新增移除資料夾-暫存專案
{
	if ( NULL == Filename ) { return true; }
	CString FolderTmp;
	CString FolderTmp2;
	CString MainNameTmp;
	CString SysTempFolder = GetAOITempDirectory();

	JetAPI::ExtractMainFileName(Filename, FolderTmp);
	JetAPI::ExtractMainFileNameNoPath(Filename, MainNameTmp);
	FolderTmp2.Format(_T("%s\\%s"), SysTempFolder, MainNameTmp);

	LockThreadRemoveFolder();
	TRemoveFolder RemoveFolder;
	RemoveFolder.Folder = FolderTmp;
	RemoveFolder.DateTime = CTime::GetCurrentTime();
	RemoveFolder.Removed = false;
	RemoveFolder.FolderType = REMOVE_FOLDER_TYPE_PROJECT_TEMP_FOLDER;
	m_RemoveFolderListNew.push_back(RemoveFolder);		

	RemoveFolder.Folder = FolderTmp2;
	RemoveFolder.DateTime = CTime::GetCurrentTime();
	RemoveFolder.Removed = false;
	RemoveFolder.FolderType = REMOVE_FOLDER_TYPE_PROJECT_TEMP_FOLDER;
	m_RemoveFolderListNew.push_back(RemoveFolder);		
	UnlockThreadRemoveFolder();
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::AddRemoveFolder_OnlineTuning(LPCTSTR Folder)//新增移除資料夾-線上調機
{
	if ( NULL == Folder ) { return true; }
	LockThreadRemoveFolder();
	TRemoveFolder RemoveFolder;
	RemoveFolder.Folder = Folder;
	RemoveFolder.DateTime = CTime::GetCurrentTime();
	RemoveFolder.Removed = false;
	RemoveFolder.FolderType = REMOVE_FOLDER_TYPE_ONLINE_TUNING_FOLDER;
	m_RemoveFolderListNew.push_back(RemoveFolder);		
	UnlockThreadRemoveFolder();
	return true;
}
//-------------------------------------------------------------------------------------//
CString CAOIDataCollect::GetDefaultLatestFilename() const//預設最近檔案名稱
{
	return _T("****");
}
//-------------------------------------------------------------------------------------//
size_t CAOIDataCollect::GetMaxLatestFileCount() const//最多紀錄最近檔案數量
{
	return 10;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::AddLatestFilename(LPCTSTR pfilename)//增加最近檔案列表
{
	size_t       i=0;
	size_t       idx=0;		
	CString      KeyName;
	CString      Section;
	CString      Default;
	CString      Filename;	
	CString      IniFilename;	
	size_t       UseLatestFileCount=0;	
	const size_t StringSize = MAX_JET_PATH;
	TCHAR        String[StringSize]=_T("");
	CString      FileFolder = GetAOIProjectDirectory();
	CString      DummyFilename = GetDefaultLatestFilename();
	const size_t MaxLatestFileCount = GetMaxLatestFileCount();
	if ( NULL == pfilename ) { return false; }
	
	if ( JetAPI::ExtractShortFilename(FileFolder, pfilename, Filename) == false )
	{	return false; }		
	
#ifndef OFFLINE_VERSION
	Section = _T("Latest File List Online");
#else
	Section = _T("Latest File List Offline");
#endif//OFFLINE_VERSION

	IniFilename.Format(_T("%s\\%s"), FileFolder, _T("Project.INI"));
	//搜尋有無重複
	UseLatestFileCount = MaxLatestFileCount;
	for ( i=0; i<MaxLatestFileCount; i++ )
	{		
		KeyName.Format(_T("%d"), i+1);
		Default = Filename;
		if ( LoadINIData(Section, KeyName, Default, String, StringSize, IniFilename, false, m_ErrorString) == false )
		{	return false; }
		if ( Default.CompareNoCase(String) != 0 ) { continue; }
		UseLatestFileCount = i+1;
		break;
	}
	
	for ( i=1; i<UseLatestFileCount; i++ )
	{
		idx = UseLatestFileCount-i-1;
		KeyName.Format(_T("%d"), idx+1);
		Default = DummyFilename;
		if ( LoadINIData(Section, KeyName, Default, String, StringSize, IniFilename, false, m_ErrorString) == false )
		{	return false; }
		if ( Default.CompareNoCase(String) == 0 ) { continue; }
		
		if ( Filename.CompareNoCase(String) != 0 ) //往後延一個index
		{
			idx = UseLatestFileCount-i;
			KeyName.Format(_T("%d"), idx+1);
			Default = String; 
		}
		if ( SaveINIData(Section, KeyName, Default, IniFilename, m_ErrorString) == false )
		{	return false; }
	}

	idx = 0;
	KeyName.Format(_T("%d"), idx+1);
	Default = Filename;
	if ( SaveINIData(Section, KeyName, Default, IniFilename, m_ErrorString) == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::UpdateLatestFilenameList(bool Offline)//更新最近檔案列表
{
	size_t       i=0;	
	CString      KeyName;
	CString      Section;
	CString      Default;
	CString      Filename;	
	CString      IniFilename;	
	const size_t StringSize = MAX_JET_PATH;
	TCHAR        String[StringSize]=_T("");
	std::vector<CString> FileNameList;
	CString      FileFolder = GetAOIProjectDirectory();
	CString      DummyFilename = GetDefaultLatestFilename();
	const size_t MaxLatestFileCount = GetMaxLatestFileCount();	
	
	if ( false == Offline )
	{	Section = _T("Latest File List Online");	}
	else
	{	Section = _T("Latest File List Offline");	}	
	IniFilename.Format(_T("%s\\%s"), FileFolder, _T("Project.INI"));
	for ( i=0; i<MaxLatestFileCount; i++ )
	{	
		KeyName.Format(_T("%d"), i+1);
		Default = DummyFilename;
		if ( LoadINIData(Section, KeyName, Default, String, StringSize, IniFilename, false, m_ErrorString) == false )
		{	return false; }
		if ( Default.CompareNoCase(String) == 0 ) { continue; }

		Filename.Format(_T("%s\\%s"), FileFolder, String);
		if ( CheckProjectFilenameValided(Filename) == false ) { continue; }
		if ( JetAPI::IsFileExist(Filename) == false ) { continue; }
		FileNameList.push_back(String);		
	}	

	const size_t FileNameCount = FileNameList.size();
	for ( i=0; i<MaxLatestFileCount; i++ )
	{	
		KeyName.Format(_T("%d"), i+1);
		if ( i < FileNameCount )
		{	Default = FileNameList[i];	}
		else
		{	Default = DummyFilename; }
		SaveINIData(Section, KeyName, Default, IniFilename, m_ErrorString);
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckLatestFilenameList(std::vector<CString> &FileNameList, bool Offline)//取得最近檔案列表
{
	size_t       i=0;	
	CString      KeyName;
	CString      Section;
	CString      Default;
	CString      Filename;	
	CString      IniFilename;	
	const size_t StringSize = MAX_JET_PATH;
	TCHAR        String[StringSize]=_T("");
	CString      FileFolder = GetAOIProjectDirectory();
	CString      DummyFilename = GetDefaultLatestFilename();
	const size_t MaxLatestFileCount = GetMaxLatestFileCount();	
	
	if ( false == Offline )
	{	Section = _T("Latest File List Online");	}
	else
	{	Section = _T("Latest File List Offline");	}	
	IniFilename.Format(_T("%s\\%s"), FileFolder, _T("Project.INI"));
	for ( i=0; i<MaxLatestFileCount; i++ )
	{	
		KeyName.Format(_T("%d"), i+1);
		Default = DummyFilename;
		if ( LoadINIData(Section, KeyName, Default, String, StringSize, IniFilename, false, m_ErrorString) == false )
		{	return false; }
		if ( Default.CompareNoCase(String) == 0 ) { continue; }

		Filename.Format(_T("%s\\%s"), FileFolder, String);
		FileNameList.push_back(Filename);
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecLaneAdjustHome()//執行軌道移動
{	
	if ( PlcCtrlPtr->WriteLaneAdjustManual(true) == false )
	{	
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
		PlcCtrlPtr->WriteLaneAdjustManual(false);
		return false;
	}
	LANE_WORK_MODE LaneWorkMode_LA = GetLaneWorkMode_LA();
	if ( LANE_WORK_DISABLE != LaneWorkMode_LA )
	{
		if ( PlcCtrlPtr->GetLaneAdjustDisableBtn_LA() == false )
		{
			if ( PlcCtrlPtr->ExecLaneAdjustHomeSearch_LA(true) == false )
			{
				m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
				PlcCtrlPtr->WriteLaneAdjustManual(false);
				return false;
			}
			PlcCtrlPtr->ReadLaneAdjustCurrentPos_LA();
		}
	}

	LANE_WORK_MODE LaneWorkMode_LB = GetLaneWorkMode_LB();
	if ( LANE_WORK_DISABLE != LaneWorkMode_LB )
	{
		if ( PlcCtrlPtr->GetLaneAdjustDisableBtn_LB() == false )
		{
			if ( PlcCtrlPtr->ExecLaneAdjustHomeSearch_LB(true) == false )
			{
				m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
				PlcCtrlPtr->WriteLaneAdjustManual(false);
				return false;
			}
			PlcCtrlPtr->ReadLaneAdjustCurrentPos_LB();
		}
	}

	if ( PlcCtrlPtr->WriteLaneAdjustManual(false) == false )
	{	
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
		return false;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecLaneAdjustHome(LANE_ID LaneID)//執行軌道移動
{
	const bool Disable = PlcCtrlPtr->GetLaneAdjustDisableBtn(LaneID);
	if ( true == Disable ) { return true; }
	if ( PlcCtrlPtr->WriteLaneAdjustManual(true) == false )
	{	
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
		PlcCtrlPtr->WriteLaneAdjustManual(false);
		return false;
	}
	if ( PlcCtrlPtr->ExecLaneAdjustHomeSearch(LaneID, true) == false )
	{
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
		PlcCtrlPtr->WriteLaneAdjustManual(false);
		PlcCtrlPtr->ReadLaneAdjustCurrentPos(LaneID);	
		return false;
	}
	PlcCtrlPtr->ReadLaneAdjustCurrentPos(LaneID);	
	if ( PlcCtrlPtr->WriteLaneAdjustManual(false) == false )
	{	
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
		return false;
	}		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecLaneAdjustWidth(LANE_ID LaneID, double Width)//執行軌道移動
{	
	PlcCtrlPtr->ReadLaneAdjustHomeDone(LaneID);
	const bool CanMove = PlcCtrlPtr->CheckLaneAdjustCanMove(LaneID);
	if ( false == CanMove )
	{
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
		return false;
	}	
	if ( PlcCtrlPtr->WriteLaneAdjustManual(true) == false )
	{	
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
		PlcCtrlPtr->WriteLaneAdjustManual(false);
		return false;
	}
	if ( PlcCtrlPtr->ExecLaneAdjustMoveToPos(LaneID, Width) == false )
	{
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
		PlcCtrlPtr->WriteLaneAdjustManual(false);
		return false;
	}
	if ( PlcCtrlPtr->WriteLaneAdjustManual(false) == false )
	{	
		m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
		return false;
	}		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SendToVRS_AOIState(ONLINE_STATE_MODE State)//傳送至VRS軟體-機台狀態
{
#ifndef OFFLINE_VERSION
	LANE_ID LaneID = LANE_ID_NULL;
	CString Section;
	CString KeyName;
	CString String;		
	//ONLINE_STATE_MODE OnlineStateMode = GetOnlineStateMode();
	const TSystemParameter &System=GetSystemParameter();
	if ( SAVE_SPC_FILE_JSON_VRS!=System.m_SaveProjectSpcFileMode )
	{
		if ( FN_DISABLE == System.m_ITSCommunicationEnabled || MES_CONTACT_IBS!=System.m_ITSContactSoftware )
		{	return true; }
	}

	Section = _T("General");
	KeyName = _T("AOI State");
	String.Format(_T("%d"), State);
	if ( SendToVRS_SaveINIData(Section, KeyName, String) == false )
	{	return false; }
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SendToVRS_ProjectList()//傳送至VRS軟體-目前專案列表
{
#ifndef OFFLINE_VERSION
	size_t  i=0;	
	LANE_ID LaneID;
	CString Section;
	CString KeyName;
	CString String;
	CString ProjectName;
	unsigned int ProjectIndex = 0;
	CAOIProject *ProjectPtr = NULL;
	CString Folder = GetAOIProjectDirectory();
	const size_t ProjectCount = GetProjectPtrCount();
	Section = _T("General");

	KeyName = _T("Count");
	String.Format(_T("%d"), ProjectCount);	
	if ( SendToVRS_SaveINIData(Section, KeyName, String) == false )
	{	return false; }

	for ( i=0; i<ProjectCount; i++ )
	{
		ProjectPtr = GetProjectPtr(i, true);
		if ( NULL == ProjectPtr ) { continue; }	
		ProjectIndex = (unsigned int)(i);
		LaneID = ProjectPtr->GetProjectActLaneID();
		ProjectName = ProjectPtr->GetProjectShowName();

		KeyName.Format(_T("Project %d"), ProjectIndex+1);		
		if ( JetAPI::ExtractFileNameNoPath(ProjectName, String) == false )
		{	String = ProjectName;	}
		if ( SendToVRS_SaveINIData(Section, KeyName, String) == false )
		{	return false; }	

		KeyName.Format(_T("Project %d Lane"), ProjectIndex+1);
		switch ( LaneID )
		{
		case LANE_ID_B:	String = _T("B");	break;
		default:
		case LANE_ID_A:	String = _T("A");	break;
		}
		if ( SendToVRS_SaveINIData(Section, KeyName, String) == false )
		{	return false; }	
	}	
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SendToVRS_MachineInfo()//傳送至VRS軟體-機台訊息
{
#ifndef OFFLINE_VERSION	
	CString Section;
	CString KeyName;
	CString String;		

	Section = _T("General");
	KeyName = _T("Machine SN");
	String = GetMachineSN();
	if ( SendToVRS_SaveINIData(Section, KeyName, String) == false )
	{	return false; }

	KeyName = _T("Line");//20210906
	String = GetMachineLine(LANE_ID_A);
	if ( SendToVRS_SaveINIData(Section, KeyName, String) == false )
	{	return false; }

	KeyName = _T("Station");//20210906
	String = GetMachineStation(LANE_ID_A);
	if ( SendToVRS_SaveINIData(Section, KeyName, String) == false )
	{	return false; }

	KeyName = _T("Line LB");//20240301
	String = GetMachineLine(LANE_ID_B);
	if ( SendToVRS_SaveINIData(Section, KeyName, String) == false )
	{	return false; }

	KeyName = _T("Station LB");//20240301
	String = GetMachineStation(LANE_ID_B);
	if ( SendToVRS_SaveINIData(Section, KeyName, String) == false )
	{	return false; }
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SendToVRS_SaveINIData(LPCTSTR Section, LPCTSTR KeyName, LPCTSTR String)//傳送至VRS軟體-儲存INI資料
{
	if ( SendToVRS_SaveINIDataFn(Section, KeyName, String) == false )
	{
		SetSystemExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SendToVRS_SaveINIDataFn(LPCTSTR Section, LPCTSTR KeyName, LPCTSTR String)//傳送至VRS軟體-儲存INI資料
{
	CString IniName = _T("");
	CString BaseFolder = GetAOIResultDirectory();
	SAVE_SPC_FILE_MODE SaveSpcFileMode = GetSaveProjectSpcFileMode();
	if ( SAVE_SPC_FILE_JSON_RSM == SaveSpcFileMode )
	{	IniName.Format(_T("%s\\%s"), BaseFolder, _T("AOISendToRSM.INI"));	}
	else 
	{	IniName.Format(_T("%s\\%s"), BaseFolder, _T("AOISendToVRS.INI"));	}	
	
	CString ErrorString;
	LockThread();	
	const bool bSucc=SaveINIData(Section, KeyName, String, IniName, ErrorString);
	UnlockThread();
	if ( false == bSucc )
	{
		SetErrorString_Locked(ErrorString);
		return false;
	}
	return true;
}
