//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LayoutLaneProjectList()//整理出軌道上專案
{	
	CString        str;
	size_t         i=0;		
	CAOIProject   *ProjectPtr = NULL;
	size_t         LaneProjectCountLA=0;
	size_t         LaneProjectCountLB=0;	
	const size_t   ProjectCount = GetProjectPtrCount();
	LANE_WORK_MODE LaneWorkMode_LA = GetLaneWorkMode_LA();
	LANE_WORK_MODE LaneWorkMode_LB = GetLaneWorkMode_LB();

	ClearMarkObjList();
	ClearLaneProjectList_LA();
	ClearLaneProjectList_LB();	
	if ( BuildLaneProjectList(LANE_ID_A, m_LaneProjectList_LA) == false )
	{	return false; }
	if ( BuildLaneProjectList(LANE_ID_B, m_LaneProjectList_LB) == false )
	{	return false; }
	LaneProjectCountLA = m_LaneProjectList_LA.size();
	LaneProjectCountLB = m_LaneProjectList_LB.size();
	//如果沒有設定則為AB軌道相同	
	if ( 0 == LaneProjectCountLA )
	{	m_LaneProjectList_LA=m_LaneProjectList_LB; }
	if ( 0 == LaneProjectCountLB )
	{	m_LaneProjectList_LB=m_LaneProjectList_LA; }

	if ( LANE_WORK_RUN != LaneWorkMode_LA )
	{	m_LaneProjectList_LA.clear();	}
	if ( LANE_WORK_RUN != LaneWorkMode_LB )
	{	m_LaneProjectList_LB.clear();	}

	if ( MULTI_PROJECT_TEST_ORDER_BY_MARK == GetMultiProjectTestOrderMode() )
	{
		if ( CheckLaneProjectMarkImage(LANE_ID_A) == false )
		{	return false; }
		if ( CheckLaneProjectMarkImage(LANE_ID_B) == false )
		{	return false; }	
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckLaneProjectMarkImage(LANE_ID LaneID)//確認軌道專案的特徵影像
{
	size_t       i=0, j=0;	
	CAOIProject *ProjectPtr = NULL;	
	const int    FnEnable = FN_ENABLE;
	const int    FnDisable= FN_DISABLE;	
	const size_t LaneProjectCount = GetLaneProjectCount(LaneID);
	
	TFrameParam *FrameParamPtr=NULL;
	IMAGE_SIZE   MarkW=0;
	IMAGE_SIZE   MarkH=0;
	IMAGE_SIZE   MarkStep=0;
	IMAGE_SIZE   BitCount=0;
	IMAGE_PTR    MarkPtr = NULL;
	unsigned int ProjectIndex = 0;	
	unsigned int MarkFrameIndex=0;
	unsigned int FrameUniqueID=0;
	size_t       SliceParamCount=0;
	size_t       FrameParamCount=0;
	size_t       FrameUniqueIDCount=0;	
	
	std::vector<TSliceParam>   TempSliceParamList;//單1影像參數列表
	std::vector<TFrameParam>   TempFrameParamList;//影像參數列表	
	std::vector<unsigned int>  TempFrameUniqueIDList;//專案影像表格-檢測使用
	std::vector<unsigned int>  LaneProjectFrameUniqueIDList;//專案影像表格-檢測使用
	
	for ( i=0; i<LaneProjectCount; i++ )
	{
		ProjectPtr = GetLaneProjectPtr(LaneID, i, false);
		if ( NULL == ProjectPtr ) { continue; }		
		ProjectIndex = ProjectPtr->GetProjectIndex();
		MarkFrameIndex = ProjectPtr->GetProjectMarkFrameIndex();
		if ( LaneProjectCount > 1 )
		{
			ProjectPtr->GetProjectMarkImage(MarkW, MarkH, MarkStep, BitCount, MarkPtr);
			if ( NULL == MarkPtr )
			{				
				m_ErrorString.Format(_T("Error, No Project Mark Image [ID:%d]"), ProjectIndex+1);
				return false;
			}			
		}		
		FrameUniqueID = ProjectPtr->GetProjectFrameUniqueID(MarkFrameIndex, true);
		if ( FRAME_UNIQUE_ID_NULL == FrameUniqueID ) { continue; }
		FrameUniqueIDCount = TempFrameUniqueIDList.size();
		for ( j=0; j<FrameUniqueIDCount; j++ )
		{	
			if ( TempFrameUniqueIDList[j] == FrameUniqueID )
			{	break; }
		}
		if ( j == FrameUniqueIDCount ) 
		{	TempFrameUniqueIDList.push_back(FrameUniqueID); }
	}

	TempSliceParamList.clear();
	TempFrameParamList.clear();
	FrameUniqueIDCount = TempFrameUniqueIDList.size();
	for ( i=0; i<FrameUniqueIDCount; i++ )
	{
		FrameUniqueID = TempFrameUniqueIDList[i];
		if ( AddFrameSliceParamListByFrameUniqueID(FrameUniqueID, TempFrameParamList, TempSliceParamList) == false )
		{	continue; }
		LaneProjectFrameUniqueIDList.push_back(FrameUniqueID);
	}
	if ( LANE_ID_A == LaneID )
	{
		m_LaneProjectSliceParamList_LA = TempSliceParamList;
		m_LaneProjectFrameParamList_LA = TempFrameParamList;
		m_LaneProjectFrameUniqueIDList_LA = LaneProjectFrameUniqueIDList;
	}
	if ( LANE_ID_B == LaneID )
	{
		m_LaneProjectSliceParamList_LB = TempSliceParamList;
		m_LaneProjectFrameParamList_LB = TempFrameParamList;
		m_LaneProjectFrameUniqueIDList_LB = LaneProjectFrameUniqueIDList;
	}
	return true;
}
