//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckLandProjectPtr(LANE_ID LaneID, CAOIProject *ProjectPtr)//確認該專案是否在此軌道上
{
	std::vector<CAOIProject*> LaneProjectList;
	if ( CloneLaneProjectList(LaneID, LaneProjectList) == false )
	{	return false; }

	size_t       i=0;
	const size_t ProjectCount = LaneProjectList.size();
	for ( i=0; i<ProjectCount; i++ )
	{
		if ( LaneProjectList[i] == ProjectPtr ) 
		{	return true; }
	}
	return false;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CloneLaneProjectList(LANE_ID LaneID, std::vector<CAOIProject*> &LaneProjectList)//複製軌道專案列表
{
	switch ( LaneID )
	{
	case LANE_ID_B:	LaneProjectList = m_LaneProjectList_LB;	break;
	case LANE_ID_A:	LaneProjectList = m_LaneProjectList_LA;	break;
	default:
		m_ErrorString.Format(_T("Error, Lane ID Exception (%d)"), LaneID);
		return false;
		break;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::BuildLaneProjectList(LANE_ID LaneID, std::vector<CAOIProject*> &LaneProjectList)//建立出軌道上專案
{
	size_t i=0;
	CAOIProject *ProjectPtr = NULL;
	const size_t ProjectCount = GetProjectPtrCount();
	LaneProjectList.clear();	
	for ( i=0; i<ProjectCount; i++ )
	{
		ProjectPtr = GetProjectPtr(i, false);		
		if ( NULL == ProjectPtr ) { continue; }	
		switch ( LaneID )
		{
		case LANE_ID_A:
			if ( ProjectPtr->GetProjectLaneEnable_LA() == true ) 
			{	LaneProjectList.push_back(ProjectPtr); }	
			break;
		case LANE_ID_B:
			if ( ProjectPtr->GetProjectLaneEnable_LB() == true ) 
			{	LaneProjectList.push_back(ProjectPtr); }	
			break;
		}
	}
	return true;
}
