//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CreateProjectMarkObj()//建立依標記切換專案物件
{
	TFrameParam *FrameParamPtr = NULL;
	const LANE_ID LaneID = GetActiveLaneID();	
	std::vector<CAOISlice*>    FrameSlicePtrList;
	std::vector<CAOIProject*>  LaneProjectList;//軌道專案指標列表			
	std::vector<TSliceParam>   SliceParamList;//單1影像參數列表
	std::vector<TFrameParam>   FrameParamList;//影像參數列表
	std::vector<unsigned int>  FrameUniqueIDList;//影像參數列表

	RemoveAllPtrList();
	ClearMarkObjList();
	switch ( LaneID )
	{
	case LANE_ID_B:
		LaneProjectList = m_LaneProjectList_LB;
		SliceParamList = m_LaneProjectSliceParamList_LB;
		FrameParamList = m_LaneProjectFrameParamList_LB;
		FrameUniqueIDList = m_LaneProjectFrameUniqueIDList_LB;
		break;
	default:
		LaneProjectList = m_LaneProjectList_LA;
		SliceParamList = m_LaneProjectSliceParamList_LA;
		FrameParamList = m_LaneProjectFrameParamList_LA;
		FrameUniqueIDList = m_LaneProjectFrameUniqueIDList_LA;
		break;
	}

	CString       str;
	CString       fnName=_T("CreateProjectMarkObj");
	CAOIProject  *ProjectPtr = NULL;	
	const size_t  LaneProjectCount=LaneProjectList.size();
	const size_t  FrameParamCount = FrameParamList.size();
	const size_t  FrameUniqueIDCount = FrameUniqueIDList.size();

	RECT          FieldRect={0};	
	TPOINT3D      StartPos, FovPos;		
	size_t        i=0, j=0, k=0, s=0;	
	size_t        FovSlices = 0;
	size_t        FrameSliceCount=0;
	unsigned int  CameraFrameIdx = 0;
	double        FovWReal=0, FovHReal=0;
	double        FovWInner = 0, FovHInner = 0;
	double        FovWOuter = 0, FovHOuter = 0;
	CAOIRgn*      RgnPtr = NULL;//檢測區域指標
	CAOIFov*      FovPtr = NULL;//視野指標	
	CAOISlice*    SlicePtr = NULL;//相機區域圖指標	
	CAOIFrame*    FramePtr = NULL;//影像指標
	CAOIField*    FieldPtr = NULL;//區域指標
	GetFovSizeReal(FovWReal, FovHReal);
	GetFovSizeInner(FovWInner, FovHInner);
	GetFovSizeOuter(FovWOuter, FovHOuter);	
	//ProjectPtr->ModifyProjectFieldSize(FovWInner, FovHInner);//修正視野使用範圍

	const double FOVW2 = FovWInner*0.5;
	const double FOVH2 = FovHInner*0.5;
	const size_t FovFields = AnalsysFovFieldCount();		
	CAMERA_ID CameraID = PRIMARY_CAMERA_ID;
	const IMAGE_SIZE ImageW = GetCameraImageW(CameraID);
	const IMAGE_SIZE ImageH = GetCameraImageH(CameraID);
	const int       nImageW = (int)(ImageW);
	const int       nImageH = (int)(ImageH);

	//最佳化路徑
	size_t        FieldIdx=0;
	size_t        JetFieldIdx=0;
	TJetField     JetField;
	TJetField    *JetPathPtr=NULL;
	TJetField    *JetFieldPtr=NULL;
	TJetFieldList JetPathList;
	TJetFieldList JetFieldList;		
	unsigned int  FrameIndex=0;
	unsigned int  FrameUniqueID=0;
	unsigned int  FrameIndex_System=0;
	
	k = 0;	
	for (i=0; i<LaneProjectCount; i++ )
	{
		ProjectPtr = LaneProjectList[i];
		if ( NULL == ProjectPtr ) { continue; }
		ProjectPtr->SetProjectMarkScore(0);		
		FrameIndex = ProjectPtr->GetProjectMarkFrameIndex();
		FrameUniqueID = ProjectPtr->GetProjectFrameUniqueID(FrameIndex, true);
		ProjectPtr->GetProjectMarkStage(FovPos.x, FovPos.y, FovPos.z);

		FrameIndex_System = 0;
		if ( FRAME_UNIQUE_ID_NULL != FrameUniqueID )
		{
			for ( j=0; j<FrameUniqueIDCount; j++ )
			{
				if ( FrameUniqueID == FrameUniqueIDList[j] )
				{
					FrameIndex_System = j;
					break;
				}
			}
		}
		ProjectPtr->SetProjectMarkFrameIndex_System(FrameIndex_System);
		JetField.FieldID = k;
		JetField.minX = FovPos.x-FOVW2;
		JetField.maxX = FovPos.x+FOVW2;
		JetField.minY = FovPos.y-FOVH2;
		JetField.maxY = FovPos.y+FOVH2;
		JetField.PosStageZ = FovPos.z;
		JetField.Ptr = ProjectPtr;
		JetFieldList.push_back(JetField);
		k ++;		
	}	
	MotionCtrlPtr->GetCurrentPos(StartPos.x, StartPos.y, StartPos.z);

	CJetFieldDivider FieldDivider;
	FieldDivider.SetSectionFactor(0.5);
	FieldDivider.SetFieldMaxW(FovWInner);
	FieldDivider.SetFieldMaxH(FovHInner);
	FieldDivider.SetPathStartPosX(StartPos.x);
	FieldDivider.SetPathStartPosY(StartPos.y);
	if ( FieldDivider.ExecFieldPath(JetFieldList) == false )
	{
		m_ErrorString.Format(_T("Error, FieldDivider.ExecFieldPath Fault [%s]"), fnName);
		return false; 
	}
	FieldDivider.CloneJetPathList(JetPathList);	
	const size_t JetFieldCount = JetFieldList.size();
	const size_t JetPathCount = JetPathList.size();
	if ( JetPathCount != JetFieldCount )
	{
		m_ErrorString.Format(_T("Error, FieldDivider.ExecFieldPath Fault [%s]"), fnName);
		return false; 
	}	
	
	DISTRICT_ID DistrictID = DISTRICT_ID_A;
	CameraFrameIdx = 0;
	FieldRect.left = 0;
	FieldRect.top  = 0;
	FieldRect.right = GetCameraImageW(CameraID);
	FieldRect.bottom = GetCameraImageH(CameraID);		
	for (i=0; i<JetPathCount; i++ )
	{
		FieldIdx = i;
		JetPathPtr = &(JetPathList[i]);
		JetFieldIdx = JetPathPtr->FieldID;
		if ( JetFieldIdx >= JetFieldCount ) { continue; }
		JetFieldPtr = &(JetFieldList[JetFieldIdx]);

		FovPos.x = (JetFieldPtr->minX+JetFieldPtr->maxX)*0.5;
		FovPos.y = (JetFieldPtr->minY+JetFieldPtr->maxY)*0.5;
		FovPos.z = JetFieldPtr->PosStageZ;
		ProjectPtr = (CAOIProject*)(JetFieldPtr->Ptr);

		FovPtr = AOIObjManager.CreateFovObj();
		if ( NULL == FovPtr )
		{	
			m_ErrorString.Format(_T("Error, Create AOI Fov Obj Fault [s]"), fnName);
			return false;
		}		
		FovPtr->SetFovFrameParamList(FrameParamList);
		FovPtr->SetFovSliceParamList(SliceParamList);
		FovPtr->SetFovStagePos(FovPos);		
		AddMarkFovPtr(FovPtr);

		//機台區分的區塊
		FieldPtr = AOIObjManager.CreateFieldObj();
		if ( NULL == FieldPtr )
		{	
			m_ErrorString.Format(_T("Error, Create AOI Field Obj Fault [%s]"), fnName);
			return false;
		}
		FieldPtr->SetFieldProjectPtr(ProjectPtr);
		FieldPtr->SetFieldLinkPointer(true);
		FieldPtr->SetFieldStagePos(FovPos);
		FieldPtr->SetFieldDistrictID(DistrictID);
		FieldPtr->SetFieldSize_Real(FovWReal, FovHReal);
		FieldPtr->SetFieldSize_Inner(FovWInner, FovHInner);
		FieldPtr->SetFieldSize_Outer(FovWOuter, FovHOuter);
		AddMarkFieldPtr(FieldPtr);
		
		//檢測區域的指標
		RgnPtr = AOIObjManager.CreateRgnObj();
		if ( NULL == RgnPtr )
		{	
			m_ErrorString.Format(_T("Error, Create AOI Region Obj Fault [%s]"), fnName);
			return false;
		}		
		RgnPtr->SetRgnProjectPtr(ProjectPtr);
		RgnPtr->SetRgnLinkPointer(false);
		FieldPtr->AddFieldRgnPtr(RgnPtr);
		AddMarkRgnPtr(RgnPtr);
		
		for ( j=0; j<FrameParamCount; j++ )
		{
			FrameParamPtr = &(FrameParamList[j]);
			if ( NULL == FrameParamPtr ) { continue; }
			FrameSlicePtrList.clear();
			if ( CreateFramePtrByFrameParam(FieldPtr, FrameParamPtr, CameraFrameIdx, FramePtr, FrameSlicePtrList) == false )
			{
				str = GetErrorString();
				AOIObjManager.DestroyFrameObj(FramePtr);
				FrameSliceCount = FrameSlicePtrList.size();
				for ( k=0; k<FrameSliceCount; k++ )
				{	AOIObjManager.DestroySliceObj(FrameSlicePtrList[k]);	}			
				m_ErrorString.Format(_T("%s [%s]"), str, fnName);
				return false;
			}
			FrameSliceCount = FrameSlicePtrList.size();
			for ( k=0; k<FrameSliceCount; k++ )
			{	AddMarkSlicePtr(FrameSlicePtrList[k]);	}			
			FieldPtr->AddFieldFramePtr(FramePtr);			
			FramePtr->SetFrameLinkPointer(false);
			FramePtr->SetFrameImageIndex((unsigned int)j);
			AddMarkFramePtr(FramePtr);
		}
	}	
	m_MarkProjectList = LaneProjectList;//軌道專案指標列表		
	m_MarkSliceParamList=SliceParamList;//單1影像參數列表
	m_MarkFrameParamList=FrameParamList;//影像參數列表	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SelectProjectMarkBestOne()//選擇專案標記成績最好 
{
	size_t  i=0;
	double  MarkScore=0;
	double  BestScore=0;
	CString strLaneID;
	LANE_ID LaneID = LANE_ID_RETURN;	
	CAOIProject *ProjectPtr = NULL;
	CAOIProject *ProjectPtrBest = NULL;
	CAOIProject *ProjectPtrBefore = NULL;	
	std::vector<CAOIProject*> LaneProjectList;	
	
	LaneID = GetActiveLaneID();	
	ProjectPtrBefore = GetActiveProject();	
	CloneLaneProjectList(LaneID, LaneProjectList);
	strLaneID = AOIDataDefine.GetLaneIDText(LaneID);
	const size_t LaneProjectCount = LaneProjectList.size();
	
	ProjectPtrBest = NULL;
	for ( i=0; i<LaneProjectCount; i++ )
	{
		ProjectPtr = LaneProjectList[i];
		if ( NULL == ProjectPtr ) { continue; }
		MarkScore = ProjectPtr->GetProjectMarkScore();
		if ( NULL==ProjectPtrBest || BestScore<MarkScore )
		{
			BestScore = MarkScore;
			ProjectPtrBest = ProjectPtr;
		}
	}
	if ( NULL == ProjectPtrBest ) 
	{
		m_ErrorString.Format(_T("Error, No Best Project in %s"), strLaneID);		
		return false;
	}
	if ( ProjectPtrBest == ProjectPtrBefore )
	{	
		SendMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_PROJECT_SWITCH_MARK, NULL);		
		return true; 
	}

	//切換專案
	const unsigned int ProjectIndex = ProjectPtrBest->GetProjectIndex();
	SetActiveProjectIndex(ProjectIndex);
	SendMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_PROJECT_SWITCH, NULL);
	return true;
}
