//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SwitchMultiLineOrder(TOnlineProcParam &Param, ONLINE_STATE_MODE &OnlineState)//切換多軌道次序
{
	LANE_ID   LaneID;		
	bool      SensorPcbStop = false;
	int       PLCPCBAutoRunMode = 0;
	const int PLCPCBAutoRunStop = PLC_PCB_AUTO_RUN_STOP;
	LANE_ID   LaneOrder[LANE_ID_RETURN];
	LANE_ID   LastLaneID=Param.eLaneID;
	LANE_ID   NextLaneID=LastLaneID;	
	const bool bDualRunMode = CheckDualRunMode();//20230425	
	LANE_WORK_MODE LaneWorkMode = LANE_WORK_RETURN;		
	PCB_OUT_DIRECTION PCBOutDirection = Param.ePCBOutDirection;	
	ONLINE_STATE_MODE OnlineStateMode = ONLINE_STATE_INSPECTION_STOP;	
	
	if ( true == bDualRunMode )
	{		
		LaneOrder[0] = LastLaneID;
		LaneOrder[1] = LANE_ID_NULL;				
	}
	else
	{
		//先跳開目前檢測的軌道
		switch ( LastLaneID )
		{
		case LANE_ID_B:	LaneOrder[0] = LANE_ID_A;	LaneOrder[1] = LANE_ID_B;
			break;
		default:
		case LANE_ID_A:	LaneOrder[0] = LANE_ID_B;	LaneOrder[1] = LANE_ID_A;
			break;
		}
	}

	//確認軌道
	for ( int i=0; i<2; i++ )
	{
		LaneWorkMode = GetLaneWorkMode(LaneOrder[i]);	
		if ( LANE_ID_NULL == LaneOrder[i] ) { continue; }//20230425	
		if ( LANE_WORK_DISABLE==LaneWorkMode ) { continue; }
		if ( ONLINE_STATE_PCB_AUTO_RUN_FINISH == OnlineState ) { continue; }		
		LaneID = LaneOrder[i];
		PLCPCBAutoRunMode = PlcCtrlPtr->GetPCBAutoRunMode(LaneID);//以PLC的執行狀態為主
		if ( PLC_PCB_AUTO_RUN_OUT_IN == PLCPCBAutoRunMode ) 
		{
			if ( PlcCtrlPtr->CheckPCBAutoOutInFault(LaneID) == true )
			{
				m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
				PlcCtrlPtr->SetPCBAutoRunMode(LaneID, PLCPCBAutoRunStop);
				return false;
			}
			if ( PlcCtrlPtr->CheckPCBAutoOutInFinish(LaneID) == true )
			{
				NextLaneID = LaneID;
				OnlineState = ONLINE_STATE_PCB_AUTO_RUN_FINISH;				
				PlcCtrlPtr->SetPCBAutoRunMode(LaneID, PLCPCBAutoRunStop);
			}
		}
		if ( PLC_PCB_AUTO_RUN_BACK_IN == PLCPCBAutoRunMode ) 
		{
			if ( PlcCtrlPtr->CheckPCBAutoBackInFault(LaneID) == true )
			{
				m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
				PlcCtrlPtr->SetPCBAutoRunMode(LaneID, PLCPCBAutoRunStop);
				return false;
			}
			if ( PlcCtrlPtr->CheckPCBAutoBackInFinish(LaneID) == true )
			{	
				NextLaneID = LaneID;
				OnlineState = ONLINE_STATE_PCB_AUTO_RUN_FINISH;				
				PlcCtrlPtr->SetPCBAutoRunMode(LaneID, PLCPCBAutoRunStop);
			}			
		}
		if ( PLC_PCB_AUTO_RUN_STOP == PLCPCBAutoRunMode )
		{
			OnlineStateMode = GetOnlineStateMode_Lane(LaneID);
			SensorPcbStop = PlcCtrlPtr->GetConveryerSensorPCBStop(LaneID);
			if ( true == SensorPcbStop ) 
			{	
				if ( ONLINE_STATE_INSPECTION_STOP==OnlineStateMode || ONLINE_STATE_PCB_READY==OnlineStateMode )
				{
					NextLaneID = LaneID;
					OnlineState = ONLINE_STATE_PCB_AUTO_RUN_FINISH;
				}
			}
		}
	}

	if ( ONLINE_STATE_PCB_AUTO_RUN_FINISH == OnlineState )
	{
		LockThread();
		LANE_ID SwitchLaneID = GetSwitchMultiLine_NextLaneID();
		if ( LANE_ID_NULL == SwitchLaneID )
		{	SetSwitchMultiLine_NextLaneID(NextLaneID); }
		UnlockThread();
	}
	if ( true == bDualRunMode )
	{	return true; }

	//可能會切換專案
	TASK_MODE TaskMode = GetTaskMode();
	if ( ONLINE_STATE_PCB_AUTO_RUN_FINISH == OnlineState )
	{
		LaneID = NextLaneID;
		SetActiveLaneID(NextLaneID);
		LaneWorkMode = GetLaneWorkMode(LaneID);
		if ( LANE_WORK_BYPASS == LaneWorkMode )			
		{	 //重新根據系統設定來決定進出板方向
			if ( ExecPCBAutoRunProc(LaneID, false, false, PCBOutDirection) == false )
			{	return false; }		
			OnlineState = ONLINE_STATE_PCB_AUTO_RUN_CHECKING;								
		}
		if ( LANE_WORK_RUN == LaneWorkMode )
		{			
			CAOIProject *ProjectPtrBefore = GetActiveProject();
			CAOIProject *ProjectPtrNew = GetConveyerFirstProjectPtr(LaneID);				
			if ( NULL == ProjectPtrNew ) 
			{
				this->m_ErrorString.Format(_T("Error, Lane Project Ptr Exception [%s]"), AOIDataDefine.GetLaneIDText(LaneID));
				return false;
			}

			if ( ProjectPtrNew != ProjectPtrBefore )
			{
				const unsigned int ProjectIndex = ProjectPtrNew->GetProjectIndex();
				SetActiveProjectIndex(ProjectIndex);
				SendMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_PROJECT_SWITCH, NULL);	
			}

			const bool bResetOKNG=false;
			TOnlineProcParam ParamNext=Param;
			DISTRICT_ID  DistrictID=DISTRICT_ID_A;
			ParamNext.eLaneID = ParamNext.eLaneIDNext = LaneID;
			const bool PreMove = CheckOnlineProcPreMoveCamera(ParamNext);
			if (true == PreMove)
			{
				if ( MoveCameraToConveyerFirstPos(ParamNext, ProjectPtrNew, bResetOKNG) == false )
				//if ( MoveCameraToProjectFirstPos(ProjectPtrNew, LaneID, DistrictID, false) == false )
				{	return false; }
			}

			//ProjectCount > 1會自動掃描專案標記
			if ( LastLaneID != LaneID )
			{	
				//PostMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_PROJECT_SWITCH_MAP, NULL);	
				PostMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_PROJECT_SWITCH_LANE, NULL);
			}
		}
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckLaneAutoRunFinish(LANE_ID LaneID, bool &Finish)//確認軌道自動運轉完成
{
	Finish = false;
	LANE_WORK_MODE LaneWorkMode = GetLaneWorkMode(LaneID);
	if ( LANE_WORK_DISABLE == LaneWorkMode )
	{	return true; }
	
	int PLCPCBAutoRunMode = PlcCtrlPtr->GetPCBAutoRunMode(LaneID);
	bool SensorPcbStop = PlcCtrlPtr->GetConveryerSensorPCBStop(LaneID);
	if ( PLC_PCB_AUTO_RUN_STOP == PLCPCBAutoRunMode )
	{
		if ( true == SensorPcbStop )
		{	Finish = true; }
	}
	if ( PLC_PCB_AUTO_RUN_OUT_IN == PLCPCBAutoRunMode ) 
	{
		if ( PlcCtrlPtr->CheckPCBAutoOutInFault(LaneID) == true )
		{
			m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
			return false;
		}
		if ( PlcCtrlPtr->CheckPCBAutoOutInFinish(LaneID) == true )
		{	Finish = true;	}
	}

	if ( PLC_PCB_AUTO_RUN_BACK_IN == PLCPCBAutoRunMode ) 
	{
		if ( PlcCtrlPtr->CheckPCBAutoBackInFault(LaneID) == true )
		{
			m_ErrorString = PlcCtrlPtr->GetPLCErrorString();
			return false;
		}
		if ( PlcCtrlPtr->CheckPCBAutoBackInFinish(LaneID) == true )
		{	Finish = true;	}
	}			
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckOtherLaneAutoRunFinish(LANE_ID CurLaneID, LANE_ID &NextLaneID)//確認其他軌道完成
{
	bool Finish = false;
	LANE_ID LaneID;

	//確認軌道A	
	LaneID = LANE_ID_A;
	if ( LaneID != CurLaneID )
	{
		if ( CheckLaneAutoRunFinish(LaneID, Finish) == false )
		{	return false; }
		if ( true == Finish )
		{
			NextLaneID = LaneID;
			return true;
		}
	}

	//確認軌道B	
	LaneID = LANE_ID_B;
	if ( LaneID != CurLaneID )
	{
		if ( CheckLaneAutoRunFinish(LaneID, Finish) == false )
		{	return false; }
		if ( true == Finish )
		{
			NextLaneID = LaneID;
			return true;
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SwitchMultiLineOrder_Dual(TOnlineProcParam &Param, ONLINE_STATE_MODE &OnlineState)//切換多軌道次序//20230425
{	
	LANE_ID   LaneID;		
	size_t    LaneIndex=0;
	PCB_OUT_MODE PCBOutMode;
	bool      SensorPcbStop = false;
	int       PLCPCBAutoRunMode = 0;
	const int PLCPCBAutoRunStop = PLC_PCB_AUTO_RUN_STOP;
	LANE_ID   LaneOrder[LANE_ID_RETURN];
	LANE_ID   LastLaneID=GetActiveLaneID();		
	LANE_ID   NextLaneID=LastLaneID;	
	LANE_WORK_MODE LaneWorkMode = LANE_WORK_RETURN;	
	LANE_ID SwitchLaneID = GetSwitchMultiLine_NextLaneID();
	PCB_OUT_DIRECTION PCBOutDirection = Param.ePCBOutDirection;	
	ONLINE_STATE_MODE OnlineStateMode = ONLINE_STATE_INSPECTION_STOP;	
	CString str;
	//str.Format(_T("CAOIDataCollect::SwitchMultiLineOrder_Dual SwitchLaneID: %d"), SwitchLaneID); SaveMovingTimeMsg(str);
	::memset(LaneOrder, 0x00, sizeof(LaneOrder));
	LANE_STATE_MODE LaneStateMode = GetOnlineLaneTaskState(SwitchLaneID);
	if (LANE_STATE_PAUSE == LaneStateMode) { SwitchLaneID = LANE_ID_NULL; }

	if ( LANE_ID_NULL != SwitchLaneID )
	{
		LaneOrder[0] = SwitchLaneID;
		LaneOrder[1] = LANE_ID_NULL;
	}
	else
	{
		//先跳開目前檢測的軌道
		switch ( LastLaneID )
		{
		case LANE_ID_B:	LaneOrder[0] = LANE_ID_A;	LaneOrder[1] = LANE_ID_B;
			break;
		default:
		case LANE_ID_A:	LaneOrder[0] = LANE_ID_B;	LaneOrder[1] = LANE_ID_A;
			break;
		}
	}
	for ( int i=0; i<2; i++ )
	{
		LaneWorkMode = GetLaneWorkMode(LaneOrder[i]);	
		if ( LANE_ID_NULL == LaneOrder[i] ) { continue; }
		if ( LANE_WORK_DISABLE == LaneWorkMode ) { continue; }
		LaneID = LaneOrder[i];				
		LaneStateMode = GetOnlineLaneTaskState(LaneID);
		if (LANE_STATE_PAUSE == LaneStateMode) { continue; }
		PCBOutMode = GetLanePCBOutMode(LaneID);
		LaneIndex = GetConveyerAutoRunLaneIdx(LaneID);		
		if ( CheckConveyerAutoRunException(LaneIndex) == true )
		{	return false; }
		bool bFinish = false;
		if ( CheckLaneDualRunFinish(LaneID, bFinish) == false )
		{	continue;	}
		if ( true == bFinish )
		{	
			NextLaneID = LaneID;
			OnlineState = ONLINE_STATE_PCB_DUAL_RUN_FINISH;			
			break;
		}
	}
	
	LaneStateMode = GetOnlineLaneTaskState(NextLaneID);
	if (LANE_STATE_PAUSE == LaneStateMode) {
		LaneID = LastLaneID;
		bool bFinished = false;

		LaneWorkMode = GetLaneWorkMode(LaneID);
		if (false == CheckLaneDualRunFinish(LaneID, bFinished)) { return false; }
		if (LANE_WORK_BYPASS == LaneWorkMode || LANE_STATE_BYPASS == LaneStateMode)
		{	 //重新根據系統設定來決定進出板方向
			if (ExecPCBDualRunProc(LaneID, false, false, NULL, PCBOutDirection, ONLINE_STATE_INSPECTION_FINISH) == false)
			{return false;	}
			OnlineState = ONLINE_STATE_PCB_DUAL_RUN_CHECKING;
		}
		if (true == bFinished) {
			OnlineState = ONLINE_STATE_PCB_DUAL_RUN_FINISH; ;
		}
		else {
			OnlineState = ONLINE_STATE_PCB_DUAL_RUN_CHECKING;
		}
	}

	//可能會切換專案
	TASK_MODE TaskMode = GetTaskMode();
	if ( ONLINE_STATE_PCB_DUAL_RUN_FINISH == OnlineState )
	{
		LaneID = NextLaneID;
		SetActiveLaneID(NextLaneID);
		LaneWorkMode = GetLaneWorkMode(LaneID);
		LaneStateMode = GetOnlineLaneTaskState(LaneID);
		//str.Format(_T("CAOIDataCollect::SwitchMultiLineOrder_Dual LaneWorkMode: %d, LaneStateMode : %d"), LaneWorkMode, LaneStateMode); SaveMovingTimeMsg(str);
		if ( LANE_WORK_BYPASS == LaneWorkMode || LANE_STATE_BYPASS == LaneStateMode)
		{	 //重新根據系統設定來決定進出板方向
			if ( ExecPCBDualRunProc(LaneID, false, false, NULL, PCBOutDirection, ONLINE_STATE_INSPECTION_FINISH) == false )
			{	return false; }
			OnlineState = ONLINE_STATE_PCB_DUAL_RUN_CHECKING;	
			return true;
		}
		if ( LANE_WORK_RUN == LaneWorkMode )
		{			
			CAOIProject *ProjectPtrBefore = GetActiveProject();
			CAOIProject *ProjectPtrNew = GetConveyerFirstProjectPtr(LaneID);			
			if ( NULL == ProjectPtrNew ) 
			{
				this->m_ErrorString.Format(_T("Error, Lane Project Ptr Exception [%s]"), AOIDataDefine.GetLaneIDText(LaneID));
				return false;
			}

			if ( ProjectPtrNew != ProjectPtrBefore )
			{
				const unsigned int ProjectIndex = ProjectPtrNew->GetProjectIndex();
				SetActiveProjectIndex(ProjectIndex);
				SendMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_PROJECT_SWITCH, NULL);	
			}				

			const bool bResetOKNG=false;
			TOnlineProcParam ParamNext=Param;
			DISTRICT_ID  DistrictID=DISTRICT_ID_A;			
			ParamNext.eLaneID = ParamNext.eLaneIDNext = LaneID;
			const bool PreMove = CheckOnlineProcPreMoveCamera(ParamNext);
			if (true == PreMove)
			{
				if ( MoveCameraToConveyerFirstPos(ParamNext, ProjectPtrNew, bResetOKNG) == false )				
				{	return false; }
			}			
			//ProjectCount > 1會自動掃描專案標記
			if ( LastLaneID != LaneID )
			{	
				//PostMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_PROJECT_SWITCH_MAP, NULL);	
				PostMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_PROJECT_SWITCH_LANE, NULL);
			}
		}
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckLaneDualRunFinish(LANE_ID LaneID, bool &Finish)//確認軌道雙軌運轉完成	
{
	Finish = false;
	size_t LaneIndex=GetConveyerAutoRunLaneIdx(LaneID);
	LANE_WORK_MODE LaneWorkMode = GetLaneWorkMode(LaneID);
	if ( LANE_WORK_DISABLE == LaneWorkMode )
	{	return true; }
	bool bPCBStop=PlcCtrlPtr->GetConveryerSensorPCBStop(LaneID);	
	if ( false == bPCBStop )
	{	return true; }
	bool bIdle=CheckConveyerAutoRunIdle(LaneIndex);
	bool bFinish=CheckConveyerAutoRunFinish(LaneIndex);	
	//CString str;
	//str.Format(_T("CAOIDataCollect::CheckLaneDualRunFinish LaneID: %d, bIdle:%d ,bFinish: %d "), LaneID, bIdle, bFinish);
	//SaveMovingTimeMsg(str);
	if ( true==bIdle || true==bFinish )	
	{	Finish = true; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckOtherLaneDualRunFinish(LANE_ID CurLaneID, LANE_ID &NextLaneID)//確認其他軌道完成
{	//20230425
	bool Finish = false;
	LANE_ID LaneID;
	std::vector<LANE_ID> LaneIDList;
	LaneIDList.push_back(LANE_ID_A);
	LaneIDList.push_back(LANE_ID_B);
	const size_t LaneIDCount=LaneIDList.size();
	for ( size_t i=0; i<LaneIDCount; i++ )
	{
		LaneID = LaneIDList[i];
		if ( LaneID == CurLaneID ) { continue; }		
		if ( CheckLaneDualRunFinish(LaneID, Finish) == false )
		{	return false; }
		if ( true == Finish )
		{
			NextLaneID = LaneID;
			return true;
		}		
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecOnlineProcPCBDualRunPauseOne(TOnlineProcParam &Param)
{
	bool            bPCBStop = false;
	bool            bPCBChanged = false;
	bool            bAutoRunFinish = false;
	int             PLCPCBAutoRunMode = 0;
	PCB_OUT_MODE    PCBOutMode;
	LANE_ID LaneID = Param.eLaneID;
	LANE_ID NewLaneID = LaneID;

	std::vector<LANE_ID> LaneIDList;
	ONLINE_STATE_MODE OnlineStageMode;
	MULTI_LANE_MODE MultiLaneMode = CheckMultiLaneMode();
	if (MULTI_LANE_2 != MultiLaneMode) { return true; }
	if (LANE_ID_NULL == LaneID) {
		LANE_STATE_MODE LaneStateMode_LA = GetOnlineLaneTaskState_LA();
		LANE_STATE_MODE LaneStateMode_LB = GetOnlineLaneTaskState_LB();
		if (LaneStateMode_LA == LANE_STATE_PAUSE) { LaneID = LANE_ID_A; }
		else { LaneID = LANE_ID_B; }
	}
	LANE_STATE_MODE  LaneStateMode = AOIDataCollect.GetOnlineLaneTaskState(LaneID);
	SaveMovingTimeMsg(_T("CAOIDataCollect::ExecOnlineProcPCBDualRunPauseOne Start"));

	OnlineStageMode = ONLINE_STATE_PCB_INSPECTION_PAUSE;
	SetOnlineStateMode_Lane(OnlineStageMode, LaneID);
	ResetSwitchMultiLine_NextLaneID();
	ExecBarcodeDeviceEndReading(LaneID);
	SaveMovingTimeMsg(_T("CAOIDataCollect::ExecOnlineProcPCBDualRunPauseOne End"));

	Param.eOnlineStateNew = OnlineStageMode;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecOnlineProcPCBDualRunResume(TOnlineProcParam &Param)
{
	
	LANE_ID LaneID = Param.eLaneID;
	LANE_ID NextLaneID = Param.eLaneID;
	ONLINE_FROM_MODE FromMode = Param.eFromMode;
	ONLINE_STATE_MODE OnlineStageMode, NewOnlineState;
	LANE_STATE_MODE LaneStateMode = GetOnlineLaneTaskState(LaneID);
	bool            bFinished = false;
	SaveMovingTimeMsg(_T("CAOIDataCollect::ExecOnlineProcPCBDualRunResume Start"));

	if (LANE_STATE_PAUSE == LaneStateMode) {
		if (LANE_ID_B == LaneID) { NextLaneID = LANE_ID_A; }
		else { NextLaneID = LANE_ID_B; }
	}

	if (false == CheckLaneDualRunFinish(NextLaneID, bFinished)) { return false; }
	if (false == bFinished) { return true; }
	SaveMovingTimeMsg(_T("CAOIDataCollect::ExecOnlineProcPCBDualRunResume Change End"));
	NewOnlineState = ONLINE_STATE_PCB_DUAL_RUN_CHECKING;
	ResetSwitchMultiLine_NextLaneID();
	Param.eOnlineStateNew = NewOnlineState;
	return true;
}
