//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::UserLogin_Sync(USER_LEVEL_MODE Level)//使用者登入
{
	const USER_LOGIN_MODE UserLoginMode=GetSystemParameter().m_UserLoginMode;
	if ( USER_LOGIN_DISABLE == UserLoginMode ) { return true; }

	LockUserInput();
	if ( GetIsStopUserInput() == true )
	{ 
		UnlockUserInput();
		return false; 
	}
	SetIsWaitUserInput(true);
	if ( SendMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_EXEC_USER_LOGIN_WND, Level) == false )
	{
		SetIsWaitUserInput(false);
		SetIsStopUserInput(true);
		UnlockUserInput();
		return false; 
	}
	if ( GetCurrentUserLevel() < Level )
	{	
		CString str, str2;
		CString strUserLevel=AOIDataDefine.GetUserLevelModeText(Level);		
		str2 = _T("Error, Login for User Level Fault");
		str2=LoadMultiLanguageString(str2, str2);
		str.Format(_T("%s [%s]"), str2, strUserLevel);
		SetErrorString(str);

		SetIsWaitUserInput(false);
		SetIsStopUserInput(true);
		UnlockUserInput();
		return false; 
	}

	SetIsWaitUserInput(false);
	UnlockUserInput();
	return true;
}
