bool CAOIDataCollect::UserLogin(USER_LEVEL_MODE Level, bool bForce)//使用者登入
{
	if ( UserLoginFn(Level, bForce) == false )
	{
		CString str, str2;
		CString strUserLevel=AOIDataDefine.GetUserLevelModeText(Level);		
		str2 = _T("Error, Login for User Level Fault");
		str2=LoadMultiLanguageString(str2, str2);
		str.Format(_T("%s [%s]"), str2, strUserLevel);
		SetErrorString(str);
		return false; 
	}
	if ( ExecMESComm_SetUserLogin_out(true) == false )
	{
		UserLogoutFn();
		return false;	
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::UserLoginFn(USER_LEVEL_MODE Level, bool bForce)//使用者登入
{
#ifdef _DEBUG
	return true;
#endif//_DEBUG
	TUserNode CurrentUser = GetLoginUserNode();	
	if ( CurrentUser.eUserLevel >= Level )
	{	return true; }
	const USER_LOGIN_MODE UserLoginMode=m_SystemParameter.m_UserLoginMode;
	//if ( USER_LEVEL_ENGINEER == Level )
	{
		if ( false == bForce )
		{
			if ( USER_LOGIN_DISABLE == UserLoginMode )
			{	return true; }
		}
	}	

	TUserNode    NewUser;
	CString      str;
	CString      strName;
	CString      strValue;
	CString      Password;
	CString      UserName;
	CString      sUserLevel;
	CString      strCaption;	
	CString      Section=_T("USER_LOGIN");
	CString      sLevel=AOIDataDefine.GetUserLevelModeText(Level);
	CInputBoxWnd InputBox;
	CFingerprintWnd FingerprintWnd;
		
	//str = _T("Input User Name");
	//str = LoadMultiLanguageString(Section, str, str);
	//strCaption.Format(_T("%s [%s]"), str, sLevel);
	//str = _T("Name");
	//strName = LoadMultiLanguageString(Section, str, str);
	//InputBox.SetParam1(strCaption, strName, strValue);
	//if ( InputBox.DoModal() == IDCANCEL ) { return false; }
	//UserName = InputBox.m_DataEdit1;

	USER_LOGIN_OPTIONS UserLoginOptions = GetSystemParameter().m_UserLoginOptions;
	if (USER_LOGIN_OPTIONS_PASSWORD < UserLoginOptions ) {
		FingerprintWnd.SetFingerPrintMode(USER_FINGERPRINT_MODE_FIND);
		if (FingerprintWnd.DoModal() == IDCANCEL) { return false; }
		if (FingerprintWnd.CheckReturnPassword() == false) {
			NewUser = FingerprintWnd.GetFingerPrintUser();
			m_LoginUserNode = NewUser;
			m_CurrentUserName = NewUser.wUserName;
			LogOperCtrl.SaveLogUserLogIn(NewUser);
			PostMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_SWITCH_USER, NULL);
			if (NewUser.eUserLevel < Level)
			{
				str = _T("Error, User level too low");
				str = LoadMultiLanguageString(Section, str, str);
				m_ErrorString.Format(_T("%s[%s--%s]"), str, UserName, sUserLevel);
				JetAPI::ShowMessageBox(m_ErrorString);
				return false;
			}
			return true;
		}
		else {
			if (USER_LOGIN_OPTIONS_FINGERPRINT_ONLY == UserLoginOptions) {
				Level = USER_LEVEL_JET_FAE;
				sLevel = AOIDataDefine.GetUserLevelModeText(Level);
			}
			UserLoginOptions = USER_LOGIN_OPTIONS_PASSWORD;
		}
	}
	if (USER_LOGIN_OPTIONS_PASSWORD == UserLoginOptions ) {
		str = _T("Input User Name");
		str = LoadMultiLanguageString(Section, str, str);
		strCaption.Format(_T("%s [%s]"), str, sLevel);
		str = _T("Name");
		strName = LoadMultiLanguageString(Section, str, str);
		InputBox.SetParam1(strCaption, strName, strValue);
		if (InputBox.DoModal() == IDCANCEL) { return false; }
		UserName = InputBox.m_DataEdit1;
	}

	str = _T("Input Password");
	str = LoadMultiLanguageString(Section, str, str);
	//strCaption.Format(_T("%s [%s]"), str, sLevel);
	strCaption.Format(_T("%s [%s] | User : [ %s ]"), str, sLevel, UserName);
	str = _T("Password");
	strName = LoadMultiLanguageString(Section, str, str);
	InputBox.SetPasswordMode(true);
	InputBox.SetParam1(strCaption, strName, strValue);
	if ( InputBox.DoModal() == IDCANCEL ) { return false; }
	Password = InputBox.m_DataEdit1;

	/*
	//移至下方
	if ( USER_LEVEL_OPERATOR == Level )
	{
		if ( CheckOnlineViewAutoLogout() == true )
		{	return true; }		
		BuildUserNode(UserName, Password, USER_LEVEL_OPERATOR, NewUser);		
		m_LoginUserNode = NewUser;
		m_CurrentUserName=NewUser.wUserName;
		LogOperCtrl.SaveLogUserLogIn(NewUser);
		PostMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_SWITCH_USER, NULL);			
		return true;								
	}	
	*/
	if ( FindUserNode(UserName, Password, NewUser) == false )
	{
		if ( USER_LEVEL_OPERATOR == Level )
		{	
			if ( CheckOperatorLoginWithPassword() == false )//作業員不用密碼
			{
				BuildUserNode(UserName, Password, USER_LEVEL_OPERATOR, NewUser);		
				m_LoginUserNode = NewUser;
				m_CurrentUserName=NewUser.wUserName;
				LogOperCtrl.SaveLogUserLogIn(NewUser);
				PostMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_SWITCH_USER, NULL);					
				return true;
			}
		}	
		JetAPI::ShowMessageBox(m_ErrorString);
		return false;	
	}

	sUserLevel=AOIDataDefine.GetUserLevelModeText(NewUser.eUserLevel);
	if ( NewUser.eUserLevel < Level )
	{
		str = _T("Error, User level too low");
		str = LoadMultiLanguageString(Section, str, str);
		m_ErrorString.Format(_T("%s[%s--%s]"), str, UserName, sUserLevel);
		JetAPI::ShowMessageBox(m_ErrorString);
		return false; 
	}	
	m_LoginUserNode = NewUser;
	m_CurrentUserName=NewUser.wUserName;
	LogOperCtrl.SaveLogUserLogIn(NewUser);
	PostMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_SWITCH_USER, NULL);		
	return true;
}
