//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::FindUserNode(LPCTSTR name, LPCTSTR password, TUserNode &User)//確認使用者
{
	CString  Folder;
	CString  filename;		
	CString  Section=_T("USER_LOGIN");
	std::vector<TUserNode> UserList;

	Folder = GetAOIDirectory();
	filename.Format(_T("%s\\%s"), Folder, _T("UserList.DAT"));
	if ( ReadUserFile(filename, UserList) == false ) 
	{	return false; }

	size_t       i=0;
	TUserNode    UserNode;
	CString      str;
	CString      UserName;
	CString      RefUserName;
	CString      Password;
	CString      RefPassword;
	const size_t UserCount = UserList.size();

	RefUserName = name;
	RefPassword = password;
	for ( i=0; i<UserCount; i++ )
	{
		UserNode = UserList[i];
		UserName = UserNode.wUserName;
		if ( UserName.CompareNoCase(RefUserName) != 0 ) { continue; }

		Password = UserNode.wPassword;
		if ( Password != RefPassword )
		{	
			str = _T("Error, User password mismatch");
			str = LoadMultiLanguageString(Section, str, str);
			m_ErrorString.Format(_T("%s[%s]"), str, RefUserName);
			return false; 
		}
		User = UserNode;
		return true;
	}
	str = _T("Error, No this User");
	str = LoadMultiLanguageString(Section, str, str);
	m_ErrorString.Format(_T("%s[%s]"), str, RefUserName);	
	return false;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::FindUserNode(const std::vector<TUserNode> &UserList, LPCTSTR name)//新增使用者
{
	size_t       i=0;
	size_t       Res=0;
	TUserNode    UserNode;
	CString      str;
	CString      UserName;
	CString      RefUserName;	
	CString      Section=_T("USER_LOGIN");
	const size_t UserCount = UserList.size();

	RefUserName = name;	
	for ( i=0; i<UserCount; i++ )
	{
		UserNode = UserList[i];
		UserName = UserNode.wUserName;
		if ( UserName.CompareNoCase(RefUserName) != 0 ) { continue; }		
		return true;
	}	
	str = _T("Error, No this User");
	str = LoadMultiLanguageString(Section, str, str);
	m_ErrorString.Format(_T("%s[%s]"), str, RefUserName);;
	return false;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ReadUserFile(LPCTSTR pfilename, std::vector<TUserNode> &UserList)//讀取使用者列表
{
	if ( ReadUserFileFn(pfilename, UserList) == false )
	{
		SetSystemExceptionCode_FileRead();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ReadUserFileFn(LPCTSTR pfilename, std::vector<TUserNode> &UserList)//讀取使用者列表
{
	if ( NULL == pfilename ) { return false; }

	size_t Res=0;	
	FILE *pfile = NULL;	
	pfile = ::_tfopen(pfilename, _T("rb"));
	if ( NULL == pfile ) 
	{
		m_ErrorString.Format(_T("Error, Open file to Read Fault [%s]"), pfilename);
		return false;
	}

	//Read Head Info
	TUserNode UserNode;
	TCHAR Info[16]=_T("JET_USER");
	Res = ::fread(Info, sizeof(Info), 1, pfile);
	if ( 0 == Res ) 
	{	
		m_ErrorString = _T("Error, Read User Info from File Fault");
		::fclose(pfile); pfile=NULL;
		return true; 
	}

	int nDataSize = (int)(sizeof(UserNode));
	Res = ::fread(&nDataSize, sizeof(nDataSize), 1, pfile);
	if ( 0 == Res ) 
	{	
		m_ErrorString = _T("Error, Read User DataSize from File Fault");
		::fclose(pfile); pfile=NULL;
		return true; 
	}
	
	const size_t CopyLen = MIN(nDataSize, sizeof(UserNode));
	unsigned char *pBuffer = new unsigned char[nDataSize];
	if ( NULL == pBuffer )
	{
		m_ErrorString.Format(_T("Error, Create User Data Buffer Fault [size:%d]"), nDataSize);
		::fclose(pfile); pfile=NULL;
		return false;
	}
	::memset(pBuffer, 0x00, sizeof(unsigned char)*nDataSize);

	while (!feof(pfile))
	{
		Res = ::fread(pBuffer, nDataSize, 1, pfile);
		if ( 0 == Res ) 
		{	break; }

		UserNode = TUserNode();
		::memcpy(&UserNode, pBuffer, sizeof(unsigned char)*CopyLen);

		UserList.push_back(UserNode);
	};
	delete[] pBuffer; pBuffer=NULL;
	::fclose(pfile); pfile=NULL;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::WriteUserFile(LPCTSTR pfilename, const std::vector<TUserNode> &UserList)//寫入使用者列表
{
	if ( WriteUserFileFn(pfilename, UserList) == false )
	{
		SetSystemExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::WriteUserFileFn(LPCTSTR pfilename, const std::vector<TUserNode> &UserList)//寫入使用者列表
{
	if ( NULL == pfilename ) { return false; }
	
	FILE *pfile = NULL;
	pfile = ::_tfopen(pfilename, _T("wb"));
	if ( NULL == pfile ) 
	{
		m_ErrorString.Format(_T("Error, Open file to Write Fault [%s]"), pfilename);
		return false;
	}

	size_t       i=0;
	size_t       Res=0;
	CString      str;	
	TUserNode    UserNode;
	const size_t UserCount = UserList.size();

	//Save Head Info
	TCHAR Info[16]=_T("JET_USER");
	Res = ::fwrite(Info, sizeof(Info), 1, pfile);
	if ( 0 == Res ) 
	{
		m_ErrorString = _T("Error, Write User Info to File Fault");
		::fclose(pfile); pfile=NULL;
		return false;
	}

	const int nDataSize = (int)(sizeof(UserNode));
	Res = ::fwrite(&nDataSize, sizeof(nDataSize), 1, pfile);
	if ( 0 == Res ) 
	{
		m_ErrorString = _T("Error, Write User DataSize to File Fault");
		::fclose(pfile); pfile=NULL;
		return false;
	}

	for ( i=0; i<UserCount; i++ )
	{
		UserNode = UserList[i];
		Res = ::fwrite(&UserNode, sizeof(UserNode), 1, pfile);
		if ( 1 != Res )
		{
			str = UserNode.wUserName;
			m_ErrorString.Format(_T("Error, Write User[%s] to File Fault"), str);
			break;
		}
	}	
	::fclose(pfile); pfile=NULL;	

	if ( UserCount != i )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::BuildUserNode(LPCTSTR name, LPCTSTR password, USER_LEVEL_MODE Level, TUserNode &User)//建立使用者	
{
	if ( NULL==name || NULL==password ) { return false; }
	std::wstring wsName;
	std::wstring wsPassword;
	JetAPI::TCHAR2wstring(name, wsName);
	JetAPI::TCHAR2wstring(password, wsPassword);

	User.eUserLevel = Level;
	::_tcscpy(User.wUserName, wsName.c_str());		
	::_tcscpy(User.wPassword, wsPassword.c_str());
	return true;
}
