//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CreateWndUniFrameList(bool bExtend, CAOIWnd *WndPtr, std::vector<TUNI_FRAME> &UniFrameList)//建立視窗的影像列表
{
	bool bSucc=true;
	if ( NULL == WndPtr ) { return false; }
	const CAlgParam &AlgParam=WndPtr->GetWndAlgParam();
	unsigned int FrameUniqueID=AlgParam.GetAlgImageBinParam().GetBinaryFrameUniqueID();
	if ( FRAME_UNIQUE_ID_DLP == FrameUniqueID )
	{	bSucc = CreateWndUniFrameListByModel(bExtend, WndPtr, UniFrameList);	}
	else
	{	bSucc = CreateWndUniFrameListByField(bExtend, WndPtr, UniFrameList);	}
	return bSucc;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CreateWndUniFrameListByModel(bool bExtend, CAOIWnd *WndPtr, std::vector<TUNI_FRAME> &UniFrameList)//建立視窗的影像列表
{
	if ( NULL == WndPtr ) { return false; }	
	CAOIModel* ModelPtr = GetModelUniFrameListModelPtr();	
	if ( NULL == ModelPtr ) { return false; }	
	const char fnName[] = "CAOIDataCollect::CreateWndUniFrameListByModel";
	const double AttachedAngle = ModelPtr->GetModelAttachedAngle();
	const bool   IsExceptionAngle = JetAPI::CheckIsExceptionAngle(AttachedAngle);
	
	const bool bCloned = false;
	TUNI_FRAME  *UniFramePtr = NULL;
	std::vector<TUNI_FRAME> WndUniFrameList;	
	std::vector<TUNI_FRAME> ModelUniFrameList;	
	if ( CopyModelUniFrameList(ModelUniFrameList, bCloned) == false )
	{	return false;	}	

	const size_t ModelUniFrameCount = ModelUniFrameList.size();
	if ( 0 == ModelUniFrameCount ) { return false; }
	
	CString    str;
	size_t     i=0;	
	size_t     WndBufferSize=0;
	RECT       ModelRect={0,0,0,0};
	RECT       WndRect={0,0,0,0};
	const int  nAlign = 4;
	TUNI_FRAME WndUniFrame;
	TPOINT2D   WndCornerPt[4];		
	TPOINT2D   ModelCornerPt[4];		
	TREGION4D  ModelRegion, WndRegion;
	TPOINT2D   ModelRgnCp, ImageSale, ModelImageCp;	
	TUNI_FRAME ModelUniFrame = ModelUniFrameList[0];	
	DRAW_MODEL_MODE DrawModelMode = GetDrawModelMode();		
	if (DRAW_MODEL_RESULT == DrawModelMode )
	{	
		WndPtr->GetWndRegionRes(WndRegion);
		WndPtr->GetWndCornerPosRes(WndCornerPt);		
		if ( true == bExtend )
		{
			WndPtr->GetWndExtendBox().GetBoxRegionRes(WndRegion);
			WndPtr->GetWndExtendBox().GetBoxCornerPosRes(WndCornerPt);			
		}
	}
	else
	{			
		WndPtr->GetWndRegion(WndRegion);
		WndPtr->GetWndCornerPos(WndCornerPt);
		if ( true == bExtend )
		{
			WndPtr->GetWndExtendBox().GetBoxRegion(WndRegion);
			WndPtr->GetWndExtendBox().GetBoxCornerPos(WndCornerPt);			
		}
	}	

	TSIZE2D    ImageSizeUm;
	IMAGE_SIZE ModelImageW = ModelUniFrame.ImageW;
	IMAGE_SIZE ModelImageH = ModelUniFrame.ImageH;
	IMAGE_SIZE ModelImageStep = ModelUniFrame.ImageStep;
	IMAGE_SIZE ModelImageBitCount = ModelUniFrame.BitCount;
	MapImageSizeToReal(PRIMARY_CAMERA_ID, ModelImageW, ModelImageH, ImageSizeUm);
	ModelPtr->SetModelImageSize_um(ImageSizeUm);
	ModelPtr->ModifyModelTotalRegionSize(ImageSizeUm.cx, ImageSizeUm.cy);
	ModelPtr->GetModelTotalRegion(ModelRegion);	
	ModelPtr->GetModelTotalCornerPts(ModelCornerPt);
	ModelPtr->CalcModelInspectionParam(ModelImageW, ModelImageH, ModelRgnCp, ModelImageCp, ImageSale);	
	
#ifdef _DEBUG
	BOOL bSave=FALSE;
#endif//_DEBUG
	if ( false == IsExceptionAngle )
	{		
		if ( CAOIModel::CalcModelBoxRegionRect(WndRegion, ModelImageW, ModelImageH, ModelRgnCp, ImageSale, ModelImageCp, WndRect) == false ) 
		{
			if ( true == bCloned )
			{	JetAPI::ClearUniFrameList(ModelUniFrameList); }
			return false; 
		}

		for ( i=0; i<ModelUniFrameCount; i++ )
		{
			ModelUniFrame = ModelUniFrameList[i];
			if ( ImageAPI.ExtractUniRoiImage(ModelUniFrame, WndRect, nAlign, fnName, WndUniFrame) == false )
			{	
				JetAPI::ClearUniFrameList(UniFrameList);
				if ( true == bCloned )
				{	JetAPI::ClearUniFrameList(ModelUniFrameList);	}
				return false;
			}
			UniFrameList.push_back(WndUniFrame);
			WndUniFrame = TUNI_FRAME();
		}
	}
	else
	{  
		//旋轉後				
		TUNI_FRAME   RotatedModelFrame;		
		TPOINT2D     ModelRoatatedRgnCp;
		TPOINT2D     ModelRotatedImageCp;
		TREGION4D    WndRoatedRgn;
		TREGION4D    ModelRoatedRgn;
		POINT        ModelRotatedStartPt;		
		const double ImageAngle = JetAPI::MapCadAngleToImageAngle(AttachedAngle);

		JetAPI::RotateCornerPos(-AttachedAngle, ModelRgnCp.x, ModelRgnCp.y, WndCornerPt);
		JetAPI::RotateCornerPos(-AttachedAngle, ModelRgnCp.x, ModelRgnCp.y, ModelCornerPt);
		JetAPI::CornerPtToRegion(WndCornerPt, WndRoatedRgn);
		JetAPI::CornerPtToRegion(ModelCornerPt, ModelRoatedRgn);

		ModelRoatatedRgnCp.x = ModelRoatedRgn.GetCpX();
		ModelRoatatedRgnCp.y = ModelRoatedRgn.GetCpY();
		const double ModelRotatedRgnW = ModelRoatedRgn.GetWidth();
		const double ModelRotatedRgnH = ModelRoatedRgn.GetHeight();
		const int    ModelRotateRectW = JetAPI::Floor(ModelRotatedRgnW*ImageSale.x);
		const int    ModelRotateRectH = JetAPI::Floor(ModelRotatedRgnH*ImageSale.y);

		for ( i=0; i<ModelUniFrameCount; i++ )
		{
			ModelUniFrame = ModelUniFrameList[i];
			if ( ImageAPI.RotateUniImage(-AttachedAngle, ModelUniFrame, nAlign, fnName, RotatedModelFrame) == false )			
			{	
				JetAPI::ClearUniFrameList(UniFrameList);
				if ( true == bCloned )
				{	JetAPI::ClearUniFrameList(ModelUniFrameList);	}
				return false;
			}

		#ifdef _DEBUG
			if ( TRUE == bSave )
			{				
				str.Format(_T("%s\\%s#d.PNG"), GetAOITempDirectory(), _T("BeforeModel"), i+1);
				ImageAPI.SaveImage(str, ModelUniFrame, true);
				
				str.Format(_T("%s\\%s#d.PNG"), GetAOITempDirectory(), _T("RotatedModel"), i+1);
				ImageAPI.SaveImage(str, RotatedModelFrame, true);
			}
		#endif//_DEBUG
			
			ModelRotatedStartPt.x = (RotatedModelFrame.ImageW-ModelRotateRectW)/2;
			ModelRotatedStartPt.y = (RotatedModelFrame.ImageH-ModelRotateRectH)/2;

			ModelRotatedImageCp.x = ModelRotateRectW;
			ModelRotatedImageCp.y = ModelRotateRectH;
			ModelRotatedImageCp.x = ModelRotatedImageCp.x*0.5;
			ModelRotatedImageCp.y = ModelRotatedImageCp.y*0.5;	
			if ( CAOIModel::CalcModelBoxRegionRect(WndRoatedRgn, ModelRotateRectW, ModelRotateRectH, ModelRoatatedRgnCp, ImageSale, ModelRotatedImageCp, WndRect) == false ) 
			{
				JetAPI::ClearUniFrame(RotatedModelFrame);
				JetAPI::ClearUniFrameList(UniFrameList);
				if ( true == bCloned )
				{	JetAPI::ClearUniFrameList(ModelUniFrameList); }
				return false; 
			}

			::OffsetRect(&WndRect, ModelRotatedStartPt.x, ModelRotatedStartPt.y);			
			if ( ImageAPI.ExtractUniRoiImage(RotatedModelFrame, WndRect, nAlign, fnName, WndUniFrame) == false )
			{	
				JetAPI::ClearUniFrame(RotatedModelFrame);
				JetAPI::ClearUniFrameList(UniFrameList);
				if ( true == bCloned )
				{	JetAPI::ClearUniFrameList(ModelUniFrameList);	}
				return false;
			}
		#ifdef _DEBUG
			if ( TRUE == bSave )
			{
				str.Format(_T("%s\\%s#d.PNG"), GetAOITempDirectory(), _T("RotatedWnd"), i+1);
				ImageAPI.SaveImage(str, WndUniFrame, true);
			}
		#endif//_DEBUG	
			JetAPI::ClearUniFrame(RotatedModelFrame);
			UniFrameList.push_back(WndUniFrame);
			WndUniFrame = TUNI_FRAME();
		}
	}	
	if ( true == bCloned )
	{	JetAPI::ClearUniFrameList(ModelUniFrameList);	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CreateWndUniFrameListByField(bool bExtend, CAOIWnd *WndPtr, std::vector<TUNI_FRAME> &UniFrameList)//建立視窗的影像列表
{
	if ( NULL == WndPtr ) { return false; }
	const char fnName[] = "CAOIDataCollect::CreateWndUniFrameListByField";
	
	bool   IsOK=true;
	size_t i=0;
	size_t BufferSize=0;	
	const int  nAlign = 4;
	double LevelingX=0.0;
	double LevelingY=0.0;
	double LevelingZ=0.0;	
	double LevelingOffset=0.0;
	double OverHigh =  DBL_MAX;
	double OverLow  = -DBL_MAX;
	TREGION4D  FieldRgn;	
	TUNI_FRAME WndUniFrame;
	TUNI_FRAME FieldUniFrame;	
	MASK_PTR   MaskPtr=NULL;
	MASK_PTR   MaskPtrRoi=NULL;
	PHASE_PTR  PhasePtr=NULL;
	PHASE_PTR  PhasePtrRoi=NULL;
	SPACE_PTR  SpacePtr=NULL;
	SPACE_PTR  SpacePtrRoi=NULL;
	IMAGE_PTR  ImagePtr=NULL;
	IMAGE_PTR  ImagePtrRoi=NULL;
	IMAGE_SIZE ImageW=0, ImageH=0, ImageStep=0, BitCount=0;	
	CAOIModel *ModelPtr = WndPtr->GetWndModelPtr();
	DRAW_MODEL_MODE DrawModelMode = GetDrawModelMode();		
	std::vector<TUNI_FRAME> FieldUniFrameList = m_FieldUniFrameList;
	const double AttachedAngle = WndPtr->GetWndAttachedAngle();
	const bool   IsExceptionAngle = JetAPI::CheckIsExceptionAngle(AttachedAngle);	
	
	RECT      BoxRect={0,0,0,0};	
	TREGION4D BoxRgn;
	TPOINT2D  ImageRes;
	TREGION4D BoxStageRgn;
	TREGION4D BoxImageRgn;	
	TPOINT2D  ImageCp, RgnCp;		
	IMAGE_SIZE RoiW=0, RoiH=0, RoiStep=0;
	
	FieldRgn = GetFieldUniFrameStageRegion();
	const double RegionW = FieldRgn.GetWidth();
	const double RegionH = FieldRgn.GetHeight();	
	RgnCp.x = FieldRgn.GetCpX();
	RgnCp.y = FieldRgn.GetCpY();	

	if ( NULL != ModelPtr )
	{
		LevelingX = ModelPtr->GetModelSpaceLeveingParamX();
		LevelingY = ModelPtr->GetModelSpaceLeveingParamY();
		LevelingZ = ModelPtr->GetModelSpaceLeveingParamZ();
		LevelingOffset = ModelPtr->GetModelSpaceLeveingOffsetZ();
	}
	JetAPI::ClearUniFrameList(UniFrameList);	
	const size_t UniFrameCount = FieldUniFrameList.size();	
	for ( i=0; i<UniFrameCount; i++ )
	{
		WndUniFrame = TUNI_FRAME();
		FieldUniFrame = FieldUniFrameList[i];		
		ImageW = FieldUniFrame.ImageW;
		ImageH = FieldUniFrame.ImageH;
		ImageStep = FieldUniFrame.ImageStep;
		BitCount = FieldUniFrame.BitCount;
		MaskPtr = FieldUniFrame.MaskPtr;
		ImagePtr = FieldUniFrame.ImagePtr;
		SpacePtr = FieldUniFrame.SpacePtr;
		PhasePtr = FieldUniFrame.PhasePtr;

		ImageRes.x = ImageW;
		ImageRes.y = ImageH;
		ImageRes.x = RegionW/ImageRes.x;
		ImageRes.y = RegionH/ImageRes.y;

		if ( false == IsExceptionAngle )
		{		
			if ( false == bExtend )
			{
				if (DRAW_MODEL_RESULT == DrawModelMode )
				{	WndPtr->GetWndRegionStageRes(BoxRgn);	}
				else
				{	WndPtr->GetWndRegionStage(BoxRgn);	}
			}
			else
			{
				if (DRAW_MODEL_RESULT == DrawModelMode )
				{	WndPtr->GetWndExtendBox().GetBoxRegionStageRes(BoxRgn);	}
				else
				{	WndPtr->GetWndExtendBox().GetBoxRegionStage(BoxRgn);	}
			}

			MapStageRegionToCamera(ImageW, ImageH, ImageRes, BoxRgn, RgnCp, BoxImageRgn);			
			JetAPI::Region4DToRect(BoxImageRgn, BoxRect, false);
			RoiW = BoxRect.right-BoxRect.left;
			RoiH = BoxRect.bottom-BoxRect.top;
			RoiStep = JetAPI::GetBMPImagePixelsPerLine(RoiW, BitCount, nAlign);
			WndUniFrame.ImageW = RoiW;
			WndUniFrame.ImageH = RoiH;
			WndUniFrame.ImageStep = RoiStep;
			WndUniFrame.BitCount = BitCount;
			if ( NULL != ImagePtr )
			{
				if ( ImageAPI.ExtractRoiImage(ImageW, ImageH, ImageStep, BitCount, ImagePtr, BoxRect, RoiStep, ImagePtrRoi, false) == false )
				{
					JetAPI::ClearUniFrame(WndUniFrame);
					JetAPI::ClearUniFrameList(UniFrameList);
					m_ErrorString = ImageAPI.GetImageApiErrorString();
					return false; 
				}
				WndUniFrame.ImagePtr = ImagePtrRoi;				
			}
			if ( NULL != MaskPtr )
			{
				if ( ImageAPI.ExtractGrayRoiImage(ImageW, ImageH, ImageStep, MaskPtr, BoxRect, RoiStep, MaskPtrRoi, false) == false )
				{					
					JetAPI::ClearUniFrame(WndUniFrame);
					JetAPI::ClearUniFrameList(UniFrameList);
					m_ErrorString = ImageAPI.GetImageApiErrorString();
					return false; 
				}
				WndUniFrame.MaskPtr = MaskPtrRoi;				
			}
			if ( NULL != PhasePtr )
			{
				if ( ImageAPI.ExtractPhaseGrayRoiImage(ImageW, ImageH, ImageStep, PhasePtr, BoxRect, RoiStep, PhasePtrRoi, false) == false )
				{					
					JetAPI::ClearUniFrame(WndUniFrame);
					JetAPI::ClearUniFrameList(UniFrameList);
					m_ErrorString = ImageAPI.GetImageApiErrorString();
					return false; 
				}
				WndUniFrame.PhasePtr = PhasePtrRoi;				
			}			
			if ( NULL != SpacePtr )
			{
				if ( ImageAPI.ExtractSpaceGrayRoiImage(ImageW, ImageH, ImageStep, SpacePtr, BoxRect, RoiStep, SpacePtrRoi, false) == false )
				{
					JetAPI::ClearUniFrame(WndUniFrame);
					JetAPI::ClearUniFrameList(UniFrameList);
					m_ErrorString = ImageAPI.GetImageApiErrorString();
					return false; 
				}
				WndUniFrame.SpacePtr = SpacePtrRoi;		
				ImageAPI.ExecSpaceImageLeveling3(RoiW, RoiH, RoiStep, SpacePtrRoi, MaskPtrRoi, 0, 0, LevelingZ, LevelingOffset, OverHigh, OverLow, SpacePtrRoi);
			}
		}
		else
		{
			RECT       ModelRect={0,0,0,0};
			TREGION4D  BoxRgnRotated;
			TPOINT2D   BoxCp;
			TPOINT2D   CornerPts[4];
			TPOINT2D   CornerPtsRotated[4];			
			IMAGE_SIZE BoxWRotated=0, BoxHRotated=0, BoxStepRotated=0;
			IMAGE_SIZE ImageWRotated=0, ImageHRotated=0, ImageStepRotated=0;
			//const double ImageRotateAngle = JetAPI::MapCadAngleToImageAngle(AttachedAngle);

			if ( false == bExtend )
			{
				if (DRAW_MODEL_RESULT == DrawModelMode )
				{	WndPtr->GetWndCornerPosStageRes(CornerPts);	}
				else
				{	WndPtr->GetWndCornerPosStage(CornerPts);	}
			}
			else
			{
				if (DRAW_MODEL_RESULT == DrawModelMode )
				{	WndPtr->GetWndExtendBox().GetBoxCornerPosStageRes(CornerPts);	}
				else
				{	WndPtr->GetWndExtendBox().GetBoxCornerPosStage(CornerPts);	}
			}
			JetAPI::CornerPtToRegion(CornerPts, BoxRgn);

			MapStageRegionToCamera(ImageW, ImageH, ImageRes, BoxRgn, RgnCp, BoxImageRgn);
			JetAPI::Region4DToRect(BoxImageRgn, BoxRect, false);			
			ImageWRotated = BoxRect.right-BoxRect.left;
			ImageHRotated = BoxRect.bottom-BoxRect.top;
			ImageStepRotated = JetAPI::GetBMPImagePixelsPerLine(ImageWRotated, BitCount, nAlign);

			BoxCp.x = BoxRgn.GetCpX();
			BoxCp.y = BoxRgn.GetCpY();
			BoxCp.x = -BoxCp.x;
			BoxCp.y = -BoxCp.y;
			//JetAPI::MoveCornerPts(CornerPts, BoxCp, CornerPtsRotated);
			//JetAPI::RotateCornerPos(-ComponentAngle, 0, 0, CornerPtsRotated);
			//JetAPI::CornerPtToRegion(CornerPtsRotated, BoxRgnRotated);		

			if ( NULL != ImagePtr )
			{
				IMAGE_PTR  BoxPtrRotated=NULL;
				IMAGE_PTR  ImagePtrRotated=NULL;
				JetAPI::MoveCornerPts(CornerPts, BoxCp, CornerPtsRotated);
				JetAPI::RotateCornerPos(-AttachedAngle, 0, 0, CornerPtsRotated);
				JetAPI::CornerPtToRegion(CornerPtsRotated, BoxRgnRotated);		
				if ( ImageAPI.ExtractRoiImage(ImageW, ImageH, ImageStep, BitCount, ImagePtr, BoxRect, ImageStepRotated, ImagePtrRotated, false) == false )
				{
					JetAPI::ClearUniFrame(WndUniFrame);
					JetAPI::ClearUniFrameList(UniFrameList);
					m_ErrorString = ImageAPI.GetImageApiErrorString();
					return false; 
				}		
			
				if ( ImageAPI.RotateImage(-AttachedAngle, ImageWRotated, ImageHRotated, ImageStepRotated, BitCount, ImagePtrRotated, BoxWRotated, BoxHRotated, BoxStepRotated, BoxPtrRotated) == false )
				{
					JetAPI::ClearUniFrame(WndUniFrame);
					JetAPI::ClearUniFrameList(UniFrameList);
					JetMemory.free_func(ImagePtrRotated);
					m_ErrorString = ImageAPI.GetImageApiErrorString();
					return false; 
				}

				double ImageCpX = BoxWRotated;
				double ImageCpY = BoxHRotated;
				ImageCpX = ImageCpX/2;
				ImageCpY = ImageCpY/2;
				BoxRgnRotated.minX = BoxRgnRotated.minX/ImageRes.x;
				BoxRgnRotated.minY = BoxRgnRotated.minY/ImageRes.y;
				BoxRgnRotated.maxX = BoxRgnRotated.maxX/ImageRes.x;
				BoxRgnRotated.maxY = BoxRgnRotated.maxY/ImageRes.y;

				BoxRect.left = JetAPI::Floor(BoxRgnRotated.minX+ImageCpX);
				BoxRect.top = JetAPI::Floor(BoxRgnRotated.minY+ImageCpY);
				BoxRect.right = JetAPI::Floor(BoxRgnRotated.maxX+ImageCpX);
				BoxRect.bottom = JetAPI::Floor(BoxRgnRotated.maxY+ImageCpY);
				RoiW = BoxRect.right-BoxRect.left;
				RoiH = BoxRect.bottom-BoxRect.top;
				RoiStep = JetAPI::GetBMPImagePixelsPerLine(RoiW, BitCount, nAlign);
				if ( ImageAPI.ExtractRoiImage(BoxWRotated, BoxHRotated, BoxStepRotated, BitCount, BoxPtrRotated, BoxRect, RoiStep, ImagePtrRoi, false) == false )
				{			
					JetAPI::ClearUniFrame(WndUniFrame);
					JetAPI::ClearUniFrameList(UniFrameList);
					JetMemory.free_func(BoxPtrRotated);
					JetMemory.free_func(ImagePtrRotated);
					m_ErrorString = ImageAPI.GetImageApiErrorString();
					return false; 
				}
				JetMemory.free_func(BoxPtrRotated);
				JetMemory.free_func(ImagePtrRotated);
				WndUniFrame.ImageW = RoiW;
				WndUniFrame.ImageH = RoiH;
				WndUniFrame.ImageStep = RoiStep;
				WndUniFrame.BitCount = BitCount;
				WndUniFrame.ImagePtr = ImagePtrRoi;
			}

			if ( NULL != MaskPtr )
			{
				MASK_PTR  BoxPtrRotated=NULL;
				MASK_PTR  MaskPtrRotated=NULL;
				JetAPI::MoveCornerPts(CornerPts, BoxCp, CornerPtsRotated);
				JetAPI::RotateCornerPos(-AttachedAngle, 0, 0, CornerPtsRotated);
				JetAPI::CornerPtToRegion(CornerPtsRotated, BoxRgnRotated);		
				if ( ImageAPI.ExtractGrayRoiImage(ImageW, ImageH, ImageStep, MaskPtr, BoxRect, ImageStepRotated, MaskPtrRotated, false) == false )
				{
					JetAPI::ClearUniFrame(WndUniFrame);
					JetAPI::ClearUniFrameList(UniFrameList);
					m_ErrorString = ImageAPI.GetImageApiErrorString();
					return false; 
				}		
			
				if ( ImageAPI.RotateMask(-AttachedAngle, ImageWRotated, ImageHRotated, ImageStepRotated, MaskPtrRotated, BoxWRotated, BoxHRotated, BoxStepRotated, BoxPtrRotated) == false )
				{
					JetAPI::ClearUniFrame(WndUniFrame);
					JetAPI::ClearUniFrameList(UniFrameList);
					JetMemory.free_func(MaskPtrRotated);
					m_ErrorString = ImageAPI.GetImageApiErrorString();
					return false; 
				}

				double ImageCpX = BoxWRotated;
				double ImageCpY = BoxHRotated;
				ImageCpX = ImageCpX/2;
				ImageCpY = ImageCpY/2;
				BoxRgnRotated.minX = BoxRgnRotated.minX/ImageRes.x;
				BoxRgnRotated.minY = BoxRgnRotated.minY/ImageRes.y;
				BoxRgnRotated.maxX = BoxRgnRotated.maxX/ImageRes.x;
				BoxRgnRotated.maxY = BoxRgnRotated.maxY/ImageRes.y;

				BoxRect.left = JetAPI::Floor(BoxRgnRotated.minX+ImageCpX);
				BoxRect.top = JetAPI::Floor(BoxRgnRotated.minY+ImageCpY);
				BoxRect.right = JetAPI::Floor(BoxRgnRotated.maxX+ImageCpX);
				BoxRect.bottom = JetAPI::Floor(BoxRgnRotated.maxY+ImageCpY);
				RoiW = BoxRect.right-BoxRect.left;
				RoiH = BoxRect.bottom-BoxRect.top;
				RoiStep = JetAPI::GetBMPImagePixelsPerLine(RoiW, BitCount, nAlign);
				if ( ImageAPI.ExtractGrayRoiImage(BoxWRotated, BoxHRotated, BoxStepRotated, BoxPtrRotated, BoxRect, RoiStep, MaskPtrRoi, false) == false )
				{			
					JetAPI::ClearUniFrame(WndUniFrame);
					JetAPI::ClearUniFrameList(UniFrameList);
					JetMemory.free_func(BoxPtrRotated);
					JetMemory.free_func(MaskPtrRotated);
					m_ErrorString = ImageAPI.GetImageApiErrorString();
					return false; 
				}
				JetMemory.free_func(BoxPtrRotated);
				JetMemory.free_func(MaskPtrRotated);
				WndUniFrame.ImageW = RoiW;
				WndUniFrame.ImageH = RoiH;
				WndUniFrame.ImageStep = RoiStep;
				WndUniFrame.BitCount = BitCount;
				WndUniFrame.MaskPtr = MaskPtrRoi;
			}	

			//少了相位旋轉

			if ( NULL != SpacePtr )
			{
				SPACE_PTR  BoxPtrRotated=NULL;
				SPACE_PTR  SpacePtrRotated=NULL;
				JetAPI::MoveCornerPts(CornerPts, BoxCp, CornerPtsRotated);
				JetAPI::RotateCornerPos(-AttachedAngle, 0, 0, CornerPtsRotated);
				JetAPI::CornerPtToRegion(CornerPtsRotated, BoxRgnRotated);		
				if ( ImageAPI.ExtractSpaceGrayRoiImage(ImageW, ImageH, ImageStep, SpacePtr, BoxRect, ImageStepRotated, SpacePtrRotated, false) == false )
				{
					JetAPI::ClearUniFrame(WndUniFrame);
					JetAPI::ClearUniFrameList(UniFrameList);
					m_ErrorString = ImageAPI.GetImageApiErrorString();
					return false; 
				}		
			
				if ( ImageAPI.RotateSpace(-AttachedAngle, ImageWRotated, ImageHRotated, ImageStepRotated, SpacePtrRotated, BoxWRotated, BoxHRotated, BoxStepRotated, BoxPtrRotated) == false )
				{
					JetAPI::ClearUniFrame(WndUniFrame);
					JetAPI::ClearUniFrameList(UniFrameList);
					JetMemory.free_func(SpacePtrRotated);
					m_ErrorString = ImageAPI.GetImageApiErrorString();
					return false; 
				}

				double ImageCpX = BoxWRotated;
				double ImageCpY = BoxHRotated;
				ImageCpX = ImageCpX/2;
				ImageCpY = ImageCpY/2;
				BoxRgnRotated.minX = BoxRgnRotated.minX/ImageRes.x;
				BoxRgnRotated.minY = BoxRgnRotated.minY/ImageRes.y;
				BoxRgnRotated.maxX = BoxRgnRotated.maxX/ImageRes.x;
				BoxRgnRotated.maxY = BoxRgnRotated.maxY/ImageRes.y;

				BoxRect.left = JetAPI::Floor(BoxRgnRotated.minX+ImageCpX);
				BoxRect.top = JetAPI::Floor(BoxRgnRotated.minY+ImageCpY);
				BoxRect.right = JetAPI::Floor(BoxRgnRotated.maxX+ImageCpX);
				BoxRect.bottom = JetAPI::Floor(BoxRgnRotated.maxY+ImageCpY);
				RoiW = BoxRect.right-BoxRect.left;
				RoiH = BoxRect.bottom-BoxRect.top;
				RoiStep = JetAPI::GetBMPImagePixelsPerLine(RoiW, BitCount, nAlign);
				if ( ImageAPI.ExtractSpaceGrayRoiImage(BoxWRotated, BoxHRotated, BoxStepRotated, BoxPtrRotated, BoxRect, RoiStep, SpacePtrRoi, false) == false )
				{			
					JetAPI::ClearUniFrame(WndUniFrame);
					JetAPI::ClearUniFrameList(UniFrameList);
					JetMemory.free_func(BoxPtrRotated);
					JetMemory.free_func(SpacePtrRotated);
					m_ErrorString = ImageAPI.GetImageApiErrorString();
					return false; 
				}
				JetMemory.free_func(BoxPtrRotated);
				JetMemory.free_func(SpacePtrRotated);
				WndUniFrame.ImageW = RoiW;
				WndUniFrame.ImageH = RoiH;
				WndUniFrame.ImageStep = RoiStep;
				WndUniFrame.BitCount = BitCount;
				WndUniFrame.SpacePtr = SpacePtrRoi;
				ImageAPI.ExecSpaceImageLeveling3(RoiW, RoiH, RoiStep, SpacePtrRoi, MaskPtrRoi, 0, 0, LevelingZ, LevelingOffset, OverHigh, OverLow, SpacePtrRoi);
			}				
		}
		UniFrameList.push_back(WndUniFrame);

		MaskPtrRoi = NULL;
		ImagePtrRoi = NULL;
		SpacePtrRoi = NULL;
		PhasePtrRoi = NULL;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CreateBarcodeDevice()
{	
#ifndef BARCODE_DEVICE_DISABLE
	size_t  i=0;
	bool    bIsOK=true;
	CString strError;
	CString strError2;		
	const size_t MaxDeviceCount = MAX_BARCODE_DEVICE_COUNT;		

	bIsOK=true;
	strError2 = _T("");
	m_ErrorString = _T("");	
	for ( i=0; i<MaxDeviceCount; i++ )
	{	
		if ( CreateBarcodeDevice(m_BarcodeParam[i]) == false )
		{
			bIsOK = false;
			if ( strError2.GetLength() > 0 )
			{	
				strError = GetErrorString(); 
				m_ErrorString.Format(_T("%s\n%s"), strError2, strError);			
			}
			strError2 = m_ErrorString;
		}
	}

	if ( strError2.GetLength() > 0 ) 
	{
		strError = GetErrorString(); 
		m_ErrorString.Format(_T("Error, %s"), strError);
	}
	return bIsOK;
#endif//BARCODE_DEVICE_DISABLE
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CreateBarcodeDevice(const TBarcodeDevice &BarcodeParam)//建立條碼機物件
{
#ifndef BARCODE_DEVICE_DISABLE
	CBarcode_Basic **Ptr = NULL;
	switch ( BarcodeParam.nDeviceID )
	{
	case BARCODE_DEVICE_ID_01: Ptr = &(m_BarcodeDevicePtr[0]); break;
	case BARCODE_DEVICE_ID_02: Ptr = &(m_BarcodeDevicePtr[1]); break;
	case BARCODE_DEVICE_ID_03: Ptr = &(m_BarcodeDevicePtr[2]); break;
	case BARCODE_DEVICE_ID_04: Ptr = &(m_BarcodeDevicePtr[3]); break;
	case BARCODE_DEVICE_ID_05: Ptr = &(m_BarcodeDevicePtr[4]); break;
	case BARCODE_DEVICE_ID_06: Ptr = &(m_BarcodeDevicePtr[5]); break;
	case BARCODE_DEVICE_ID_07: Ptr = &(m_BarcodeDevicePtr[6]); break;
	case BARCODE_DEVICE_ID_08: Ptr = &(m_BarcodeDevicePtr[7]); break;	
	}
	if ( NULL == Ptr ) 
	{
		this->m_ErrorString.Format(_T("Barcode Device ID Exception [%d]"), BarcodeParam.nDeviceID);
		SetBarcodeDeviceExceptionCode_Create(m_ErrorString);
		return false; 
	}

	if ( NULL != (*Ptr) )
	{	
		delete (*Ptr); 
		(*Ptr) = NULL; 
	}

#ifndef BARCODE_DEVICE_MODULE
	switch ( BarcodeParam.eDevieType )
	{
	case BARCODE_DEVICE_HONEYWELL_3310GHD:
		(*Ptr) = new CBarcode_Honeywell_3310GHD();
		if ( NULL == (*Ptr) )
		{
			m_ErrorString.Format(_T("Create Honeywell 3310GHD Device Object[%d] Fault"), BarcodeParam.nDeviceID);
			SetBarcodeDeviceExceptionCode_Create(m_ErrorString);
			return false; 
		}
		break;
	case BARCODE_DEVICE_DATALOGIC_MATRIX_210:
		(*Ptr) = new CBarcode_DataLogic_Matrix210();
		if ( NULL == (*Ptr) )
		{
			m_ErrorString.Format(_T("Create Datalogic Matrix210 Device Object[%d] Fault"), BarcodeParam.nDeviceID);
			SetBarcodeDeviceExceptionCode_Create(m_ErrorString);
			return false; 
		}
		break;
	case BARCODE_DEVICE_DATALOGIC_MATRIX_210N:
		(*Ptr) = new CBarcode_DataLogic_Matrix210N();
		if ( NULL == (*Ptr) )
		{
			m_ErrorString.Format(_T("Create Datalogic Matrix210N Device Object[%d] Fault"), BarcodeParam.nDeviceID);
			SetBarcodeDeviceExceptionCode_Create(m_ErrorString);
			return false; 
		}
		break;
	case BARCODE_DEVICE_KEYENCE_SR2000:
		(*Ptr) = new CBarcode_Keyence_SR2000();
		if ( NULL == (*Ptr) )
		{
			m_ErrorString.Format(_T("Create Keyence SR2000 Device Object[%d] Fault"), BarcodeParam.nDeviceID);
			SetBarcodeDeviceExceptionCode_Create(m_ErrorString);
			return false; 
		}
		break;
	case BARCODE_DEVICE_KEYENCE_SR751:
		(*Ptr) = new CBarcode_Keyence_SR751();
		if ( NULL == (*Ptr) )
		{
			m_ErrorString.Format(_T("Create KEYENCE SR751 Device Object[%d] Fault"), BarcodeParam.nDeviceID);
			SetBarcodeDeviceExceptionCode_Create(m_ErrorString);
			return false;
		}
		break;
	case BARCODE_DEVICE_OTHER_AZUREWAVE:
		(*Ptr) = new CBarcode_Azurewave();
		if ( NULL == (*Ptr) )
		{
			m_ErrorString.Format(_T("Create Azurewave Device Object[%d] Fault"), BarcodeParam.nDeviceID);
			SetBarcodeDeviceExceptionCode_Create(m_ErrorString);
			return false;
		}
		break;
	case BARCODE_DEVICE_GENERAL_DEVICE_01:
	case BARCODE_DEVICE_GENERAL_DEVICE_02:
	case BARCODE_DEVICE_GENERAL_DEVICE_03:
	case BARCODE_DEVICE_GENERAL_DEVICE_04:
	case BARCODE_DEVICE_GENERAL_DEVICE_05:
	case BARCODE_DEVICE_GENERAL_DEVICE_06:
	case BARCODE_DEVICE_GENERAL_DEVICE_07:
	case BARCODE_DEVICE_GENERAL_DEVICE_08:
		(*Ptr) = new CBarcode_General(BarcodeParam.eDevieType-BARCODE_DEVICE_GENERAL_GROUP);
		if ( NULL == (*Ptr) )
		{			
			m_ErrorString.Format(_T("Create General Device Object[%d] Fault"), BarcodeParam.nDeviceID);
			SetBarcodeDeviceExceptionCode_Create(m_ErrorString);
			return false;
		}
		break;
	case BARCODE_DEVICE_NULL:
	default:
		break;
	}
#else
	switch ( BarcodeParam.eDevieType )
	{
	case BARCODE_DEVICE_MICROSCAN_MS3:
	case BARCODE_DEVICE_MICROSCAN_MINI:
	case BARCODE_DEVICE_MICROSCAN_MINI_VELOCITY:
	case BARCODE_DEVICE_MICROSCAN_MINI3:
	case BARCODE_DEVICE_MICROSCAN_MINI_HAWK:

	case BARCODE_DEVICE_DATALOGIC_M1000:
	case BARCODE_DEVICE_DATALOGIC_MATRIX_200:
	case BARCODE_DEVICE_DATALOGIC_MATRIX_210:	
	case BARCODE_DEVICE_DATALOGIC_GFS4400:		

	case BARCODE_DEVICE_HONEYWELL_3310GHD:
	case BARCODE_DEVICE_HONEYWELL_1900:	
	
	case BARCODE_DEVICE_SICK_442:
	case BARCODE_DEVICE_SICK_ICR840:
		(*Ptr) = new CBarcode_Device_Module(BarcodeParam.eDevieType);
		if ( NULL == (*Ptr) )
		{
			m_ErrorString.Format(_T("Create Barcode Device Module[%d] Fault"), BarcodeParam.nDeviceID);
			SetBarcodeDeviceExceptionCode_Create(m_ErrorString);
			return false; 
		}				
		break;
	case BARCODE_DEVICE_NULL:
	default:
		break;
	}

#endif//BARCODE_DEVICE_MODULE

	if ( NULL == (*Ptr) ) { return true; }	
	(*Ptr)->SetBarcodeDeviceID(BarcodeParam.nDeviceID);
	(*Ptr)->SetBarcodeDevicePort(BarcodeParam.sDevicePort);
	if ( (*Ptr)->ConnectToDevice() == false )
	{	
		m_ErrorString = (*Ptr)->GetErrorString();	
		SetBarcodeDeviceExceptionCode_Connect(m_ErrorString);
		return false;
	}
#endif//BARCODE_DEVICE_DISABLE
	return true;
}
