//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckBarcodeDeviceIDList_LA(bool EnableList[])//確認條碼引數列表-LA
{
#ifndef BARCODE_DEVICE_DISABLE
	size_t  i=0;
	CString strError, strError2, strError3, strIndex, strLane;
	int     BarcodeDeviceID=0;
	CBarcode_Basic *BarcodeDevicePtr=NULL;
	const size_t MaxDeviceCount = MAX_BARCODE_DEVICE_COUNT;		
	strIndex = AOIDataDefine.GetIndexText();
	strLane = AOIDataDefine.GetLaneIDText(LANE_ID_A);	
	for ( i=0; i<MaxDeviceCount; i++ )
	{
		if ( false == EnableList[i] ) { continue; }
		BarcodeDeviceID = m_BarcodeDeviceIDList_LA[i];	
		BarcodeDevicePtr = GetBarcodeDevicePtr(BarcodeDeviceID);
		if ( BARCODE_DEVICE_ID_OFF==BarcodeDeviceID || NULL==BarcodeDevicePtr )
		{ 			
			strError3 = _T("Barcode Device does not setup");
			strError3 = AOIDataDefine.LoadMultiLanguageString_BarcodeDevice(strError3, strError3);
			strError2.Format(_T("%s %s[%s:%d]"), strLane, strError3, strIndex, i+1);
			if ( strError.GetLength() == 0 ) 
			{	strError = strError2; }
			else
			{
				strError3 = strError;
				strError.Format(_T("%s\n%s"), strError2, strError3);
			}
			SetBarcodeDeviceExceptionCode_Create(strError);
			continue; 
		}
		
		if ( BarcodeDevicePtr->GetBarcodeDeviceConnected() == false )
		{	
			strError3 = _T("Barcode Device does not connect to device");
			strError3 = AOIDataDefine.LoadMultiLanguageString_BarcodeDevice(strError3, strError3);
			strError2.Format(_T("%s %s[%s:%d]"), strLane, strError3, strIndex, i+1);
			if (strError.GetLength() == 0 ) 
			{	strError = strError2; }
			else
			{
				strError3 = strError;
				strError.Format(_T("%s\n%s"), strError2, strError3);
			}
			SetBarcodeDeviceExceptionCode_Connect(strError);
			continue;
		}
	}

	if ( strError.GetLength() > 0 )
	{	
		SetErrorString(strError);	
		return false;
	}
#endif//BARCODE_DEVICE_DISABLE
	return true;
}
