bool CAOIDataCollect::CheckOpenProjectBarcodeCanRun(ONLINE_FROM_MODE eFrom) const//確認可執行開專案條碼
{
	if ( ONLINE_FROM_ONLINE_THREAD != eFrom )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecOpenProjectBarcodeHandHeldReading(LANE_ID LaneID)//執行開專案手持條碼機讀取條碼
{
	if ( GetIsStopUserInput() == true ) { return false; }
	const TSystemParameter &SystemParam = GetSystemParameter();
	MULTI_LANE_MODE MultiLaneMode = CheckMultiLaneMode();
	ONLINE_OPEN_PROJECT_MODE  OnlineOpenProjectMode = SystemParam.m_OnlineOpenProjectMode;	
	if ( ONLINE_OPEN_PROJECT_BARCODE_HANDHELD != OnlineOpenProjectMode ) { return true; }	
	
	CString str;	

	LockUserInput();
	if ( GetIsStopUserInput() == true )
	{ 
		UnlockUserInput();
		return false; 
	}
	SetIsWaitUserInput(true);
	SetOnlineOpenProjectHandHeldResult(0);	
	SetOnlineOpenProjectHandHeldBarcode(_T(""));
	SendMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_EXEC_OPEN_PROJECT_BARCODE_WND , NULL);
	DWORD dwRet = GetOnlineOpenProjectHandHeldResult();
	CString strBarcode = GetOnlineOpenProjectHandHeldBarcode();		
	if ( IDCANCEL == dwRet )
	{	SetIsStopUserInput(true);	}
	SetIsWaitUserInput(false);
	UnlockUserInput();

	if ( IDCANCEL == dwRet )
	{
		str = _T("Error, User cancel the barcode input");
		m_ErrorString = LoadMultiLanguageString(str, str);
		return false;
	}
	const int BarcodeLen=1024;
	char Barcode[BarcodeLen];		
	std::vector<std::string> strBarcodeList;
	JetAPI::TCHAR2char(strBarcode, Barcode, BarcodeLen);
	strBarcodeList.push_back(Barcode);
	if ( ExecOnlineProcBarcodeOpenProject(strBarcodeList, ONLINE_OPEN_PROJECT_BARCODE_HANDHELD) == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecOpenProjectBarcodeDeviceStartToRead(ONLINE_STATE_MODE OnlineState, LANE_ID LaneID, bool BeforeRetrieveCode)//執行開專案條碼機開始讀取條碼
{
#ifndef BARCODE_DEVICE_DISABLE	
	MULTI_LANE_MODE MultiLaneMode = CheckMultiLaneMode();
	const TSystemParameter &SystemParam = GetSystemParameter();
	ONLINE_OPEN_PROJECT_MODE  OnlineOpenProjectMode = SystemParam.m_OnlineOpenProjectMode;
	BARCODE_DEVICE_GRAB_MODE  BarcodeDeviceGrabMode = SystemParam.m_OnlineOpenProjectBarcodeDeviceGrabMode;
	if ( ONLINE_OPEN_PROJECT_BARCODE_DEVICE != OnlineOpenProjectMode ) { return true; }
	switch ( BarcodeDeviceGrabMode )
	{
	case BARCODE_DEVICE_GRAB_BEFORE_PCB_IN://進板前
		if ( ONLINE_STATE_PCB_IN_START != OnlineState ) { return true; }
		break;
	case BARCODE_DEVICE_GRAB_WHILE_PCB_IN://進板中
		if ( MULTI_LANE_1 == MultiLaneMode )
		{	//開始進板
			if ( ONLINE_STATE_PCB_IN_START != OnlineState ) {	return true; }
		}
		else
		{	//檢測完畢
			if ( ONLINE_STATE_INSPECTION_FINISH != OnlineState ) {	return true; }
		}
		break;
	case BARCODE_DEVICE_GRAB_AFTER_PCB_IN://進板後
		if ( true == BeforeRetrieveCode ) { return true; }
		if ( ONLINE_STATE_INSPECTION_STOP  != OnlineState && 
		     ONLINE_STATE_INSPECTION_START != OnlineState 
		   )
		{ return true; }
		break;
	case BARCODE_DEVICE_GRAB_BEFORE_INSPECT://檢測前
		if ( false == BeforeRetrieveCode ) { return true; }
		if ( ONLINE_STATE_INSPECTION_START != OnlineState ) { return true; }		
		break;
	}
	
	size_t           i=0;
	bool             IsOK=false;
	int              BarcodeDeviceID=0;
	CString strError, strError2, strError3, strLane, strID;
	CBarcode_Basic  *BarcodeDevicePtr=NULL;
	bool BarcodeDeviceUsedList[MAX_BARCODE_DEVICE_COUNT];
	const size_t MaxBarcodeDeviceCount = MAX_BARCODE_DEVICE_COUNT;	

	IsOK = true;
	strID = AOIDataDefine.GetIDText();
	strLane = AOIDataDefine.GetLaneIDText(LaneID);	
	CloneOpenProjectBarcodeDeviceUsedList(BarcodeDeviceUsedList);	
	for ( i=0; i<MaxBarcodeDeviceCount; i++ )
	{
		if ( BarcodeDeviceUsedList[i] == false ) { continue; }
		if ( LANE_ID_B == LaneID )
		{	BarcodeDeviceID = this->m_BarcodeDeviceIDList_LB[i]; }
		else
		{	BarcodeDeviceID = this->m_BarcodeDeviceIDList_LA[i]; }
		BarcodeDevicePtr = GetBarcodeDevicePtr(BarcodeDeviceID);
		if ( NULL == BarcodeDevicePtr )
		{
			strError3 = _T("Barcode Device does not setup");
			strError3 = AOIDataDefine.LoadMultiLanguageString_BarcodeDevice(strError3, strError3);
			strError2.Format(_T("%s %s[%s:%d]"), strLane, strError3, strID, BarcodeDeviceID);
			if ( strError.GetLength() == 0 ) { strError = strError2; }
			else
			{
				strError3.Format(_T("%s\n%s"), strError, strError2);
				strError = strError3;
			}
			IsOK = false;
			SetBarcodeDeviceExceptionCode_Create(strError);
			continue;
		}
		if ( BarcodeDevicePtr->GetBarcodeDeviceConnected() == false )
		{
			strError3 = _T("Barcode Device does not connect to device");
			strError3 = AOIDataDefine.LoadMultiLanguageString_BarcodeDevice(strError3, strError3);
			strError2.Format(_T("%s %s[%s:%d]"), strLane, strError3, strID, BarcodeDeviceID);
			if ( strError.GetLength() == 0 ) { strError = strError2; }
			else
			{
				strError3.Format(_T("%s\n%s"), strError, strError2);
				strError = strError3;
			}
			IsOK = false;
			SetBarcodeDeviceExceptionCode_Connect(strError);
			continue;
		}
		if ( BarcodeDevicePtr->StartToRead() == false )
		{	
			strError3 = _T("Barcode Device start to read fault");
			strError3 = AOIDataDefine.LoadMultiLanguageString_BarcodeDevice(strError3, strError3);
			strError2.Format(_T("%s %s[%s:%d]"), strLane, strError3, strID, BarcodeDeviceID);
			if ( strError.GetLength() == 0 ) { strError = strError2; }
			else
			{
				strError3.Format(_T("%s\n%s"), strError, strError2);
				strError = strError3;
			}
			IsOK = false;
			SetBarcodeDeviceExceptionCode_Start(strError);
			continue;
		}		
	}
	if ( false == IsOK )
	{	
		strError2 = AOIDataDefine.GetErrorText();
		strError3.Format(_T("%s, %s"), strError2, strError);
		strError = strError3;
		SetErrorString(strError);	
	}
#endif//BARCODE_DEVICE_DISABLE	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecOpenProjectBarcodeDeviceRetrieveCode(ONLINE_STATE_MODE OnlineState, LANE_ID LaneID)//執行開專案條碼機讀取條碼
{	
#ifndef BARCODE_DEVICE_DISABLE
	const TSystemParameter &SystemParam = GetSystemParameter();
	ONLINE_OPEN_PROJECT_MODE  OnlineOpenProjectMode = SystemParam.m_OnlineOpenProjectMode;
	BARCODE_DEVICE_GRAB_MODE  BarcodeDeviceGrabMode = SystemParam.m_OnlineOpenProjectBarcodeDeviceGrabMode;
	if ( ONLINE_OPEN_PROJECT_BARCODE_DEVICE != OnlineOpenProjectMode ) { return true; }
	switch ( BarcodeDeviceGrabMode )
	{
	case BARCODE_DEVICE_GRAB_BEFORE_PCB_IN://進板前
		if ( ONLINE_STATE_PCB_IN_START != OnlineState ) { return true; }
		break;
	case BARCODE_DEVICE_GRAB_WHILE_PCB_IN://進板中
		//if ( ONLINE_STATE_INSPECTION_START != OnlineState ) { return true; }
		if ( ONLINE_STATE_PCB_READY != OnlineState ) { return true; }		
		break;
	case BARCODE_DEVICE_GRAB_AFTER_PCB_IN://進板後
		//單軌可以改成進板前讀取
		if ( ONLINE_STATE_INSPECTION_START != OnlineState ) { return true; }		
		break;
	case BARCODE_DEVICE_GRAB_BEFORE_INSPECT://檢測前
		if ( ONLINE_STATE_INSPECTION_START != OnlineState ) { return true; }		
		break;
	}

	size_t           i=0, j=0;
	bool             IsOK=true;
	int              BarcodeDeviceID=0;	
	CString strError, strError2, strError3, strLane, strID;
	CBarcode_Basic  *BarcodeDevicePtr=NULL;	
	std::vector<CBarcode_Basic*> BarcodeDeviceOkList;
	std::vector<CBarcode_Basic*> BarcodeDeviceNgList;
	BARCODE_NG_HANDLE_MODE BarcodeNGHandleMode = BARCODE_NG_HANDLE_ALARM;
	bool BarcodeDeviceUsedList[MAX_BARCODE_DEVICE_COUNT];
	const size_t MaxBarcodeDeviceCount = MAX_BARCODE_DEVICE_COUNT;
	IsOK=true;
	strID = AOIDataDefine.GetIDText();
	strLane = AOIDataDefine.GetLaneIDText(LaneID);	
	CloneOpenProjectBarcodeDeviceUsedList(BarcodeDeviceUsedList);	
	for ( i=0; i<MaxBarcodeDeviceCount; i++ )
	{
		if ( BarcodeDeviceUsedList[i] == false ) { continue; }
		if ( LANE_ID_B == LaneID )
		{	BarcodeDeviceID = this->m_BarcodeDeviceIDList_LB[i]; }
		else
		{	BarcodeDeviceID = this->m_BarcodeDeviceIDList_LA[i]; }
		BarcodeDevicePtr = GetBarcodeDevicePtr(BarcodeDeviceID);
		if ( NULL == BarcodeDevicePtr )
		{
			strError3 = _T("Barcode Device does not setup");
			strError3 = AOIDataDefine.LoadMultiLanguageString_BarcodeDevice(strError3, strError3);
			strError2.Format(_T("%s %s[%s:%d]"), strLane, strError3, strID, BarcodeDeviceID);
			if ( strError.GetLength() == 0 ) { strError = strError2; }
			else
			{
				strError3.Format(_T("%s\n%s"), strError, strError2);
				strError = strError3;
			}
			IsOK = false;
			SetBarcodeDeviceExceptionCode_Create(strError);
			continue;
		}
		if ( BarcodeDevicePtr->GetBarcodeDeviceConnected() == false )
		{
			strError3 = _T("Barcode Device does not connect to device");
			strError3 = AOIDataDefine.LoadMultiLanguageString_BarcodeDevice(strError3, strError3);
			strError2.Format(_T("%s %s[%s:%d]"), strLane, strError3, strID, BarcodeDeviceID);
			if ( strError.GetLength() == 0 ) { strError = strError2; }
			else
			{
				strError3.Format(_T("%s\n%s"), strError, strError2);
				strError = strError3;
			}
			IsOK = false;
			SetBarcodeDeviceExceptionCode_Connect(strError);
			continue;
		}
		if ( BarcodeDevicePtr->RetrieveCode() == false )
		{
			strError3 = _T("Barcode Device read barcode fault");
			strError3 = AOIDataDefine.LoadMultiLanguageString_BarcodeDevice(strError3, strError3);
			strError2.Format(_T("%s %s[%s:%d]"), strLane, strError3, strID, BarcodeDeviceID);
			if ( strError.GetLength() == 0 ) { strError = strError2; }
			else
			{
				strError3.Format(_T("%s\n%s"), strError, strError2);
				strError = strError3;
			}
			IsOK = false;
			SetBarcodeDeviceExceptionCode_Decode(strError);
			BarcodeDevicePtr->EndReading();//關閉讀取
			BarcodeDeviceNgList.push_back(BarcodeDevicePtr);
			continue;
		}
		BarcodeDevicePtr->EndReading();//關閉讀取
		BarcodeDeviceOkList.push_back(BarcodeDevicePtr);
	}	

	const bool   bOpenProjectFinish = GetOnlineOpenProjectFinish();
	if ( true == bOpenProjectFinish )
	{	return true; }

	const size_t BarcodeDeviceOkCount=BarcodeDeviceOkList.size();	
	const size_t BarcodeDeviceNgCount=BarcodeDeviceNgList.size();
	if ( BARCODE_NG_HANDLE_PASS != BarcodeNGHandleMode )//異常時不警報
	{
		if ( false==IsOK || 0==BarcodeDeviceOkCount )
		{	
			if ( BARCODE_NG_HANDLE_ALARM==BarcodeNGHandleMode || 0==BarcodeDeviceNgCount )
			{
				strError2 = AOIDataDefine.GetErrorText();
				strError3.Format(_T("%s, %s"), strError2, strError);
				strError = strError3;
				SetErrorString(strError);	
				if ( ExecOnlineProcBarcodeOpenProjectCheckEnd(ONLINE_OPEN_PROJECT_BARCODE_DEVICE) == false )
				{	return true; }
				return false;
			}
			if ( BARCODE_NG_HANDLE_INPUT == BarcodeNGHandleMode )
			{
				strError2 = AOIDataDefine.GetErrorText();
				strError3.Format(_T("%s, %s"), strError2, strError);
				strError = strError3;
				SetErrorString(strError);	
				if ( ExecOnlineProcBarcodeOpenProjectCheckEnd(ONLINE_OPEN_PROJECT_BARCODE_DEVICE) == false )
				{	return true; }
				return false;
			}
		}
	}
	
	if ( true==IsOK && 0!=BarcodeDeviceOkCount )
	{
		char *strBarcodePtr=NULL;
		std::vector<std::string> strBarcodeList;
		for ( i=0; i<BarcodeDeviceOkCount; i++ )
		{
			BarcodeDevicePtr = BarcodeDeviceOkList[i];
			if ( NULL == BarcodeDevicePtr ) { continue; }
			strBarcodePtr = (char*)BarcodeDevicePtr->GetResultSubBackup(0);
			if ( NULL == strBarcodePtr ) { continue; }
			strBarcodeList.push_back(strBarcodePtr);
		}	
		if ( 0 != strBarcodeList.size() )
		{
			if ( ExecOnlineProcBarcodeOpenProject(strBarcodeList, ONLINE_OPEN_PROJECT_BARCODE_DEVICE) == false )
			{	return false; }
		}
	}	
#endif//BARCODE_DEVICE_DISABLE	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecProjectBarcodeDeviceInputCode(CAOIProject *ProjectPtr, CBarcode_Basic* BarcodeDevicePtr, LANE_ID LaneID)//執行專案條碼機輸入條碼
{
	if ( GetIsStopUserInput() == true ) { return false; }
	if ( CheckProjectPtr(ProjectPtr) == false ) { return false; }
	BARCODE_INPUT_TYPE  BarcodeInputType = ProjectPtr->GetProjectParameter().m_BarcodeInputType;
	BARCODE_NG_HANDLE_MODE BarcodeNGHandleMode = ProjectPtr->GetProjectParameter().m_BarcodeNGHandleMode;
	if ( BARCODE_INPUT_DEVICE != BarcodeInputType ) { return true; }
	if ( true )
	{	
		switch ( LaneID )
		{
		case LANE_ID_B:	SaveDebugMessage(_T("CAOIDataCollect::ExecProjectBarcodeDeviceInputCode_LB"));	break;			
		default:
		case LANE_ID_A:	SaveDebugMessage(_T("CAOIDataCollect::ExecProjectBarcodeDeviceInputCode_LA"));	break;
		}
		SaveDebugMessage(ProjectPtr->GetProjectShowName());
	}

	CString strError, strError2, strError3;		
	LockUserInput();
	if ( GetIsStopUserInput() == true )
	{ 
		UnlockUserInput();
		return false; 
	}
	SetIsWaitUserInput(true);
	SetBarcodeHandHeldResult(0);
	SetBarcodeHandHeldLaneID(LaneID);
	SetBarcodeHandHeld_Project(ProjectPtr);
	SendMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_EXEC_BARCODE_HANDHELD_WND, NULL);
	SetBarcodeHandHeld_Project(NULL);
	DWORD Res = GetBarcodeHandHeldResult();		
	if ( IDOK != Res ) 
	{	SetIsStopUserInput(true);	}
	SetIsWaitUserInput(false);
	UnlockUserInput();

	if ( IDOK != Res ) 
	{
		strError2 = AOIDataDefine.GetErrorText();
		strError = _T("User cancel the barcode input");
		strError = AOIDataDefine.LoadMultiLanguageString_BarcodeHandHeld(strError, strError);
		strError3.Format(_T("%s, %s"), strError2, strError);
		SetErrorString(strError3);
		return false; 		
	}

	CBarcode_Handheld *Barcode_HandheldPtr=GetBarcodeHandHeldPtr(LaneID);
	if ( NULL == Barcode_HandheldPtr )
	{	
		strError=_T("Error, Barcode_HandheldPtr == NULL");
		SetErrorString(strError);	
		return false; 
	}
	
	size_t i=0;
	std::string   Barcode;
	TBarcodeInfo *BarcodeInfoPtr=NULL;
	const size_t  BarcodeInfoCount=Barcode_HandheldPtr->GetBarcodeInfoCount();
	if ( NULL != BarcodeDevicePtr )
	{
		for ( i=0; i<BarcodeInfoCount; i++ )
		{
			BarcodeInfoPtr=Barcode_HandheldPtr->GetBarcodeInfoPtr(i, true);
			if ( NULL == BarcodeInfoPtr )
			{	
				strError=_T("Error, BarcodeInfoPtr == NULL");
				SetErrorString(strError);	
				return false; 
			}
			JetAPI::wchar2string(BarcodeInfoPtr->wsBarcode.c_str(), Barcode);				
			BarcodeDevicePtr->SetResultSubBuffer(i, Barcode.c_str());			
			BarcodeDevicePtr->BackupResultBuffer();				
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecProjectBarcodeDeviceStartToRead(CAOIProject *ProjectPtr, ONLINE_STATE_MODE OnlineState, LANE_ID LaneID, bool BeforeRetrieveCode)//執行專案條碼機開始讀取條碼
{
	if ( CheckProjectPtr(ProjectPtr) == false )	{	return false;	}
#ifndef BARCODE_DEVICE_DISABLE
	LANE_STATE_MODE LaneStateMode = GetOnlineLaneTaskState(LaneID);
	if (LANE_STATE_BYPASS == LaneStateMode)
	{	return true;	}

	PCB_OUT_MODE PCBOutMode = GetLanePCBOutMode(LaneID);	
	BARCODE_INPUT_TYPE  BarcodeInputType = ProjectPtr->GetProjectParameter().m_BarcodeInputType;
	BARCODE_DEVICE_GRAB_MODE BarcodeDeviceGrabMode = ProjectPtr->GetProjectParameter().m_BarcodeDeviceGrabMode;
	if ( BARCODE_INPUT_DEVICE != BarcodeInputType ) { return true; }
	if ( true )
	{		
		switch ( LaneID )
		{
		case LANE_ID_B:	SaveDebugMessage(_T("CAOIDataCollect::ExecProjectBarcodeDeviceStartToRead_LB"));	break;			
		default:
		case LANE_ID_A:	SaveDebugMessage(_T("CAOIDataCollect::ExecProjectBarcodeDeviceStartToRead_LA"));	break;
		}
		SaveDebugMessage(ProjectPtr->GetProjectShowName());
	}
	switch ( BarcodeDeviceGrabMode )
	{
	case BARCODE_DEVICE_GRAB_BEFORE_PCB_IN://進板前
		if ( ONLINE_STATE_PCB_IN_START != OnlineState ) { return true; }
		break;
	case BARCODE_DEVICE_GRAB_WHILE_PCB_IN://進板中
		if ( PCB_OUT_LANE_AUTO == PCBOutMode )//20230425
		{	//檢測完畢
			if ( ONLINE_STATE_INSPECTION_FINISH != OnlineState ) {	return true; }
		}
		else
		{	//開始進板
			if ( ONLINE_STATE_PCB_IN_START != OnlineState ) {	return true; }
		}		
		break;
	case BARCODE_DEVICE_GRAB_AFTER_PCB_IN://進板後
		if ( true == BeforeRetrieveCode ) { return true; }
		if ( ONLINE_STATE_INSPECTION_STOP  != OnlineState && 
		     ONLINE_STATE_INSPECTION_START != OnlineState 
		   )
		{ return true; }
		break;
	case BARCODE_DEVICE_GRAB_BEFORE_INSPECT://檢測前
		if ( false == BeforeRetrieveCode ) { return true; }
		if ( ONLINE_STATE_INSPECTION_START != OnlineState ) { return true; }		
		break;
	}
	
	size_t           i=0;
	bool             IsOK=false;
	int              BarcodeDeviceID=0;
	CString strError, strError2, strError3, strLane, strID;
	CBarcode_Basic  *BarcodeDevicePtr=NULL;
	bool BarcodeDeviceUsedList[MAX_BARCODE_DEVICE_COUNT];
	const size_t MaxBarcodeDeviceCount = MAX_BARCODE_DEVICE_COUNT;
	ProjectPtr->CloneProjectBarcodeDeviceUsedList(BarcodeDeviceUsedList);

	IsOK = true;
	strID = AOIDataDefine.GetIDText();
	strLane = AOIDataDefine.GetLaneIDText(LaneID);	
	for ( i=0; i<MaxBarcodeDeviceCount; i++ )
	{
		if ( BarcodeDeviceUsedList[i] == false ) { continue; }
		if ( LANE_ID_B == LaneID )
		{	BarcodeDeviceID = this->m_BarcodeDeviceIDList_LB[i]; }
		else
		{	BarcodeDeviceID = this->m_BarcodeDeviceIDList_LA[i]; }
		BarcodeDevicePtr = GetBarcodeDevicePtr(BarcodeDeviceID);
		if ( NULL == BarcodeDevicePtr )
		{
			strError3 = _T("Barcode Device does not setup");
			strError3 = AOIDataDefine.LoadMultiLanguageString_BarcodeDevice(strError3, strError3);
			strError2.Format(_T("%s %s[%s:%d]"), strLane, strError3, strID, BarcodeDeviceID);
			if ( strError.GetLength() == 0 ) { strError = strError2; }
			else
			{
				strError3.Format(_T("%s\n%s"), strError, strError2);
				strError = strError3;
			}
			IsOK = false;
			SetBarcodeDeviceExceptionCode_Create(strError);
			continue;
		}
		if ( BarcodeDevicePtr->GetBarcodeDeviceConnected() == false )
		{
			strError3 = _T("Barcode Device does not connect to device");
			strError3 = AOIDataDefine.LoadMultiLanguageString_BarcodeDevice(strError3, strError3);
			strError2.Format(_T("%s %s[%s:%d]"), strLane, strError3, strID, BarcodeDeviceID);
			if ( strError.GetLength() == 0 ) { strError = strError2; }
			else
			{
				strError3.Format(_T("%s\n%s"), strError, strError2);
				strError = strError3;
			}
			IsOK = false;
			SetBarcodeDeviceExceptionCode_Connect(strError);
			continue;
		}
		if ( BarcodeDevicePtr->StartToRead() == false )
		{	
			strError3 = _T("Barcode Device start to read fault");
			strError3 = AOIDataDefine.LoadMultiLanguageString_BarcodeDevice(strError3, strError3);
			strError2.Format(_T("%s %s[%s:%d]"), strLane, strError3, strID, BarcodeDeviceID);
			if ( strError.GetLength() == 0 ) { strError = strError2; }
			else
			{
				strError3.Format(_T("%s\n%s"), strError, strError2);
				strError = strError3;
			}
			IsOK = false;
			SetBarcodeDeviceExceptionCode_Start(strError);
			continue;
		}		
	}
	if ( false == IsOK )
	{	
		strError2 = AOIDataDefine.GetErrorText();
		strError3.Format(_T("%s, %s"), strError2, strError);
		strError = strError3;
		SetErrorString(strError);	
		return false;
	}
#endif//BARCODE_DEVICE_DISABLE
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecProjectBarcodeDeviceRetrieveCode(CAOIProject *ProjectPtr, ONLINE_STATE_MODE OnlineState, LANE_ID LaneID)//執行專案條碼機讀取條碼
{
	if ( CheckProjectPtr(ProjectPtr) == false )	{	return false;	}
#ifndef BARCODE_DEVICE_DISABLE	
	LANE_STATE_MODE LaneStateMode = GetOnlineLaneTaskState(LaneID);
	if (LANE_STATE_BYPASS == LaneStateMode)
	{	return true;	}

	PCB_OUT_MODE PCBOutMode = GetLanePCBOutMode(LaneID);
	BARCODE_INPUT_TYPE  BarcodeInputType = ProjectPtr->GetProjectParameter().m_BarcodeInputType;
	BARCODE_DEVICE_GRAB_MODE BarcodeDeviceGrabMode = ProjectPtr->GetProjectParameter().m_BarcodeDeviceGrabMode;
	if ( BARCODE_INPUT_DEVICE != BarcodeInputType ) { return true; }
	if ( true )
	{		
		switch ( LaneID )
		{
		case LANE_ID_B:	SaveDebugMessage(_T("CAOIDataCollect::ExecProjectBarcodeDeviceRetrieveCode_LB"));	break;			
		default:
		case LANE_ID_A:	SaveDebugMessage(_T("CAOIDataCollect::ExecProjectBarcodeDeviceRetrieveCode_LA"));	break;
		}		
		SaveDebugMessage(ProjectPtr->GetProjectShowName());
	}
	switch ( BarcodeDeviceGrabMode )
	{
	case BARCODE_DEVICE_GRAB_BEFORE_PCB_IN://進板前
		if ( ONLINE_STATE_PCB_IN_START != OnlineState ) { return true; }
		break;
	case BARCODE_DEVICE_GRAB_WHILE_PCB_IN://進板中
		if ( ONLINE_STATE_INSPECTION_START != OnlineState ) { return true; }
		break;
	case BARCODE_DEVICE_GRAB_AFTER_PCB_IN://進板後		
		switch (PCBOutMode)
		{
		case PCB_OUT_WITH_IN:
		case PCB_OUT_LANE_AUTO://檢測前讀取
			if (ONLINE_STATE_INSPECTION_START != OnlineState) { return true; }
			break;
		default:
		case PCB_OUT_NORMAL:
		case PCB_OUT_SIDE_OUT://進板前讀取
		case PCB_OUT_OK_OUT_NG_SIDE:
			if (ONLINE_STATE_PCB_IN_START != OnlineState) { return true; }
			break;
		}
		break;
	case BARCODE_DEVICE_GRAB_BEFORE_INSPECT://檢測前
		if ( ONLINE_STATE_INSPECTION_START != OnlineState ) { return true; }		
		break;
	}

	size_t           i=0;
	bool             IsOK=true;
	int              BarcodeDeviceID=0;
	CString strError, strError2, strError3, strLane, strID;
	CBarcode_Basic  *BarcodeDevicePtr=NULL;
	std::vector<CBarcode_Basic*> BarcodeDeviceNgList;
	BARCODE_NG_HANDLE_MODE BarcodeNGHandleMode = ProjectPtr->GetProjectParameter().m_BarcodeNGHandleMode;
	bool BarcodeDeviceUsedList[MAX_BARCODE_DEVICE_COUNT];
	const size_t MaxBarcodeDeviceCount = MAX_BARCODE_DEVICE_COUNT;
	IsOK=true;
	strID = AOIDataDefine.GetIDText();
	strLane = AOIDataDefine.GetLaneIDText(LaneID);	
	ProjectPtr->CloneProjectBarcodeDeviceUsedList(BarcodeDeviceUsedList);
	for ( i=0; i<MaxBarcodeDeviceCount; i++ )
	{
		if ( BarcodeDeviceUsedList[i] == false ) { continue; }
		if ( LANE_ID_B == LaneID )
		{	BarcodeDeviceID = this->m_BarcodeDeviceIDList_LB[i]; }
		else
		{	BarcodeDeviceID = this->m_BarcodeDeviceIDList_LA[i]; }
		BarcodeDevicePtr = GetBarcodeDevicePtr(BarcodeDeviceID);
		if ( NULL == BarcodeDevicePtr )
		{
			strError3 = _T("Barcode Device does not setup");
			strError3 = AOIDataDefine.LoadMultiLanguageString_BarcodeDevice(strError3, strError3);
			strError2.Format(_T("%s %s[%s:%d]"), strLane, strError3, strID, BarcodeDeviceID);
			if ( strError.GetLength() == 0 ) { strError = strError2; }
			else
			{
				strError3.Format(_T("%s\n%s"), strError, strError2);
				strError = strError3;
			}
			IsOK = false;
			SetBarcodeDeviceExceptionCode_Create(strError);
			continue;
		}
		if ( BarcodeDevicePtr->GetBarcodeDeviceConnected() == false )
		{
			strError3 = _T("Barcode Device does not connect to device");
			strError3 = AOIDataDefine.LoadMultiLanguageString_BarcodeDevice(strError3, strError3);
			strError2.Format(_T("%s %s[%s:%d]"), strLane, strError3, strID, BarcodeDeviceID);
			if ( strError.GetLength() == 0 ) { strError = strError2; }
			else
			{
				strError3.Format(_T("%s\n%s"), strError, strError2);
				strError = strError3;
			}
			IsOK = false;
			SetBarcodeDeviceExceptionCode_Connect(strError);
			continue;
		}
		if ( BarcodeDevicePtr->RetrieveCode() == false )
		{
			strError3 = _T("Barcode Device read barcode fault");
			strError3 = AOIDataDefine.LoadMultiLanguageString_BarcodeDevice(strError3, strError3);
			strError2.Format(_T("%s %s[%s:%d]"), strLane, strError3, strID, BarcodeDeviceID);
			if ( strError.GetLength() == 0 ) { strError = strError2; }
			else
			{
				strError3.Format(_T("%s\n%s"), strError, strError2);
				strError = strError3;
			}
			IsOK = false;
			SetBarcodeDeviceExceptionCode_Decode(strError);
			BarcodeDevicePtr->EndReading();//關閉讀取
			BarcodeDeviceNgList.push_back(BarcodeDevicePtr);
			continue;
		}
		BarcodeDevicePtr->EndReading();//關閉讀取
	}
	const size_t BarcodeDeviceNgCount=BarcodeDeviceNgList.size();
	if ( BARCODE_NG_HANDLE_PASS != BarcodeNGHandleMode )//異常時不警報
	{
		if ( false == IsOK )
		{	
			if ( BARCODE_NG_HANDLE_ALARM==BarcodeNGHandleMode || 0==BarcodeDeviceNgCount )
			{
				strError2 = AOIDataDefine.GetErrorText();
				strError3.Format(_T("%s, %s"), strError2, strError);
				strError = strError3;
				SetErrorString(strError);	
				return false;
			}
			if ( BARCODE_NG_HANDLE_INPUT == BarcodeNGHandleMode )
			{					
				for ( i=0; i<BarcodeDeviceNgCount; i++ )
				{
					BarcodeDevicePtr = BarcodeDeviceNgList[i];
					if ( ExecProjectBarcodeDeviceInputCode(ProjectPtr, BarcodeDevicePtr, LaneID) == false )
					{	return false; }					
				}
			}
		}
	}
#endif//BARCODE_DEVICE_DISABLE
	return true;
}
