SPC_TOWARD CAOIDataCollect::MapBoxTowardToSpcToward(BOX_TOWARD Toward)//將框朝向轉成SPC的朝向
{
	SPC_TOWARD SpcToward;
	switch ( Toward )
	{
	case BOX_TOWARD_UP:		SpcToward=SPC_TOWARD_TOP;	break;
	case BOX_TOWARD_LEFT:	SpcToward=SPC_TOWARD_LEFT;	break;
	case BOX_TOWARD_DOWN:	SpcToward=SPC_TOWARD_BOT; 	break;
	case BOX_TOWARD_RIGHT:	SpcToward=SPC_TOWARD_RIGHT;	break;
	default:
		SpcToward=SPC_TOWARD_NONE;
		break;
	}
	return SpcToward;
}
