//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::BuildMotionXYCaliList(bool Rebuild)//建立運動系統的 XY校正表
{
	CAOIProject *ProjectPtr = GetActiveProject();
	if ( NULL == ProjectPtr ) { return false; }

	bool           First=true;
	size_t         i=0, j=0, k=0;	
	double         CaliX=0, CaliY=0;
	double         StageX=0, StageY=0;
	double         MinL = 0;
	double         OffsetX=0, OffsetY=0, OffsetL=0;
	double         StageOrgX=0, StageOrgY=0;
	double         StageMinX=0, StageMinY=0;
	double         StageMaxX=0, StageMaxY=0;	
	const size_t   ComponentCount = ProjectPtr->GetProjectComponentCount();
	CAOIComponent *ComponentPtr = NULL;
	CAOIComponent *ComponentPtr2 = NULL;
	std::vector<CAOIComponent*> ComponentPtrList;

	First=true;	
	for ( i=0; i<ComponentCount; i++ )
	{
		ComponentPtr = ProjectPtr->GetProjectComponentPtr(i, false);
		if ( ComponentPtr == NULL ) { continue; }
		if ( ComponentPtr->GetComponentDeleted() == true ) { continue; }
		ComponentPtrList.push_back(ComponentPtr);

		if ( First == true ) 
		{
			First = false;
			MinL = DBL_MAX;
			StageMinX = DBL_MAX;
			StageMinY = DBL_MAX;
			StageOrgX = ComponentPtr->GetComponentStagePosX();
			StageOrgY = ComponentPtr->GetComponentStagePosY();
			continue;
		}

		StageX = ComponentPtr->GetComponentStagePosX();
		StageY = ComponentPtr->GetComponentStagePosY();
		OffsetX = fabs(StageX-StageOrgX);
		OffsetY = fabs(StageY-StageOrgY);
		OffsetL = ::sqrt((OffsetX*OffsetX)+(OffsetY*OffsetY));
		if ( OffsetL < MinL ) { MinL = OffsetL; }
		if ( OffsetX < StageMinX ) { StageMinX = OffsetX; }
		if ( OffsetY < StageMinY ) { StageMinY = OffsetY; }				
	}	

	int          NPos = 0;
	TXYCali      XYCali, Cali;
	std::vector<TXYCali> XYCaliList;
	double       CadOffsetX=0, CadOffsetY=0;
	double       StageOffsetX=0, StageOffsetY=0;
	const double CellRangeXMin = MinL*0.25;
	const double CellRangeYMin = MinL*0.25;
	const double CellRangeXMax = MinL*1.25;
	const double CellRangeYMax = MinL*1.25;
	const size_t TotalComponents = (ComponentPtrList.size());
	const bool  bSignX = GetStageSignPositiveX();
	const bool  bSignY = GetStageSignPositiveY();

	for ( i=0; i<TotalComponents; i++ )
	{		
		ComponentPtr = ComponentPtrList[i];
		NPos = 0;		
		MotionCtrlPtr->InitMotionXYCali(XYCali);

		NPos = 1;
		CadOffsetX = ComponentPtr->GetComponentResultOffsetX();
		CadOffsetY = ComponentPtr->GetComponentResultOffsetY();
		MapCadOffsetPtToStage(CadOffsetX, CadOffsetY, StageOffsetX, StageOffsetY);		
		XYCali.PosX1 = ComponentPtr->GetComponentStagePosX();
		XYCali.PosY1 = ComponentPtr->GetComponentStagePosY();
		XYCali.CaliX1 = XYCali.PosX1+StageOffsetX;
		XYCali.CaliY1 = XYCali.PosY1+StageOffsetY;

		StageMinX = XYCali.PosX1-CellRangeXMin;
		StageMinY = XYCali.PosY1-CellRangeYMin;
		StageMaxX = XYCali.PosX1+CellRangeXMax;
		StageMaxY = XYCali.PosY1+CellRangeYMax;
		for ( j=0; j<TotalComponents; j++ )
		{
			if ( j == i ) { continue; }
			ComponentPtr2 = ComponentPtrList[j];
			StageX = ComponentPtr2->GetComponentStagePosX();
			StageY = ComponentPtr2->GetComponentStagePosY();
			if ( StageX < StageMinX ) { continue; }
			if ( StageY < StageMinY ) { continue; }
			if ( StageX > StageMaxX ) { continue; }
			if ( StageY > StageMaxY ) { continue; }
			CadOffsetX = ComponentPtr2->GetComponentResultOffsetX();
			CadOffsetY = ComponentPtr2->GetComponentResultOffsetY();
			MapCadOffsetPtToStage(CadOffsetX, CadOffsetY, StageOffsetX, StageOffsetY);		
			CaliX = StageX+StageOffsetX;
			CaliY = StageY+StageOffsetY;

			NPos ++;
			switch ( NPos )
			{
			case 2:				
				XYCali.PosX2 = StageX;
				XYCali.PosY2 = StageY;
				XYCali.CaliX2 = CaliX;
				XYCali.CaliY2 = CaliY;
				break;
			case 3:
				XYCali.PosX3 = StageX;
				XYCali.PosY3 = StageY;
				XYCali.CaliX3 = CaliX;
				XYCali.CaliY3 = CaliY;
				break;
			case 4:
				XYCali.PosX4 = StageX;
				XYCali.PosY4 = StageY;
				XYCali.CaliX4 = CaliX;
				XYCali.CaliY4 = CaliY;
				break;
			default:
				break;
			}

		}
		if ( NPos < 4 ) { continue; }
		if ( NPos > 4 ) 
		{
			continue; 
		}

		MotionCtrlPtr->RearrangeMotionXYCali(XYCali);
		MotionCtrlPtr->CalcMotionXYCaliLimit(XYCali);
		MotionCtrlPtr->CalcMotionXYCaliTransform(XYCali);
		Cali = XYCali;
		XYCaliList.push_back(XYCali);
	}

	MotionCtrlPtr->SetMotionXYYCaliList(XYCaliList, Rebuild);
	MotionCtrlPtr->SaveMotionXYCali();
	//MotionCtrlPtr->LoadMotionXYCali();	
	return true;
}
