//-------------------------------------------------------------------------------------//
void CAOIDataCollect::ClearTempWndList()//清除暫時檢測框列表
{
	size_t       i=0;	
	CAOIWnd     *WndPtr=NULL;
	const size_t Count = m_TempWndList.size();
	for ( i=0; i<Count; i++ )
	{
		WndPtr = m_TempWndList[i];
		if ( NULL == WndPtr ) { continue; }
		AOIObjManager.DestroyWndObj(WndPtr);
		m_TempWndList[i] = NULL;
	}
	m_TempWndList.clear();
}
//-------------------------------------------------------------------------------------//
size_t CAOIDataCollect::GetTempWndCount() const//取得暫時檢測框數量
{
	return m_TempWndList.size();
}
//-------------------------------------------------------------------------------------//
CAOIWnd* CAOIDataCollect::GetTempWndPtr(size_t idx, bool bCheck)//取得暫時檢測框指標
{
	if ( true == bCheck )
	{
		const size_t Count = m_TempWndList.size();
		if ( idx >= Count ) { return NULL; }
	}
	return (m_TempWndList[idx]);
}
//-------------------------------------------------------------------------------------//
void CAOIDataCollect::SetTempWndList(std::vector<CAOIWnd*> WndList)//複製暫時檢測框列表
{
	size_t       i=0;	
	CAOIWnd     *WndPtr=NULL;
	const size_t Count = WndList.size();

	ClearTempWndList();
	for ( i=0; i<Count; i++ )
	{
		WndPtr = WndList[i];
		if ( NULL == WndPtr ) { continue; }				
		WndPtr = WndPtr->CloneWndObj();
		if ( NULL == WndPtr ) { continue; }
		WndPtr->SetWndLandPtr(NULL);
		m_TempWndList.push_back(WndPtr);
	}
	return;
}
//-------------------------------------------------------------------------------------//
void CAOIDataCollect::GetTempWndList(std::vector<CAOIWnd*> &WndList)//取得暫時檢測框列表
{
	WndList = m_TempWndList;
}
