bool CAOIDataCollect::ExecLockScreen(WPARAM wParam, HWND hWnd)
{
#ifndef OFFLINE_VERSION
	if ( FN_ENABLE == m_SystemParameter.m_LockScreenEnabled )
	{
		if ( GetLockScreenEnabled() == false )
		{
			if( wParam == m_SystemParameter.m_LockScreenKeyID )
			{
				if ( GetKeyState(VK_LWIN) < 0 )
				{	LockScreenFunc(hWnd);	}
			}
		}
	}	
#endif//OFFLINE_VERSION
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::UnlockScreenFunc()//取消鎖住
{
#ifndef OFFLINE_VERSION
	UnLockScreenHook();
	SetLockScreenEnabled(false);
#endif//OFFLINE_VERSION	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LockScreenFunc(HWND hWnd)//啟用鎖住
{	
	//MSG_LOCK_SCREEN_HOOK	
	int SysUnLockKey = VK_LWIN;	
	HWND hLimitWnd=GetLockScreenLimitWnd();	
	int UnLockKey = m_SystemParameter.m_LockScreenKeyID;
#ifndef OFFLINE_VERSION
	UnLockScreenHook();
	SetLockScreenHook(hWnd, hLimitWnd, MSG_LOCK_SCREEN_HOOK, UnLockKey, SysUnLockKey);	// hReportWnd:Message回傳目標	hLimitWnd:主要Handle
	SetLockScreenEnabled(true);
#endif//OFFLINE_VERSION
	return true;
}
