//-------------------------------------------------------------------------------------//
CString CAOIDataCollect::GetMESComm_ProjectFullName(LPCTSTR val) const//MES遠端控制專案
{
	CString Filename=val;
	if ( Filename.GetLength() == 0 ) { return Filename; }
	CString ExtName;
	CString PatherName;
	CString Folder=GetSystemParameter().m_AOIProjectFolder;	
	JetAPI::ExtractExtendFileName(Filename, ExtName);
	if ( ExtName.GetLength() != 0 )
	{	PatherName.Format(_T("%s\\%s"), Folder, Filename);	}
	else
	{	PatherName.Format(_T("%s\\%s.%s"), Folder, Filename, _T("PRG")); }	
	return PatherName;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckMESComm_ProjectIsEmpty()//MES專案空的
{
	CString LockFilename=GetMESComm_RemoteCtrlProject();
	if ( LockFilename.GetLength() != 0 )
	{
		m_ErrorString.Format(_T("Error, MES does not Finished Last File\n%s"), GetMESComm_RemoteCtrlProject());
		return false; 
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckMESComm_ProjectIsFree(LPCTSTR val)//MES專案是自由的
{
	CString LockFilename=GetMESComm_ProjectFullName(GetMESComm_RemoteCtrlProject());
	if ( LockFilename.GetLength() == 0 ) { return true; }
	if ( LockFilename.CompareNoCase(val) != 0 )
	{	return true; }
	m_ErrorString.Format(_T("Error, the file is locked by MES"));
	return false;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckMESComm_ProjectUploadCanRun(LPCTSTR val)//專案上傳檔名
{
	if ( CheckMESComm_ProjectIsEmpty() == false )
	{	return false; }
	CString UploadName = GetMESComm_ProjectFullName(val);	
	CAOIProject *ProjectPtr=GetProjectPtrByFilename(UploadName);
	if ( CheckProjectPtr(ProjectPtr) == true )
	{	
		bool bSucc=true;
		const bool bOnline=true;
		CString Filename = ProjectPtr->GetProjectFileName();
		CString Filename_show = ProjectPtr->GetProjectShowName();	
		const bool bPartialCopy = GetPartialCopyProjectLibrary();
		const DWORD dwCopyFlag = COPY_PROJECT_FOLDER_NO_OFFLINE;		
		bSucc = ProjectPtr->SaveProject(Filename, Filename_show, dwCopyFlag, bPartialCopy);		
		if ( false == bSucc )
		{
			SetErrorString(ProjectPtr->GetErrorString());				
			return false;
		}	
		LogOperCtrl.SaveLogProjectSave(ProjectPtr, Filename_show);
	}
	SetMESComm_RemoteCtrlProject(val);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckMESComm_ProjectDownloadCanRun(LPCTSTR val)//專案下載檔名
{
	if ( CheckMESComm_ProjectIsEmpty() == false )
	{	return false; }
	CString Filename=GetMESComm_ProjectFullName(val);
	CAOIProject *ProjectPtr = GetProjectPtrByFilename(Filename);
	if ( NULL != ProjectPtr )
	{	return false; }
	SetMESComm_RemoteCtrlProject(val);
	return true;
}
