//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecMESComm_ApplySystemParam()//更新系統參數至MES
{
#ifndef MES_DISABLE
	if ( GetMES_CommunicationEnabled() == false ) { return true; }	
	if ( MES_OBJ.GetMESConnected() == false )
	{
		if ( MES_OBJ.ConnectMESLinker() == false )
		{
			SetErrorString(MES_OBJ.GetErrorString());
			return false;
		}
	}
	if ( GetMES_SecsGemEnabled() == false )
	{	MES_OBJ.ResetMesEqpCtrlStateMode();	}
	else
	{
		if ( MES_EQP_CTRL_STATE_NONE==MES_OBJ.GetMesEqpCtrlStateMode() )
		{
			if ( ExecMESComm_SetControlStateMode(MES_EQP_CTRL_STATE_OFFLINE) == false )
			{	return false; }			
		}
	}	
	if ( ExecMESComm_SetSystemParam() == false )
	{	return false; }		
#endif//MES_DISABLE
	return true;
}
