//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecMESComm_LoadProject()//執行MES溝通-開啟專案	
{
	if ( GetMES_CommunicationEnabled() == false ) { return true; }	
#ifndef MES_DISABLE
	SaveMESTimeMsg(_T("CAOIDataCollect::ExecMESComm_LoadProject() Start"));

	bool IsOK = true;
	CString PathName;
	std::vector<TMES_ProjectOpen> OpenList;	
	CString ProjectFolder = GetAOIProjectDirectory();
	MES_OBJ.CloneProjectOpenList(OpenList);	
	const size_t OpenCount=OpenList.size();
	if ( 0 == OpenCount )
	{	return false;	}
	
	bool bSucc=true;
	LANE_ID LaneID;
	TMES_ProjectOpen ProjectOpen=OpenList[0];
	const LANE_ID LaneID_Before=GetActiveLaneID();	
	switch ( ProjectOpen.nLaneID )
	{
	case 2:		LaneID = LANE_ID_B;	break;
	case 1:
	default:	LaneID = LANE_ID_A;	break;		
	}
	if ( LaneID != LaneID_Before )
	{	SetActiveLaneID(LaneID); }

	
	switch ( ProjectOpen.nLaneClearType )
	{
	case 0:
	default:
		break;
	case 1:
		bSucc = PlcCtrlPtr->ExecPCBClear(LaneID, true);
		break;
	case 2:
		bSucc = PlcCtrlPtr->ExecPCBClear(LANE_ID_A, true);
		if ( true == bSucc )
		{	bSucc = PlcCtrlPtr->ExecPCBClear(LANE_ID_B, true); }
		break;
	}
	if ( false == bSucc )
	{
		SetErrorString(PlcCtrlPtr->GetPLCErrorString());
		return false;
	}	
		
	CAOIProject *ProjectPtr = GetActiveProject();	
	if ( NULL != ProjectPtr )
	{	SendMainFrameWndMessage(MSG_MAIN_FRAME_MESSAGE, WPARAM_PROJECT_CLOSE, NULL);	}

	const int ProjectIndex = GetProjectPtrCount();
	ProjectPtr = GetLaneProjectPtr(LaneID, 0, true);
	if ( NULL == ProjectPtr )
	{	
		ProjectPtr = AOIObjManager.CreateProjectObj();	
		if ( NULL == ProjectPtr )
		{	return CheckProjectPtr(ProjectPtr);	}		
		AddProjectPtr(ProjectPtr, false);
		SetActiveProjectIndex(ProjectIndex);
	}	

	const bool bOnline = true;	
	PathName.Format(_T("%s\\%s"), ProjectFolder, ProjectOpen.sFilename);
	if ( OpenProject(ProjectPtr, PathName, bOnline) == false )
	{	return false; }	
	SaveMESTimeMsg(_T("CAOIDataCollect::ExecMESComm_LoadProject() End"));
#endif//MES_DISABLE
	return true;
}
