//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::WaitForPCBOKNGSignalOnDelayTime(LANE_ID LaneID)
{
	DWORD TickCntGap=0;
	DWORD TickCntNow=GetTickCount();	
	DWORD TickCntLast=GetPCBOKNGSignalOnTickCount(LaneID);
	DWORD TickCntCheck=GetSystemParameter().m_PCBOKNGSignalDelayTime;
	if ( 0 == TickCntLast ) { return true; }
	if ( 0 == TickCntCheck ) { return true; }
	if ( TickCntNow < TickCntLast ) { return true; }

	while ( true )
	{
		TickCntGap = TickCntNow-TickCntLast;
		if ( TickCntGap > TickCntCheck )
		{	return true; }
		TickCntNow = GetTickCount();
		::Sleep(0);
	};
	return true;
}
