//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecAutoSwitchWnd3DFrame(CAOIModel *ModelPtr, CAOIWnd *WndPtr)//自動切換3D畫面
{
	if ( NULL == WndPtr ) { return false; }
	if ( NULL == ModelPtr ) { return false; }

	double     RegionW=0.0;
	double     RegionH=0.0;
	TREGION4D  ModelRegion;	
	bool      Switch3DFrame=false;	
	CAlgParam &AlgParam = WndPtr->GetWndAlgParam();
	unsigned int WndIdx = WndPtr->GetWndIndex();
	const int WndGroupID = WndPtr->GetWndGroupID();
	unsigned int FrameIndex = AlgParam.GetAlgImageBinParam().GetBinaryFrameIndex();
	unsigned int FrameUniqueID = AlgParam.GetAlgImageBinParam().GetBinaryFrameUniqueID();

	MODEL_TYPE ModelType = ModelPtr->GetModelType();
	UINT EditImagePageWndID = GetEditImagePageWndID();
	const int AutoSwitchSizeLimit = GetSystemParameter().m_AutoSwitchWnd3DFrameSizeLimit;
	AUTO_SWITCH_WND_3D_FRAME_MODE AutoSwitchWnd3DFrame = GetSystemParameter().m_AutoSwitchWnd3DFrameMode;

	switch ( AutoSwitchWnd3DFrame )
	{
	case AUTO_SWITCH_WND_3D_FRAME_ENABLE:
		Switch3DFrame = true;
		break;
	case AUTO_SWITCH_WND_3D_FRAME_BY_SIZE:
		ModelPtr->GetModelTotalRegion(ModelRegion);
		RegionW = ModelRegion.GetWidth();
		RegionH = ModelRegion.GetHeight();
		if ( RegionW>AutoSwitchSizeLimit || RegionH>AutoSwitchSizeLimit ) 
		{	Switch3DFrame = false; }
		else
		{	Switch3DFrame = true; }
		break;
	case AUTO_SWITCH_WND_3D_FRAME_BY_TYPE:
		Switch3DFrame = AOIDataDefine.CheckAutoSwitchWnd3DFrameByType(ModelType);		
		break;
	case AUTO_SWITCH_WND_3D_FRAME_BY_GROUP_CHANGE:
		Switch3DFrame = GetIsModelWndGroupSelChange();		
		SetIsModelWndGroupSelChange(false);
		break;
	default:
		Switch3DFrame = false;
		break;
	}

	if ( true == Switch3DFrame ) 
	{
		if ( FRAME_UNIQUE_ID_DLP == FrameUniqueID ) 
		{	SendMainFrameWndMessage(MSG_EDIT_IMAGE_VIEW_WND, WPARAM_SHOW_IMAGE_OPENGL_3D_PAGE, NULL);	}
		else
		{
			if ( WPARAM_SHOW_IMAGE_OPENGL_3D_PAGE == EditImagePageWndID ) 
			{	SendMainFrameWndMessage(MSG_EDIT_IMAGE_VIEW_WND, WPARAM_SHOW_IMAGE_PROCESS_PAGE, NULL);	}
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecDebayerImage(const char *fnName, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, BAYER_PATTERN_MODE BayerMode, IMAGE_SIZE &DstStep, IMAGE_SIZE &DstBit, unsigned char *&pDst)
{
	const int     nAlign=4;	
	IMAGE_SIZE    BitCnt=0;	
	IMAGE_SIZE    BufferStep=0;
	IMAGE_DEBAYER_MODE DebayerMode = GetSystemParameter().m_DebayerMode;
	DebayerMode = IMAGE_DEBAYER_OPEN_CV;
	switch ( DebayerMode )
	{
	case IMAGE_DEBAYER_RAW_MONO:
		BitCnt = 8;
		BufferStep = ImageStep;
		break;
	default:
	case IMAGE_DEBAYER_OPEN_CV:
	case IMAGE_DEBAYER_RAW_COLOR:
		BitCnt = 24;	
		BufferStep=JetAPI::GetBMPImagePixelsPerLine(ImageW, BitCnt, nAlign);		
		break;
	}

	bool         IsOK = true;
	IMAGE_PTR    BufferPtr=NULL;	
	const size_t BufferSize=BufferStep*ImageH;
	if ( JetMemory.alloc_func(BufferSize, BufferPtr, fnName, "BufferPtr") == false )
	{
		m_ErrorString = JetMemory.GetErrorString();
		return false;
	}
	//DebayerMode = IMAGE_DEBAYER_RAW_COLOR;
	switch ( DebayerMode )
	{	
	case IMAGE_DEBAYER_RAW_COLOR:
		IsOK = ImageAPI.DebayerRawColorImage3(ImageW, ImageH, ImageStep, pImage, BayerMode, BufferStep, BufferPtr);
		break;
	case IMAGE_DEBAYER_RAW_MONO:
		IsOK = ImageAPI.DebayerGrayImage3(ImageW, ImageH, ImageStep, pImage, BayerMode, BufferPtr);
		break;
	default:
	case IMAGE_DEBAYER_OPEN_CV:
		IsOK = ImageAPI.DebayerColorImage3(ImageW, ImageH, ImageStep, pImage, BayerMode, BufferStep, BufferPtr);	
		break;
	}
	if ( false == IsOK )
	{
		JetMemory.free_func(BufferPtr);
		m_ErrorString = ImageAPI.GetImageApiErrorString();
		return false;
	}
	pDst = BufferPtr;
	DstBit = BitCnt;
	DstStep = BufferStep;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::OpenJetDongle()//開啟JET硬體鎖
{
#ifdef ROCKEY4ND_USE
	JET_Rockey4ND.SetJETAppID(JET_APP_JET8000);
	if ( JET_Rockey4ND.OpenRockey4() == false )
	{
		m_ErrorString = JET_Rockey4ND.GetErrorString();
		m_ErrorString = LoadMultiLanguageString(_T("JET_DONGLE"), m_ErrorString, m_ErrorString);
		return false;
	}
#endif//ROCKEY4ND_USE
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckJetDongleValid()//確認JET硬體鎖授權
{
	if ( ExecCheckJetDongleValid() == false )
	{
		m_ErrorString = LoadMultiLanguageString(_T("JET_DONGLE"), m_ErrorString, m_ErrorString);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ExecCheckJetDongleValid()//確認JET硬體鎖授權
{
#ifdef ROCKEY4ND_USE	
	CString str;
	bool  bValid;	
	bool  bEnable;
	const int AppID = JET_Rockey4ND.GetJETAppID();
	//For App
	if ( JET_Rockey4ND.CheckJETAppValid(AppID, bValid) == false )
	{
		m_ErrorString = JET_Rockey4ND.GetErrorString();		
		return false;
	}
	if ( JET_Rockey4ND.CheckAppValid(bValid) == false )
	{
		m_ErrorString = JET_Rockey4ND.GetErrorString();		
		return false;
	}

	//For Timer	
	if ( JET_Rockey4ND.CheckJETTimerValid(AppID, bEnable, bValid) == false )
	{
		m_ErrorString = JET_Rockey4ND.GetErrorString();
		return false;
	}	
	if ( JET_Rockey4ND.CheckAppTimerValid(bValid) == false )		
	{
		m_ErrorString = JET_Rockey4ND.GetErrorString();
		return false;
	}	
	
	//For Count		
	/*
	if ( JET_Rockey4ND.CheckJETCountValid(AppID, bEnable, bValid) == false )
	{
		m_ErrorString = JET_Rockey4ND.GetErrorString();			
		return false;
	}	
	if ( JET_Rockey4ND.CheckAppCountValid(bValid) == false )		
	{
		m_ErrorString = JET_Rockey4ND.GetErrorString();
		return false;
	}	*/
#endif//ROCKEY4ND_USE
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckJetDongleWarning()//確認JET硬體鎖警告
{	
#ifdef ROCKEY4ND_USE	
	CString str;
	bool  bValid;	
	const int AppID = JET_Rockey4ND.GetJETAppID();
	const TSystemParameter &SysParam = GetSystemParameter();

	//For App
	if ( JET_Rockey4ND.CheckJETAppValid(AppID, bValid) == false )
	{
		m_ErrorString = JET_Rockey4ND.GetErrorString();		
		return false;
	}
	if ( JET_Rockey4ND.CheckAppValid(bValid) == false )
	{
		m_ErrorString = JET_Rockey4ND.GetErrorString();		
		return false;
	}

	//For Timer	
	DWORD dwDays = (DWORD)(SysParam.m_DongleWarningRemainingDays);//硬體鎖警告剩餘天數		 
	if ( JET_Rockey4ND.CheckAppRemainingDay(AppID, dwDays) == false )
	{
		CString strTime;
		SYSTEMTIME ExpTime;
		JET_Rockey4ND.GetAppExpiredTime(AppID, ExpTime);
		str = JET_Rockey4ND.GetErrorString();
		strTime.Format(_T("Exp:%04d/%02d/%02d %02d:%02d:%02d"), ExpTime.wYear, ExpTime.wMonth, ExpTime.wDay, ExpTime.wHour, ExpTime.wMinute, ExpTime.wSecond);
		m_ErrorString.Format(_T("%s\n%s"), str, strTime);
		return false;
	}
	//For Count		
	DWORD dwCount = (DWORD)(SysParam.m_DongleWarningRemainingCount);//硬體鎖警告剩餘次數
	if ( JET_Rockey4ND.CheckAppRemainingCount(AppID, dwCount) == false )
	{
		m_ErrorString = JET_Rockey4ND.GetErrorString();			
		return false;
	}
#endif//ROCKEY4ND_USE
	return true;
}
