//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::LaunchExternalCopyFileApp(bool &bLaunch)//啟動外部複製檔案軟體
{	
	bLaunch = false;
	bool bSucc=true;	
#ifndef OFFLINE_VERSION		
	const CString MutexName=_T("FileCopyApp");
	const TSystemParameter &SysParam = GetSystemParameter();
	if ( false == SysParam.m_ExternalCopyFileEnabled )	{	return true; }
	CString AppName = SysParam.m_ExternalCopyFileAppName;
	if ( AppName.GetLength() == 0 )
	{	
		bLaunch = true;
		return true; 
	}

	HANDLE hMutex = ::CreateMutex(NULL, TRUE, MutexName);
	DWORD dwError = ::GetLastError();
	switch ( dwError )
	{
	case ERROR_SUCCESS:
		::ReleaseMutex(hMutex);			
		break;
	case ERROR_ALREADY_EXISTS:			
		bLaunch = true;		
		break;
	default:
		bSucc = false;		
		::ReleaseMutex(hMutex);
		break;
	}
	if ( NULL != hMutex )
	{
		::CloseHandle(hMutex);
		hMutex=NULL;
	}
	if ( false == bSucc )
	{
		JetAPI::GetSystemLastError(m_ErrorString);
		return false; 
	}
	if ( false == bLaunch )
	{	
		::ShellExecute(NULL, _T("open"), AppName, NULL, NULL, SW_SHOW);

		int Count = 0;		
		const int MaxCount = 20;		
		do
		{
			::Sleep(100);
			hMutex = ::CreateMutex(NULL, TRUE, MutexName);
			dwError = ::GetLastError();
			switch ( dwError )
			{
			case ERROR_SUCCESS:
				::ReleaseMutex(hMutex);
				break;
			case ERROR_ALREADY_EXISTS:
				bLaunch = true;				
				break;
			default:
				bSucc = false;				
				::ReleaseMutex(hMutex);				
				break;
			}
			if ( NULL != hMutex )
			{
				::CloseHandle(hMutex);
				hMutex=NULL;
			}
			if ( false==bSucc || true==bLaunch )
			{	break; }
			Count ++;
		} while ( Count < MaxCount );
		if ( Count == MaxCount )
		{	bSucc = false;	}
	}
#endif//OFFLINE_VERSION
	return bSucc;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckExternalCopyFileEnabed()//確認外部複製檔案啟用
{	
	const TSystemParameter &SysParam = GetSystemParameter();
	bool bExternalCopyFileEnabed = SysParam.m_ExternalCopyFileEnabled;
	if ( true == bExternalCopyFileEnabed )
	{
		const bool bCheckSoftware=true;//確認軟體
		if ( true == bCheckSoftware )
		{			
			bool bLaunch=false;
			if ( LaunchExternalCopyFileApp(bLaunch) == false )
			{	bExternalCopyFileEnabed = false;	}
			if ( false == bLaunch )
			{	bExternalCopyFileEnabed = false;	}
		}		

		CString SendFolder = SysParam.m_ExternalCopyFileSendFolder;
		if ( CreateNewFolder(SendFolder) == false )
		{	bExternalCopyFileEnabed = false;	}
	}
	m_ExternalCopyFileEnabed = bExternalCopyFileEnabed;
	return bExternalCopyFileEnabed;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::GetExternalCopyFileEnabed() const//取得外部複製檔案啟用
{
	return m_ExternalCopyFileEnabed;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveExternalCopyFileList()//儲存外部複製檔案列表
{
	if ( SaveExternalCopyFileListFn() == false )
	{
		SetSystemExceptionCode_FileWrite();
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveExternalCopyFileListFn()//儲存外部複製檔案列表
{	
	LockThread();
	std::vector<TCopyFileNode> List = m_ExternalCopyFileList;	
	UnlockThread();
	ClearExternalCopyFileList();
	
	int i=0;
	CString str;
	CString Section;
	CString KeyName;
	CString String;
	CString FileName;		
	const size_t Count=List.size();
	CTime Time=CTime::GetCurrentTime();
	CString strTime=Time.Format(_T("%Y%m%d%H%M%S"));
	CString FileFolder=GetSystemParameter().m_ExternalCopyFileSendFolder;

	::CreateDirectory(FileFolder, NULL);
	FileName.Format(_T("%s\\Copy_%s.INI"), FileFolder, strTime);

	for ( size_t i=0; i<Count; i++ )
	{
		const TCopyFileNode &rNode=List[i];

		Section.Format(_T("Copy Node %04u"), i+1);

		KeyName = _T("Src");
		String = rNode.SrcFile;
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }

		KeyName = _T("Dst");
		String = rNode.DstFile;
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }

		KeyName = _T("Del Src");
		if ( false == rNode.bDelSrc )
		{	String = _T("0"); }
		else
		{	String = _T("1"); }
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }

		KeyName = _T("File");
		if ( false == rNode.bFileMode )
		{	String = _T("0"); }
		else
		{	String = _T("1"); }
		if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
		{	return false; }
	}

	Section = _T("Copy Info");
	
	KeyName = _T("Count");
	String.Format(_T("%u"), Count);
	if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
	{	return false; }

	KeyName = _T("Build Time");
	String = strTime;
	if ( SaveINIData(Section, KeyName, String, FileName, m_ErrorString) == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::ClearExternalCopyFileList()//清除外部複製檔案列表
{
	LockThread();
	m_ExternalCopyFileList.clear();
	UnlockThread();
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::AddExternalCopyFile(LPCTSTR Src, LPCTSTR Dst, bool bFile, bool bDelSrc)//加入外部複製檔案
{
	TCopyFileNode Node;
	Node.SrcFile = Src;
	Node.DstFile = Dst;
	Node.bDelSrc = bDelSrc;
	Node.bFileMode = bFile;
	LockThread();
	m_ExternalCopyFileList.push_back(Node);
	UnlockThread();
	return true;
}
//-------------------------------------------------------------------------------------//	
double CAOIDataCollect::CalcProjectFocusOffset(LANE_ID LaneID)//計算專案焦距偏移值
{	
	double FocusOffsetZ = 0.0;
	double FocusLA=0, FocusLB=0;	
	double PosX=0, PosY=0, PosZ=0;	
	const bool IsRightIn = PlcCtrlPtr->GetIsPCBRightInDirection();		
	const TMotionParameter &MotionParam = MotionCtrlPtr->GetMotionParameter();
	MotionCtrlPtr->GetCurrentPos(PosX, PosY, PosZ);
	if ( true == IsRightIn )
	{
		FocusLA = MotionParam.m_PCBStopLPosZ_LA;
		FocusLB = MotionParam.m_PCBStopLPosZ_LB;
	}
	else
	{
		FocusLA = MotionParam.m_PCBStopRPosZ_LA;
		FocusLB = MotionParam.m_PCBStopRPosZ_LB;		
	}
	switch ( LaneID ) 
	{
	case LANE_ID_B:	FocusOffsetZ = PosZ-FocusLB;	break;
	default:
	case LANE_ID_A:	FocusOffsetZ = PosZ-FocusLA;	break;
	}
	return FocusOffsetZ;
}
