//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::CheckXboardMappingFileViaMESCommBoardCountIsCorrect(CAOIProject *ProjectPtr) 
{
	const TProjectParameter &ProjectParam = ProjectPtr->GetProjectParameter();
	if ( XBOARD_MAPPING_FILE_MES_COMM != ProjectParam.m_XBoardMappingFileMode) { return true; }
	if ( FN_ENABLE != ProjectParam.m_XBoardMappingMESCheck ) { return true; }

	CAOIPanel *PanelPtr = NULL;
	CAOIBoard *BoardPtr = NULL;
	const size_t PanelCount = ProjectPtr->GetProjectPanelCount();
	size_t i;
	for (i = 0; i < PanelCount; i++) {
		PanelPtr = ProjectPtr->GetProjectPanelPtr(i,false);
		if (NULL == PanelPtr) { continue; }
		const size_t PanelID = PanelPtr->GetPanelIndex_Project()+1;
		const size_t BoardCount = PanelPtr->GetPanelBoardCount();
		const size_t BoardColCount = PanelPtr->GetPanelBoardColCount();
		const size_t BoardColBlockCount = PanelPtr->GetPanelBoardColBlockCount();
		const size_t BoardRowCount = PanelPtr->GetPanelBoardRowCount();
		if (BoardCount != BoardColCount*BoardColBlockCount*BoardRowCount){
			m_ErrorString.Format(_T("Please check the number of rows and columns of boards on the panel [%d]"), PanelID);
			return false;
		}
	}	
	return true;
}
