bool CAOIDataCollect::SaveGrabListStats()
{
	CString str;
	CString strFolder = GetAOILogDirectory();
	AOIObjManager.LockManager();

	str.Format(_T("%s\\%s"), strFolder, _T("GrabRgnList.TXT"));
	SaveGrabRgnListStats(str, m_RgnPtrList);

	str.Format(_T("%s\\%s"), strFolder, _T("GrabFovList.TXT"));
	SaveGrabFovListStats(str, m_FovPtrList);

	str.Format(_T("%s\\%s"), strFolder, _T("GrabSliceList.TXT"));
	SaveGrabSliceListStats(str, m_SlicePtrList);

	str.Format(_T("%s\\%s"), strFolder, _T("GrabFrameList.TXT"));
	SaveGrabFrameListStats(str, m_FramePtrList);

	str.Format(_T("%s\\%s"), strFolder, _T("GrabFieldList.TXT"));
	SaveGrabFieldListStats(str, m_FieldPtrList);

	AOIObjManager.UnlockManager();
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveGrabRgnListStats(LPCTSTR filename, const std::vector<CAOIRgn*> &List)
{
	FILE *pfile = NULL;
	TCHAR   TMode[32] = _T("");
	const size_t Count=List.size();	
	_tcscpy(TMode, _T("w+"));
	JetAPI::ModifyOpenFileMode_Write(TMode);
	pfile = ::_tfopen(filename, TMode);
	if ( NULL == pfile )
	{	return false;	}

	::_ftprintf(pfile, _T("idx, FieldID, FullName, SubRgn, Calc, Calced, SubRngCnt, NeedToCalc, AllFrameMerge, ReadyToCalc\n"));
	for ( size_t i=0; i<Count; i++ )
	{
		CAOIRgn *RgnPtr=List[i];
		if ( NULL == RgnPtr ) { continue; }				
		CString strSubRgn;
		CString strCalced;
		CString strCalcState;
		CString strFullName;
		CString strNeedToCalculate;
		CString strAllFrameMergeFinish;
		CString strReadyToCalc;
		CAOIRgn *ObjRgn = RgnPtr;
		CAOIRgn *ParentPtr = RgnPtr->GetRgnParent();
		const size_t SubRgnCnt = RgnPtr->GetRgnSubRgnCount();
		const size_t FieldIndex = RgnPtr->GetRgnFieldIndex();
		const bool bCalculated = RgnPtr->GetRgnCalculated();
		REGION_CALC_STATE CalcState = RgnPtr->GetRgnCalcState();
		const bool bNeedToCalculate = RgnPtr->CheckRgnNoNeedToCalculate();
		const bool bAllFrameMergeFinish = RgnPtr->CheckRgnFieldAllFrameMergeFinish();
		const bool bReadyToCalc = RgnPtr->CheckRgnReadyToCalc();
		if ( NULL != ParentPtr )
		{	ObjRgn = ParentPtr;	}
		if ( NULL != ObjRgn )
		{
			CAOIFd *FdPtr = NULL;
			CAOIMark *MarkPtr = NULL;
			CAOIBarcode *BarcodePtr = NULL;
			CAOIComponent *ComponentPtr = NULL;
			AOI_OBJ_TYPE ObjType = ObjRgn->GetObjType();
			switch ( ObjType )
			{
			case AOI_OBJ_FD: 
				FdPtr = dynamic_cast<CAOIFd*>(ObjRgn);
				if ( NULL != FdPtr )
				{	strFullName = FdPtr->GetFdFullName(); }
				break;
			case AOI_OBJ_MARK:
				MarkPtr = dynamic_cast<CAOIMark*>(ObjRgn);
				if ( NULL != MarkPtr )
				{	strFullName = MarkPtr->GetMarkFullName(); }
				break;
			case AOI_OBJ_BARCODE:
				BarcodePtr = dynamic_cast<CAOIBarcode*>(ObjRgn);
				if ( NULL != BarcodePtr )
				{	strFullName = BarcodePtr->GetBarcodeFullName(); }
				break;
			case AOI_OBJ_COMPONENT:
				ComponentPtr = dynamic_cast<CAOIComponent*>(ObjRgn);
				if ( NULL != ComponentPtr )
				{	strFullName = ComponentPtr->GetComponentFullName(); }
				break;
			default:
			case AOI_OBJ_RGN:
				strFullName.Format(_T("Rgn#04d"), RgnPtr->GetRgnIndex_Project()+1);
				break;
			}
		}		

		if ( NULL == ParentPtr ) { strSubRgn = _T("N"); }
		else { strSubRgn = _T("Y"); }

		if ( true == bCalculated ) { strCalced = _T("Y"); }
		else { strCalced = _T("N"); }
		switch ( CalcState )
		{
		case REGION_CALC_NONE: strCalcState=_T("None"); break;
		case REGION_CALC_DOING: strCalcState=_T("Doing"); break;
		case REGION_CALC_DONE: strCalcState=_T("Done"); break;
		case REGION_CALC_CLEAR: strCalcState=_T("Clear"); break;
		default: strCalcState=_T("Others"); break;
		}


		if ( true == bNeedToCalculate ) { strNeedToCalculate = _T("Y"); }
		else { strNeedToCalculate = _T("N"); }

		if ( true == bAllFrameMergeFinish ) { strAllFrameMergeFinish = _T("Y"); }
		else { strAllFrameMergeFinish = _T("N"); }

		if ( true == bReadyToCalc ) { strReadyToCalc = _T("Y"); }
		else { strReadyToCalc = _T("N"); }

		::_ftprintf(pfile, _T("%d, %d, %s, %s, %s, %s, %d, %s, %s, %s\n"), i+1, FieldIndex+1, strFullName, strSubRgn, strCalcState, strCalced, SubRgnCnt, strNeedToCalculate, strAllFrameMergeFinish, strReadyToCalc);
	}
	::fclose(pfile); pfile=NULL;
	return true;	
}
