bool CAOIDataCollect::SaveGrabSliceListStats(LPCTSTR filename, const std::vector<CAOISlice*> &List)
{
	FILE *pfile = NULL;
	TCHAR   TMode[32] = _T("");
	const size_t Count=List.size();	
	_tcscpy(TMode, _T("w+"));
	JetAPI::ModifyOpenFileMode_Write(TMode);
	pfile = ::_tfopen(filename, TMode);
	if ( NULL == pfile )
	{	return false;	}

	::_ftprintf(pfile, _T("idx, FrameID, Fill\n"));
	for ( size_t i=0; i<Count; i++ )
	{
		const CAOISlice *SlicePtr=List[i];
		if ( NULL == SlicePtr ) { continue; }		
		CString strState;
		const size_t FrameIndex = SlicePtr->GetSliceFrameIdx();
		SLICE_FILL_STATE State = SlicePtr->GetSliceFillState();
		switch ( State )
		{
		case SLICE_FILL_NONE: strState=_T("None"); break;
		case SLICE_FILL_DOING: strState=_T("Doing"); break;
		case SLICE_FILL_DONE: strState=_T("Done"); break;
		case SLICE_FILL_CLEAR: strState=_T("Clear"); break;
		default: strState=_T("Others"); break;
		}
		::_ftprintf(pfile, _T("%d, %d, %s\n"), i+1, FrameIndex+1, strState);
	}
	::fclose(pfile); pfile=NULL;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CAOIDataCollect::SaveGrabFrameListStats(LPCTSTR filename, const std::vector<CAOIFrame*> &List)
{
	FILE *pfile = NULL;
	TCHAR   TMode[32] = _T("");
	const size_t Count=List.size();	
	_tcscpy(TMode, _T("w+"));
	JetAPI::ModifyOpenFileMode_Write(TMode);
	pfile = ::_tfopen(filename, TMode);
	if ( NULL == pfile )
	{	return false;	}

	::_ftprintf(pfile, _T("idx, FovID, FieldID, SliceCount, Type, Merge, Calc\n"));
	for ( size_t i=0; i<Count; i++ )
	{
		const CAOIFrame *FramePtr=List[i];
		if ( NULL == FramePtr ) { continue; }		
		CString strType;
		CString strCalcState;
		CString strMergeState;		
		const size_t FovIndex = FramePtr->GetFrameFovIndex();
		const size_t FieldIndex = FramePtr->GetFrameFieldIndex();
		const size_t SliceCount = FramePtr->GetFrameSliceCount();
		const FRAME_TYPE FrameType = FramePtr->GetFrameType();
		FRAME_CALC_STATE CalcState = FramePtr->GetFrameCalcState();
		FRAME_MERGE_STATE MergeState = FramePtr->GetFrameMergeState();		
		
		switch ( FrameType )
		{
		case FRAME_NULL: strType=_T("NULL"); break;
		case FRAME_GRAY: strType=_T("Gray"); break;
		case FRAME_BAYER: strType=_T("Bayer"); break;		
		case FRAME_COLOR: strType=_T("Color"); break;		
		case FRAME_SPACE: strType=_T("Space"); break;		
		}

		switch ( CalcState )
		{
		case FRAME_CALC_NONE: strCalcState=_T("None"); break;
		case FRAME_CALC_DOING: strCalcState=_T("Doing"); break;
		case FRAME_CALC_DONE: strCalcState=_T("Done"); break;		
		default: strCalcState=_T("Others"); break;
		}
		switch ( MergeState )
		{
		case FRAME_MERGE_NONE: strMergeState=_T("None"); break;
		case FRAME_MERGE_DOING: strMergeState=_T("Doing"); break;
		case FRAME_MERGE_DONE: strMergeState=_T("Done"); break;
		case FRAME_MERGE_CLEAR: strMergeState=_T("Clear"); break;
		default: strMergeState=_T("Others"); break;
		}
		::_ftprintf(pfile, _T("%d, %d, %d, %d, %s, %s, %s\n"), i+1, FovIndex+1, FieldIndex+1, SliceCount, strType, strMergeState, strCalcState);
	}
	::fclose(pfile); pfile=NULL;
	return true;
}
